export default {"1":{"html":"<p>तुमच्या वयाच्या असताना तुमच्या आई-वडिलांना इडलीच्या एका प्लेटची किंवा एका लिटर पेट्रोलची किंमत काय विचारा, आणि आज तुम्हाला विनोदी वाटणारा नंबर ऐकू येईल. त्या शांत, अथक भाववाढीला एक नाव आहे, <strong>महागाई</strong>, आणि हा कोर्स अस्तित्वात आहे हे एकमेव सर्वात महत्वाचे कारण आहे. बसून राहिलेला पैसा स्थिर राहत नाही; ते हळूहळू संकुचित होते. गुंतवणूक करणे शिकणे म्हणजे फक्त तुमचे पैसे वाढवायला शिकणे <em>जलद</em> किंमती वाढण्यापेक्षा, जेणेकरून तुमचा भविष्यातील माणूस तुमच्या वर्तमानापेक्षा श्रीमंत असेल, गरीब नाही.</p>\n<p>ही चांगली बातमी आणि आश्चर्यकारक भाग आहे: हे चांगले करण्यासाठी तुम्हाला प्रतिभावान असण्याची, पुढील क्रॅशचा अंदाज लावण्याची किंवा पुढील मल्टीबॅगर निवडण्याची गरज नाही. तुला दोन निंदनीय गोष्टींची गरज आहे, <strong>वेळ</strong> आणि <strong>संयम</strong>, आणि तुम्ही जितक्या लवकर सुरुवात कराल, तितकी कमी तुम्हाला आवश्यक आहे. हा पहिला अध्याय याबद्दल आहे <em>का</em>. कोर्समधील इतर सर्व काही याबद्दल आहे <em>कसे</em>.</p>\n<h2 id=\"saving-is-not-the-same-as-investing\">बचत करणे हे गुंतवणुकीसारखे नाही</h2>\n<p>बहुतेक लोकांना शिकवले जाते <em>जतन करा</em>, खर्च न करणे. ही एक चांगली सवय आहे, परंतु केवळ बचत करणे हे केवळ अर्धे काम आहे. नियमित बचत खात्यात ठेवलेले पैसे वर्षाला सुमारे 3% कमावतात, तर किंमती वर्षाला अंदाजे 5-6% वाढतात. त्यामुळे \"सुरक्षित\" बचत खाते हे खऱ्या अर्थाने धीमे गळती आहे.</p>\n<ul>\n<li><strong>बचत करत आहे</strong> पैसे बाजूला ठेवत आहे. हे रुपयाच्या रकमेचे संरक्षण करते.</li>\n<li><strong>गुंतवणूक करत आहे</strong> ते वाचवलेले पैसे टाकत आहे <em>काम</em> वाढणाऱ्या मालमत्तेत. ते रुपयाचे संरक्षण करते (आणि वाढवते). <em>खरेदी शक्ती</em>.</li>\n</ul>\n<p>फरक लहान वाटतो. आयुष्यभर स्क्रॅप करणे आणि आरामदायक असणे यात फरक आहे.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>बचत केल्याने तुमचे पैसे तेवढेच रुपये राहतात. गुंतवणुकीचे उद्दिष्ट ते रुपये प्रत्यक्षात काय ठेवू शकतात आणि वाढू शकतात <em>खरेदी</em>. महागाईला मारणे ऐच्छिक नाही; तो संपूर्ण मुद्दा आहे.</p>\n</div></div>\n<h2 id=\"the-silent-thief-inflation\">मोकाट चोर : महागाई</h2>\n<p>कल्पना करा की तुम्ही 1,00,000 रुपये 2000 साली एका गादीखाली ठेवले होते. नोटांवरचा क्रमांक कधीही बदलला नाही. पण सरासरी 6% महागाई दराने, 1,00,000 रु <em>खरेदी</em> वर्षानुवर्षे कमी होत गेले, सुमारे 25 वर्षांनंतर, ते त्यावेळेस सुमारे 23,000 रुपये खरेदी करते. तुम्ही एक रुपयाही खर्च न करता तुमची तीन चतुर्थांश क्रयशक्ती गमावली आहे. तोच कामातला मोकाट चोर.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch01-inflation-erosion.png\" alt=\"100 रुपयांची खरेदी शक्ती 25 वर्षांत 6% महागाईवर वितळते, आज 100 रुपयांची खरेदी उद्या खूपच कमी आहे\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">डेटा उदा</span>100 रुपयांची खरेदी शक्ती 25 वर्षांत 6% महागाईवर वितळते, आज 100 रुपयांची खरेदी उद्या खूपच कमी आहे</figcaption></figure>\n<p>म्हणूनच केवळ रोख आणि बचत खात्यांसह \"ते सुरक्षितपणे खेळणे\" हे विरोधाभासाने, एक आहे. <em>सर्वात धोकादायक</em> ज्या गोष्टी तुम्ही पैशाने करू शकता त्या गोष्टी तुम्हाला अनेक वर्षे लागणार नाहीत. धोका हा नाही की संख्या घसरली आहे, तो हा आहे की जग अधिक महाग होत असताना संख्या स्थिर आहे.</p>\n<h2 id=\"compounding-the-eighth-wonder\">कंपाउंडिंग: आठवे आश्चर्य</h2>\n<p>आता तुमच्या बाजूने काम करणारी जादू. तुम्ही गुंतवणूक करता तेव्हा तुम्हाला परतावा मिळतो. पुढील वर्षी तुम्ही तुमच्या मूळ पैशावर परतावा मिळवाल <em>अधिक</em> गेल्या वर्षीचा परतावा. वर्षानंतर, पुन्हा त्या सर्वांवर. तुमचे पैसे कमावायला लागतात, जे पैसे कमवतात. या स्नोबॉलला म्हणतात <strong>कंपाउंडिंग</strong>, आणि दीर्घकाळापर्यंत तो अशा गोष्टी करतो ज्या जवळजवळ अयोग्य वाटतात.</p>\n<p>एक साधी, वास्तविक-जागतिक सवय विचारात घ्या: एका इंडेक्स फंडात दरमहा रु 5,000 गुंतवणे जे वर्षाला सुमारे 12% (निफ्टी 50 च्या दीर्घकालीन सरासरीच्या जवळपास) आहे.</p>\n<table>\n<thead>\n<tr>\n<th>वर्षे गुंतवली</th>\n<th align=\"right\">तू टाक</th>\n<th align=\"right\">ते (अंदाजे) पर्यंत वाढू शकते.</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>10 वर्षे</td>\n<td align=\"right\">6,00,000 रु</td>\n<td align=\"right\">11.6 लाख रु</td>\n</tr>\n<tr>\n<td>20 वर्षे</td>\n<td align=\"right\">12,00,000 रु</td>\n<td align=\"right\">50 लाख रु</td>\n</tr>\n<tr>\n<td>30 वर्षे</td>\n<td align=\"right\">18,00,000 रु</td>\n<td align=\"right\">1.76 कोटी रु</td>\n</tr>\n</tbody></table>\n<p>बारकाईने पहा. वेळ तिप्पट केल्याने (10 ते 30 वर्षे) परिणाम तिप्पट झाला नाही, तो पेक्षा जास्त गुणाकार झाला <em>पंधरा</em> वेळा ती कंपाऊंडिंगची स्वाक्षरी आहे: सर्वात मोठी वर्षे सर्वात जास्त वजन उचलतात आणि ते नेहमीच असतात <em>शेवटचे</em> च्या जो या संपूर्ण अभ्यासक्रमातील सर्वात महत्त्वाचा धडा घेऊन जातो.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch01-compounding-snowball.png\" alt=\"दोन मित्र, समान 5,000 रुपये मासिक SIP, जो 25 पासून सुरू होतो तो 35 वर्षापासून सुरू होणाऱ्याच्या दुप्पट संपतो, पूर्णपणे दहा वर्षांच्या सुरुवातीपासून\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">डेटा उदा</span>दोन मित्र, समान 5,000 रुपये मासिक SIP, जो 25 पासून सुरू होतो तो 35 वर्षापासून सुरू होणाऱ्याच्या दुप्पट संपतो, पूर्णपणे दहा वर्षांच्या सुरुवातीपासून</figcaption></figure>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>अल्बर्ट आइनस्टाईन अनेकदा चक्रवाढ व्याज म्हणून उद्धृत केले जातात \"जगाचे आठवे आश्चर्य, ज्याला ते समजते, तो कमावतो; जो नाही तो देतो.\" तो खरोखर म्हणाला किंवा नाही, प्रत्येक दीर्घकालीन गुंतवणूकदाराला शेवटी कळते की तो बरोबर होता.</p>\n</div></div>\n<h2 id=\"start-young-time-beats-timing\">तरुण प्रारंभ करा: वेळ वेळेवर मात करतो</h2>\n<p>दोन मित्रांचे चित्र. <strong>रिया</strong> वयाच्या 25 व्या वर्षी दरमहा रु 5,000 गुंतवायला सुरुवात करते आणि 35 व्या वर्षी थांबते, फक्त दहा वर्षात, एकूण रु. 6 लाख, नंतर कधीही आणखी एक रुपया जोडत नाही, ती 60 वर्षांची होईपर्यंत एकत्र करू देते. <strong>आरव</strong> 35 पर्यंत काहीही करत नाही, त्यानंतर पुढील 25 वर्षांसाठी तेच 5,000 रुपये प्रति महिना मेहनतीने गुंतवतो, एकूण 15 लाख रुपये. 60 वर कोण जास्त आहे?</p>\n<p>गुंतवणूक करूनही रिया आरामात करते <em>अर्ध्याहून कमी</em> तितके पैसे. तिचे रहस्य कौशल्य किंवा नशीब नव्हते. ही दहा वर्षांची सुरुवात होती ज्याने कंपाउंडिंग अधिक काळ चालू द्या. बाजारातील वेळेने ते केले जे हुशार वेळेनुसार करू शकत नाही.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>तरुण गुंतवणूकदार म्हणून तुमचा सर्वात मोठा फायदा आहे <strong>वेळ</strong>, बुद्धिमत्ता नाही. 32 ऐवजी 22 पासून सुरू करणे तुम्ही निवडलेल्या प्रत्येक स्टॉकपेक्षा जास्त महत्त्वाचे ठरू शकते. सुरुवात करण्याचा सर्वोत्तम दिवस वर्षापूर्वी होता; दुसरा सर्वोत्तम आज आहे.</p>\n</div></div>\n<h2 id=\"why-you-can-t-and-needn-t-predict-the-market\">आपण बाजाराचा अंदाज का करू शकत नाही (आणि गरज नाही)</h2>\n<p>हा सापळा आहे ज्यामध्ये जवळजवळ प्रत्येक नवशिक्या येतो: ध्येयावर विश्वास ठेवणे <em>अंदाज</em> पुढील आठवड्यात बाजार काय करेल, तळाचा अंदाज लावा आणि अचूक प्रवेशाची वेळ द्या. थांबा. प्रामाणिक सत्य ते आहे <strong>कोणीही नाही, निधी व्यवस्थापक नाही, TV तज्ञ नाही, सर्वात मोठा YouTube चॅनेल असलेली व्यक्ती नाही, अल्पकालीन बाजारातील हालचालींचा विश्वासार्हपणे अंदाज लावू शकतो.</strong> अद्याप घडलेल्या बातम्यांवर लाखो लोक प्रतिक्रिया देणाऱ्यांद्वारे बाजारपेठ चालविली जाते. ते, अल्पावधीत, खरोखर अप्रत्याशित आहेत.</p>\n<p>आणि सुंदर भाग तो आहे <em>तुम्हाला कशाचाही अंदाज लावण्याची गरज नाही</em>. संपत्ती निर्माण करणारे इंजिन अंदाज लावत नाही; आहे <strong>चांगल्या मालमत्तेचे मालक असणे आणि चढ-उतारांदरम्यान गुंतवणूक करणे.</strong> अभ्यास वारंवार दाखवतात की जे गुंतवणूकदार आत आणि बाहेर उडी मारण्याचा प्रयत्न करतात, भीतीपोटी विक्री करतात, लोभात खरेदी करतात, ज्यांनी फक्त स्थिरपणे गुंतवणूक केली आणि काहीही केले नाही त्यांच्यासाठी वाईट कामगिरी करतात.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>पुढच्या आठवड्यात बाजार कुठे चालला आहे हे सांगण्याचे वचन देणारा किंवा परताव्याची हमी देणारा कोणीही सावध रहा. भविष्यवाणी आत्मविश्वास विकते, परिणाम नाही. नवशिक्याचे काम बाजाराचा अंदाज बांधणे नाही, ते आहे <em>सहभागी होणे</em> त्यामध्ये संयमाने, महिन्यामागून महिना, दशकांमागून दशके संपत्ती निर्माण करणे. जोखीम आणि गुंतवणूकदाराच्या मनावर आम्ही नंतरच्या अध्यायात या शिस्तीकडे परत येऊ.</p>\n</div></div>\n<h2 id=\"real-returns-the-number-that-actually-matters\">वास्तविक परतावा: वास्तविक महत्त्वाची संख्या</h2>\n<p>जेव्हा कोणी गुंतवणुकीला \"९% दिले\" म्हणते, तेव्हा नेहमी विचारा: ९% <em>आधी</em> किंवा <em>नंतर</em> महागाई? मथळा आकृती आहे <strong>नाममात्र परतावा</strong>. महागाई वजा करा आणि तुम्हाला मिळेल <strong>वास्तविक परतावा</strong>, तुमची वास्तविक खरेदी शक्ती वाढवणारा एकमेव.</p>\n<ul>\n<li>7% ची मुदत ठेव आणि 6% महागाई फक्त ~1% चा वास्तविक परतावा देते.</li>\n<li>समान महागाईसह सरासरी ~12% इक्विटीज ~6% चा वास्तविक परतावा देतात, सहा पट अधिक <em>उपयुक्त</em> वाढ, वाटेत चढ-उतार स्वीकारण्याच्या बदल्यात.</li>\n</ul>\n<p>हा व्यापार, दीर्घकालीन वास्तविक वाढीच्या मोबदल्यात अल्प-मुदतीचा अडथळे स्वीकारणे, हा स्टॉकमधील गुंतवणुकीचा मध्यवर्ती सौदा आहे. काही महिन्यांत, इक्विटी रोलर-कोस्टर आहेत. काही दशकांमध्ये, ते भारतातील सर्वात शक्तिशाली संपत्ती-निर्माते आहेत.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch01-asset-returns.png\" alt=\"भारतातील अंदाजे दीर्घकालीन वार्षिक परतावा, इक्विटी विरुद्ध सोने वि मुदत ठेवी वि बचत खाते, सर्व 6% महागाई रेषेच्या विरुद्ध\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">डेटा उदा</span>भारतातील अंदाजे दीर्घकालीन वार्षिक परतावा, इक्विटी विरुद्ध सोने वि मुदत ठेवी वि बचत खाते, सर्व 6% महागाई रेषेच्या विरुद्ध</figcaption></figure>\n<h2 id=\"india-is-investing-like-never-before\">भारतात कधीही पूर्वीसारखी गुंतवणूक होत आहे</h2>\n<p>हे आता एक कोनाडा पाठपुरावा नाही. भारताने पार केले आहे <strong>21 कोटी डिमॅट खाती</strong>, आणि मासिक <strong>SIP म्युच्युअल फंडातील योगदान 25,000 कोटी रुपयांपेक्षा जास्त आहे</strong>, विक्रम जे तुटत राहतात. केवळ पगाराने संपत्ती निर्माण होत नाही, हे तरुण भारतीयांच्या संपूर्ण पिढीला समजले आहे; गुंतवलेल्या बचत करतात. तुम्ही त्या शिफ्टमध्ये अगदी योग्य वेळी सामील होत आहात, अगदी योग्य कल्पनेसह: लवकर सुरुवात करा, धीर धरा, चक्रवाढ कार्य करू द्या.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>या संपूर्ण कोर्समध्ये, \"बाजार\" म्हणजे भारतीय शेअर बाजार, नॅशनल स्टॉक एक्स्चेंज (NSE) आणि बॉम्बे स्टॉक एक्सचेंज (BSE), आणि आकडे रुपये आणि भारतीय उदाहरणे वापरतात. येथे काहीही गुंतवणूक सल्ला नाही; हे सर्व कसे कार्य करते हे समजून घेण्यास आणि आपले स्वतःचे माहितीपूर्ण निर्णय घेण्यास मदत करणे हे शिक्षण आहे.</p>\n</div></div>\n<h2 id=\"quick-recap\">क्विक रिकॅप</h2>\n<ul>\n<li><strong>महागाई</strong> निष्क्रिय रोख खरेदीची शक्ती शांतपणे नष्ट करते, \"सुरक्षित\" बचत कालांतराने शांतपणे मूल्य गमावते.</li>\n<li><strong>बचत करत आहे</strong> रुपये वाचवतो; <strong>गुंतवणूक</strong> ते रुपये जे विकत घेऊ शकतात ते वाढतात. तुम्हाला दोन्हीची गरज आहे.</li>\n<li><strong>कंपाउंडिंग</strong> पैसे कमावतात आणि त्याचा सर्वात मोठा फायदा अंतिम, प्रदीर्घ वर्षांमध्ये होतो.</li>\n<li><strong>तरुण सुरुवात</strong> नवशिक्यासाठी सर्वात मोठी धार आहे: बाजारातील वेळ बाजाराच्या वेळेला मारतो.</li>\n<li>आपण <strong>अंदाज करू शकत नाही आणि आवश्यक नाही</strong> अल्पकालीन हालचाली, रुग्णांचा सहभाग, अंदाज न लावणे, संपत्ती निर्माण करते.</li>\n<li>द्वारे गुंतवणूक न्याय <strong>वास्तविक (महागाई नंतर) परतावा</strong>, आणि दीर्घकालीन वाढीसाठी अल्पकालीन अडथळे स्वीकारा.</li>\n</ul>\n<p>पुढे, आम्ही पाहतो <em>कुठे</em> इक्विटी आणि डेटपासून ते सोने आणि क्रिप्टोपर्यंत तुमचा पैसा, प्रमुख मालमत्ता वर्ग, आणि इक्विटींनी ऐतिहासिकदृष्ट्या सर्वात जास्त संपत्ती का निर्माण केली आहे.</p>\n","toc":[{"level":2,"text":"बचत करणे हे गुंतवणुकीसारखे नाही","id":"saving-is-not-the-same-as-investing"},{"level":2,"text":"मोकाट चोर : महागाई","id":"the-silent-thief-inflation"},{"level":2,"text":"कंपाउंडिंग: आठवे आश्चर्य","id":"compounding-the-eighth-wonder"},{"level":2,"text":"तरुण प्रारंभ करा: वेळ वेळेवर मात करतो","id":"start-young-time-beats-timing"},{"level":2,"text":"आपण बाजाराचा अंदाज का करू शकत नाही (आणि गरज नाही)","id":"why-you-can-t-and-needn-t-predict-the-market"},{"level":2,"text":"वास्तविक परतावा: वास्तविक महत्त्वाची संख्या","id":"real-returns-the-number-that-actually-matters"},{"level":2,"text":"भारतात कधीही पूर्वीसारखी गुंतवणूक होत आहे","id":"india-is-investing-like-never-before"},{"level":2,"text":"क्विक रिकॅप","id":"quick-recap"}],"imgCount":3,"hasContent":true},"2":{"html":"<p>पैसा तिथे बसू शकत नाही. ज्या क्षणी तुमच्याकडे काही बचत असेल, तेव्हा तुम्हाला एका शांत पण अपरिहार्य प्रश्नाचा सामना करावा लागतो: <em>ते कोठे राहावे?</em> बँक खाते, फिक्स डिपॉझिट, लॉकरमधील सोने, फ्लॅट, काही शेअर्स, कदाचित क्रिप्टोचा एक तुकडा, प्रत्येक तुमच्या पैशासाठी वेगळे घर आहे, त्याचे स्वतःचे व्यक्तिमत्त्व आहे. काही घरे शांत आणि सुरक्षित असतात पण तुमचा पैसा फारच कमी होतो. इतर काही दशकांपासून ते शक्तिशालीपणे वाढवतात परंतु वाटेत वर-खाली होतात.</p>\n<p>या घरांना योग्य नाव आहे: <strong>मालमत्ता वर्ग</strong>. खरोखरच काही मोजकेच आहेत, आणि एकदा का तुम्ही त्यांच्यातील ट्रेड-ऑफ समजून घेतल्यावर, गुंतवणुकीचे संपूर्ण जग कॅसिनोसारखे दिसणे थांबते आणि योग्य पर्यायांच्या संचासारखे दिसू लागते. हा धडा तुमच्या प्रदेशाचा नकाशा आहे, प्रत्येक मालमत्ता वर्ग कोणता आहे, तो किती धोकादायक आहे, ऐतिहासिकदृष्ट्या काय परत केले आहे आणि तुम्ही ते किती लवकर रोखीत परत करू शकता.</p>\n<h2 id=\"the-handful-of-homes-for-your-money\">तुमच्या पैशासाठी मूठभर घरे</h2>\n<p>शब्दजाल काढून टाका आणि तुम्ही ज्यामध्ये गुंतवणूक करू शकता ती जवळपास सर्व सहा बादलींपैकी एकामध्ये येते:</p>\n<ul>\n<li><strong>इक्विटी (साठा)</strong>, वास्तविक व्यवसायाची अंशतः मालकी. व्यवसाय वाढल्याने तुम्हाला नफा होतो.</li>\n<li><strong>कर्ज (एफडी आणि बाँड)</strong>, तुम्ही <em>कर्ज देणे</em> बँक, कंपनी किंवा सरकारला पैसे द्या आणि त्या बदल्यात निश्चित व्याज मिळवा.</li>\n<li><strong>सोने</strong>, एक वास्तविक, दुर्मिळ धातू लोकांनी 5,000 वर्षांपासून विश्वास ठेवला आहे; सर्व काही डळमळते तेव्हा हेज.</li>\n<li><strong>रिअल इस्टेट</strong>, जमीन आणि मालमत्ता, जे भाडे मिळवू शकतात आणि मूल्य वाढू शकतात.</li>\n<li><strong>रोख (आणि बचत खाती)</strong>, पैसे तुम्ही झटपट खर्च करू शकता, जवळजवळ काहीही मिळवू शकत नाही.</li>\n<li><strong>क्रिप्टो</strong>, बिटकॉइन सारख्या डिजिटल मालमत्ता; नवीन, सीमाहीन आणि अत्यंत अस्थिर.</li>\n</ul>\n<p>तो संपूर्ण मेनू आहे. फॅन्सियर, म्युच्युअल फंड, ईटीएफ, इंडेक्स फंड, सर्व काही फक्त सोयीस्कर आहे <em>टोपली</em> याच बिल्डिंग ब्लॉक्सपैकी.</p>\n<h2 id=\"the-one-rule-that-explains-everything-risk-vs-return\">एक नियम जो सर्व काही स्पष्ट करतो: जोखीम वि रिटर्न</h2>\n<p>येथे गुंतवणुकीची सर्वात महत्वाची कल्पना आहे आणि ती वरील प्रत्येक मालमत्तेवर नियंत्रण ठेवते: <strong>उच्च संभाव्य परतावा नेहमी उच्च जोखमीसह येतो.</strong> अशी कोणतीही मालमत्ता नाही जी दोन्ही पूर्णपणे सुरक्षित आहे <em>आणि</em> अत्यंत फायद्याचे. जर कोणी तुम्हाला ऑफर करत असेल तर ते एकतर चुकीचे किंवा खोटे बोलत आहेत.</p>\n<p>येथे \"जोखीम\" याचा अर्थ \"तुम्ही नक्कीच पैसे गमावाल.\" याचा अर्थ <em>अनिश्चितता</em>, मूल्य किती बाउन्स होते आणि परिणामांची श्रेणी किती विस्तृत आहे. फिक्स्ड डिपॉझिटमध्ये एक लहान श्रेणी असते (तुम्हाला जवळजवळ नक्की काय मिळेल हे माहित आहे). एका वर्षात इक्विटीची श्रेणी खूप मोठी आहे (ती 30% वाढू शकते किंवा 20% कमी होऊ शकते) परंतु एका दशकात खूपच संकुचित, खूप जास्त श्रेणी आहे.</p>\n<p>मालमत्तेचे वर्ग शिडीवरील पायर्या म्हणून चित्रित करा. सर्वात कमी पट्ट्या शांत आणि सुरक्षित आहेत परंतु तुमचे पैसे हळूहळू वाढवा. वर चढणे आणि संभाव्य बक्षीस दोन्ही <em>आणि</em> अडथळे एकत्र वाढतात.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch02-risk-return-ladder.png\" alt=\"जोखीम-परतावा शिडी, तळाशी सुरक्षित, मंद रोख ते उच्च-रिटर्न, उच्च-अस्थिरता इक्विटी आणि शीर्षस्थानी क्रिप्टो; बक्षीस आणि जोखीम एकत्रितपणे वाढते\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>जोखीम-परतावा शिडी, तळाशी सुरक्षित, मंद रोख ते उच्च-रिटर्न, उच्च-अस्थिरता इक्विटी आणि शीर्षस्थानी क्रिप्टो; बक्षीस आणि जोखीम एकत्रितपणे वाढते</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>गुंतवणुकीत मोफत जेवण नाही. अपेक्षित परताव्याचा प्रत्येक अतिरिक्त रुपया जोखमीच्या अतिरिक्त युनिटसह भरला जातो. कौशल्य जोखीम टाळत नाही, ते घेत आहे <em>योग्य रक्कम</em> तुमच्या ध्येयांसाठी आणि तुमच्या टाइमलाइनसाठी जोखीम.</p>\n</div></div>\n<h2 id=\"liquidity-how-fast-can-you-get-your-cash-back\">तरलता: तुम्ही तुमची रोख किती लवकर परत मिळवू शकता?</h2>\n<p>परतावा आणि जोखीम या दोनच गोष्टी नाहीत. <strong>तरलता</strong>, तुम्ही एखाद्या मालमत्तेचे किती लवकर आणि स्वस्तात रूपांतर खर्च करण्यायोग्य रोखीत करू शकता, हे तितकेच महत्त्वाचे आहे, विशेषतः आपत्कालीन परिस्थितीत.</p>\n<ul>\n<li><strong>रोख</strong> उत्तम प्रकारे द्रव आहे <em>आहे</em> रोख</li>\n<li><strong>साठा</strong> अत्यंत तरल असतात, बाजाराच्या वेळेत विक्री करतात आणि पैसे एक-दोन दिवसात तुमच्या बँकेत पोहोचतात.</li>\n<li><strong>गोल्ड ईटीएफ आणि एफडी</strong> बऱ्यापैकी द्रव आहेत; भौतिक सोन्याला खरेदीदार आणि किमतीनुसार केस कापण्याची गरज आहे.</li>\n<li><strong>रिअल इस्टेट</strong> सर्वात कमी द्रव आहे, फ्लॅट विकण्यासाठी काही महिने लागू शकतात आणि जड कागदपत्रे.</li>\n</ul>\n<p>तुम्हाला अचानक गरज असताना तुमचे पैसे एखाद्या मालमत्तेत लॉक केले असल्यास उच्च परतावा हा थंड आराम आहे. यामुळे तुमचे <em>आपत्कालीन निधी</em> नेहमी रोख किंवा द्रव पर्यायांमध्ये बसतो, कधीही मालमत्तेत नाही.</p>\n<h2 id=\"a-one-line-note-on-tax\">करावर एक ओळीची टीप</h2>\n<p>प्रत्येक रिटर्नमध्ये कर शांतपणे खातो, आणि तो मालमत्तेनुसार वेगळा असतो (नियम अंदाजे असतात आणि प्रत्येक बजेटमध्ये बदलतात):</p>\n<table>\n<thead>\n<tr>\n<th>मालमत्ता</th>\n<th>नफ्यावर कर कसा लावला जातो (अंदाजे, भारत)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>इक्विटी / इक्विटी फंड</td>\n<td>12.5% ​​दीर्घकालीन (1 वर्षापेक्षा जास्त, रु. 1.25 लाखांपेक्षा जास्त); 20% अल्पकालीन</td>\n</tr>\n<tr>\n<td>एफडी/डेट फंड</td>\n<td>तुमच्या स्लॅब दराने कर आकारला, तुमच्या उत्पन्नात जोडले</td>\n</tr>\n<tr>\n<td>सोने (ETF/funds)</td>\n<td>24 महिन्यांच्या होल्डिंगनंतर 12.5% ​​दीर्घकालीन</td>\n</tr>\n<tr>\n<td>रिअल इस्टेट</td>\n<td>24 महिन्यांनंतर 12.5% ​​दीर्घकालीन</td>\n</tr>\n<tr>\n<td>क्रिप्टो</td>\n<td>सपाट <strong>30%</strong> नफ्यावर, अधिक 1% TDS, कोणत्याही तोटा सेट-ऑफशिवाय</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>भारतात जवळपास इतर कोणत्याही मालमत्तेपेक्षा क्रिप्टोवर अधिक कठोरपणे कर आकारला जातो: प्रत्येक नफ्यावर सपाट 30%, प्रत्येक विक्रीवर स्त्रोतावर 1% कर वजा केला जातो आणि अनन्यपणे, तुम्ही तुमचा क्रिप्टो ऑफसेट करू शकत नाही. <em>नुकसान</em> तुमच्या क्रिप्टो विरुद्ध <em>नफा</em>. टॅक्समन तुमचा नफा शेअर करतो पण तुमचे दुख नाही.</p>\n</div></div>\n<h2 id=\"the-big-comparison-side-by-side\">मोठी तुलना, बाजूला</h2>\n<p>आता हे सर्व एकत्र ठेवा. खालील तक्ता या धड्याचे हृदय आहे, ते तुमच्या भिंतीवर टेप करा. (परतावे दीर्घकालीन असतात <em>ऐतिहासिक</em> रुपयांमध्ये सरासरी, अंदाजे आहेत आणि कधीही हमी दिली जात नाहीत.)</p>\n<table>\n<thead>\n<tr>\n<th>मालमत्ता वर्ग</th>\n<th>ठराविक धोका</th>\n<th>ठराविक दीर्घकालीन परतावा (अंदाजे)</th>\n<th>तरलता</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>रोख / बचत</td>\n<td>खूप कमी</td>\n<td>3-4%</td>\n<td>झटपट</td>\n</tr>\n<tr>\n<td>कर्ज (एफडी, बाँड)</td>\n<td>कमी</td>\n<td>6-7%</td>\n<td>मध्यम-उच्च</td>\n</tr>\n<tr>\n<td>सोने</td>\n<td>मध्यम</td>\n<td>8-10%</td>\n<td>मध्यम-उच्च</td>\n</tr>\n<tr>\n<td>रिअल इस्टेट</td>\n<td>मध्यम-उच्च</td>\n<td>७-९% (अधिक भाडे)</td>\n<td>खूप कमी</td>\n</tr>\n<tr>\n<td>इक्विटी (साठा)</td>\n<td>उच्च (अल्पकालीन)</td>\n<td>~12%</td>\n<td>उच्च</td>\n</tr>\n<tr>\n<td>क्रिप्टो</td>\n<td>खूप उच्च</td>\n<td>अज्ञात, अत्यंत स्विंग्स</td>\n<td>उच्च</td>\n</tr>\n</tbody></table>\n<p>इक्विटी पंक्ती काळजीपूर्वक वाचा. तो सर्वोच्च वाहून नेतो <em>अल्पकालीन</em> जोखीम तरीही सर्वाधिक दीर्घकालीन परतावा, आणि हाच सौदा आहे जो आम्ही प्रकरण 1 मध्ये भेटला: महिन्यांत अडथळे स्वीकारा आणि इक्विटीने तुम्हाला अनेक दशकांहून अधिक ऐतिहासिकदृष्ट्या पुरस्कृत केले आहे.</p>\n<h2 id=\"why-equity-has-built-the-most-wealth\">इक्विटीने सर्वाधिक संपत्ती का निर्माण केली आहे</h2>\n<p>दीर्घकाळापर्यंत, कोणतीही मुख्य प्रवाहातील भारतीय मालमत्ता इक्विटीशी जुळलेली नाही. कारण सोपे आणि सामर्थ्यवान आहे: जेव्हा तुमच्याकडे स्टॉक असतो, तेव्हा तुमच्या मालकीचा एक तुकडा असतो <em>जगणे, वाढणारा व्यवसाय</em> जे त्याच्या नफ्याची पुनर्गुंतवणूक करते, विस्तार करते, महागाईसह किमती वाढवते आणि वर्षानुवर्षे त्याची कमाई वाढवते. सोने फक्त तिजोरीत बसते; एक चांगली कंपनी <em>कार्य करते</em> तुमच्यासाठी</p>\n<p>त्याचा पुरावा हेडलाइन इंडेक्समध्येच आहे. BSE सेन्सेक्स 1979 मध्ये 100 च्या मूळ मूल्याने सुरू झाला. आज तो 76,000-77,000 च्या आसपास व्यापार करतो. 1979 मध्ये काही लाख किमतीचा फ्लॅट आजही तितका जवळ आला नाही.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch02-asset-returns.png\" alt=\"भारतातील मालमत्ता वर्गानुसार अंदाजे दीर्घकालीन वार्षिक परतावा, इक्विटी अग्रगण्य, नंतर सोने आणि रिअल इस्टेट, कर्ज आणि रोख मागे चलनवाढीसह\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">डेटा उदा</span>भारतातील मालमत्ता वर्ग, इक्विटी अग्रगण्य, नंतर सोने आणि रिअल इस्टेट, कर्ज आणि रोखीच्या मागच्या चलनवाढीनुसार अंदाजे दीर्घकालीन वार्षिक परतावा</figcaption></figure>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>1979 च्या 100 च्या बेसवरून आज अंदाजे 77,000 पर्यंत, सेन्सेक्स सुमारे गुणाकार झाला आहे <strong>770 वेळा</strong> सुमारे 45 वर्षांत. ती म्हणजे व्यवसायांची मालकी घेण्याची आणि त्यांना एकत्र येण्याची शांत शक्ती, ज्या प्रकारची वाढ सोन्याने भरलेल्या लॉकरने आजपर्यंत केली नाही.</p>\n</div></div>\n<h2 id=\"the-recent-picture-gold-s-golden-run-and-crypto-s-wild-ride\">अलीकडील चित्र: सोन्याची सोनेरी धाव आणि क्रिप्टोची जंगली सवारी</h2>\n<p>गुंतवणूक हे संग्रहालय नाही, मालमत्ता वर्ग जिवंत आणि फिरत आहेत आणि गेली दोन वर्षे नाट्यमय आहेत.</p>\n<p><strong>सोने</strong> नेत्रदीपक धाव घेतली आहे. 2024 मध्ये ते अंदाजे 27% वाढले आणि 2025 पर्यंत आणखी वाढले, विक्रमानंतर विक्रमी नोंदी करत, MCX सोन्याने 1,23,000 रुपये प्रति 10 ग्रॅम पार केले आणि आंतरराष्ट्रीय स्तरावर सोन्याने इतिहासात प्रथमच $4,000 प्रति औंस पार केले. ड्रायव्हर्स: जागतिक अनिश्चितता, युद्धे आणि जगभरातील केंद्रीय बँका US डॉलरवर कमी झुकण्यासाठी सोने खरेदी करत आहेत. पोर्टफोलिओमध्ये सोन्याचे काम नेमके हेच असते, जेव्हा अस्वस्थता वाढते तेव्हा चमकणे.</p>\n<p>एक बदल लक्षात घ्या: लोकप्रिय <strong>सार्वभौम सुवर्ण रोखे (SGBs)</strong>, सोन्याच्या किमतीचा मागोवा घेणारे सरकारी रोखे <em>आणि</em> 2.5% वार्षिक व्याज दिलेले, 2025 च्या अर्थसंकल्पात बंद केले गेले, कोणतेही नवीन भाग जारी केले गेले नाहीत. ज्या गुंतवणूकदारांनी ते आधीच ठेवले आहेत ते परिपक्वतेपर्यंत व्याज मिळवत राहतात, परंतु नवीन खरेदीदारांनी आता त्याऐवजी गोल्ड ईटीएफ किंवा गोल्ड फंड वापरणे आवश्यक आहे.</p>\n<p><strong>क्रिप्टो</strong>, दरम्यानच्या काळात, शिडीवरील सर्वात जंगली पट्टा राहते. बिटकॉइन एका दिवसात 10% स्विंग करू शकतो आणि मागील चक्रांमध्ये, पुनर्प्राप्त होण्यापूर्वी त्याच्या शिखरावरून 70%+ घसरले आहे. ते कोणतेही नफा उत्पन्न करत नाही, लाभांश देत नाही आणि दीर्घकालीन ट्रॅक रेकॉर्ड नाही, म्हणून याला एक लहान, सट्टेबाज स्लाइस म्हणून हाताळा जे तुम्ही गमावू शकता, कधीही तुमच्या संपत्तीचा पाया नाही.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>एक सामान्य नवशिक्या चूक गेल्या वर्षी सर्वात जास्त गुलाब पाठलाग आहे. क्रिप्टोच्या मागील रॅलींनंतर क्रूर क्रॅश झाले होते त्याचप्रमाणे सोन्याची 2024-25 ची प्रचंड धाव पुनरावृत्तीची हमी देत ​​नाही. भूतकाळातील कामगिरी ही एक कथा आहे, वचन नाही. नवीनतम विजेत्यानंतर धावण्याऐवजी वैविध्य आणा.</p>\n</div></div>\n<h2 id=\"building-a-simple-mix\">एक साधे मिश्रण तयार करणे</h2>\n<p>तुम्हाला तुमच्या सर्व पैशांसाठी एक घर निवडण्याची गरज नाही, खरं तर, तुम्ही करू नये. मालमत्ता वर्गांमध्ये पैसे पसरवणे म्हणतात <strong>मालमत्ता वाटप</strong>, आणि तो तुमचा सीटबेल्ट आहे: जेव्हा एक ढीग करतो, तेव्हा दुसरा अनेकदा झिजतो. एक सामान्य, समजूतदार प्रारंभिक फ्रेमवर्क (एक उदाहरण, सल्ला नाही) तुमचा इक्विटी शेअर तुमच्या टाइमलाइनशी जोडतो, जोपर्यंत तुम्हाला पैशांची गरज भासेल तितकी जास्त इक्विटी तुम्ही पोटात घेऊ शकता.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch02-simple-mix.png\" alt=\"एक साधे उदाहरणात्मक मालमत्ता मिश्रण, दीर्घकालीन वाढीसाठी एक मोठा इक्विटी स्लाइस, स्थिरतेसाठी डेट कुशन आणि एक लहान सोन्याचे हेज, अनटच न केलेले आपत्कालीन निधी रोख\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">इन्फोग्राफिक</span>एक साधे उदाहरणात्मक मालमत्ता मिश्रण, दीर्घकालीन वाढीसाठी एक मोठा इक्विटी स्लाइस, स्थिरतेसाठी डेट कुशन आणि एक लहान सोन्याचे हेज, अनटच न केलेले आपत्कालीन निधी रोख</figcaption></figure>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>इक्विटीमध्ये अंदाजे \"(100 वजा तुमचे वय)%\" ठेवा, म्हणून 25 वर्षांच्या व्यक्तीकडे ~75% इक्विटी, बाकीचे कर्ज आणि थोडे सोने असू शकते. हा केवळ एक प्रारंभिक बिंदू आहे, कायदा नाही, परंतु तो योग्य अंतःप्रेरणा कॅप्चर करतो: तरुण, त्यांच्या बाजूने वेळ असल्याने, इक्विटीच्या लहरींवर स्वार होऊ शकतात.</p>\n</div></div>\n<p>अचूक टक्केवारी सवयीपेक्षा खूपच कमी महत्त्वाची आहे: आपत्कालीन निधी रोखीत ठेवा, दीर्घकालीन वाढीसाठी इक्विटीवर अवलंबून रहा, स्थिरतेसाठी काही कर्ज ठेवा आणि विमा म्हणून थोडे सोने घाला.</p>\n<h2 id=\"quick-recap\">क्विक रिकॅप</h2>\n<ul>\n<li>तुमचे पैसे राहतात <strong>मालमत्ता वर्ग</strong>, इक्विटी, कर्ज, सोने, रिअल इस्टेट, रोख आणि क्रिप्टो, प्रत्येकाचे स्वतःचे व्यक्तिमत्व.</li>\n<li>मुख्य नियम आहे <strong>जोखीम वि परतावा</strong>: उच्च संभाव्य बक्षीस नेहमी उच्च जोखमीच्या सोबत असते. मोफत जेवण नाही.</li>\n<li><strong>तरलता</strong> तुम्हाला किती लवकर कॅश बॅक मिळेल हे ठरवते, स्टॉक आणि एफडी जलद आहेत, रिअल इस्टेट मंद आहे; आपत्कालीन परिस्थिती रोखीत ठेवा.</li>\n<li><strong>इक्विटी</strong> सर्वात अल्प-मुदतीची अडचण आहे परंतु ऐतिहासिकदृष्ट्या सर्वात जास्त संपत्ती निर्माण केली आहे, कारण तुम्ही वाढत्या व्यवसायांचे मालक आहात.</li>\n<li><strong>सोने</strong> सुरक्षित आश्रयस्थान म्हणून 2024-25 मध्ये विक्रमी धाव घेतली होती (टीप: SGBs आता बंद आहेत), तर <strong>क्रिप्टो</strong> अत्यंत अस्थिर राहते आणि फ्लॅट 30% वर कर आकारला जातो.</li>\n<li><strong>मालमत्ता वाटप</strong>, वर्गांमध्ये समजूतदारपणे पैसे पसरवणे, तुमचा सीटबेल्ट आहे; सवय अचूक टक्केवारीपेक्षा जास्त महत्त्वाची आहे.</li>\n</ul>\n<p>आता तुम्हाला माहीत आहे <em>कुठे</em> पैसा वाढू शकतो, चला सर्वांत शक्तिशाली घर, शेअर बाजार पाहू या आणि सर्वांत मूलभूत प्रश्नाचे उत्तर देऊ या: काय <em>आहे</em> एक वाटा, खरोखर?</p>\n","toc":[{"level":2,"text":"तुमच्या पैशासाठी मूठभर घरे","id":"the-handful-of-homes-for-your-money"},{"level":2,"text":"एक नियम जो सर्व काही स्पष्ट करतो: जोखीम वि रिटर्न","id":"the-one-rule-that-explains-everything-risk-vs-return"},{"level":2,"text":"तरलता: तुम्ही तुमची रोख किती लवकर परत मिळवू शकता?","id":"liquidity-how-fast-can-you-get-your-cash-back"},{"level":2,"text":"करावर एक ओळीची टीप","id":"a-one-line-note-on-tax"},{"level":2,"text":"मोठी तुलना, बाजूला","id":"the-big-comparison-side-by-side"},{"level":2,"text":"इक्विटीने सर्वाधिक संपत्ती का निर्माण केली आहे","id":"why-equity-has-built-the-most-wealth"},{"level":2,"text":"अलीकडील चित्र: सोन्याची सोनेरी धाव आणि क्रिप्टोची जंगली सवारी","id":"the-recent-picture-gold-s-golden-run-and-crypto-s-wild-ride"},{"level":2,"text":"एक साधे मिश्रण तयार करणे","id":"building-a-simple-mix"},{"level":2,"text":"क्विक रिकॅप","id":"quick-recap"}],"imgCount":3,"hasContent":true},"3":{"html":"<p>जेव्हा तुम्ही रिलायन्स किंवा TCS चा शेअर खरेदी करता, तेव्हा तुम्ही स्क्रीनवर फ्लॅशिंग नंबर खरेदी करत आहात अशी कल्पना करणे सोपे आहे, एक प्रकारचे लॉटरी तिकीट ज्याची तुम्हाला आशा आहे की वाढेल. ते मानसिक चित्र जवळजवळ प्रत्येक नवशिक्याच्या चुकीचे मूळ आहे. सत्य कितीतरी जास्त आधारभूत आणि कितीतरी अधिक आश्वासक आहे: शेअर हा खरा, कायदेशीर आहे <strong>वास्तविक व्यवसायातील मालकीचा तुकडा</strong>. रिलायन्सच्या एका शेअरचे मालक आहात आणि तुम्ही रिफायनरीज, पेट्रोल पंप, जिओ नेटवर्क आणि रिलायन्स रिटेल स्टोअर्सचे अक्षरशः एक अंश-मालक आहात, एक लहान मालक आहात, परंतु वास्तविक आहात.</p>\n<p>एकदा ते क्लिक केल्यानंतर, स्टॉक मार्केट एक रहस्यमय जुगार अड्डा बनणे थांबवते आणि तुम्हाला आधीच समजलेले काहीतरी बनते: एक अशी बाजारपेठ जिथे लोक कंपन्यांची मालकी खरेदी करतात आणि विकतात. हा धडा संपूर्ण गोष्ट उलगडून दाखवतो, तुमच्या मालकीचे काय आहे, कंपन्या स्वतःचे तुकडे का विकतात आणि मार्केट कसे वायर्ड आहे जेणेकरून लाखो अनोळखी लोक दर सेकंदाला या तुकड्यांचा व्यापार करू शकतील.</p>\n<h2 id=\"a-share-is-a-slice-of-ownership\">शेअर हा मालकीचा एक तुकडा आहे</h2>\n<p>कल्पना करा की एक कंपनी एक विशाल पिझ्झा आहे. पैसे उभारण्यासाठी, संस्थापकांनी तो पिझ्झा ठराविक संख्येच्या समान स्लाइसमध्ये कापला आणि त्यातील काही लोकांना विकले. प्रत्येक स्लाइस ए <strong>शेअर</strong>, आणि स्लाइसची एकूण संख्या कंपनीची आहे <strong>समभाग थकबाकी</strong>. एक स्लाइस विकत घ्या आणि तुमचा तो अंश आहे <em>संपूर्ण</em> व्यवसाय, त्याचे कारखाने, त्याचा ब्रँड, त्याचे रोख, त्याचे भविष्यातील नफा.</p>\n<p>जर एखाद्या कंपनीने 100 कोटी शेअर्स जारी केले असतील आणि त्यातील 100 शेअर्स तुमच्या मालकीचे असतील, तर कंपनी जे काही आहे आणि कधीही कमावणार आहे, त्यातील दहा-दशलक्षांश भाग तुमच्या मालकीचा आहे. हे लहान वाटते, परंतु रिलायन्स सारख्या कंपनीसाठी, ज्याची किंमत 15 लाख कोटींपेक्षा जास्त आहे, अगदी एक स्लिव्हर देखील वास्तविक, कार्यरत एंटरप्राइझशी जोडलेले वास्तविक मूल्य दर्शवते.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch03-company-slices.png\" alt=\"एकाच कंपनीचे अनेक शेअर्समध्ये तुकडे केले जातात, प्रत्येक शेअर वेगळ्या शेअरहोल्डरकडे असतो, संस्थापक, मोठ्या संस्था आणि सामान्य किरकोळ गुंतवणूकदार सर्व एकाच व्यवसायाचे तुकडे असतात.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>एकाच कंपनीचे अनेक शेअर्समध्ये तुकडे केले जातात, प्रत्येक शेअर वेगळ्या शेअरहोल्डरकडे असतो, संस्थापक, मोठ्या संस्था आणि सामान्य किरकोळ गुंतवणूकदार सर्व एकाच व्यवसायाचे तुकडे असतात.</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>शेअर म्हणजे बेटिंग स्लिप नाही. ही कंपनीची अंशतः मालकी आहे. किंमत वर आणि खाली हलते, परंतु प्रत्येक टिकरच्या खाली कर्मचारी, उत्पादने, ग्राहक आणि नफा यांचा एक वास्तविक व्यवसाय आहे. तुम्ही नंबरवर सट्टा लावत नाही, तुम्ही एखाद्या एंटरप्राइझच्या मालकीचे आहात.</p>\n</div></div>\n<h2 id=\"what-you-actually-own\">जे तुमच्या मालकीचे आहे</h2>\n<p>भाग-मालक असल्याने, ए <strong>भागधारक</strong>, तीन ठोस गोष्टींसह येतो, फक्त वळवळणारी संख्या नाही.</p>\n<ul>\n<li><strong>नफ्यावर दावा.</strong> जेव्हा एखादी कंपनी पैसे कमवते तेव्हा ती त्या नफ्यातील काही हिस्सा मालकांना परत देऊ शकते <strong>लाभांश</strong>, प्रति शेअर रोख पैसे दिले जातात, फक्त ते मालकीसाठी. तुमच्याकडे 100 शेअर्स असल्यास, किंमत जिंकल्यास किंवा हारल्यास प्रति शेअर 8 रुपये लाभांश देणारी कंपनी तुम्हाला 800 रुपये पाठवते.</li>\n<li><strong>कंपनीच्या मूल्यावर दावा.</strong> तुमचे शेअर्स कंपनीच्या कर्जानंतर मालकीच्या प्रत्येक गोष्टीचा एक अंश दर्शवतात. जसजसा व्यवसाय अधिक मौल्यवान होतो, तसतसा तुमचा तुकडाही वाढतो.</li>\n<li><strong>मतदानाचा हक्क.</strong> भागधारक मोठ्या निर्णयांवर मत देतात, संचालक निवडतात, विलीनीकरण मंजूर करतात, मोठे वेतन पॅकेज, सहसा प्रति शेअर एक मत. काही शेअर्सचे मालक आहात आणि तुमचे मत लहान आहे, परंतु ते वास्तविक आहे आणि तुम्हाला कंपनीच्या वार्षिक सर्वसाधारण सभेत (AGM) मत देण्यासाठी सूचना प्राप्त होतील.</li>\n</ul>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>अगदी एका शेअरची मालकी तुम्हाला AGM मध्ये उपस्थित राहण्याचा अधिकार असलेले अधिकृत सह-मालक बनवते आणि त्याच खोलीत, त्याच कायदेशीर पायावर, अब्जाधीश गुंतवणूकदारांप्रमाणे व्यवस्थापनाला प्रश्न विचारतात. रिलायन्स इंडस्ट्रीजचे 35 लाखाहून अधिक वैयक्तिक भागधारक आहेत; एक वाटा असलेला शालेय विद्यार्थी, कागदावर, त्यांच्यापैकी कोणीही मालक असतो.</p>\n</div></div>\n<h2 id=\"why-companies-sell-pieces-of-themselves\">कंपन्या स्वतःचे तुकडे का विकतात</h2>\n<p>हा स्वाभाविक प्रश्न आहे: जर एखादा व्यवसाय चांगला असेल, तर त्याचे संस्थापक अनोळखी लोकांना मालकी का विकतील? उत्तर आहे <strong>वाढण्यासाठी पैसा</strong>.</p>\n<p>समजा एखाद्या कंपनीला ५०० कोटी रुपये खर्चाचा नवीन कारखाना बांधायचा आहे. हे पैसे उभे करण्याचे दोन मार्ग आहेत:</p>\n<ol>\n<li><strong>ते (कर्ज).</strong> व्यवसाय चांगला असो किंवा वाईट असो कर्ज घ्या आणि व्याजासह परत करा. देयके चुकतात आणि सावकार कंपनीला दिवाळखोरीत ओढू शकतो. कर्ज हे एक जड, निश्चित बंधन आहे.</li>\n<li><strong>मालकी (इक्विटी) विकणे.</strong> नवीन शेअर्स जारी करा आणि ते गुंतवणूकदारांना विका. कंपनीला रोख रक्कम मिळते आणि ती कधीही परत करावी लागत नाही. त्या बदल्यात, नवीन भागधारक व्यवसायाचा एक भाग घेतात आणि त्याच्या भविष्यातील नफ्यात भाग घेतात.</li>\n</ol>\n<p>इक्विटी तंतोतंत शक्तिशाली आहे कारण ती आहे <em>नाही</em> कर्ज. कोणतेही व्याज नाही, परतफेडीची अंतिम मुदत नाही, डिफॉल्टचा धोका नाही. कंपनी फक्त नवीन सह-मालकांना घेऊन जाते जे जिंकतात तेव्हा जिंकतात. त्यामुळे इन्फोसिसपासून झोमॅटोपर्यंत तुम्हाला माहीत असलेली जवळपास प्रत्येक मोठी कंपनी अखेरीस इक्विटी विकून पैसे उभारते.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>इक्विटी विक्रीची किंमत असते: <strong>सौम्य करणे</strong>. जारी केलेला प्रत्येक नवीन शेअर म्हणजे विद्यमान मालकांचा पिझ्झाचा तुकडा थोडा पातळ होतो. संस्थापकांनी हे मान्य केले कारण एखाद्या मोठ्या, वेगाने वाढणाऱ्या कंपनीच्या लहान तुकड्याचे मालक असणे हे एका लहान कंपनीच्या मोठ्या तुकड्यापेक्षा अधिक मोलाचे आहे.</p>\n</div></div>\n<h2 id=\"primary-market-vs-secondary-market\">प्राथमिक बाजार वि दुय्यम बाजार</h2>\n<p>येथेच बहुतेक नवशिक्या गोंधळून जातात, म्हणून आपण ते सोपे करूया. दोन वेगळे टप्पे आहेत आणि ते मिसळणे सोपे आहे.</p>\n<p>द <strong>प्राथमिक बाजार</strong> जेथे समभाग आहेत <em>जन्म</em>. कंपनी स्वतः अगदी नवीन शेअर्स थेट गुंतवणूकदारांना विकते आणि पैसे खिशात टाकते. उत्कृष्ट उदाहरण म्हणजे एक <strong>IPO (प्रारंभिक सार्वजनिक ऑफर)</strong>, पहिल्यांदाच एखादी कंपनी त्याचे शेअर्स लोकांना ऑफर करते. प्राइमरी मार्केटमध्ये रोकड वाहते <em>कंपनीला</em> आणि व्यवसाय वाढवण्यासाठी वापरला जातो.</p>\n<p>द <strong>दुय्यम बाजार</strong> ते विद्यमान शेअर्स कुठे आहेत <em>व्यापार केला</em> नंतर, गुंतवणूकदार ते गुंतवणूकदार. हे स्टॉक एक्स्चेंज (TheNSEआणि BSE) आहे जे तुम्ही बातम्यांवर पाहता. तुम्ही आज TCS चे 10 शेअर्स खरेदी करता तेव्हा तुम्ही आहात <em>नाही</em> TCS ला पैसे देणे; तुम्ही ते दुसऱ्या गुंतवणूकदाराकडून विकत घेत आहात ज्याला विक्री करायची आहे. TCS या व्यापारातून काहीही मिळत नाही, दोन गुंतवणूकदारांमध्ये पैसे वाहतात.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch03-primary-vs-secondary.png\" alt=\"प्राथमिक बाजार (कंपनी गुंतवणूकदारांना रोख वाढण्यासाठी नवीन समभाग जारी करते) विरुद्ध दुय्यम बाजार (गुंतवणूकदार ते विद्यमान समभाग एक्सचेंजवर आपापसात विकतात)\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">फ्लो चार्ट</span>प्राथमिक बाजार (कंपनी गुंतवणूकदारांना रोख वाढण्यासाठी नवीन समभाग जारी करते) विरुद्ध दुय्यम बाजार (गुंतवणूकदार ते विद्यमान समभाग एक्सचेंजवर आपापसात विकतात)</figcaption></figure>\n\n<div class=\"callout example\"><span class=\"callout-tag\">खरे उदाहरण</span><div><p>कारचा विचार करा. द <strong>प्राथमिक बाजार</strong> शोरूम आहे: तुम्ही एकदम नवीन कार खरेदी करता आणि पैसे निर्मात्याकडे जातात. द <strong>दुय्यम बाजार</strong> वापरलेल्या कारचे मार्केट आहे: तुम्ही तीच कार त्याच्या आधीच्या मालकाकडून नंतर खरेदी करता, निर्मात्याला पुनर्विक्रीतून काहीही मिळत नाही. कंपनीचे IPO हे शोरूम आहे; दैनंदिन स्टॉक ट्रेडिंग हे वापरलेल्या कारचे बाजार आहे.</p>\n</div></div>\n<p>दुय्यम बाजार इतका महत्त्वाचा का आहे? कारण त्याशिवाय, कोणीही प्रथम स्थानावर शेअर्स खरेदी करणार नाही. तुम्हाला पाहिजे तेव्हा तुमचा तुकडा विकण्याची क्षमता, मालकी काही सेकंदात रोखीत बदलण्याची क्षमता, यामुळेच कंपन्यांमध्ये गुंतवणूक करणे व्यावहारिक बनते. दुय्यम बाजार हे महत्त्वपूर्ण घटक प्रदान करते: <strong>तरलता</strong>.</p>\n<h2 id=\"how-you-actually-make-money\">तुम्ही प्रत्यक्षात पैसे कसे कमावता</h2>\n<p>शेअरहोल्डर म्हणून, तुमचा पैसा दोन प्रकारे वाढतो आणि शहाणा गुंतवणूकदार या दोन्ही गोष्टींची काळजी घेतो:</p>\n<ul>\n<li><strong>किमतीत वाढ (भांडवली नफा).</strong> 500 रुपयांना शेअर खरेदी करा आणि नंतर 800 रुपयांना विका आणि तुम्ही 300 रुपयांचा फरक ठेवा. जसजसा व्यवसाय वाढतो आणि अधिक कमाई करतो, खरेदीदार त्याच्या एका तुकड्यासाठी अधिक पैसे देण्यास तयार असतात आणि किंमत वाढते. येथूनच सर्वात मोठा दीर्घकालीन नफा सहसा येतो.</li>\n<li><strong>लाभांश.</strong> नफा शेअरिंग रोखीचा स्थिर प्रवाह, तुम्ही फक्त शेअर धारण करत असताना अधूनमधून पैसे दिले जातात. काही परिपक्व कंपन्या उदार लाभांश देतात; झपाट्याने वाढणारे लोक बऱ्याचदा कमी पैसे देतात आणि वेगाने वाढण्यासाठी सर्वकाही पुन्हा गुंतवतात.</li>\n</ul>\n<p>दीर्घ होल्डिंग कालावधीत, एक चांगला व्यवसाय तुम्हाला दोन्ही आघाड्यांवर बक्षीस देऊ शकतो: वाढती किंमत <em>आणि</em> वाढता लाभांश, वर्षानुवर्षे, इक्विटी संपत्तीचे दुहेरी इंजिन.</p>\n<h2 id=\"the-market-as-a-giant-auction\">एक राक्षस लिलाव म्हणून बाजार</h2>\n<p>मग कोणत्याही क्षणी किंमत काय ठरवते? समिती नाही, कंपनी नाही, फक्त <strong>पुरवठा आणि मागणी</strong>, लिलावासारखे सतत स्थिरावले. प्रत्येक क्षणी, काही लोकांना शेअर खरेदी करायचा असतो आणि इतरांना तो विकायचा असतो. किंमत ही फक्त पातळी आहे जिथे इच्छुक खरेदीदार आणि इच्छुक विक्रेता सध्या व्यवसाय करण्यास सहमत आहेत.</p>\n<p>अधिक लोकांना ते विकण्यापेक्षाTCS′ खरेदी करायचे असल्यास, खरेदीदार त्यांच्या ऑफरला धक्का देतात आणि किंमत वाढते. विक्रेत्यांची संख्या खरेदीदारांपेक्षा जास्त असल्यास, किंमत घसरते. तुम्हाला दिसणारा फ्लॅशिंग नंबर हा खरेदीदार आणि विक्रेत्यामध्ये नवीनतम सहमतीच्या किंमतीपेक्षा अधिक काही नाही, या व्यवसायाचा स्लाइस या सेकंदाची किंमत किती आहे यावर बाजाराचा निर्णय आहे.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>भारतातील सर्वात महाग स्टॉक, MRF, 1,50,000 च्या वर ट्रेड केला आहे. <em>अविवाहित</em> शेअर, अनेक दुचाकींच्या किमतीपेक्षा जास्त. कंपनीने कधीही त्याचे शेअर्स लहान, स्वस्त युनिट्समध्ये विभाजित केले नाहीत, त्यामुळे त्याच्या पिझ्झाचा एक स्लाइस प्रसिद्धपणे मोठा राहतो.</p>\n</div></div>\n<h2 id=\"quick-recap\">क्विक रिकॅप</h2>\n<ul>\n<li>ए <strong>शेअर</strong> लॉटरी तिकीट किंवा फ्लॅशिंग नंबर नसून कंपनीमधील मालकीचा खरा, कायदेशीर तुकडा आहे.</li>\n<li>शेअरहोल्डर म्हणून तुमच्याकडे व्यवसायाचा काही अंश आहे आणि अ <strong>नफ्यावर दावा (लाभांश)</strong>, त्याच्या मूल्यावर दावा, आणि <strong>मतदानाचा हक्क</strong>.</li>\n<li>कंपन्या विकतात <strong>इक्विटी</strong> पैसे उभे करण्यासाठी त्यांना कधीही परतफेड करावी लागत नाही, कर्जाप्रमाणे, कोणतेही व्याज किंवा डिफॉल्ट धोका नाही, फक्त नवीन सह-मालक.</li>\n<li>द <strong>प्राथमिक बाजार</strong> जेथे नवीन शेअर्सचा जन्म होतो (TheIPO; रोख कंपनीकडे जाते); द <strong>दुय्यम बाजार</strong> जेथे गुंतवणूकदार विद्यमान समभाग आपापसात व्यापार करतात.</li>\n<li>तुम्ही दोन प्रकारे पैसे कमावता: <strong>किंमत प्रशंसा</strong> जसजसा व्यवसाय वाढतो, आणि <strong>लाभांश</strong> तुम्ही धरून असताना पैसे दिले.</li>\n<li>किंमती सतत सारख्या हलतात <strong>लिलाव</strong>, खरेदीदार आणि विक्रेत्याने नुकतेच सहमती दर्शवली असेल अशी नवीनतम संख्या आहे.</li>\n</ul>\n<p>आता तुम्हाला समजले आहे की तुम्ही काय आणि कुठे खरेदी करत आहात. पुढे, आम्ही रेफरींना भेटतो जे या संपूर्ण मार्केटप्लेसला विश्वासार्ह बनवतात, SEBI, RBI आणि भूतकाळातील घोटाळ्यांपासून जन्मलेल्या प्रत्येक गुंतवणूकदाराचे संरक्षण करणारे नियम.</p>\n","toc":[{"level":2,"text":"शेअर हा मालकीचा एक तुकडा आहे","id":"a-share-is-a-slice-of-ownership"},{"level":2,"text":"जे तुमच्या मालकीचे आहे","id":"what-you-actually-own"},{"level":2,"text":"कंपन्या स्वतःचे तुकडे का विकतात","id":"why-companies-sell-pieces-of-themselves"},{"level":2,"text":"प्राथमिक बाजार वि दुय्यम बाजार","id":"primary-market-vs-secondary-market"},{"level":2,"text":"तुम्ही प्रत्यक्षात पैसे कसे कमावता","id":"how-you-actually-make-money"},{"level":2,"text":"एक राक्षस लिलाव म्हणून बाजार","id":"the-market-as-a-giant-auction"},{"level":2,"text":"क्विक रिकॅप","id":"quick-recap"}],"imgCount":2,"hasContent":true},"4":{"html":"<p>पंच नसलेल्या क्रिकेट सामन्याची कल्पना करा. नो बॉल म्हणायला कोणी नाही, बॅट्समनला आऊट द्यायला कोणी नाही, बॉलरला बॉलशी छेडछाड करण्यापासून कोणी रोखणार नाही. काही मिनिटांतच खेळ कोलमडून पडेल, कारण खेळाडू वाईट लोक आहेत म्हणून नाही, तर निष्पक्ष पंच नसल्यामुळे, <em>निकालावर कोणीही विश्वास ठेवू शकत नाही</em>. शेअर बाजारही अगदी तसाच आहे. हे लाखो अनोळखी लोकांमध्ये कोट्यवधी रुपये फिरवते जे कधीही भेटणार नाहीत. तुम्ही तुमचे कष्टाने कमावलेले पैसे स्क्रीनवर पाठवण्यास आणि तुमच्या खात्यात खरे शेअर्स येतात यावर विश्वास ठेवण्याचे एकमेव कारण म्हणजे कोणीतरी पाहत आहे, नियमांची अंमलबजावणी करत आहे आणि फसवणूक करणाऱ्यांना शिक्षा करत आहे.</p>\n<p>की कोणीतरी, भारतात, प्रामुख्याने आहे <strong>SEBI</strong>, सिक्युरिटीज अँड एक्स्चेंज बोर्ड ऑफ इंडिया, द्वारे समर्थित <strong>RBI</strong>. हा धडा बाजाराच्या संरक्षकांचा परिचय करून देतो: ते कोण आहेत, ते साध्या इंग्रजीत काय करतात, ते तुमच्यासारख्या सामान्य गुंतवणूकदारांचे संरक्षण कसे करतात आणि नाटकीय घोटाळा ज्याने SEBI ला त्याची वास्तविक शक्ती दिली. कारण येथे अस्वस्थ सत्य आहे, बाजार नियमन भूतकाळातील आपत्तींच्या शाईने लिहिलेले आहे.</p>\n<h2 id=\"why-markets-must-be-regulated\">बाजाराचे नियमन का केले पाहिजे</h2>\n<p>विश्वास हा प्रत्येक बाजाराचा अदृश्य पाया आहे. काही मूठभर गोष्टी खऱ्या आहेत यावर तुमचा विश्वास असेल तरच तुम्ही आनंदाने शेअर्स खरेदी कराल: कंपनीचा नफा हा खरा आहे आणि बनावट नाही, किमतीची किंमत मॅनिपुलेटरपेक्षा प्रामाणिक पुरवठा आणि मागणीने सेट केली आहे, तुमचा ब्रोकर तुमचे पैसे घेऊन पळून जाणार नाही आणि तुम्ही दिलेले शेअर्स तुमच्या खात्यात प्रत्यक्षात दिसतील.</p>\n<p>त्यापैकी एक काढून टाका आणि संपूर्ण यंत्रणा गोठली जाईल. कोणीही अशा गेममध्ये गुंतवणूक करत नाही ज्यामध्ये त्यांना हेराफेरी झाल्याचा संशय आहे. त्यामुळे नियमन म्हणजे बाजाराच्या मार्गात येणारी लाल फिती नाही, नियमन <em>बाजार सर्व शक्य करते काय आहे</em>. हे संशयाच्या गुहेचे अशा ठिकाणी रूपांतरित करते जिथे एका छोट्या शहरातील 22 वर्षांचा तरुण भारतातील सर्वात मोठ्या कंपन्यांचा एक भाग आत्मविश्वासाने घेऊ शकतो.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>नियमन सर्व वरील एका कारणासाठी अस्तित्वात आहे: <strong>विश्वास</strong>. वाजवी नियम, प्रामाणिक किंमती आणि संरक्षित गुंतवणूकदार हे काही चांगले अतिरिक्त नाहीत, ते बाजाराचा श्वास घेणारा ऑक्सिजन आहेत. त्यांच्याशिवाय, कोणतीही तर्कशुद्ध व्यक्ती कधीही गुंतवणूक करणार नाही आणि बोलण्यासाठी कोणतीही बाजारपेठ नसेल.</p>\n</div></div>\n<h2 id=\"meet-sebi-the-market-s-chief-referee\">SEBI, मार्केटचे मुख्य रेफरी यांना भेटा</h2>\n<p><strong>SEBI</strong> भारताच्या सिक्युरिटीज मार्केट, स्टॉक्स, बाँड्स, म्युच्युअल फंड, डेरिव्हेटिव्ह, लॉटचे मुख्य नियामक आहे. पंच, नियम-निर्माता आणि बाजारपेठेतील पोलिस दल एक झाले म्हणून विचार करा. त्याचे काम, साध्या भाषेत, बाजार राखणे आहे <strong>निष्पक्ष, पारदर्शक आणि सुरक्षित</strong> सामान्य गुंतवणूकदारांसाठी. हे तीन व्यापक भूमिकांद्वारे करते:</p>\n<ul>\n<li><strong>गुंतवणूकदारांचे संरक्षण.</strong> SEBI ची सांगितलेली पहिली प्राथमिकता ही लहान गुंतवणूकदार आहे, तुमच्याशी न्याय्यपणे वागले जाईल याची खात्री करून घ्या आणि अधिक माहिती किंवा सामर्थ्य असलेल्यांकडून तुमची छेडछाड होणार नाही.</li>\n<li><strong>खेळाडूंचे नियमन.</strong> स्टॉक एक्स्चेंज, ब्रोकर, म्युच्युअल फंड, रेटिंग एजन्सी, गुंतवणूक सल्लागार, सर्वांनी SEBI सह नोंदणी करणे आणि त्याचे नियम पाळणे आवश्यक आहे. त्यांना तोडून टाका आणि SEBI तुम्हाला दंड करू शकतो, तुमच्यावर बंदी घालू शकतो किंवा केस कोर्टाकडे सोपवू शकतो.</li>\n<li><strong>बाजारपेठ विकसित करणे.</strong> SEBI देखील बाजाराचे आधुनिकीकरण करते, जलद सेटलमेंट, इलेक्ट्रॉनिक शेअरहोल्डिंग आणि कडक प्रकटीकरण यांसारख्या सुधारणांना पुढे नेत आहे, त्यामुळे भारताची बाजारपेठ जागतिक दर्जाची राहते.</li>\n</ul>\n<p>SEBI च्या शक्तीचा एक मोठा भाग हा नियम आहे <strong>प्रकटीकरण</strong>: कंपन्या <em>आवश्यक</em> त्यांचे आर्थिक परिणाम, प्रमुख निर्णय आणि जोखीम सार्वजनिकपणे प्रकट करा, जेणेकरून प्रत्येक गुंतवणूकदार समान तथ्ये वापरून निर्णय घेतील. आतल्यांसाठी कोणतीही गुप्त माहिती नाही, कोणतीही वाईट बातमी लपवत नाही. सूर्यप्रकाश, SEBI विश्वास, सर्वोत्तम जंतुनाशक आहे.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch04-regulatory-structure.png\" alt=\"नियामक पदानुक्रम, SEBI आणि RBI शीर्षस्थानी, एक्स्चेंज, ब्रोकर्स, डिपॉझिटरीज आणि सूचीबद्ध कंपन्यांवर देखरेख करणे, हे सर्व मूलभूत गुंतवणूकदाराच्या संरक्षणासाठी सेवेत आहे.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>नियामक पदानुक्रम, SEBI आणि RBI शीर्षस्थानी, एक्स्चेंज, ब्रोकर्स, डिपॉझिटरीज आणि सूचीबद्ध कंपन्यांची देखरेख करणे, हे सर्व मूलभूत गुंतवणूकदाराच्या संरक्षणासाठी सेवेत आहे.</figcaption></figure>\n<h2 id=\"the-rbi-guardian-of-money-and-banks\">RBI: पैसे आणि बँकांचे संरक्षक</h2>\n<p>जर SEBI रक्षण करते <em>बाजार</em>, द <strong>भारतीय रिझर्व्ह बँक (RBI)</strong> रक्षण करते <em>पैसे</em> आणि <em>बँका</em> त्यांच्या मागे.RBI′ ही भारताची मध्यवर्ती बँक आहे, आणि ती तुमच्या शेअर्सच्या व्यवहारांवर नियंत्रण ठेवत नसली तरी, तिचे निर्णय प्रत्येक बाजारात उमटतात.</p>\n<p>RBI चे मुख्य कार्य म्हणजे रुपया जारी करणे, व्याजदर सेट करून महागाई नियंत्रित करणे, बँकांचे नियमन करणे (तुमचे खाते असलेल्या व्यक्तीसह), आणि देशाचे परकीय चलन व्यवस्थापित करणे. जेव्हा RBI वाढवते किंवा कापते <strong>रेपो दर</strong>, हे संपूर्ण अर्थव्यवस्थेमध्ये कर्ज घेण्याच्या खर्चात बदल करते, जे FD दर, कर्ज EMIs आणि, अप्रत्यक्षपणे, स्टॉकच्या किमती बदलते.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>विभाजन लक्षात ठेवण्याचा एक सोपा मार्ग: <strong>SEBI शेअर मार्केट पाहतो; RBI बँकिंग आणि मनी सिस्टीम पाहतो.</strong> ते काठावर ओव्हरलॅप होतात, उदाहरणार्थ, मार्केट इन्फ्रास्ट्रक्चरमध्ये दोघांचे म्हणणे आहे, परंतु त्यांचे मुख्य ठोके भिन्न आहेत. SEBI तुमचे संरक्षण करते <em>गुंतवणूक</em>; RBI तुमचे संरक्षण करते <em>रुपया</em> आणि ज्या बँका ते ठेवतात.</p>\n</div></div>\n<h2 id=\"how-investors-are-protected\">गुंतवणूकदारांचे संरक्षण कसे केले जाते</h2>\n<p>SEBI चे गुंतवणूकदार-संरक्षण टूलकिट खरोखर उपयुक्त आहे आणि एक नवशिक्या म्हणून तुम्हाला हे माहित असले पाहिजे की तुमच्या आणि शार्कमध्ये काय आहे:</p>\n<ul>\n<li><strong>न्याय्य नियम</strong> जे इनसाइडर ट्रेडिंग, किंमतीमध्ये फेरफार आणि दिशाभूल करणाऱ्या जाहिरातींवर बंदी घालतात.</li>\n<li><strong>अनिवार्य प्रकटीकरण</strong>त्यामुळे कंपन्या त्यांची खरी आर्थिक स्थिती लपवू शकत नाहीत.</li>\n<li><strong>तुमच्या मालमत्तेचे पृथक्करण</strong>, तुमचे शेअर्स डिपॉझिटरीमध्ये तुमच्या स्वत:च्या डीमॅट खात्यात ठेवलेले असतात, जेथे दलाल त्यांचा दुरुपयोग करू शकतील असे नाही.</li>\n<li><strong>फसवणूक विरुद्ध कारवाई</strong>, तपास, भारी दंड, बाजारातून बंदी आणि खटला चालवण्यासाठी संदर्भ.</li>\n<li><strong>तक्रार प्रणाली</strong>, अधिकारी <strong>SCORES</strong> प्लॅटफॉर्म, जिथे कोणताही गुंतवणूकदार औपचारिकपणे तक्रार मांडू शकतो आणि त्याचा मागोवा घेऊ शकतो.</li>\n</ul>\n<h3 id=\"scores-your-formal-complaint-channel\">SCORES: तुमची औपचारिक तक्रार चॅनेल</h3>\n<p>जर एखादा ब्रोकर, कंपनी किंवा म्युच्युअल फंड तुमची चूक करत असेल आणि त्याचे निराकरण करत नसेल, तर तुम्हाला भीक मागण्याची किंवा हार मानण्याची गरज नाही. <strong>SCORES</strong> (SEBI तक्रार निवारण प्रणाली) हे एक विनामूल्य ऑनलाइन पोर्टल आहे जेथे तुम्ही तक्रार नोंदवता, जे SEBI नंतर प्रतिसाद देण्यासाठी मुदतीसह आक्षेपार्ह घटकाकडे जाते आणि तुम्ही संपूर्ण स्थितीचा मागोवा घेऊ शकता.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch04-scores-flow.png\" alt=\"गुंतवणुकदाराची तक्रार SCORES द्वारे कशी प्रवास करते, ऑनलाइन नोंदवलेली, SEBI द्वारे अंतिम मुदतीसह घटकाकडे अग्रेषित केली जाते, निराकरण केले जाते किंवा वाढवले ​​जाते, गुंतवणूकदार प्रत्येक चरणाचा मागोवा घेत असतो\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">फ्लो चार्ट</span>गुंतवणुकदाराची तक्रार SCORES द्वारे कशी प्रवास करते, ऑनलाइन नोंदवलेली, SEBI द्वारे अंतिम मुदतीसह घटकाकडे अग्रेषित केली जाते, निराकरण केले जाते किंवा वाढवले ​​जाते, गुंतवणूकदार प्रत्येक चरणाचा मागोवा घेत असतो</figcaption></figure>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>तुम्ही कधीही एक रुपयाची गुंतवणूक करण्यापूर्वी, तुम्ही कोणाशी व्यवहार करत आहात, ब्रोकर, सल्लागार, म्युच्युअल फंड, हे तपासा. <strong>SEBI सह नोंदणीकृत</strong> (आपण SEBI च्या वेबसाइटवर याची पडताळणी करू शकता). SEBI नोंदणी क्रमांक ही नफ्याची हमी नाही, परंतु नोंदणीकृत, जबाबदार संस्थांशी व्यवहार करणे ही फसवणुकीपासून बचावाची तुमची पहिली आणि स्वस्त ओळ आहे.</p>\n</div></div>\n<h2 id=\"written-in-the-ink-of-scandal-the-harshad-mehta-story\">घोटाळ्याच्या शाईत लिहिलेली: हर्षद मेहताची कथा</h2>\n<p>बहुतेक लोकांना माहित नसलेला भाग येथे आहे: SEBI 1988 पासून कागदावर अस्तित्त्वात आहे परंतु जवळजवळ कोणतीही वास्तविक शक्ती नव्हती, ती एक दात नसलेली सल्लागार संस्था होती. त्याला दात काय दिले ते एक आपत्ती होते.</p>\n<p>1992 मध्ये, स्टॉक ब्रोकर <strong>हर्षद मेहता</strong>, \"बिग बुल\" असे टोपणनाव असलेले, अंदाजे गळफास घेतल्याचे आढळले <strong>4,000 कोटी रुपये</strong> बनावट पावत्या वापरून बँकिंग प्रणालीतून बाहेर काढले, आणि ते मूठभर स्टॉक्समध्ये भरले आणि त्यांच्या किमती चकचकीत उंचीवर नेल्या. जेव्हा घोटाळा उघडकीस आला तेव्हा बाजार कोसळला, सामान्य गुंतवणूकदार नष्ट झाले आणि जनतेचा विश्वास उडाला. देशाला कळून चुकले की, आपला कोणीही खरा पोलीस नाही.</p>\n<p>प्रतिसाद होता <strong>SEBI 1992 चा कायदा</strong>, ज्याने तपास, दंड आणि बंदी घालण्याचे अधिकार असलेल्या वैधानिक नियामकामध्ये शक्तीहीन समितीपासून SEBI चे रूपांतर केले. आज तुम्हाला लाभलेले जवळपास प्रत्येक मोठे संरक्षण, डीमटेरियल केलेले शेअर्स, जलद सेटलमेंट, कडक खुलासा, प्रत्यक्ष किंवा अप्रत्यक्षपणे, त्या घोटाळ्याचे धडे.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>जवळजवळ प्रत्येक प्रमुख भारतीय बाजार सुधारणा आपत्तीतून जन्माला आली. 1992 च्या हर्षद मेहता घोटाळ्याने SEBI ला त्याचे वैधानिक दात दिले; 2001 च्या केतन पारेख घोटाळ्याने समझोता घट्ट केला आणि धोकादायक \"बदला\" प्रणालीवर बंदी घातली; 2009 च्या सत्यम फसवणुकीने कॉर्पोरेट-गव्हर्नन्स नियमांची फेरबदल केली. आज तुमचे संरक्षण करणारे नियमपुस्तक हे कालच्या घोटाळ्यांच्या शाईने लिहिलेले आहे.</p>\n</div></div>\n<h2 id=\"the-modern-frontier-finfluencers-and-f-o\">आधुनिक सीमा: फिनफ्लुएंसर्स आणि F&amp;O</h2>\n<p>पालक अजूनही खूप कामावर आहेत, आणि युद्धभूमी तुमच्या फोनवर हलवली आहे. दोन अलीकडील क्रॅकडाऊन SEBI नवीन धोक्यांशी जुळवून घेत असल्याचे दर्शविते.</p>\n<p>प्रथम, <strong>finfluencers</strong>. सोशल मीडिया स्वयं-शैलीतील \"तज्ञ\" पुशिंग स्टॉक टिप्स, कोर्स आणि \"गॅरंटीड\" धोरणांनी भरलेला असल्याने, SEBI पुढे सरकले. 2025 च्या सुरुवातीपासून नोंदणीकृत संस्था (दलाल, म्युच्युअल फंड, सल्लागार) यांच्याशी संबंध ठेवण्यापासून प्रतिबंधित केले. <em>नोंदणी न केलेले</em> finfluencers, आणि प्रतिबंधित शिक्षकांना अलीकडील थेट बाजार डेटा वापरून टिपा \"शिक्षण\" म्हणून वेष. संदेश स्पष्ट आहे: SEBI नोंदणीशिवाय विशिष्ट स्टॉक सल्ला देणे बेकायदेशीर आहे, तुमचे अनेक अनुयायी असले तरीही.</p>\n<p>दुसरे, द <strong>फ्युचर्स अँड ऑप्शन्स (F&amp;O) क्लॅम्पडाउन</strong>. SEBI च्या स्वतःच्या संशोधनाने एक गंभीर निर्णय दिला: अंदाजे <strong>91% वैयक्तिक F&amp;O व्यापाऱ्यांनी पैसे गमावले</strong> FY25 मध्ये, एका वर्षात सुमारे 1.05 लाख कोटी रुपयांच्या निव्वळ तोट्यासह. प्रत्युत्तरादाखल, SEBI नियम कडक केले, कमी साप्ताहिक मुदती, मोठे किमान करार आकार आणि कडक देखरेख, विशेषत: लहान गुंतवणूकदारांना अशा खेळात आकर्षित होण्यापासून रोखण्यासाठी जेथे बहुसंख्य लोक गमावतात.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>ऑनलाइन आश्वासने देणाऱ्या \"शूर-शॉट\" टिपा, खात्रीशीर परतावा किंवा लवकर श्रीमंत-श्रीमंत व्हा, विशेषत: खाजगी व्हॉट्सॲप किंवा टेलिग्राम गटांमध्ये, सावध रहा. SEBI चा डेटा क्रूरपणे स्पष्ट आहे: बहुसंख्य जलद-व्यापार किरकोळ सहभागी <em>गमावणे</em> पैसे नियामक फसवणुकीला शिक्षा देऊ शकतो, परंतु केवळ <em>आपण</em> प्रथम ठिकाणी सापळा टाळू शकता. संशयवाद हे तुमचे सर्वात मजबूत संरक्षण आहे.</p>\n</div></div>\n<h2 id=\"quick-recap\">क्विक रिकॅप</h2>\n<ul>\n<li>बाजार चालतात <strong>विश्वास</strong>, आणि नियमन ते तयार करते, वाजवी नियम आणि प्रामाणिक किमतींशिवाय कोणीही गुंतवणूक करणार नाही.</li>\n<li><strong>SEBI</strong> ते भारताच्या सिक्युरिटीज मार्केटचे मुख्य पंच आहेत, गुंतवणूकदारांचे संरक्षण करतात, ब्रोकर्स आणि एक्सचेंजेसचे नियमन करतात आणि कडक अंमलबजावणी करतात. <strong>प्रकटीकरण</strong>.</li>\n<li>द <strong>RBI</strong> पैसे आणि बँकांचे रक्षण करते, व्याजदर सेट करतात जे प्रत्येक बाजारपेठेत उमटतात; SEBI शेअर्स पाहतो, RBI रुपयाला पाहतो.</li>\n<li>गुंतवणूकदारांना वाजवी नियम, अनिवार्य प्रकटीकरण, विभक्त डीमॅट होल्डिंग, फसवणूक विरोधी कारवाई आणि <strong>SCORES</strong> तक्रार मंच.</li>\n<li>SEBI हे खरे झाले <strong>1992 च्या SEBI कायद्याचे वैधानिक अधिकार</strong>, हर्षद मेहता घोटाळ्यानंतर पास झालेल्या, सुधारणा भूतकाळातील घोटाळ्यांच्या शाईने लिहिलेल्या आहेत.</li>\n<li>आज SEBI नोंदणी नसलेल्यांवर कारवाई करत आहे <strong>finfluencers</strong> आणि घट्ट करणे <strong>F&amp;O</strong> ~91% वैयक्तिक डेरिव्हेटिव्ह ट्रेडर्स पैसे गमावतात असे आढळल्यानंतर नियम.</li>\n</ul>\n<p>मार्केटला कोण प्रामाणिक ठेवतो हे आता तुम्हाला माहीत आहे. पुढे, आम्ही स्वतः मशिनरी, एक्सचेंजेस, ब्रोकर्स आणि डिपॉझिटरीजचा दौरा करतो जे तुमचे क्लिक घेतात आणि ते वास्तविक, सुरक्षितपणे मालकीमध्ये बदलतात.</p>\n","toc":[{"level":2,"text":"बाजाराचे नियमन का केले पाहिजे","id":"why-markets-must-be-regulated"},{"level":2,"text":"SEBI, मार्केटचे मुख्य रेफरी यांना भेटा","id":"meet-sebi-the-market-s-chief-referee"},{"level":2,"text":"RBI: पैसे आणि बँकांचे संरक्षक","id":"the-rbi-guardian-of-money-and-banks"},{"level":2,"text":"गुंतवणूकदारांचे संरक्षण कसे केले जाते","id":"how-investors-are-protected"},{"level":3,"text":"SCORES: तुमची औपचारिक तक्रार चॅनेल","id":"scores-your-formal-complaint-channel"},{"level":2,"text":"घोटाळ्याच्या शाईत लिहिलेली: हर्षद मेहताची कथा","id":"written-in-the-ink-of-scandal-the-harshad-mehta-story"},{"level":2,"text":"आधुनिक सीमा: फिनफ्लुएंसर्स आणि F&O","id":"the-modern-frontier-finfluencers-and-f-o"},{"level":2,"text":"क्विक रिकॅप","id":"quick-recap"}],"imgCount":2,"hasContent":true},"5":{"html":"<p>जेव्हा तुम्ही रिलायन्सच्या 10 शेअर्सवर \"खरेदी करा\" वर टॅप करता आणि ऑर्डर एका सेकंदाच्या आत भरते, तेव्हा जादू, एक टॅप, पूर्ण झाल्यासारखे वाटते. पण तो एकच टॅप शांतपणे चार वेगवेगळ्या संस्थांमधली रिले शर्यत सुरू करतो, प्रत्येकाकडे एक काम असते, प्रत्येकाने पुढच्या हातात दंडुका सोपवला होता. त्यापैकी कोणीही तुम्ही नाही, त्यापैकी कोणतीही तुम्ही नुकतीच खरेदी केलेली कंपनी नाही, आणि तरीही चारही एकत्र काम केल्याशिवाय तुमचा व्यापार होऊ शकत नाही आणि तुमचे शेअर्स सुरक्षितपणे ठेवता येणार नाहीत.</p>\n<p>हा धडा त्या पात्रांची ओळख करून देतो: द <strong>देवाणघेवाण</strong> जेथे खरेदीदार आणि विक्रेते भेटतात, द <strong>दलाल</strong> तेथे तुमची ऑर्डर कोण घेऊन जाते, द <strong>डिपॉझिटरी</strong> जे तुमचे शेअर्स इलेक्ट्रॉनिक पद्धतीने ठेवतात आणि <strong>क्लिअरिंग कॉर्पोरेशन</strong> कोणाचीही फसवणूक होणार नाही याची हमी देते. या चार गोष्टी समजून घ्या आणि स्टॉक मार्केट ब्लॅक बॉक्ससारखे वाटणे थांबवते आणि एक विलक्षण सुव्यवस्थित असेंब्ली लाइनसारखे दिसू लागते.</p>\n<h2 id=\"the-exchange-a-giant-organised-marketplace\">एक्सचेंज: एक विशाल संघटित बाजारपेठ</h2>\n<p>एक स्टॉक <strong>देवाणघेवाण</strong> फक्त एक बाजारपेठ आहे, परंतु भाज्या किंवा सोन्याऐवजी, खरेदी आणि विक्री केली जाणारी वस्तू कंपन्यांमध्ये मालकी आहे. ही अशी जागा आहे जिथे रिलायन्सचे 10 शेअर्स विकू इच्छिणाऱ्या एखाद्याला ते विकत घेऊ इच्छिणाऱ्या व्यक्तीशी जुळतात, ज्या किंमतीवर दोघेही सहमत असतात. एक्सचेंज शेअर्सचे मालक नाही किंवा किंमत सेट करत नाही; ते लिलाव चालवते, ऑर्डर जुळवते आणि प्रत्येक ट्रेड प्रकाशित करते जेणेकरून संपूर्ण बाजार समान वाजवी किंमत पाहतो.</p>\n<p>भारतामध्ये दोन मुख्य स्टॉक एक्स्चेंज आहेत आणि त्यांच्याकडे अधिक भिन्न बॅकस्टोरी असू शकत नाहीत.</p>\n<ul>\n<li>द <strong>बॉम्बे स्टॉक एक्सचेंज (BSE)</strong>, मध्ये स्थापना केली <strong>1875</strong>, आहे <strong>आशियातील सर्वात जुने स्टॉक एक्सचेंज</strong>. त्याची सुरुवात एका वटवृक्षाखाली झाली जिथे मूठभर स्टॉक ब्रोकर्स व्यापार करण्यासाठी भेटले आणि आज हजारो कंपन्यांची यादी आहे, भारतातील इतर कोणत्याही एक्सचेंजपेक्षा जास्त.</li>\n<li>द <strong>नॅशनल स्टॉक एक्सचेंज (NSE)</strong>मध्ये लाँच केले <strong>1994</strong>, नवीन, पूर्णपणे इलेक्ट्रॉनिक एक्सचेंज आहे. तो आहे <strong>ट्रेडिंग व्हॉल्यूमनुसार दोघांपैकी मोठा</strong>, भारतातील बहुतांश रोख-बाजार आणि डेरिव्हेटिव्ह उलाढाल येथे होते.</li>\n</ul>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch05-trade-relay.png\" alt=\"एका टॅपमागे रिले रेस, तुमची ऑर्डर तुमच्याकडून तुमच्या ब्रोकरपर्यंत, एक्सचेंजवर, क्लिअरिंग कॉर्पोरेशनच्या माध्यमातून जाते आणि शेवटी तुमचे शेअर्स डिपॉझिटरीमध्ये सेटल होतात.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">फ्लो चार्ट</span>एका टॅपमागे रिले रेस, तुमची ऑर्डर तुमच्याकडून तुमच्या ब्रोकरपर्यंत, एक्सचेंजवर, क्लिअरिंग कॉर्पोरेशनच्या माध्यमातून जाते आणि शेवटी तुमचे शेअर्स डिपॉझिटरीमध्ये सेटल होतात.</figcaption></figure>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>BSE ची सुरुवात 1875 मध्ये मुंबईतील दलाल स्ट्रीटवर एका वटवृक्षाखाली झाली, जिथे दलाल अक्षरशः व्यापारासाठी उघड्यावर जमले होते. \"दलाल स्ट्रीट\" तेव्हापासून संपूर्ण भारतीय शेअर बाजारासाठी शॉर्टहँड बनला आहे, ज्या प्रकारे \"वॉल स्ट्रीट\" अमेरिकेसाठी उभा आहे.</p>\n</div></div>\n<h2 id=\"when-the-market-is-open\">जेव्हा बाजार खुला असतो</h2>\n<p>तुम्हाला आवडेल त्या वेळी तुम्ही शेअर खरेदी किंवा विकू शकत नाही. एक्सचेंज असतानाच व्यापार होतो <strong>उघडा</strong>, आणि भारताचे इक्विटी मार्केट नियमित कार्यालयीन तास ठेवते (IST):</p>\n<ul>\n<li><strong>सामान्य व्यापार: 9:15 AM ते 3:30 PM</strong>, सोमवार ते शुक्रवार. जेव्हा जवळजवळ सर्व खरेदी आणि विक्री होते तेव्हा असे होते.</li>\n<li><strong>प्री-ओपन: 9:00 ते 9:15 AM</strong>, एक छोटी खिडकी जिथे ऑर्डर गोळा केल्या जातात आणि जत्रा <em>उघडण्याची किंमत</em> लिलावाद्वारे शोधला जातो, म्हणून दिवसाची सुरुवात गोंधळलेल्या उडीने होत नाही.</li>\n<li><strong>पोस्ट-क्लोज: 3:40 ते 4:00 PM</strong>, दिवसाच्या बंद किंमतीवर ऑर्डर देण्यासाठी एक संक्षिप्त विंडो.</li>\n<li>बाजार आहे <strong>आठवड्याच्या शेवटी बंद आणि सुट्ट्यांची देवाणघेवाण</strong>, जरी तुम्हाला अधूनमधून एक विशेष एक तास ऐकू येईल <em>मुहूर्त</em> दिवाळीच्या संध्याकाळी सत्र.</li>\n</ul>\n<p>त्यामुळे तुम्ही 9 PM किंवा रविवारी खरेदी करा वर टॅप केल्यास, तुमची ऑर्डर फक्त कार्यान्वित होणार नाही <em>प्रतीक्षा करते</em>. बऱ्याच ॲप्स तुम्हाला एक ठेवू देतात <strong>बाजारानंतरची ऑर्डर (AMO)</strong> जे रांगेत उभं राहतं आणि लगेच पाठवलं जातं, पुढचा बाजार उघडतो. शेवटी तुम्हाला जी किंमत मिळते ती असते तेव्हा मार्केट जे काही करत असते, ते तुम्ही ठेवल्यावर नाही.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>बाजार बंद असताना शेअरची थेट किंमत नसते. तुम्ही रात्री पाहत असलेली \"अंतिम खरेदी-विक्रीची किंमत\" ही शेवटच्या खुल्या सत्रातील अंतिम किंमत आहे, पुढील ट्रेडिंग दिवस 9:15 AM पर्यंत गोठवली आहे. वास्तविक खरेदी आणि विक्री केवळ बाजाराच्या वेळेतच होऊ शकते.</p>\n</div></div>\n<h2 id=\"who-is-trading-the-market-participants\">कोण ट्रेडिंग करत आहे: बाजारातील सहभागी</h2>\n<p>जेव्हा तुम्ही शेअर खरेदी करता तेव्हा दुसऱ्या बाजूला कोणीतरी तो विकत असतो, पण कोण <em>आहेत</em> हे सर्व खरेदीदार आणि विक्रेते? इक्विटी मार्केट हे अगदी वेगवेगळ्या खेळाडूंची गर्दी असते, प्रत्येकाची उद्दिष्टे, आकार आणि वेळ वेगवेगळी असते.</p>\n<table>\n<thead>\n<tr>\n<th>सहभागी</th>\n<th>ते कोण आहेत</th>\n<th>ते बाजारात काय करतात</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>किरकोळ गुंतवणूकदार</strong></td>\n<td>तुमच्यासारख्या व्यक्ती, फोन किंवा लॅपटॉपवरून व्यापार करत आहेत</td>\n<td>खरेदी आणि विक्री अल्प प्रमाणात, प्रति व्यापार लहान, परंतु एकूण संख्येत प्रचंड</td>\n</tr>\n<tr>\n<td><strong>HNIs / अल्ट्रा-HNIs</strong></td>\n<td>मोठ्या रकमेची गुंतवणूक करणाऱ्या उच्च-निव्वळ-वर्थ व्यक्ती</td>\n<td>बिग-तिकीट व्यवहार, अनेकदा PMS किंवा AIFs द्वारे; लहान स्टॉक स्वतःहून हलवू शकतात</td>\n</tr>\n<tr>\n<td><strong>म्युच्युअल फंड</strong></td>\n<td>अनेक लोकांच्या पैशाचे पूल व्यावसायिक व्यवस्थापकांद्वारे चालवले जातात</td>\n<td>तुमची SIP आणि एकरकमी समभागांमध्ये गुंतवा, एक प्रचंड, स्थिर देशांतर्गत शक्ती</td>\n</tr>\n<tr>\n<td><strong>डीआयआय</strong> (घरगुती संस्था)</td>\n<td>भारतीय म्युच्युअल फंड, विमा कंपन्या (जसे की LIC), बँका, पेन्शन फंड</td>\n<td>घरगुती बचत तैनात करा; अलिकडच्या वर्षांत त्यांच्याकडे आहे <em>उशी</em> जेव्हा परदेशी विकतात तेव्हा बाजार</td>\n</tr>\n<tr>\n<td><strong>FIIs / FPIs</strong> (परदेशी गुंतवणूकदार)</td>\n<td>भारतात गुंतवणूक करणारे मोठे विदेशी फंड</td>\n<td>प्रचंड रक्कम आत आणि बाहेर हलवा; त्यांचा \"रिस्क-ऑन / रिस्क-ऑफ\" मूड निर्देशांकांना झपाट्याने बदलू शकतो</td>\n</tr>\n<tr>\n<td><strong>प्रोप्रायटरी (प्रॉप) डेस्क</strong></td>\n<td>ब्रोकरेज आणि ट्रेडिंग फर्म त्यांचे व्यापार करतात <em>स्वतःचे</em> भांडवल</td>\n<td>जलद, उच्च-व्हॉल्यूम ट्रेडिंग आणि आर्बिट्रेज जे तरलता जोडते, त्यामुळे तुमची ऑर्डर मिलिसेकंदांमध्ये जुळते</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch05-market-participants.png\" alt=\"इक्विटी मार्केटमधील प्रमुख खेळाडू, किरकोळ गुंतवणूकदार, एचएनआय, म्युच्युअल फंड, देशांतर्गत संस्था (DII), विदेशी गुंतवणूकदार (FII) आणि मालकी डेस्क, प्रत्येकाच्या भूमिकेसह एक्सचेंजच्या आसपास व्यवस्था केली जाते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>इक्विटी मार्केटमधील प्रमुख खेळाडू, किरकोळ गुंतवणूकदार, एचएनआय, म्युच्युअल फंड, देशांतर्गत संस्था (DII), विदेशी गुंतवणूकदार (FII) आणि मालकी डेस्क, प्रत्येकाच्या भूमिकेसह एक्सचेंजच्या आसपास व्यवस्था केली जाते.</figcaption></figure>\n<p>काही नमुने लक्षात ठेवण्यासारखे आहेत. <strong>FII आणि DII हे हेवीवेट आहेत</strong>, जेव्हा या संस्था अब्जावधींची हालचाल करतात, तेव्हा संपूर्ण निर्देशांकाला ते जाणवते (मॅक्रो धड्यातील टग-ऑफ-वॉर रिटर्न) <strong>किरकोळ विक्री संख्येने बलाढ्य आहे</strong> परंतु प्रति व्यापार लहान. आणि <strong>प्रॉप आणि उच्च-वारंवारता डेस्क</strong> हे शांत प्लंबिंग आहेत जे किमती घट्ट ठेवतात आणि व्यापार त्वरित भरतात. प्रत्येक वेळी तुम्ही खरेदी करता, तुम्ही कदाचित यापैकी एका खेळाडूविरुद्ध व्यापार करत असाल, सहसा कोणता हे न कळता.</p>\n<h2 id=\"the-broker-your-gateway-to-the-exchange\">ब्रोकर: तुमचे एक्सचेंजचे प्रवेशद्वार</h2>\n<p>येथे एक कॅच आहे: तुम्ही NSE किंवा BSE पर्यंत चालत जाऊ शकत नाही आणि स्वतः ऑर्डर देऊ शकत नाही. फक्त नोंदणीकृत सदस्य, <strong>दलाल</strong>, एक्सचेंजला ऑर्डर पाठविण्याची परवानगी आहे. त्यामुळे ब्रोकर हा तुमचा प्रवेशद्वार आहे. तुम्ही ॲपमध्ये खरेदी करा वर टॅप करता तेव्हा, ती ऑर्डर तुमच्या ब्रोकरकडे जाते, जो मिलिसेकंदमध्ये एक्स्चेंजकडे राउट करतो. ब्रोकर हा तुमचा परवानाधारक मध्यस्थ आहे आणि त्या सेवेसाठी ते नावाचे शुल्क आकारतात <strong>दलाली</strong>.</p>\n<p>ब्रोकर्स दोन व्यापक स्वादांमध्ये येतात:</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>सवलत दलाल</th>\n<th>पूर्ण-सेवा दलाल</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ते काय देतात</td>\n<td>व्यवहार करण्यासाठी एक नो-फ्रिल ॲप</td>\n<td>ट्रेड प्लस संशोधन, टिपा, संबंध व्यवस्थापक, सल्ला</td>\n</tr>\n<tr>\n<td>दलाली</td>\n<td>सपाट, कमी (अनेकदा प्रति ऑर्डर एक लहान निश्चित शुल्क, किंवा वितरणावर शून्य)</td>\n<td>सहसा प्रत्येक व्यापाराच्या मूल्याची टक्केवारी</td>\n</tr>\n<tr>\n<td>साठी सर्वोत्तम</td>\n<td>स्व-निर्देशित गुंतवणूकदार जे स्वत: निर्णय घेतात</td>\n<td>ज्या लोकांना हात धरून सल्ला हवा आहे</td>\n</tr>\n</tbody></table>\n<p>कमी खर्चाची वाढ <strong>सवलत दलाल</strong>, टक्केवारी ऐवजी अंदाजे 20 रुपये प्रति निष्पादित ऑर्डर सारखे फ्लॅट शुल्क आकारणे, हे एक मोठे कारण आहे की संपूर्ण तरुण भारतीयांनी गुंतवणूक करण्यास सुरुवात केली. यामुळे काही शेअर्स खरेदी करणे खरोखर स्वस्त झाले.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>एक सामान्य नवशिक्याची चूक म्हणजे दलाली ही एकमात्र किंमत आहे. हे सहसा आहे <em>सर्वात लहान</em> भाग प्रत्येक व्यापारात वैधानिक शुल्क देखील असते आणि छोट्या व्यापारांसाठी, ते ब्रोकरेजपेक्षा जास्त जोडू शकतात. नेहमी पहा <em>एकूण</em> खर्च, फक्त ब्रोकरेज लाइन नाही.</p>\n</div></div>\n<h3 id=\"what-you-actually-pay-on-a-trade\">आपण प्रत्यक्षात व्यापारावर काय देय</h3>\n<p>दलालीच्या पलीकडे, लहानाची टोपली <strong>शुल्क आणि कर</strong> प्रत्येक व्यापारात सोबत चालते. तुम्ही हे तुमच्या ब्रोकरला नफा म्हणून देत नाही, ब्रोकर फक्त त्यापैकी बहुतेक गोळा करतो आणि सरकार किंवा एक्सचेंजला देतो. मुख्य, सर्व अंदाजे:</p>\n<ul>\n<li><strong>सिक्युरिटीज ट्रान्झॅक्शन टॅक्स (STT)</strong>, व्यापार मूल्यावर सरकारी कर.</li>\n<li><strong>विनिमय व्यवहार शुल्क</strong>, सामन्यासाठी एक्सचेंज घेते एक लहान फी.</li>\n<li><strong>GST</strong>, ब्रोकरेज आणि व्यवहार शुल्कावर 18% आकारले जाते.</li>\n<li><strong>मुद्रांक शुल्क</strong>, खरेदीवर एक लहान राज्य आकारणी.</li>\n<li><strong>SEBI टर्नओव्हर फी</strong>, रेग्युलेटरला निधी देणारा एक उणे शुल्क.</li>\n<li><strong>DP शुल्क</strong>, जेव्हा शेअर्स तुमचे डिमॅट खाते विक्रीवर सोडतात तेव्हा फ्लॅट फी (बहुतेकदा सुमारे 13-20 रुपये)</li>\n</ul>\n<p>हेडलाइन टेकअवे: ब्रोकरेजची जाहिरात \"शून्य\" म्हणून केली जाऊ शकते, परंतु व्यापार कधीही विनामूल्य नसतो. चांगली बातमी अशी आहे की दीर्घकालीन गुंतवणूकदार खरेदी आणि होल्डिंगसाठी, हे खर्च क्वचितच दिले जातात आणि थोडेसे महत्त्वाचे असतात.</p>\n<h2 id=\"the-depository-a-bank-for-your-shares\">डिपॉझिटरी: तुमच्या शेअर्ससाठी बँक</h2>\n<p>एकदा तुम्ही शेअर्स खरेदी केले की ते प्रत्यक्षात कुठे करतात <em>जगणे</em>? तुमच्या ब्रोकरच्या ॲपमध्ये नाही, ती फक्त एक विंडो आहे. ते राहतात ए <strong>डिमॅट खाते</strong>, येथे आयोजित <strong>डिपॉझिटरी</strong>. डिपॉझिटरी एक बँक म्हणून विचार करा, परंतु ती रुपये ठेवण्याऐवजी इलेक्ट्रॉनिक पद्धतीने तुमचे शेअर्स ठेवते. जसे तुमचे बँक खाते तुमचे पैसे स्क्रीनवर नंबर म्हणून दाखवते, त्याचप्रमाणे तुमचे डिमॅट खाते तुमचे शेअर्स इलेक्ट्रॉनिक नोंदी म्हणून दाखवते. \"डीमॅट\" साठी लहान आहे <strong>अभौतिकीकरण</strong>, म्हणजे शेअर्स कागद म्हणून नव्हे तर डेटा म्हणून अस्तित्वात आहेत.</p>\n<p>भारताकडे नक्की आहे <strong>दोन डिपॉझिटरीज</strong>:</p>\n<ul>\n<li><strong>NSDL</strong>, नॅशनल सिक्युरिटीज डिपॉझिटरी लिमिटेड, भारतातील पहिली, 1996 मध्ये स्थापित.</li>\n<li><strong>CDSL</strong>, सेंट्रल डिपॉझिटरी सर्व्हिसेस लिमिटेड.</li>\n</ul>\n<p>तुम्ही त्यांच्याशी थेट व्यवहार करत नाही. तुमचा ब्रोकर ए म्हणून काम करतो <strong>डिपॉझिटरी सहभागी (DP)</strong>, तुम्ही आणि डिपॉझिटरी यांच्यातील सेतू, आणि तुमचे डिमॅट खाते दोनपैकी एकावर उघडते. तुमच्या ब्रोकरच्या ॲपचे काय होते याची पर्वा न करता तुमचे शेअर्स NSDL किंवा CDSL वर सुरक्षितपणे बसतात.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch05-demat-ecosystem.png\" alt=\"डीमॅट इकोसिस्टम, तुम्ही आणि तुमचा ब्रोकर एका बाजूला, दोन डिपॉझिटरीज NSDL आणि CDSL तुमचे शेअर्स इलेक्ट्रॉनिक पद्धतीने धारण करतात.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">इन्फोग्राफिक</span>डीमॅट इकोसिस्टम, तुम्ही आणि तुमचा ब्रोकर एका बाजूला, दोन डिपॉझिटरीज NSDL आणि CDSL तुमचे शेअर्स इलेक्ट्रॉनिक पद्धतीने धारण करतात.</figcaption></figure>\n<h3 id=\"the-demat-revolution\">डीमॅट क्रांती</h3>\n<p>हे इलेक्ट्रॉनिक जग आश्चर्यकारकपणे अलीकडील आहे. 1990 च्या दशकाच्या उत्तरार्धापर्यंत, मालकीचा हिस्सा असणे म्हणजे ए <strong>भौतिक कागद प्रमाणपत्र</strong>. विक्री म्हणजे ते प्रमाणपत्र स्वाक्षरी केलेल्या हस्तांतरण फॉर्मसह देशभरात कुरियर करणे, ते नोंदणीकृत होण्यासाठी आठवडे वाट पाहणे आणि ते हरवले, फाटलेले, बनावट किंवा \"खराब वितरण\" विवादांमध्ये अडकले नाही अशी प्रार्थना करणे. सेटलमेंटला काही महिने लागू शकतात. फसवणूक सर्रास सुरू होती.</p>\n<p>1996 मध्ये NSDL चे प्रक्षेपण सुरू झाले <strong>डीमॅट क्रांती</strong>, कागदी प्रमाणपत्रे इलेक्ट्रॉनिक रेकॉर्डमध्ये रूपांतरित करणे. याने भारतीय बाजारपेठा मंद आणि जोखमीपासून जलद आणि सुरक्षित मध्ये बदलल्या आणि सामान्य लोक आता काही टॅप्ससह गुंतवणूक करू शकतील हे सर्वात मोठे कारण आहे. आज फिजिकल शेअर सर्टिफिकेट्स धारण करणे मूलत: नामशेष झाले आहे.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>तुमचे शेअर्स डिपॉझिटरी ( NSDL किंवा CDSL) येथे ठेवलेले आहेत. <strong>नाही</strong> तुमच्या ब्रोकरद्वारे. दलाल हा फक्त प्रवेश बिंदू आहे. हे वेगळे करणे ही जाणीवपूर्वक केलेली सुरक्षा रचना आहे: जरी तुमचा ब्रोकर उद्या बंद झाला तरी तुमचे शेअर्स डिपॉझिटरीमधील तुमच्या डिमॅट खात्यात सुरक्षित असतील.</p>\n</div></div>\n<h3 id=\"types-of-demat-account\">डिमॅट खात्याचे प्रकार</h3>\n<p>प्रत्येक डिमॅट खाते सारखे नसते. आपण कोण आहात आणि आपल्याला कशाची आवश्यकता आहे यावर अवलंबून, आपण मूठभर मानक प्रकारांपैकी एक उघडता. येथे भारतातील सामान्य आहेत:</p>\n<table>\n<thead>\n<tr>\n<th>डिमॅट खाते प्रकार</th>\n<th>साठी योग्य</th>\n<th>मुख्य वैशिष्ट्य</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>नियमित</strong></td>\n<td>रहिवासी व्यक्ती</td>\n<td>अमर्यादित होल्डिंग्स</td>\n</tr>\n<tr>\n<td><strong>संयुक्त</strong></td>\n<td>कुटुंब/व्यवसाय भागीदार</td>\n<td>सामायिक नियंत्रण</td>\n</tr>\n<tr>\n<td><strong>कॉर्पोरेट</strong></td>\n<td>कंपन्या, एलएलपी</td>\n<td>कायदेशीर-संस्था अनुपालन</td>\n</tr>\n<tr>\n<td><strong>NRI परत करण्यायोग्य</strong></td>\n<td>NRE बँक खाते असलेले अनिवासी भारतीय</td>\n<td>परदेशात निधी हस्तांतरित केला जाऊ शकतो</td>\n</tr>\n<tr>\n<td><strong>NRI नॉन-रिपेट्रिएबल</strong></td>\n<td>NRO खाते असलेले अनिवासी भारतीय</td>\n<td>निधी भारतातच राहतो</td>\n</tr>\n<tr>\n<td><strong>BSDA (मूलभूत सेवा)</strong></td>\n<td>लहान / नवशिक्या गुंतवणूकदार</td>\n<td>कमी किंवा शून्य AMC, होल्डिंग मर्यादेसह</td>\n</tr>\n<tr>\n<td><strong>कोठडीत</strong></td>\n<td>अल्पवयीन, पालकाद्वारे</td>\n<td>संरक्षकाद्वारे चालवले जाते</td>\n</tr>\n<tr>\n<td><strong>प्रीमियम</strong></td>\n<td>HNIs आणि वारंवार व्यापारी</td>\n<td>अतिरिक्त सेवा आणि समर्थन</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>तुम्ही नुकतीच सुरुवात करत असाल आणि थोडीच रक्कम ठेवणार असाल, तर ए <strong>BSDA, एक मूलभूत सेवा डिमॅट खाते</strong>. SEBI ने हे लहान गुंतवणूकदारांसाठी डिझाइन केले आहे: वार्षिक देखभाल शुल्क (AMC) आहे <strong>4 लाखांपर्यंतच्या होल्डिंगसाठी शून्य</strong> आणि 10 लाखांपर्यंत फक्त एक लहान फी, त्यामुळे तुमचा पोर्टफोलिओ अजूनही लहान असताना तुम्ही वार्षिक फी भरत नाही. तुमच्याकडे फक्त एक BSDA असू शकते आणि ते तुमचे एकमेव डिमॅट खाते असणे आवश्यक आहे, जे नवशिक्यासाठी अगदी योग्य आहे.</p>\n</div></div>\n<h2 id=\"the-clearing-corporation-the-guarantor-in-the-middle\">क्लिअरिंग कॉर्पोरेशन: मध्यभागी हमीदार</h2>\n<p>एक शेवटचा, शांत नायक आहे. जेव्हा तुम्ही खरेदी करता आणि कोणीतरी विकतो तेव्हा तुम्ही कसे करता <em>माहित</em> विक्रेता प्रत्यक्षात समभाग वितरीत करेल, आणि विक्रेत्याला कसे कळेल की आपण खरोखर पैसे द्याल? जुन्या दिवसांत, या ट्रस्ट गॅपमुळे डिफॉल्ट होते. आज ती सोडवली आहे <strong>क्लिअरिंग कॉर्पोरेशन</strong>.</p>\n<p>क्लिअरिंग कॉर्पोरेशन प्रत्येक व्यापाराच्या मध्यभागी पाऊल टाकते आणि बनते <strong>खरेदीदार प्रत्येक विक्रेत्याला आणि विक्रेता प्रत्येक खरेदीदाराला</strong>. हे व्यापाराची हमी देते: खरेदीदाराला नेहमी शेअर्स मिळतात, विक्रेत्याला नेहमी पैसे मिळतात, जरी एक बाजू चुकली तरीही. हे काढून टाकते <strong>प्रतिपक्ष धोका</strong>, तुमच्या व्यापाराच्या दुसऱ्या बाजूची व्यक्ती नाहीशी होते. NSE चा क्लिअरिंग आर्म NSE क्लिअरिंग आहे; BSE भारतीय क्लिअरिंग कॉर्पोरेशन मार्फत स्पष्ट व्यापार करते. हे नेमके कसे कार्य करते ते आपण पुढील अध्यायात पाहू.</p>\n<h2 id=\"india-is-opening-demat-accounts-like-never-before\">भारत पूर्वी कधीही न करता डीमॅट खाती उघडत आहे</h2>\n<p>चारही एकत्र ठेवा आणि परिणाम इतका स्वस्त आणि विश्वासार्ह प्रणाली आहे की भारतीय लोक त्यात सामील होत आहेत. ची संख्या <strong>डिमॅट खाती 21.6 कोटी म्हणजे सुमारे 216 दशलक्ष ओलांडली आहेत</strong> (एकत्रित NSDL आणि CDSL, डिसेंबर 2025 पर्यंत), महामारीच्या अगदी आधी 4 कोटींपेक्षा कमी. ही काही कमी वर्षांत पाचपट पेक्षा जास्त उडी आहे.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch05-demat-account-growth.png\" alt=\"किरकोळ तेजी, भारतातील एकूण डिमॅट खाती 2019 मध्ये 4 कोटींहून 2025 च्या उत्तरार्धात सुमारे 21.6 कोटी (216 दशलक्ष) पर्यंत वाढली, बाजारपेठ शोधणाऱ्या पिढीचे अंदाजे चित्र\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>किरकोळ तेजी, भारतातील एकूण डिमॅट खाती 2019 मध्ये 4 कोटींहून 2025 च्या उत्तरार्धात सुमारे 21.6 कोटी (216 दशलक्ष) पर्यंत वाढली, बाजारपेठ शोधणाऱ्या पिढीचे अंदाजे चित्र</figcaption></figure>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>त्या खात्यांपैकी, <strong>CDSL कडे मोठे बहुमत आहे <em>संख्या</em>, अंदाजे प्रत्येक पाच खात्यांपैकी चार, सुमारे 17 कोटी, तर NSDL खूपच कमी, सुमारे 4 कोटी.</strong> तरीहीNSDL′ चा वाटा खूप मोठा आहे <em>मूल्य</em> मालमत्तेचे, कारण मोठ्या संस्था आणि उच्च-मूल्य असलेल्या होल्डिंग्स त्याच्याकडे बसतात. दोन डिपॉझिटरीज, दोन अतिशय भिन्न गुरुत्व केंद्रे.</p>\n</div></div>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>पण खाते <em>उघडले</em> गुंतवणूकदार नाही <em>कामावर</em>. त्या अंदाजे 21.6 कोटी खात्यांपैकी, NSE फक्त <strong>सक्रिय म्हणून 4.9 कोटी</strong>, गेल्या वर्षात एकच व्यापार केला. ब्रोकर्समध्ये अनेक खाती धारण करणाऱ्या बऱ्याच लोकांना काढून टाका (बहुतेकदा IPO-वाटप शक्यता सुधारण्यासाठी) आणि त्यांची संख्या <em>वेगळे</em> गुंतवणूकदार जवळ आहेत <strong>12 कोटी</strong>. खात्यांचा मोठा वाटा फक्त निष्क्रिय किंवा डुप्लिकेट बसतो. खाते फक्त दार आहे; <strong>खरं तर, संयमाने आणि नियमितपणे गुंतवणूक करणे हीच खरी पायरी आहे</strong>, आणि जेव्हा तुम्ही गुंतवणूकदार म्हणून तुमची पहिली पावले उचलता तेव्हा आम्ही त्या प्रवासाचा नकाशा बनवतो.</p>\n</div></div>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>डिमॅट खाते (ज्यामध्ये शेअर्स असतात) सहसा अ सह जोडलेले असते <strong>ट्रेडिंग खाते</strong> (जे ऑर्डर देते) आणि तुमचे <strong>बँक खाते</strong> (ज्यात रोख रक्कम असते). हे तिघे एकत्र काम करतात: बँक खरेदीसाठी निधी देते, ट्रेडिंग खाते ते ठेवते, डीमॅट खाते शेअर्स साठवते. जेव्हा तुम्ही गुंतवणूकदार म्हणून तुमची पहिली पावले उचलाल तेव्हा आम्ही ते उघडू.</p>\n</div></div>\n<h2 id=\"quick-recap\">क्विक रिकॅप</h2>\n<ul>\n<li>ए <strong>स्टॉक एक्सचेंज</strong> (NSE किंवा BSE) हे खरेदीदार आणि विक्रेत्यांशी जुळणारे बाजार आहे, <strong>BSE आशियातील सर्वात जुने आहे</strong> (1875), <strong>NSE व्हॉल्यूमनुसार सर्वात मोठा आहे</strong>.</li>\n<li>ए <strong>दलाल</strong> एक्सचेंजसाठी तुमचा परवानाकृत प्रवेशद्वार आहे; <strong>सवलत दलाल</strong> कमी फ्लॅट फी आकारणे, <strong>पूर्ण-सेवा दलाल</strong> सल्ल्यासाठी अधिक शुल्क आकारा.</li>\n<li>ब्रोकरेजच्या पलीकडे, प्रत्येक व्यापार लहान असतो <strong>शुल्क आणि कर</strong> (STT, GST, मुद्रांक शुल्क, विनिमय आणि DP शुल्क), त्यामुळे कोणताही व्यापार खरोखर विनामूल्य नाही.</li>\n<li>ए <strong>डिपॉझिटरी</strong> (NSDL किंवा CDSL) ही तुमच्या शेअर्ससाठी बँक आहे; आपले <strong>डिमॅट खाते</strong> तुमचा ब्रोकर गायब झाला तरीही ते इलेक्ट्रॉनिक पद्धतीने सुरक्षित ठेवते.</li>\n<li>द <strong>डीमॅट क्रांती</strong> धोकादायक कागदी प्रमाणपत्रे इलेक्ट्रॉनिक रेकॉर्डने बदलली आणि भारताकडे आता जवळपास आहे <strong>21.6 कोटी डिमॅट खाती</strong> (डिसेंबर 2025), जरी फक्त काही अंश सक्रियपणे व्यवहार केले जातात.</li>\n<li>द <strong>क्लिअरिंग कॉर्पोरेशन</strong> प्रत्येक व्यापाराची हमी देते, दुसरी बाजू डीफॉल्ट होणारी जोखीम काढून टाकते.</li>\n</ul>\n<p>पुढे, आम्ही खरेदीच्या क्लिकनंतर आणि प्लंबिंगमध्ये तुमच्या ऑर्डरचे अनुसरण करतो, व्यापार कसा आहे <em>साफ आणि स्थायिक</em>, आणि का, T+1 चे आभार, तुमचे शेअर्स जवळपास दुसऱ्याच दिवशी दिसतात.</p>\n","toc":[{"level":2,"text":"एक्सचेंज: एक विशाल संघटित बाजारपेठ","id":"the-exchange-a-giant-organised-marketplace"},{"level":2,"text":"जेव्हा बाजार खुला असतो","id":"when-the-market-is-open"},{"level":2,"text":"कोण ट्रेडिंग करत आहे: बाजारातील सहभागी","id":"who-is-trading-the-market-participants"},{"level":2,"text":"ब्रोकर: तुमचे एक्सचेंजचे प्रवेशद्वार","id":"the-broker-your-gateway-to-the-exchange"},{"level":3,"text":"आपण प्रत्यक्षात व्यापारावर काय देय","id":"what-you-actually-pay-on-a-trade"},{"level":2,"text":"डिपॉझिटरी: तुमच्या शेअर्ससाठी बँक","id":"the-depository-a-bank-for-your-shares"},{"level":3,"text":"डीमॅट क्रांती","id":"the-demat-revolution"},{"level":3,"text":"डिमॅट खात्याचे प्रकार","id":"types-of-demat-account"},{"level":2,"text":"क्लिअरिंग कॉर्पोरेशन: मध्यभागी हमीदार","id":"the-clearing-corporation-the-guarantor-in-the-middle"},{"level":2,"text":"भारत पूर्वी कधीही न करता डीमॅट खाती उघडत आहे","id":"india-is-opening-demat-accounts-like-never-before"},{"level":2,"text":"क्विक रिकॅप","id":"quick-recap"}],"imgCount":4,"hasContent":true},"6":{"html":"<p>तुम्ही आज सकाळी 10:15 वाजता रिलायन्सचे 10 शेअर्स खरेदी केले. तुम्ही तुमचा फोन लॉक करेपर्यंत, ऑर्डरमध्ये \"अंमलबजावणी झाली\" असे म्हटले होते आणि शेअर्स तुमच्या पोर्टफोलिओमध्ये दिसू लागले. केले आणि धूळ, बरोबर? अगदीच नाही. त्या क्षणी, कोणतेही शेअर्स आणि कोणतेही पैसे प्रत्यक्षात हात बदलले नाहीत. आपण जे साक्षीदार होता ते ए <em>वचन</em>, एक बंधनकारक करार जो तुम्ही देय द्याल आणि विक्रेता वितरीत करेल. शेअर्ससाठी पैशाची खरी अदलाबदली नंतर, पडद्यामागे, नावाच्या प्रक्रियेद्वारे होते <strong>सेटलमेंट</strong>.</p>\n<p>हे बाजारपेठेतील अशोभनीय प्लंबिंग आहे आणि हे एका कारणास्तव समजून घेण्यासारखे आहे: हा एक भाग आहे जो इतर सर्व काही बनवतो. <em>विश्वासार्ह</em>. जेव्हा ही यंत्रसामग्री काम करते, आणि भारतात ती जवळजवळ नेहमीच असते, तेव्हा तुम्ही देशाच्या पलीकडे असलेल्या एखाद्या अनोळखी व्यक्तीकडून खरेदी करू शकता आणि तुम्हाला तुमचे शेअर्स मिळतील आणि त्यांना त्यांचे पैसे मिळतील याची खात्री बाळगा. चला हुड उघडूया.</p>\n<h2 id=\"a-trade-is-a-promise-settlement-is-the-delivery\">व्यापार एक वचन आहे; सेटलमेंट म्हणजे वितरण</h2>\n<p>या प्रकरणातील सर्वात उपयुक्त कल्पना अशी आहे की अ <strong>व्यापार</strong> आणि त्याचे <strong>सेटलमेंट</strong> वेळेतील दोन वेगळे क्षण आहेत.</p>\n<ul>\n<li>द <strong>व्यापार</strong> हा करार आहे: 10:15 वाजता, एक खरेदीदार आणि विक्रेता 10 शेअर्सच्या किंमतीवर सहमत झाला. देवाणघेवाण त्यांच्याशी जुळली. करार अस्तित्वात आहे, परंतु केवळ कागदावर.</li>\n<li>द <strong>सेटलमेंट</strong> त्याची पूर्तता आहे: खरेदीदाराचे पैसे प्रत्यक्षात विक्रेत्याकडे जातात आणि विक्रेत्याचे शेअर्स प्रत्यक्षात खरेदीदाराकडे जातात. हे काही तास किंवा एक दिवस नंतर घडते.</li>\n</ul>\n<p>त्या दोन क्षणांच्या दरम्यान दोन गोष्टी शोधून काढाव्या लागतात. काम करत आहे <em>कोण काय देणे आहे</em> म्हणतात <strong>साफ करणे</strong>. वास्तविक <em>पैसे आणि शेअर्स हलवणे</em> म्हणतात <strong>सेटलमेंट</strong>.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch06-trade-lifecycle.png\" alt=\"व्यापाराचे जीवन, T दिवसाच्या जुळलेल्या ऑर्डरपासून, क्लिअरिंग आणि ऑब्लिगेशन नेटिंगद्वारे, T+1 वर पैसे-आणि-शेअर सेटलमेंटपर्यंत\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">फ्लो चार्ट</span>व्यापाराचे जीवन, T दिवसाच्या जुळलेल्या ऑर्डरपासून, क्लिअरिंग आणि ऑब्लिगेशन नेटिंगद्वारे, T+1 वर पैसे-आणि-शेअर सेटलमेंटपर्यंत</figcaption></figure>\n<h2 id=\"clearing-working-out-who-owes-what\">साफ करणे: कोणाला काय देणे आहे हे शोधून काढणे</h2>\n<p>कोणत्याही दिवशी, तुम्ही रिलायन्सचे 10 शेअर्स खरेदी करू शकता, 5 विकू शकता आणि आणखी 8 खरेदी करू शकता. लाखो गुंतवणुकदारांच्या करोडो व्यवहारांनी त्याचा गुणाकार करा आणि एक्सचेंजमध्ये जबाबदाऱ्यांचे एक गुंतागुंतीचे जाळे आहे. <strong>क्लिअरिंग</strong> प्रत्येक सहभागीसाठी ते उलगडण्याची, गणना करण्याची प्रक्रिया आहे <em>निव्वळ</em> पैसे आणि शेअर्सची रक्कम त्यांना देणे आहे किंवा दिवसाच्या शेवटी देणे बाकी आहे.</p>\n<p>येथे मुख्य युक्ती आहे <strong>जाळी</strong>. प्रत्येक ट्रेडचा स्वतंत्रपणे निपटारा करण्याऐवजी, क्लिअरिंग कॉर्पोरेशन तुमच्या सर्व खरेदी-विक्री स्टॉकमध्ये जोडते आणि तुमचे काम <em>निव्वळ</em> स्थिती जर तुम्ही 10 विकत घेतले आणि 5 समान शेअर विकले, तर तुम्हाला फक्त 5 निव्वळ शेअर्स मिळणे आवश्यक आहे, 15 स्वतंत्रपणे बदलू नका. नेटिंग प्रत्येक गुंतवणूकदार प्रति सिक्युरिटीमध्ये वैयक्तिक व्यापारांचा डोंगर कोसळतो. कोट्यवधींचे व्यवहार निश्चित करणे आणि मूठभर निव्वळ जबाबदाऱ्यांचे निराकरण करणे यातील फरक आहे, प्रचंड कार्यक्षमता.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p><strong>\"कोणाला काय देणे आहे?\" सेटलमेंट उत्तर देते \"आता खरंच पैसे देऊ आणि वितरित करू.\"</strong> क्लिअरिंग म्हणजे हिशेब; सेटलमेंट ही क्रिया आहे. क्लिअरिंग कॉर्पोरेशन पहिले करते आणि दुसरे ऑर्केस्ट्रेट करते.</p>\n</div></div>\n<h2 id=\"settlement-the-actual-swap\">सेटलमेंट: वास्तविक स्वॅप</h2>\n<p>एकदा क्लिअरिंगने प्रत्येकाची निव्वळ जबाबदारी निर्माण केली, <strong>सेटलमेंट</strong> त्यांना अंमलात आणतो. सेटलमेंटच्या दिवशी, सिस्टम दोन गोष्टी एकाच वेळी करते:</p>\n<ul>\n<li><strong>पे-इन</strong>, खरेदीदारांचे पैसे आणि विक्रेत्यांचे शेअर्स गोळा केले जातात. खरेदीदारांच्या बँक खात्यातून पैसे डेबिट केले जातात; विक्रेत्यांच्या डिमॅट खात्यातून शेअर्स डेबिट केले जातात.</li>\n<li><strong>पे-आउट</strong>, शेअर्स खरेदीदारांच्या डिमॅट खात्यात जमा केले जातात आणि पैसे विक्रेत्यांच्या बँक खात्यात जमा केले जातात.</li>\n</ul>\n<p>हे एकाचवेळी होणारे स्वॅप संपूर्ण बिंदू आहे. रोख सह खरेदीदार भाग <em>म्हणून</em> त्यांना शेअर्स मिळतात; समभागांसह विक्रेता भाग <em>म्हणून</em> त्यांना रोख रक्कम मिळते. कोणत्याही बाजूने दुसऱ्यावर थेट विश्वास ठेवण्याची गरज नाही, कारण क्लिअरिंग कॉर्पोरेशन एकाच वेळी दोन्ही पाय हाताळते.</p>\n<h2 id=\"rolling-settlement-and-the-road-to-t-1\">रोलिंग सेटलमेंट आणि T+1 चा रस्ता</h2>\n<p>यास किती वेळ लागेल? मध्ये अ <strong>रोलिंग सेटलमेंट</strong> प्रणाली, ट्रेड्स ट्रेड तारखेनंतर ठराविक व्यावसायिक दिवसांची पूर्तता करतात. व्यापार दिवस म्हणतात <strong>टी</strong>, आणि सेटलमेंट काही दिवसांनंतर होते.</p>\n<p>भारताने गेल्या काही वर्षांत हे अंतर सातत्याने कमी केले आहे आणि हा खरा अभिमानाचा मुद्दा आहे:</p>\n<table>\n<thead>\n<tr>\n<th>युग</th>\n<th>सायकल</th>\n<th>त्याचा अर्थ काय होता</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>2001 पर्यंत</td>\n<td>साप्ताहिक \"बदला\" बंदोबस्त</td>\n<td>आठवड्यातून एकदा व्यापारांचा ढीग झाला आणि स्थिरावला</td>\n</tr>\n<tr>\n<td>2002</td>\n<td>T+3</td>\n<td>व्यापारानंतर तीन कामकाजाचे दिवस सेटल करा</td>\n</tr>\n<tr>\n<td>2003</td>\n<td>T+2</td>\n<td>दोन दिवस, दोन दशकांसाठी जागतिक मानक</td>\n</tr>\n<tr>\n<td><strong>जानेवारी २०२३</strong></td>\n<td><strong>T+1</strong></td>\n<td><strong>कामाच्या पुढच्याच दिवशी सेटल करा</strong></td>\n</tr>\n<tr>\n<td>2024-25</td>\n<td>पर्यायी T+0</td>\n<td>त्याच दिवशी सेटलमेंट, टप्प्याटप्प्याने केले जात आहे</td>\n</tr>\n</tbody></table>\n<p>मध्ये <strong>जानेवारी 2023 मध्ये, भारताने T+1 मध्ये आपली वाटचाल पूर्ण केली</strong>, म्हणजे आज केलेला व्यापार उद्या स्थिरावतो. निर्णायकपणे, <strong>T+1 पूर्णपणे स्वीकारणाऱ्या जगातील पहिल्या प्रमुख बाजारपेठांपैकी भारत होता.</strong> युनायटेड स्टेट्स, संदर्भासाठी, फक्त T+1 मध्ये हलविले <strong>मे २०२४</strong>, एक वर्षापेक्षा जास्त <em>नंतर</em> भारत. एकेकाळी, भारताचे मार्केट प्लंबिंग वॉल स्ट्रीटच्या पुढे होते.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>जानेवारी 2023 मध्ये जेव्हा भारत पूर्णपणे T+1 मध्ये बदलला तेव्हा त्याने विकसित जगाला मागे टाकले. US, UK आणि युरोप अजूनही धीमे T+2 चक्रावर होते. अनेकदा \"उभरती\" म्हणून दिसणारी बाजारपेठ, सेटलमेंटच्या वेगाने, ग्रहाचे नेतृत्व करत होती.</p>\n</div></div>\n<h3 id=\"what-t-1-actually-feels-like\">T+1 प्रत्यक्षात कसे वाटते</h3>\n<p>एक गुंतवणूकदार म्हणून तुमच्यासाठी, T+1 म्हणजे खरी सोय. तुमचे शेअर्स आजच विका आणि पुढील कामकाजाच्या दिवशी तुमच्या खात्यात पैसे वापरता येतील. आजच खरेदी करा, आणि शेअर्स दृढपणे तुमचे आहेत, दुसऱ्या दिवशी वितरित करण्यायोग्य आहेत. जलद सेटलमेंटचा अर्थ असा आहे की गोष्टींमध्ये चूक होण्यासाठी कमी वेळ आहे, जे फक्त जलदच नाही तर संपूर्ण प्रणाली सुरक्षित करते.</p>\n<h2 id=\"t-0-the-same-day-experiment\">T+0: त्याच दिवशीचा प्रयोग</h2>\n<p>भारत T+1 वर थांबला नाही. मध्ये <strong>मार्च २०२४</strong>, SEBI लाँच केले a <strong>पर्यायी T+0 सेटलमेंटचा बीटा</strong>, त्याच-दिवशी सेटलमेंट, जिथे तुम्ही व्यापार करता त्याच दिवशी पैसे आणि शेअर्स बदलतात. पासून <strong>2025 च्या सुरुवातीस</strong>, तो ओलांडून टप्प्याटप्प्याने रोलआउट सुरू झाला <strong>शीर्ष 500 स्टॉक</strong> बाजार मूल्यानुसार, एका वेळी अंदाजे 100 स्टॉक जोडणे.</p>\n<p>सरळ ठेवण्यासाठी काही गोष्टी:</p>\n<ul>\n<li>T+0 आहे <strong>पर्यायी</strong>, धावणे <em>बाजूने</em> T+1, ते बदलत नाही. तुम्ही आणि तुमचे ब्रोकर निवडा.</li>\n<li>हे मोठ्या स्टॉकच्या परिभाषित सूचीवर लागू होते, हळूहळू विस्तारत आहे.</li>\n<li>त्याच दिवसाची तरलता, सकाळी विक्री करणे, त्याच दिवशी दुपारी रोख असणे हे उद्दिष्ट आहे.</li>\n</ul>\n<p>हा एक प्रयोग आहे की, तो यशस्वी झाल्यास, मुख्य प्रवाहात समान-दिवसाच्या सेटलमेंटसह भारताला पहिल्या बाजारपेठांपैकी एक बनवू शकेल.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>उपवास गोंधळ करू नका <em>सेटलमेंट</em> इंट्राडे ट्रेडिंगसह सायकल. T+1 आणि T+0 किती लवकर a <em>पूर्ण</em> व्यापार अंतिम. तुम्ही एकाच दिवसात (इंट्राडे) समान स्टॉक खरेदी आणि विकू शकता, हे वेगळे वैशिष्ट्य आहे. धूळ शेवटी मालकी आणि रोख वर स्थिरावते तेव्हा सेटलमेंट आहे.</p>\n</div></div>\n<h2 id=\"the-clearing-corporation-the-guarantor-in-the-middle\">क्लिअरिंग कॉर्पोरेशन: मध्यभागी हमीदार</h2>\n<p>आता सगळ्यात महत्त्वाची सुरक्षा कल्पना. आपण खरेदी करता तेव्हा, आपण कसे असू शकते <em>खात्रीने</em> निनावी विक्रेता वितरित करेल? आपण करू शकत नाही, आणि आपण करण्याची गरज नाही. द <strong>क्लिअरिंग कॉर्पोरेशन</strong> प्रत्येक व्यापाराच्या केंद्रस्थानी पाऊल टाकते आणि कायदेशीररित्या बनते <strong>खरेदीदार प्रत्येक विक्रेत्याला आणि विक्रेता प्रत्येक खरेदीदाराला</strong>. याला म्हणतात <strong>नवीनता</strong>.</p>\n<p>यामुळे, तुम्ही प्रत्यक्षात दुसऱ्या बाजूला असलेल्या अनोळखी व्यक्तीवर कधीच विसंबून राहत नाही. तुम्ही क्लिअरिंग कॉर्पोरेशनवर अवलंबून आहात आणि ते व्यापाराची हमी देते. खरेदीदाराला त्यांच्या समभागांची हमी दिली जाते; विक्रेत्याला त्यांच्या पैशाची हमी दिली जाते. दुसरा पक्ष नाहीसा होणारा धोका, <strong>प्रतिपक्ष धोका</strong>, पूर्णपणे काढून टाकले आहे.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch06-clearing-guarantor.png\" alt=\"क्लिअरिंग कॉर्पोरेशन मध्यभागी हमीदार म्हणून बसते, ते प्रत्येक विक्रेत्यासाठी खरेदीदार बनते आणि प्रत्येक खरेदीदारासाठी विक्रेता बनते, म्हणून दोन्ही बाजूंनी दुसऱ्यावर विश्वास ठेवू नये.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>क्लिअरिंग कॉर्पोरेशन मध्यभागी हमीदार म्हणून बसते, ते प्रत्येक विक्रेत्यासाठी खरेदीदार बनते आणि प्रत्येक खरेदीदारासाठी विक्रेता बनते, म्हणून दोन्ही बाजूंनी दुसऱ्यावर विश्वास ठेवू नये.</figcaption></figure>\n<h3 id=\"why-settlement-failures-are-vanishingly-rare\">सेटलमेंट अयशस्वी का अदृश्यपणे दुर्मिळ आहेत</h3>\n<p>जर क्लिअरिंग कॉर्पोरेशन प्रत्येक गोष्टीची हमी देत ​​असेल, तर जेव्हा कोणी पैसे देण्यास किंवा वितरण करण्यात खरोखर अपयशी ठरते तेव्हा काय होते? हे चिलखत बांधलेल्या थरांनी संरक्षित आहे <em>आधी</em> व्यापारांना देखील परवानगी आहे:</p>\n<ul>\n<li><strong>समास</strong>, व्यापाऱ्यांनी सिक्युरिटी कुशन म्हणून आधीच पैसे जमा करणे आवश्यक आहे, जेणेकरून गेममध्ये त्यांची त्वचा असेल.</li>\n<li><strong>सेटलमेंट गॅरंटी फंड (SGF)</strong>, एखाद्या सदस्याने चूक केल्यास सेटलमेंट पूर्ण करण्यासाठी पैशांचा मोठा पूल विशेषतः बाजूला ठेवला जातो.</li>\n<li><strong>लिलाव आणि दंड</strong>, विक्रेता समभाग वितरित करण्यात अयशस्वी झाल्यास, खरेदीदार पूर्ण करण्यासाठी सिस्टम त्यांना खुल्या बाजारात खरेदी करते आणि डिफॉल्टरला दंड करते.</li>\n</ul>\n<p>एकत्रितपणे, हे खरे सेटलमेंट अयशस्वी बनवतात भारतात विलक्षण दुर्मिळ. हमी जवळजवळ कधीच तपासली जात नाही, त्यामुळेच गुंतवणूकदार कोणताही विचार न करता एकूण अनोळखी व्यक्तींसोबत व्यापार करू शकतात.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>एखाद्या दूरच्या शहरात, पूर्ण आत्मविश्वासाने, तुम्ही कधीही भेटणार नसलेल्या व्यक्तीकडून शेअर्स खरेदी करू शकता, याचे कारण <strong>क्लिअरिंग कॉर्पोरेशनची हमी</strong>. तो शांतपणे दुसऱ्या बाजूने डिफॉल्ट होण्याचा धोका शोषून घेतो, विश्वासाची झेप नित्यक्रम, कंटाळवाणा, सुरक्षित व्यवहारात बदलतो.</p>\n</div></div>\n<h2 id=\"closing-price-is-not-the-settlement-cycle-vwap-and-cas\">बंद किंमत सेटलमेंट सायकल नाही: VWAP आणि CAS</h2>\n<p>शब्द <strong>सेटलमेंट</strong> जेव्हा एक्स्चेंज अधिकृत क्लोजिंग व्हॅल्यू निवडते ज्यावर कालबाह्य करार मोजला जातो तेव्हा डेरिव्हेटिव्हमध्ये देखील वापरला जातो. हे या प्रकरणात स्पष्ट केलेल्या शेअर्स आणि पैशांच्या T+1 किंवा T+0 हालचालींपेक्षा वेगळे आहे.</p>\n<p>पासून <strong>3 ऑगस्ट 2026</strong>, भारत वापरतो अ <strong>क्लोजिंग लिलाव सत्र (CAS)</strong> डेरिव्हेटिव्ह कॉन्ट्रॅक्ट उपलब्ध असलेल्या स्टॉकची अधिकृत रोख-बाजार बंद किंमत निर्धारित करण्यासाठी. त्यांचा सतत रोखीचा व्यापार 15:15 वाजता थांबतो. एक्सचेंज स्टॉकच्या 15:00-15:15 VWAP पासून संदर्भ किंमत मोजते, CAS दरम्यान ऑर्डर संकलित करते आणि एक समतोल किंमत निवडते जी एक्झिक्युटेबल मात्रा जास्तीत जास्त करते. ऑर्डर एंट्री 15:28 आणि 15:30 च्या दरम्यान यादृच्छिकपणे बंद होते, जुळणारे 15:35 पर्यंत पूर्ण होते आणि सामान्य CAS बँड संदर्भ किंमतीच्या जवळपास अधिक किंवा उणे 3% असतो.</p>\n<p>समतोल किंमत सापडली नाही तर, संदर्भ किंमत बंद होते.CAS′ द्वारे कव्हर न केलेले सिक्युरिटीज 15:30 पर्यंत व्यापार सुरू ठेवतात आणि मागील शेवटच्या-30-मिनिटांचीVWAP′ बंद करण्याची पद्धत कायम ठेवतात. इक्विटी डेरिव्हेटिव्ह्ज CAS प्रविष्ट करत नाहीत; ते 15:40 पर्यंत व्यापार करतात आणि त्यांचा स्वतःचा करार 15:10-15:40VWAP′ पर्यंत राहतो. निर्देशांक स्वतंत्र लिलावात प्रवेश करत नाही, परंतु त्याचे अंतिम मूल्य त्याच्या घटक समभागांच्या अधिकृत बंद किंमती दर्शवते.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>CAS बदलते <strong>बंद-किंमत शोध</strong>, T+1/T+0 सेटलमेंट सायकल नाही. पहा <a href=\"https://www.sebi.gov.in/legal/circulars/jan-2026/introduction-of-closing-auction-session-cas-in-the-equity-cash-segment-and-certain-modifications-in-the-pre-open-auction-session_99122.html\">SEBI CAS परिपत्रक</a>, द <a href=\"https://nsearchives.nseindia.com/web/mediaattachment/2026-07/FAQs_on_Closing_Auction_Session_CAS_in_the_CM_and_changes_in_FO_Segment_ver1_20260706173436.pdf\">NSE CAS FAQ</a>, आणि <a href=\"https://groww.in/blog/closing-auction-session\">Groww चे काम केलेले स्पष्टीकरण</a>.</p>\n</div></div>\n<h2 id=\"closing-price-is-not-the-settlement-cycle-vwap-and-cas\">बंद किंमत सेटलमेंट सायकल नाही: VWAP आणि CAS</h2>\n<p>शब्द <strong>सेटलमेंट</strong> जेव्हा एक्स्चेंज अधिकृत क्लोजिंग व्हॅल्यू निवडते ज्यावर कालबाह्य करार मोजला जातो तेव्हा डेरिव्हेटिव्हमध्ये देखील वापरला जातो. हे या प्रकरणात स्पष्ट केलेल्या शेअर्स आणि पैशांच्या T+1 किंवा T+0 हालचालींपेक्षा वेगळे आहे.</p>\n<p>पासून <strong>3 ऑगस्ट 2026</strong>, भारत वापरतो अ <strong>क्लोजिंग लिलाव सत्र (CAS)</strong> डेरिव्हेटिव्ह कॉन्ट्रॅक्ट उपलब्ध असलेल्या स्टॉकची अधिकृत रोख-बाजार बंद किंमत निर्धारित करण्यासाठी. त्यांचा सतत रोखीचा व्यापार 15:15 वाजता थांबतो. एक्सचेंज स्टॉकच्या 15:00-15:15 VWAP पासून संदर्भ किंमत मोजते, CAS दरम्यान ऑर्डर संकलित करते आणि एक समतोल किंमत निवडते जी एक्झिक्युटेबल मात्रा जास्तीत जास्त करते. ऑर्डर एंट्री 15:28 आणि 15:30 दरम्यान यादृच्छिकपणे बंद होते, जुळणारे 15:35 पर्यंत पूर्ण होते आणि सामान्य CAS बँड संदर्भ किमतीच्या जवळपास अधिक किंवा उणे 3% असतो.</p>\n<p>समतोल किंमत सापडली नाही तर, संदर्भ किंमत बंद होते.CAS′ द्वारे कव्हर न केलेले सिक्युरिटीज 15:30 पर्यंत व्यापार सुरू ठेवतात आणि मागील शेवटच्या 30-मिनिटVWAP′ बंद करण्याची पद्धत कायम ठेवतात. इक्विटी डेरिव्हेटिव्ह्ज CAS प्रविष्ट करत नाहीत; ते 15:40 पर्यंत व्यापार करतात आणि त्यांचा स्वतःचा करार 15:10-15:40VWAP′ पर्यंत राहतो. निर्देशांक स्वतंत्र लिलावात प्रवेश करत नाही, परंतु त्याचे अंतिम मूल्य त्याच्या घटक समभागांच्या अधिकृत बंद किंमती दर्शवते.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>CAS बदलते <strong>बंद-किंमत शोध</strong>, T+1/T+0 सेटलमेंट सायकल नाही. पहा <a href=\"https://www.sebi.gov.in/legal/circulars/jan-2026/introduction-of-closing-auction-session-cas-in-the-equity-cash-segment-and-certain-modifications-in-the-pre-open-auction-session_99122.html\">SEBI CAS परिपत्रक</a>, द <a href=\"https://nsearchives.nseindia.com/web/mediaattachment/2026-07/FAQs_on_Closing_Auction_Session_CAS_in_the_CM_and_changes_in_FO_Segment_ver1_20260706173436.pdf\">NSE CAS FAQ</a>, आणि <a href=\"https://groww.in/blog/closing-auction-session\">Groww चे काम केलेले स्पष्टीकरण</a>.</p>\n</div></div>\n<h2 id=\"quick-recap\">क्विक रिकॅप</h2>\n<ul>\n<li>ए <strong>व्यापार</strong> जेव्हा खरेदीदार आणि विक्रेता जुळतात तेव्हा दिलेले वचन आहे; <strong>सेटलमेंट</strong> जेव्हा पैसा आणि शेअर्स प्रत्यक्षात हात बदलतात, दोन वेगळे क्षण.</li>\n<li><strong>क्लिअरिंग</strong> कोणाला काय देणे आहे (वापरून <strong>जाळी</strong> अनेक व्यवहार नीटनेटक्या आकृत्यांमध्ये संकुचित करण्यासाठी); <strong>सेटलमेंट</strong> वास्तविक पे-इन आणि पे-आउट पार पाडते.</li>\n<li>भारत वापरतो <strong>रोलिंग सेटलमेंट</strong> आणि त्याची हालचाल पूर्ण केली <strong>जानेवारी २०२३ मध्ये T+1</strong>, US च्या पुढे, जगातील पहिल्या प्रमुख बाजारपेठांपैकी.</li>\n<li>SEBI ने ओळख करुन दिली <strong>पर्यायी T+0 (त्याच दिवशी) सेटलमेंट</strong> 2024-25 पासून, टॉप 500 समभागांमध्ये टप्प्याटप्प्याने केले जात आहे.</li>\n<li>द <strong>क्लिअरिंग कॉर्पोरेशन</strong> प्रत्येक विक्रेत्यासाठी खरेदीदार बनतो आणि प्रत्येक खरेदीदाराला विक्रेता काढून टाकतो <strong>प्रतिपक्ष धोका</strong> आणि व्यापाराची हमी.</li>\n<li>चे आभार <strong>मार्जिन, सेटलमेंट गॅरंटी फंड आणि लिलाव</strong>, सेटलमेंट अपयश अत्यंत दुर्मिळ आहेत.</li>\n</ul>\n<p>पुढे, आम्ही कंपनीच्या आयुष्याच्या सुरुवातीपर्यंत सर्व मार्ग रिवाइंड करतो, एक छोटासा स्टार्टअप कसा पैसा गोळा करतो, एका कल्पनेतून मोठा व्यवसाय बनतो आणि एक दिवस त्याचे शेअर्स तुम्हाला विकू शकतो.</p>\n","toc":[{"level":2,"text":"व्यापार एक वचन आहे; सेटलमेंट म्हणजे वितरण","id":"a-trade-is-a-promise-settlement-is-the-delivery"},{"level":2,"text":"साफ करणे: कोणाला काय देणे आहे हे शोधून काढणे","id":"clearing-working-out-who-owes-what"},{"level":2,"text":"सेटलमेंट: वास्तविक स्वॅप","id":"settlement-the-actual-swap"},{"level":2,"text":"रोलिंग सेटलमेंट आणि T+1 चा रस्ता","id":"rolling-settlement-and-the-road-to-t-1"},{"level":3,"text":"T+1 प्रत्यक्षात कसे वाटते","id":"what-t-1-actually-feels-like"},{"level":2,"text":"T+0: त्याच दिवशीचा प्रयोग","id":"t-0-the-same-day-experiment"},{"level":2,"text":"क्लिअरिंग कॉर्पोरेशन: मध्यभागी हमीदार","id":"the-clearing-corporation-the-guarantor-in-the-middle"},{"level":3,"text":"सेटलमेंट अयशस्वी का अदृश्यपणे दुर्मिळ आहेत","id":"why-settlement-failures-are-vanishingly-rare"},{"level":2,"text":"बंद किंमत सेटलमेंट सायकल नाही: VWAP आणि CAS","id":"closing-price-is-not-the-settlement-cycle-vwap-and-cas"},{"level":2,"text":"बंद किंमत सेटलमेंट सायकल नाही: VWAP आणि CAS","id":"closing-price-is-not-the-settlement-cycle-vwap-and-cas"},{"level":2,"text":"क्विक रिकॅप","id":"quick-recap"}],"imgCount":2,"hasContent":true},"7":{"html":"<p>इन्फोसिस, झोमॅटो, रिलायन्स या सर्व मोठ्या कंपनीच्या शेअर्सची किंमत तुमच्या स्क्रीनवर स्क्रोल करते, एकेकाळी हास्यास्पदरीत्या लहान होती: काही लोक, एक कल्पना आणि ती प्रत्यक्षात आणण्यासाठी पुरेसा पैसा नव्हता. 1 लाख कोटींच्या कंपनीत कोणीही जन्माला येत नाही. ते तिथे चढतात, एका वेळी एक निधी गोळा करतात, रोख वाढण्यासाठी मालकीच्या तुकड्यांचा व्यापार करतात. कंपनीचे शेअर्स तुमच्या खरेदीसाठीNSE′ किंवाBSE′ वर उतरतील, तोपर्यंत, ते सहसा दीर्घ, नाट्यमय आर्थिक जीवन जगले आहे जे तुम्ही कधीही पाहिले नाही.</p>\n<p>हा धडा त्या छुप्या प्रवासाचा मागोवा घेतो, द <strong>निधी शिडी</strong> व्यवसाय कल्पनेतूनIPOवर चढतो. ते समजून घेतल्याने दोन गोष्टी होतात. सूचीबद्ध कंपन्या प्रत्यक्षात कुठून येतात हे हे स्पष्ट करते. आणि ते स्पष्ट करते <em>का</em> एक कंपनी अखेरीस जनतेला शेअर्स विकण्याचा निर्णय घेते, जे शेवटी, ज्या क्षणी तुम्हाला त्याचा एक भाग मिळेल.</p>\n<h2 id=\"the-funding-ladder\">निधीची शिडी</h2>\n<p>शिडीचे चित्र काढा. तळाशी एक पैसा नसलेली कल्पना आहे; शीर्षस्थानी लोकांसाठी शेअर्स विकणारी कंपनी आहे. प्रत्येक पंक्ती थोड्या मोठ्या, अधिक व्यावसायिक स्त्रोताकडून थोडे अधिक पैसे गोळा करते आणि प्रत्येक पंक्तीवर, संस्थापक त्याबदल्यात मालकीचा तुकडा सोडून देतात. येथे चढाई आहे.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch07-funding-ladder.png\" alt=\"निधीची शिडी, कल्पना आणि संस्थापकाच्या स्वतःच्या बचतीतून, देवदूत आणि उद्यम भांडवल फेरीतून, खाजगी इक्विटीमध्ये आणि शेवटी सार्वजनिक सूची\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">फ्लो चार्ट</span>निधीची शिडी, कल्पना आणि संस्थापकाच्या स्वतःच्या बचतीतून, देवदूत आणि उद्यम भांडवल फेरीतून, खाजगी इक्विटीमध्ये आणि शेवटी सार्वजनिक सूची</figcaption></figure>\n<h3 id=\"rung-0-the-idea\">रंग 0, कल्पना</h3>\n<p>हे एखाद्या समस्येपासून सुरू होते ज्याचे निराकरण करायचे आहे आणि जवळजवळ पैसे नाहीत. या टप्प्यावर \"कंपनी\" फक्त एक पिच डेक आणि शनिवार व रविवार रोजी तयार केलेला नमुना असू शकतो.</p>\n<h3 id=\"rung-1-bootstrapping\">रंग 1, बूटस्ट्रॅपिंग</h3>\n<p><strong>बूटस्ट्रॅपिंग</strong> म्हणजे संस्थापकांसोबत व्यवसायाला निधी देणे <em>स्वतःचे</em> पैसे, बचत, क्रेडिट कार्ड, पहिल्या ग्राहकांकडून मिळणारा महसूल. बाहेरील गुंतवणूकदार नाहीत, सौम्यता नाही: संस्थापक 100% मालकीचे आहेत. नकारात्मक बाजू मर्यादित इंधन आहे; तुम्ही तुमच्या स्वतःच्या वॉलेटला परवानगी देईल तेवढ्याच वेगाने वाढू शकता.</p>\n<h3 id=\"rung-2-friends-family-and-angels\">रंग 2, मित्र, कुटुंब आणि देवदूत</h3>\n<p>जेव्हा वैयक्तिक बचत कमी होते, तेव्हा संस्थापक विश्वास ठेवणाऱ्या लोकांकडे वळतात <em>त्यांना</em>: प्रथम मित्र आणि कुटुंब, नंतर <strong>देवदूत गुंतवणूकदार</strong>, श्रीमंत व्यक्ती जे त्यांच्या स्वत: च्या पैशाने अगदी सुरुवातीच्या स्टार्टअप्सला पाठीशी घालतात, बहुतेकदा रु. 25 लाख ते काही कोटी, थोड्या मालकीच्या भागिदारीच्या बदल्यात. एक विजेता सर्व गमावलेल्यांसाठी पैसे देईल या आशेने देवदूत प्रचंड जोखीम घेतात (बहुतेक लवकर स्टार्टअप अयशस्वी होतात).</p>\n<h3 id=\"rung-3-venture-capital\">Rung 3, उद्यम भांडवल</h3>\n<p>इथेच तो गंभीर होतो. <strong>उद्यम भांडवल (VC)</strong> फर्म हे व्यावसायिक गुंतवणूकदार असतात जे मोठ्या संस्थांकडून पैसे गोळा करतात आणि ते टप्प्याटप्प्याने आशादायक स्टार्टअप्समध्ये गुंतवतात. <strong>फेऱ्या</strong>:</p>\n<ul>\n<li><strong>बी</strong>, कल्पना कार्य करते हे सिद्ध करणारा पहिला संस्थात्मक धनादेश.</li>\n<li><strong>मालिका ए</strong>, लवकर ट्रॅक्शन झाल्यावर पुनरावृत्ती करण्यायोग्य व्यवसाय तयार करण्यासाठी.</li>\n<li><strong>मालिका B, C, D...</strong>, जलद स्केल करण्यासाठी, नवीन शहरांमध्ये प्रवेश करण्यासाठी, सैन्य नियुक्त करण्यासाठी आणि प्रतिस्पर्ध्यांना चिरडण्यासाठी उत्तरोत्तर मोठ्या फेऱ्या.</li>\n</ul>\n<p>प्रत्येक अक्षरी फेरीत विशेषत: शेवटच्या पेक्षा जास्त मुल्यांकनावर जास्त पैसे जमा होतात. VC हे धर्मादाय संस्था नाहीत, त्यांना कंपनी खूप मौल्यवान बनवायची आहे त्यामुळे त्यांची हिस्सेदारी वाढेल.</p>\n<h3 id=\"rung-4-private-equity\">रंग 4, खाजगी इक्विटी</h3>\n<p>जसजशी कंपनी परिपक्व होते, तसतसे मोठे होते <strong>खाजगी इक्विटी (PE)</strong> कंपन्या गुंतवणूक करू शकतात, आता-स्थापित, अनेकदा फायदेशीर व्यवसायात खूप मोठे धनादेश लिहून. PE पैसे नंतर येतात, मोठ्या प्रमाणात, जंगली सुरुवातीच्या दिवसांपेक्षा कमी धोका असतो.</p>\n<h3 id=\"rung-5-the-ipo\">रंग 5, IPO</h3>\n<p>शेवटी, कंपनी शेअर्स विकू शकते <em>सार्वजनिक</em> द्वारे प्रथमच <strong>प्रारंभिक सार्वजनिक ऑफर (IPO)</strong>, आणि एक्सचेंजवर सूची. ही शिडीचा सर्वात वरचा भाग आहे, ज्या क्षणी एखादी खाजगी कंपनी सार्वजनिक बनते ज्याची तुम्ही आणि इतर लाखो लोक मालकी घेऊ शकतात. आम्ही पुढील संपूर्ण अध्याय त्याला समर्पित करतो.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>जसजसे तुम्ही चढता तसतसे नावे आकारात वाढतात: देवदूत गुंतवणूक करतात <strong>लाख ते काही कोटी</strong>, VC गुंतवणूक करतात <strong>कोटी ते शेकडो कोटी</strong>, PE कंपन्या आणि IPO मध्ये व्यवहार करतात <strong>शेकडो ते हजारो कोटी</strong>. मोठा पल्ला, मोठा चेक, मोठी कंपनी.</p>\n</div></div>\n<h2 id=\"valuation-what-is-a-company-worth\">मूल्यांकन: कंपनी \"मूल्य\" काय आहे?</h2>\n<p>प्रत्येक टप्प्यावर, दोन पक्ष एका जादुई क्रमांकावर भांडण करतात: कंपनीचे <strong>मूल्यांकन</strong>, संपूर्ण व्यवसायाची किंमत किती आहे याचा अंदाज <em>आज</em>. हे तंतोतंत तथ्य नसून महसूल, वाढीचा दर, बाजाराचा आकार, संघ आणि गुंतवणूकदारांना किती वाईट रीतीने हवे आहे यावर आधारित वाटाघाटी केलेले मत आहे.</p>\n<p>मूल्यांकन एका साध्या नियमाद्वारे केले जाते. जर गुंतवणूकदारांनी 10 कोटी रुपये ठेवले आणि कंपनीचे 20% मिळवले, तर त्यांनी स्पष्टपणे <em>संपूर्ण</em> कंपनी रु. 50 कोटी (कारण रु. 10 कोटी रु. 50 कोटीच्या 20% आहेत). हे वारंवार करा, आणि स्टार्टअपचे मूल्यांकन काही कोटींपासून हजारो कोटींपर्यंत वाढू शकते, कारण प्रत्येक नवीन गुंतवणूकदार शेवटच्यापेक्षा जास्त पैसे देतो, त्यामुळे व्यवसाय वाढतच जातो.</p>\n<p>एक स्टार्टअप जे मूल्यांकन ओलांडते <strong>एक अब्ज US डॉलर</strong> (अंदाजे रु. 8,000-8,500 कोटी) एक विशेष टोपणनाव मिळवते: a <strong>युनिकॉर्न</strong>, असे म्हणतात कारण अशा कंपन्या एकेकाळी पौराणिक पशूसारख्या दुर्मिळ मानल्या जात होत्या.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>\"युनिकॉर्न\" हा शब्द 2013 मध्ये तयार करण्यात आला कारण अब्ज डॉलर्स स्टार्टअप्स जवळजवळ पौराणिकदृष्ट्या दुर्मिळ मानले जात होते. ते आता इतके दुर्मिळ नाहीत, <strong>एकट्या भारतात 100 पेक्षा जास्त युनिकॉर्न आहेत</strong> 2026 पर्यंत, पृथ्वीवरील सर्वात मोठ्या स्टार्टअप इकोसिस्टमपैकी एक. पशू आहे, तो बाहेर वळते, गुणाकार.</p>\n</div></div>\n<h2 id=\"dilution-giving-up-a-slice-to-grow-the-pie\">पातळ करणे: पाई वाढवण्यासाठी स्लाइस सोडणे</h2>\n<p>येथे प्रत्येक फंडिंग फेरीच्या केंद्रस्थानी व्यापार आहे. गुंतवणुकदाराचे पैसे मिळवण्यासाठी, संस्थापकांना सुपूर्द करणे आवश्यक आहे <strong>नवीन शेअर्स</strong>, ज्याचा अर्थ त्यांचा <em>स्वतःचे</em> मालकीची टक्केवारी कमी होते. याला आकुंचन म्हणतात <strong>सौम्य करणे</strong>.</p>\n<p>हे वेदनादायक वाटते आणि नवशिक्या सहसा मागे हटतात: संस्थापक मालकी का देत राहतील? उत्तर हे स्टार्टअप फायनान्समधील सर्वात बुद्धिमान कल्पना आहे: <strong>मोठ्या पाईचा एक लहान तुकडा लहान पाईच्या मोठ्या तुकड्यापेक्षा जास्त चांगला आहे.</strong> प्रत्येक फेरी संस्थापकांची टक्केवारी कमी करते परंतु इंधन ओतते (जर ते कार्य करते तर) कंपनी इतकी वाढवते की <em>मूल्य</em> त्यांचे छोटे तुकडे वाढतच राहतात.</p>\n<p>प्रत्येक गोष्टीची मालकी सुरू करणाऱ्या संस्थापकासाठी ते कसे चालते ते पहा:</p>\n<table>\n<thead>\n<tr>\n<th>स्टेज</th>\n<th align=\"right\">कंपनीचे मूल्यांकन (अंदाजे)</th>\n<th align=\"right\">संस्थापकाची मालकी</th>\n<th align=\"right\">संस्थापकाच्या स्टेकचे मूल्य</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>बूटस्ट्रॅप्ड</td>\n<td align=\"right\">2 कोटी रु</td>\n<td align=\"right\">100%</td>\n<td align=\"right\">2 कोटी रु</td>\n</tr>\n<tr>\n<td>बीज फेरी नंतर</td>\n<td align=\"right\">20 कोटी रु</td>\n<td align=\"right\">75%</td>\n<td align=\"right\">15 कोटी रु</td>\n</tr>\n<tr>\n<td>मालिका ए नंतर</td>\n<td align=\"right\">100 कोटी रु</td>\n<td align=\"right\">55%</td>\n<td align=\"right\">55 कोटी रु</td>\n</tr>\n<tr>\n<td>मालिका बी नंतर</td>\n<td align=\"right\">500 कोटी रुपये</td>\n<td align=\"right\">40%</td>\n<td align=\"right\">200 कोटी रु</td>\n</tr>\n<tr>\n<td>IPO वर</td>\n<td align=\"right\">4,000 कोटी रुपये</td>\n<td align=\"right\">30%</td>\n<td align=\"right\">1,200 कोटी रुपये</td>\n</tr>\n</tbody></table>\n<p>संस्थापक च्या <em>टक्केवारी</em> 100% वरून 30% पर्यंत घसरले, परंतु <em>मूल्य</em> त्यातील स्टेक रु. 2 कोटींवरून रु. 1,200 कोटी झाला. ते म्हणजे उद्दिष्टानुसार काम करणे: मोठ्या कंपनीचा एक छोटा भाग. (यंत्रणा दर्शविण्यासाठी आकडे उदाहरणात्मक आहेत.)</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch07-valuation-dilution.png\" alt=\"एक गोष्ट सांगणाऱ्या दोन ओळी, फंडिंग फेऱ्यांमध्ये कंपनीचे मूल्यांकन मोठ्या प्रमाणात वाढत आहे, तर संस्थापकांच्या मालकीची टक्केवारी सातत्याने घसरत आहे, तरीही त्यांच्या स्टेकचे मूल्य वाढतच आहे.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>एक गोष्ट सांगणाऱ्या दोन ओळी, फंडिंग फेऱ्यांमध्ये कंपनीचे मूल्यांकन मोठ्या प्रमाणात वाढत आहे, तर संस्थापकांच्या मालकीची टक्केवारी सातत्याने घसरत आहे, तरीही त्यांच्या स्टेकचे मूल्य वाढतच आहे.</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p><strong>सौम्यता आपल्या <em>टक्केवारी</em> पण तुमचे वाढू शकते <em>मूल्य</em>.</strong> 4,000 कोटी रुपयांच्या कंपनीचे 30% मालक असलेले संस्थापक 2 कोटी रुपयांच्या 100% मालकीपेक्षा खूप श्रीमंत असतात. पैसे उभारणे म्हणजे कंपनीचे नुकसान होत नाही, तर संपूर्ण गोष्ट मोठी करण्यासाठी इंधनासाठी मालकी व्यापार करणे होय.</p>\n</div></div>\n<h2 id=\"why-go-public-at-all\">अजिबात सार्वजनिक का जावे?</h2>\n<p>जर व्हेंचर कॅपिटल आणि प्रायव्हेट इक्विटी आधीच पैशांचा पुरवठा करत असेल, तर सार्वजनिक सूचीच्या गोंगाट आणि छाननीचा त्रास का? मूठभर शक्तिशाली कारणांसाठी कंपन्या सार्वजनिक होतात:</p>\n<ul>\n<li><strong>मोठे भांडवल उभारावे</strong>, एक IPO एकाच वेळी शेकडो किंवा हजारो कोटी आणू शकतो, बहुतेक खाजगी फेऱ्यांपेक्षा कितीतरी जास्त, विस्तारासाठी निधी देण्यासाठी किंवा कर्ज फेडण्यासाठी.</li>\n<li><strong>लवकर गुंतवणूकदार आणि कर्मचाऱ्यांना बाहेर पडू द्या</strong>, देवदूत, व्हीसी आणि स्टॉक पर्यायांसह कर्मचारी शेवटी सार्वजनिक बाजार मिळवतात जेथे ते त्यांचे शेअर्स विकू शकतात आणि कागदावर अनेक वर्षांचा नफा मिळवू शकतात.</li>\n<li><strong>प्रतिष्ठा आणि दृश्यमानता</strong>, सूचीबद्ध केल्यामुळे विश्वासार्हता, माध्यमांचे लक्ष आणि ग्राहक, सावकार आणि भविष्यातील नोकरदारांकडून विश्वास प्राप्त होतो.</li>\n</ul>\n<p>दुसरी बाजू खरी आहे: सार्वजनिक कंपन्यांनी प्रत्येक तिमाहीत निकाल जाहीर केले पाहिजेत, हजारो भागधारकांना उत्तर दिले पाहिजे आणि त्यांना दररोज न्याय देणाऱ्या शेअरच्या किंमतीसह जगले पाहिजे. सार्वजनिक जाणे हा भांडवल आणि तरलतेसाठी गोपनीयतेचा व्यापार आहे.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>एक वाढत्या खाजगी मूल्यांकन आहे <em>नाही</em> IPO सार्वजनिक गुंतवणूकदारांना बक्षीस देईल असे वचन. अनेक समृद्ध मूल्यवान स्टार्टअप्सनी सूचीबद्ध केले आणि नंतर सार्वजनिक गुंतवणूकदारांनी केवळ वाढीच्या कथाच नव्हे तर नफ्याची मागणी केली तेव्हा त्यांच्या शेअर्सच्या किमतीत मोठी घसरण झाली. उच्च अंतिम फेरीचे मूल्यांकन हे आतल्यांचे मत असते, तुमच्यासाठी हमी नसते. पुढील प्रकरणात आपण आयपीओचे काळजीपूर्वक परीक्षण करू.</p>\n</div></div>\n<h2 id=\"india-s-startup-decade\">भारताचे स्टार्टअप दशक</h2>\n<p>ही संपूर्ण शिडी भारतात नेत्रदीपकपणे जिवंत झाली आहे. एका दशकात स्टार्टअप्सची लाट कल्पनेपासून सूचीपर्यंत चढली आहे. <strong>Zomato</strong>, 2008 मध्ये स्थापित, 2021 मध्ये त्याच्या ब्लॉकबस्टर IPO आधी अनेक वर्षे एंजेल आणि VC पैसे चालवले. <strong>स्विगी</strong> 2024 च्या उत्तरार्धात एक्स्चेंजवर त्याच्या प्रतिस्पर्ध्याचे अनुसरण केले. परिणाम म्हणजे एक परिसंस्था <strong>100 पेक्षा जास्त युनिकॉर्न</strong> आणि सार्वजनिक बाजारपेठेच्या दिशेने एक स्थिर पाइपलाइन परिपक्व होत आहे. तुमच्यासाठी, गुंतवणूकदार, हे महत्त्वाचे आहे: आजचे खाजगी प्रवास हे उद्याचे सूचीबद्ध स्टॉक आहेत.</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">खरे उदाहरण</span><div><p><strong>Zomato चा चाप एका ओळीत:</strong> 2008 ची रेस्टॉरंट-लिस्टिंग वेबसाइट, अनेक वर्षांच्या तोट्यातून देवदूत आणि VCs द्वारे राउंड नंतर निधी, 2021 मध्ये भारतातील सर्वात जास्त पाहिल्या गेलेल्या IPO मध्ये सार्वजनिकपणे सूचीबद्ध केले गेले, सुरुवातीच्या खाजगी पाठीराख्यांना सार्वजनिक भागधारकांमध्ये बदलले आणि सामान्य गुंतवणूकदारांना शेवटी एक तुकडा मालकी द्या. पूर्ण निधीची शिडी, सार्वजनिक दृश्यात चढली.</p>\n</div></div>\n<h2 id=\"quick-recap\">क्विक रिकॅप</h2>\n<ul>\n<li>प्रत्येक सूचीबद्ध राक्षस लहान सुरुवात केली आणि एक चढला <strong>निधी शिडी</strong>: कल्पना, बूटस्ट्रॅपिंग, मित्र/family आणि <strong>देवदूत</strong>, <strong>उद्यम भांडवल</strong> (बियाणे, मालिका A/B/C...), <strong>खाजगी इक्विटी</strong>, आणि शेवटी एक <strong>IPO</strong>.</li>\n<li>प्रत्येक पंक्ती मोठ्या स्त्रोताकडून अधिक पैसे गोळा करते, लाखोंमध्ये देवदूत, कोटींमध्ये VC, PE आणि IPO शेकडो ते हजारो कोटींमध्ये.</li>\n<li><strong>मूल्यमापन</strong> संपूर्ण कंपनीची किंमत किती आहे याचा वाटाघाटी केलेला अंदाज आहे; तो फुगा फिरवू शकतो, आणि अब्ज डॉलर्सच्या स्टार्टअपला a म्हणतात <strong>युनिकॉर्न</strong>.</li>\n<li><strong>सौम्य करणे</strong> संस्थापकांचे आकुंचन <em>टक्केवारी</em> पण वाढू शकते <em>मूल्य</em> त्यांच्या स्टेकचा, एका मोठ्या पाईचा एक छोटा तुकडा एका छोट्या मोठ्या स्लाइसला मारतो.</li>\n<li>कंपन्या सार्वजनिक जातात <strong>मोठे भांडवल उभे करा, लवकर गुंतवणूकदारांना बाहेर पडू द्या आणि प्रतिष्ठा मिळवा</strong>, सतत प्रकटीकरण आणि छाननीच्या खर्चावर.</li>\n<li>भारताकडे आता आहे <strong>100 पेक्षा जास्त युनिकॉर्न</strong>, आणि Zomato आणि Swiggy सारखे अलीकडील प्रवास स्टार्टअपपासून स्टॉकपर्यंत पूर्ण शिडी चढलेले दाखवतात.</li>\n</ul>\n<p>पुढे, आम्ही अंतिम पंक्तीवर झूम वाढवतो <strong>IPO</strong> स्वतः: एखादी कंपनी प्रत्यक्षात कशी सार्वजनिक होते, किंमत बँड आणि लॉट साइजचा अर्थ काय आणि तुम्ही शेअर्ससाठी अर्ज कसा करू शकता.</p>\n","toc":[{"level":2,"text":"निधीची शिडी","id":"the-funding-ladder"},{"level":3,"text":"रंग 0, कल्पना","id":"rung-0-the-idea"},{"level":3,"text":"रंग 1, बूटस्ट्रॅपिंग","id":"rung-1-bootstrapping"},{"level":3,"text":"रंग 2, मित्र, कुटुंब आणि देवदूत","id":"rung-2-friends-family-and-angels"},{"level":3,"text":"Rung 3, उद्यम भांडवल","id":"rung-3-venture-capital"},{"level":3,"text":"रंग 4, खाजगी इक्विटी","id":"rung-4-private-equity"},{"level":3,"text":"रंग 5, IPO","id":"rung-5-the-ipo"},{"level":2,"text":"मूल्यांकन: कंपनी \"मूल्य\" काय आहे?","id":"valuation-what-is-a-company-worth"},{"level":2,"text":"पातळ करणे: पाई वाढवण्यासाठी स्लाइस सोडणे","id":"dilution-giving-up-a-slice-to-grow-the-pie"},{"level":2,"text":"अजिबात सार्वजनिक का जावे?","id":"why-go-public-at-all"},{"level":2,"text":"भारताचे स्टार्टअप दशक","id":"india-s-startup-decade"},{"level":2,"text":"क्विक रिकॅप","id":"quick-recap"}],"imgCount":2,"hasContent":true},"8":{"html":"<p>तुम्ही ह्युंदाई कारमध्ये प्रवास केला असेल, स्विगीवर डिनरची ऑर्डर दिली असेल किंवा विशाल मेगा मार्टमधून फिरला असेल. वर्षानुवर्षे यापैकी प्रत्येक ए <em>खाजगी</em> कंपनी, तिच्या संस्थापकांच्या मालकीची आणि गुंतवणुकदारांच्या एका छोट्या मंडळाची, तिचे शेअर्स सामान्य व्यक्तीला विकत घेणे अशक्य आहे. त्यानंतर, एका विशिष्ट सकाळी, ते बदलले: त्यांचे शेअर्स NSE आणि BSE वर दिसू लागले आणि डीमॅट खाते असलेल्या कोणालाही एक स्लाइस मिळू शकतो. त्या सकाळला ए <strong>सूची</strong>, आणि त्यापर्यंत नेणाऱ्या अनेक महिन्यांच्या प्रवासाला तुम्ही नक्कीच ऐकले असेल, द <strong>IPO</strong>, किंवा प्रारंभिक सार्वजनिक ऑफर.</p>\n<p>IPO ही बाजारातील सर्वात रोमांचक आणि सर्वात गैरसमज असलेल्या घटनांपैकी एक आहे. वृत्तपत्रे \"लिस्टिंग नफा\" बद्दल ओरडतात, WhatsApp गट \"ग्रे मार्केट प्रीमियम\" बद्दल कुजबुजतात आणि नवशिक्या लवकर दुप्पट होण्याच्या आशेवर असतात. हा धडा तुम्हाला संपूर्ण प्रक्रियेत शांतपणे घेऊन जातो, कंपनीने शेअर केलेल्या पहिल्या जाड दस्तऐवजापासून ते स्टॉक ट्रेडिंग सुरू होण्याच्या क्षणापर्यंत, त्यामुळे तुम्ही प्रत्यक्षात कशासाठी अर्ज करत आहात हे तुम्हाला समजते.</p>\n<h2 id=\"what-an-ipo-actually-is\">IPO प्रत्यक्षात काय आहे</h2>\n<p>जेव्हा एखादी कंपनी प्रथमच सामान्य लोकांना आपले शेअर्स विकते तेव्हा ती \"सार्वजनिक\" होते. तोपर्यंत संस्थापक, देवदूत, उद्यम भांडवल, खाजगी इक्विटी (आम्ही शेवटचा अध्याय शोधलेला प्रवास) कडून खाजगीरित्या पैसे उभे केले. एक IPO ती मालकी प्रत्येकासाठी उघडते आणि त्या बदल्यात, कंपनी स्टॉक एक्स्चेंजमध्ये सर्व छाननी, प्रकटीकरण आणि शिस्त आणते.</p>\n<p>IPO आत घडणाऱ्या दोन वेगळ्या गोष्टी आहेत आणि त्या खूप महत्त्वाच्या आहेत:</p>\n<ul>\n<li><strong>ताजा मुद्दा.</strong> कंपनी अगदी नवीन समभाग तयार करते आणि त्यांची विक्री करते, म्हणून <em>कंपनीत पैसा येतो</em> वाढीसाठी निधी, कर्ज फेडणे किंवा कारखाने बांधणे.</li>\n<li><strong>विक्रीसाठी ऑफर (OFS).</strong> विद्यमान मालक, संस्थापक, प्रारंभिक गुंतवणूकदार, काही विकतात <em>त्यांचे</em> शेअर्स, त्यामुळे द <em>पैसा त्यांच्याकडे जातो</em>, कंपनी नाही. व्यवसायात नवीन काही मिळत नाही; विक्रेता फक्त पैसे काढतो.</li>\n</ul>\n<p>अनेक आयपीओ दोन्हीचे मिश्रण आहेत. कोणते हे जाणून घेणे योग्य आहे: नवीन इश्यू कंपनीच्या भविष्यासाठी निधी देतो; शुद्ध OFS हे वृद्ध गुंतवणूकदार आहेत जे बाहेर पडण्याच्या मार्गावर आहेत.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>IPO मध्ये घडते <strong>प्राथमिक बाजार</strong>, शेअर्स पहिल्यांदा विकले. प्रत्येक व्यापार <em>नंतर</em> मध्ये सूची होते <strong>दुय्यम बाजार</strong>, गुंतवणूकदारांमध्ये, कंपनीकडे पैसेच जात नाहीत. सूचीच्या दिवशी खरेदी करणे आधीच दुय्यम बाजार आहे.</p>\n</div></div>\n<h2 id=\"the-paperwork-drhp-and-rhp\">कागदपत्र: DRHP आणि RHP</h2>\n<p>कंपनी तुमच्या पैशाची मागणी करण्यापूर्वी, कंपनीने तुम्हाला स्वतःबद्दल जवळजवळ सर्व काही सांगणे आवश्यक आहे. हे SEBI सह दाखल केलेल्या जाड दस्तऐवजात करते.</p>\n<ul>\n<li>द <strong>DRHP</strong> (ड्राफ्ट रेड हेरिंग प्रॉस्पेक्टस) आहे <em>मसुदा</em> आवृत्ती, प्रथम दाखल करा आणि सार्वजनिक टिप्पणीसाठी ऑनलाइन ठेवा. SEBI त्याचे पुनरावलोकन करते आणि प्रश्न परत पाठवते.</li>\n<li>द <strong>RHP</strong> (रेड हेरिंग प्रॉस्पेक्टस) ही इश्यू उघडण्यापूर्वी दाखल केलेली जवळपास अंतिम आवृत्ती आहे, ज्यामध्ये आता किंमत बँड आणि तारखा आहेत.</li>\n</ul>\n<p>दस्तऐवज मुद्दाम कारण \"रेड हेरिंग\" वाक्यांश टिकून आहे <em>शेवटच्या क्षणापर्यंत एक महत्त्वाचे तथ्य वगळले</em>, अंतिम किंमत. ती गहाळ किंमत \"रेड हेरिंग\" आहे.</p>\n<p>तुम्हाला सर्व 600 पाने वाचण्याची गरज नाही. हे विभाग स्किम करा:</p>\n<ul>\n<li><strong>समस्येच्या वस्तू</strong>, नक्की पैसा कुठे जातो (वास्तविक वाढ, किंवा मुख्यतः एक OFS बाहेर पडा?).</li>\n<li><strong>जोखीम घटक</strong>, काय चूक होऊ शकते याची कंपनीची स्वतःची प्रामाणिक यादी.</li>\n<li><strong>आर्थिक</strong>, महसूल वाढत आहे का? तो प्रत्यक्षात फायदेशीर आहे, की रोख बर्निंग?</li>\n<li><strong>प्रवर्तक धारण</strong>, यादी केल्यानंतर संस्थापकांनी किती त्वचा ठेवली.</li>\n<li><strong>इश्यू किमतीचा आधार</strong>, मूल्यमापन, आणि त्याची P/E′ सूचीबद्ध समवयस्कांशी कशी तुलना करते.</li>\n</ul>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>जोखीम घटक वाचा <em>प्रथम</em>, शेवटचे नाही. कंपनीच्या संरक्षणासाठी ते कंपनीच्या स्वतःच्या वकिलांनी लिहिलेले आहेत, म्हणून ते असामान्यपणे स्पष्ट आहेत. जर तुम्हाला खरोखरच जोखीम वाटत असेल तर, सूची-दिवसाच्या कोणत्याही प्रचाराने तुमचा विचार बदलू नये.</p>\n</div></div>\n<h2 id=\"book-building-and-the-price-band\">बुक-बिल्डिंग आणि किंमत बँड</h2>\n<p>बहुतेक मोठे IPO वापरतात <strong>पुस्तक इमारत</strong>: एक किंमत निश्चित करण्याऐवजी, कंपनी ऑफर करते अ <strong>किंमत बँड</strong>, 700 ते 740 रुपये प्रति शेअर (2025 मध्येHDB′ वित्तीय सेवांसाठी वास्तविक बँड) म्हणा आणि मागणीला अंतिम क्रमांक शोधू द्या. तीन दिवसांच्या खिडकीमध्ये, गुंतवणूकदार बँडमध्ये किंमतींवर बोली लावतात. एकदा ते बंद झाल्यावर, कंपनी एकल सेट करते <strong>कट ऑफ किंमत</strong> ज्यावर शेअर्सचे वाटप केले जाते.</p>\n<p>किरकोळ गुंतवणूकदार म्हणून तुम्ही फक्त \"कट-ऑफवर\" बोली लावू शकता, म्हणजे अंतिम किंमत ठरलेली कोणतीही रक्कम देण्यास तुम्ही सहमत आहात. अशा प्रकारे बँडच्या शीर्षस्थानी किंमत निश्चित केली असली तरीही तुमचा अर्ज वैध राहील.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch08-ipo-process-flow.png\" alt=\"IPO खाजगी कंपनीचा प्रवास DRHP सह SEBI, RHP आणि प्राइस बँडद्वारे, तीन दिवसांची बुक-बिल्डिंग विंडो, वाटप आणि शेवटी एक्सचेंजवर सूचीबद्ध दिवस.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">फ्लो चार्ट</span>IPO खाजगी कंपनीचा प्रवास DRHP सह SEBI, RHP आणि प्राइस बँडद्वारे, तीन दिवसांची बुक-बिल्डिंग विंडो, वाटप आणि शेवटी एक्सचेंजवर सूचीबद्ध करण्याचा दिवस.</figcaption></figure>\n<h2 id=\"lot-size-upi-and-the-money-that-gets-blocked\">लॉट साइज, UPI आणि ब्लॉक केलेले पैसे</h2>\n<p>तुम्ही एकाच शेअरसाठी अर्ज करू शकत नाही. IPOs मध्ये विकले जातात <strong>खूप</strong>, एक निश्चित बंडल. SEBI एक किरकोळ लॉट अंदाजे मूल्य ठेवते <strong>14,000-15,000 रु</strong> (अंदाजे), त्यामुळे रु. 740 चा शेअर कदाचित 20 मध्ये येऊ शकतो. तो तुमचा किमान अर्ज आहे; तुम्ही रु. 2 लाख किरकोळ मर्यादेपर्यंत अधिक लॉटसाठी अर्ज करू शकता.</p>\n<p>नवशिक्यांना समजल्यानंतर त्यांना आवडणारा भाग येथे आहे. तुम्ही माध्यमातून अर्ज करा <strong>ASBA</strong>, ब्लॉक केलेल्या रकमेद्वारे समर्थित अर्ज. वापरून a <strong>UPI आदेश</strong>, तुमचा अर्ज <em>ब्लॉक</em> तुमच्या स्वतःच्या बँक खात्यात पैसे; आहे <strong>डेबिट केलेले नाही</strong>. वाटपाचा निर्णय होईपर्यंत रोख गोठलेली आहे, तरीही तुमचे बचत व्याज मिळत आहे.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>कारण पैसे फक्त ब्लॉक केलेले आहेत, पैसे दिलेले नाहीत, जर तुम्हाला शेअर्स मिळाले नाहीत तर IPO साठी अर्ज केल्याने तुम्हाला काहीही लागत नाही. आपण असल्यास <strong>नाही</strong> वाटप झाले, ब्लॉक सहज सोडला जाईल आणि पैसे पुन्हा तुमचे आहेत. जर तुम्ही <em>आहेत</em> वाटप केले, तरच ते डेबिट केले जाते. वाटप नाही, तोटा नाही.</p>\n</div></div>\n<h2 id=\"allotment-and-oversubscription\">वाटप आणि ओव्हरसबस्क्रिप्शन</h2>\n<p>शेअर्सपेक्षा चांगल्या IPO ला जास्त मागणी असते <strong>ओव्हरसबस्क्रिप्शन</strong>. एक IPO \"40 वेळा सदस्यत्व घेतले\" ला ऑफरवरील शेअर्सच्या चाळीस पट बोली प्राप्त झाली. असे झाल्यावर, किरकोळ गुंतवणूकदार सर्वच समाधानी होऊ शकत नाहीत, म्हणून वाटप अ <strong>संगणकीकृत लॉटरी</strong>: प्रत्येक अर्जदाराला प्रति लॉट एक एंट्री मानली जाते आणि यादृच्छिक सोडतीने ठरवले जाते की किमान एक लॉट कोणाला मिळेल. दहा लॉटसाठी अर्ज केल्याने त्या पहिल्या लॉटची तुमची शक्यता सुधारत नाही, प्रत्येकजण त्यासाठी समान स्पर्धा करतो.</p>\n<h2 id=\"listing-day-and-listing-gains\">लिस्टिंग दिवस आणि \"लिस्टिंग नफा\"</h2>\n<p>लिस्टिंगच्या दिवशी स्टॉकचा व्यापार सुरू होतो आणि इश्यू किंमत आणि सुरुवातीची किंमत यांच्यातील अंतर प्रसिद्ध आहे <strong>यादी नफा</strong> (किंवा नुकसान). त्यानंतर आलेले मथळे खरे आहेत, पण धोकाही आहे.</p>\n<table>\n<thead>\n<tr>\n<th>IPO (इश्यू किंमत -&gt; सूची किंमत)</th>\n<th align=\"right\">लिस्टिंग दिवस हलवा (अंदाजे)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>बजाज हाउसिंग फायनान्स (रु. 70 -&gt; रु. 150)</td>\n<td align=\"right\">सुमारे +114%</td>\n</tr>\n<tr>\n<td>LG इलेक्ट्रॉनिक्स इंडिया (2025)</td>\n<td align=\"right\">सुमारे +50%</td>\n</tr>\n<tr>\n<td>विशाल मेगा मार्ट (रु. 78 -&gt; रु. 112)</td>\n<td align=\"right\">सुमारे +44%</td>\n</tr>\n<tr>\n<td>HDB वित्तीय सेवा (रु. 740 -&gt; रु 835)</td>\n<td align=\"right\">सुमारे +13%</td>\n</tr>\n<tr>\n<td>स्विगी (रु. 420 जवळ सूचीबद्ध)</td>\n<td align=\"right\">सुमारे +8%</td>\n</tr>\n<tr>\n<td>Hyundai Motor India (रु. 1,960 -&gt; रु 1,934)</td>\n<td align=\"right\">सुमारे -1% (एक फ्लॉप)</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>Hyundai Motor India ची 2024 IPO होती <strong>भारतीय इतिहासातील सर्वात मोठे अंदाजे रु. 27,860 कोटी</strong>, आणि ते <em>पडले</em> सूचीच्या दिवशी. दरम्यान, बजाज हाऊसिंग फायनान्स पदार्पणात दुप्पट झाला, त्यानंतर पुढील महिन्यांत सुमारे 26% खाली आला. धडा एकाच टेबलमध्ये बसतो: मोठे नाव पॉपची हमी नाही आणि पॉप टिकेल याची हमी नाही.</p>\n</div></div>\n<h2 id=\"the-grey-market-premium-handle-with-care\">ग्रे मार्केट प्रीमियम, काळजीपूर्वक हाताळा</h2>\n<p>सूची करण्यापूर्वी, एक अनधिकृत <strong>राखाडी बाजार</strong> अवतरण a <strong>GMP</strong> (ग्रे मार्केट प्रीमियम), एक अफवा असलेली किंमत ज्यावर अद्याप सूचीबद्ध नसलेले शेअर्स \"ट्रेडिंग\" आहेत. हे टेलीग्राम समूहांमध्ये नफ्याच्या यादीसाठी क्रिस्टल बॉल म्हणून कुजबुजले जाते.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>ग्रे मार्केट आहे <strong>अनधिकृत, अनियंत्रित आणि SEBI द्वारे परीक्षण केलेले नाही</strong>. कोणतीही देवाणघेवाण नाही, सेटलमेंट गॅरंटी नाही, तक्रार निवारण नाही, निनावी डीलर्समध्ये फक्त विश्वास आहे. GMP आकड्यांमध्ये हाईप तयार करण्यासाठी सहजपणे हेराफेरी केली जाते आणि SEBI ने गुंतवणूकदारांना अनधिकृत प्लॅटफॉर्मवर असूचीबद्ध शेअर्सची ट्रेडिंग करण्यापासून वारंवार चेतावणी दिली आहे.GMP′ ला गपशप समजा, गुंतवणुकीचे कारण नाही. SEBI हा गोंधळलेला कोपरा बदलण्यासाठी तंतोतंत अधिकृत \"वेन-लिस्टेड\" ट्रेडिंग विंडो तयार करत आहे.</p>\n</div></div>\n<h2 id=\"decoding-the-ipo-jargon\">IPO शब्दजाल डीकोड करणे</h2>\n<p>प्रत्येक IPO वेगवेगळ्या प्रकारच्या गुंतवणूकदारांसाठी राखीव बकेटमध्ये विभागले गेले आहे. मानक पुस्तक-निर्मित विभाजन असे दिसते:</p>\n<table>\n<thead>\n<tr>\n<th>श्रेणी</th>\n<th>ते कोण आहेत</th>\n<th>ठराविक आरक्षण</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>QIB</strong> (पात्र संस्थात्मक खरेदीदार)</td>\n<td>म्युच्युअल फंड, बँका, विमा कंपन्या, FII</td>\n<td>५०% पर्यंत</td>\n</tr>\n<tr>\n<td><strong>NII / HNI</strong> (गैर-संस्थात्मक गुंतवणूकदार)</td>\n<td>2 लाखांपेक्षा जास्त अर्ज करणाऱ्या व्यक्ती</td>\n<td>किमान 15%</td>\n</tr>\n<tr>\n<td><strong>किरकोळ (RII)</strong></td>\n<td>तुम्ही, रु. 2 लाखांपर्यंतचे अर्ज</td>\n<td>किमान 35%</td>\n</tr>\n</tbody></table>\n<p><strong>अँकर गुंतवणूकदार</strong> QIB कोटा (त्यातील 60% पर्यंत) कोरलेले एक विशेष स्लाइस आहेत. या मोठ्या, मार्की संस्था आहेत ज्यांना वचनबद्धतेसाठी आमंत्रित केले आहे <em>आदल्या दिवशी</em> IPO उघडतो, त्यांचा सहभाग इतर प्रत्येकासाठी आत्मविश्वास दर्शवतो. त्यांना जलद नफ्यासाठी फ्लिप करणे थांबविण्यासाठी, त्यांचे शेअर्स आहेत <strong>लॉक इन</strong> (अर्धा ३० दिवस, अर्धा ९० दिवस).</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch08-investor-categories.png\" alt=\"पुस्तक-निर्मित IPO, अँकर आणि QIB संस्था, गैर-संस्थात्मक HNIs आणि किरकोळ कोटा, प्रत्येक श्रेणीला मिळणारा ढोबळ वाटा दर्शविते कसे विभाजित केले आहे\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">इन्फोग्राफिक</span>पुस्तक-निर्मित IPO, अँकर आणि QIB संस्था, गैर-संस्थात्मक HNIs आणि किरकोळ कोटा, प्रत्येक श्रेणीला मिळणारा ढोबळ वाटा दर्शविते कसे विभाजित केले आहे</figcaption></figure>\n<p>एक शेवटचा भेद. ए <strong>मेनबोर्ड IPO</strong> संपूर्ण प्रकटीकरणासह मुख्य NSE/BSE प्लॅटफॉर्मवर सूचीबद्ध असलेली एक मोठी कंपनी आहे. अ <strong>SME IPO</strong> समर्पित NSE इमर्ज किंवा BSE SME प्लॅटफॉर्मवर एक लहान व्यवसाय सूची आहे, हलक्या नियमांसह आणि खूप मोठा किमान अनुप्रयोग (अनेकदा एक लाखापेक्षा जास्त). SME IPO नाटकीय हालचाली, वर आणि खाली, आणि अनुभवी गुंतवणूकदारांना अनुकूल करू शकतात, प्रथम-समर्थक नाही.</p>\n<p>उन्माद परिप्रेक्ष्य मध्ये ठेवण्यासाठी: 2024 हे विक्रमी वर्ष होते ज्यामध्ये सुमारे 91 मेनबोर्ड IPO ने अंदाजे 1.6 लाख कोटी रुपये उभारले होते आणि 100 पेक्षा जास्त मेनबोर्ड समस्यांसह 2025 अजून मोठे होते. जेव्हा एवढा पैसा नवीन सूचींचा पाठलाग करतो, तेव्हा हाईप गरम होते आणि तुमचा खरा बचाव हा कंटाळवाणा सामग्री आहे: RHP, आर्थिक आणि किंमत.</p>\n<h2 id=\"quick-recap\">क्विक रिकॅप</h2>\n<ul>\n<li>अ <strong>IPO</strong> मध्ये प्रथमच कंपनीचे शेअर्स जनतेला विकतात <strong>प्राथमिक बाजार</strong>; सूचीकरणानंतरचे सर्व व्यवहार दुय्यम आहेत.</li>\n<li>ए <strong>ताजी समस्या</strong> कंपनीला निधी; एक <strong>OFS</strong> केवळ विद्यमान मालकांना रोखते, नेहमी कोणते वर्चस्व आहे ते तपासा.</li>\n<li>द <strong>DRHP</strong> (मसुदा) आणि <strong>RHP</strong> (अंतिम, किंमत बँडसह) तुम्हाला सर्व काही सांगा; वस्तू, जोखीम, आर्थिक आणि मूल्यांकन स्किम करा.</li>\n<li><strong>पुस्तकबांधणी</strong> बँडमध्ये किंमत शोधते; तुम्ही अर्ज करा <strong>बरेच</strong> द्वारे <strong>UPI/ASBA</strong>, पैसा कुठे आहे <em>ब्लॉक केलेले, डेबिट केलेले नाही</em>, वाटप होईपर्यंत.</li>\n<li><strong>लिस्टिंग नफ्याची हमी कधीही दिली जात नाही</strong>, अगदी भारतातील आतापर्यंतचा सर्वात मोठा IPO पदार्पण करताना पडला, आणि द <strong>ग्रे मार्केट प्रीमियम ही अनियंत्रित अफवा आहे</strong>.</li>\n<li>IPO समभागांमध्ये विभागले गेले आहेत <strong>QIB, NII आणि किरकोळ</strong>, सह <strong>अँकर गुंतवणूकदार</strong> आत्मविश्वास सिग्नल करण्यासाठी लॉक इन.</li>\n</ul>\n<p>एखादी कंपनी यादी दिल्यानंतर बाजाराला स्पर्श करणे थांबवत नाही. हे नवीन भांडवल वाढवत राहते आणि हक्काच्या समस्या, FPOs, OFS, बोनस, स्प्लिट्स आणि बायबॅक द्वारे भागधारकांना पुरस्कृत करते आणि प्रत्येकजण अशा प्रकारे शेअरची किंमत हलवतो ज्यामुळे नवशिक्याला विनाकारण घाबरवता येईल. त्या कॉर्पोरेट क्रिया डीकोड करणे म्हणजे आपण पुढे कुठे जातो.</p>\n","toc":[{"level":2,"text":"IPO प्रत्यक्षात काय आहे","id":"what-an-ipo-actually-is"},{"level":2,"text":"कागदपत्र: DRHP आणि RHP","id":"the-paperwork-drhp-and-rhp"},{"level":2,"text":"बुक-बिल्डिंग आणि किंमत बँड","id":"book-building-and-the-price-band"},{"level":2,"text":"लॉट साइज, UPI आणि ब्लॉक केलेले पैसे","id":"lot-size-upi-and-the-money-that-gets-blocked"},{"level":2,"text":"वाटप आणि ओव्हरसबस्क्रिप्शन","id":"allotment-and-oversubscription"},{"level":2,"text":"लिस्टिंग दिवस आणि \"लिस्टिंग नफा\"","id":"listing-day-and-listing-gains"},{"level":2,"text":"ग्रे मार्केट प्रीमियम, काळजीपूर्वक हाताळा","id":"the-grey-market-premium-handle-with-care"},{"level":2,"text":"IPO शब्दजाल डीकोड करणे","id":"decoding-the-ipo-jargon"},{"level":2,"text":"क्विक रिकॅप","id":"quick-recap"}],"imgCount":2,"hasContent":true},"9":{"html":"<p>कल्पना करा की तुम्ही एका सकाळी तुमचा पोर्टफोलिओ उघडला आणि तुमच्या मालकीचा स्टॉक, काल तो रु. 2,900 च्या जवळ बंद झाला म्हणा, अचानक रु. 1,450 च्या आसपास दिसत आहे. आपले पोट थेंब. कंपनी रातोरात कोसळली का? तुम्ही तुमचे अर्धे पैसे गमावले का? जवळजवळ नक्कीच नाही. तुम्ही जे बघत आहात ते आहे <strong>कॉर्पोरेट क्रिया</strong>, एक बोनस समस्या, या प्रकरणात, आणि तुमची संपत्ती काल रात्री होती तशीच आहे. तुमच्याकडे निम्म्या किमतीत दुप्पट शेअर्स आहेत.</p>\n<p>हा एकच गैरसमज कोणत्याही खऱ्या वाईट बातमीपेक्षा नवशिक्यांना चांगल्या स्टॉकपासून घाबरवतो. सूचीबद्ध कंपन्या त्यांच्या शेअर्ससाठी सतत गोष्टी करत आहेत: नवीन पैसे गोळा करणे, रोख परत करणे, त्यांचे स्टॉक विभाजित करणे, मोफत देणे. हा धडा प्रत्येक कॉर्पोरेट कृती डीकोड करतो आणि सर्वात महत्त्वाचे म्हणजे तुम्हाला दाखवतो <em>किंमतीतील बदल सहसा घाबरण्यासारखे का नाहीत.</em></p>\n<h2 id=\"two-families-of-corporate-action\">कॉर्पोरेट कारवाईची दोन कुटुंबे</h2>\n<p>या प्रकरणातील प्रत्येक गोष्ट दोन बादलींपैकी एका बादलीमध्ये येते:</p>\n<ul>\n<li><strong>अधिक पैसे उभारणे</strong>, कंपनीला (किंवा त्याचे मोठे भागधारक) भांडवल आवश्यक आहे: <strong>अधिकार समस्या, FPO, OFS</strong>.</li>\n<li><strong>पुरस्कृत किंवा आकार बदलणे</strong>, कंपनी मूल्य परत करते किंवा तिच्या शेअर्सची संख्या पुन्हा बदलते: <strong>लाभांश, बोनस, स्टॉक स्प्लिट, बायबॅक</strong>.</li>\n</ul>\n<p>चला त्या बदल्यात घेऊ.</p>\n<h2 id=\"raising-more-money\">अधिक पैसे उभारणे</h2>\n<h3 id=\"rights-issue\">हक्काचा मुद्दा</h3>\n<p>ए <strong>अधिकार समस्या</strong> ऑफर <em>नवीन</em> ला शेअर करते <em>विद्यमान</em> शेअरहोल्डर्स, सामान्यत: बाजारभावाच्या सवलतीवर, एका निश्चित प्रमाणात. \"रु. 200 वर 1:5 राइट्स\" म्हणजे तुम्ही धारण केलेल्या प्रत्येक 5 शेअर्ससाठी तुम्ही 200 रुपयांना 1 नवीन शेअर खरेदी करू शकता (बाजारातील किंमत 300 रुपये असली तरीही). तुमची मालकी कमी होण्यापासून रोखण्याचा पहिला अधिकार तुम्हाला दिला जात आहे.</p>\n<p>तुम्हाला खरेदी करण्यास भाग पाडले जात नाही. जर तुम्हाला नवीन शेअर्स नको असतील तर तुमचे <strong>हक्क हक्क</strong> एक्स्चेंजवर दुसऱ्याला विकले जाऊ शकते (ते वेगळे तात्पुरते टिकर म्हणून व्यापार करते), त्यामुळे अधिकारालाच मूल्य असते. जर तुम्ही त्याकडे दुर्लक्ष केले तर तुमचा स्टेक थोडा कमी होतो.</p>\n<h3 id=\"fpo-follow-on-further-public-offer\">FPO (फॉलो-ऑन / पुढील सार्वजनिक ऑफर)</h3>\n<p>अ <strong>FPO</strong> दुसऱ्या IPO प्रमाणे आहे: an <em>आधीच सूचीबद्ध</em> कंपनी नवीन समभाग जारी करते <em>प्रत्येकजण</em> अधिक भांडवल उभारण्यासाठी बाजारात. हक्काच्या समस्येच्या विपरीत, ते केवळ वर्तमान धारकांसाठीच नव्हे तर सामान्य लोकांसाठी खुले आहे.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>Vodafone Idea च्या 2024 FPO बद्दल वाढ झाली <strong>18,000 कोटी रुपये</strong>, भारतीय इतिहासातील सर्वात मोठी फॉलो-ऑन ऑफर. वर्षभरापूर्वी, अदानी एंटरप्रायझेसने 20,000 कोटी रुपयांचे आणखी मोठे FPO लॉन्च केले, त्यानंतर ते पूर्णतः सदस्य झाले. <em>ते रद्द केले आणि प्रत्येक रुपया परत केला</em> हिंडेनबर्ग अहवालादरम्यान स्टॉक क्रॅश झाल्यानंतर. पूर्ण झाले तरी, सदस्यता घेतलेल्या ऑफर बंद केल्या जाऊ शकतात.</p>\n</div></div>\n<h3 id=\"ofs-offer-for-sale\">OFS (विक्रीसाठी ऑफर)</h3>\n<p>एक मध्ये <strong>OFS</strong>, मोठे विद्यमान भागधारक, प्रवर्तक, सरकार, लवकर गुंतवणूकदार, विक्री <em>त्यांचे</em> देवाणघेवाण द्वारे सार्वजनिक शेअर्स. कोणतेही नवीन शेअर्स तयार केले जात नाहीत आणि कंपनीला स्वतःच काहीही मिळत नाही; पैसे विक्रेत्याकडे जातात. सार्वजनिक क्षेत्रातील कंपन्यांमधील भागभांडवल कमी करण्यासाठी सरकार नियमितपणे OFS वापरते, अनेकदा लहान <strong>रिटेलसाठी सवलत</strong> अर्जदार कारण कोणतेही नवीन शेअर्स तयार केले जात नाहीत, एक OFS करते <strong>पातळ नाही</strong> विद्यमान धारक ज्या प्रकारे नवीन इश्यू करतात, ते फक्त मालकी हस्तांतरित करते.</p>\n<h2 id=\"rewarding-and-reshaping\">पुरस्कृत आणि आकार बदलणे</h2>\n<h3 id=\"dividends\">लाभांश</h3>\n<p>ए <strong>लाभांश</strong> हा कंपनीच्या नफ्याचा एक तुकडा आहे जो रोख स्वरूपात दिला जातो, सामान्यतः काही रुपये प्रति शेअर. ते कोणाला मिळते हे जाणून घेण्यासाठी कंपनी सेट करते अ <strong>रेकॉर्ड तारीख</strong>: आधी शेअर तुमच्या मालकीचा असणे आवश्यक आहे <strong>माजी लाभांश तारीख</strong> (कट-ऑफ) पात्र होण्यासाठी. भारताच्या सध्याच्या T+1 सेटलमेंट अंतर्गत, एक्स-डेट आणि रेकॉर्ड डेट सामान्यत: एकाच दिवशी येतात, त्यामुळे साधा नियम आहे: <em>लाभांश प्राप्त करण्यासाठी एक्स-डेटच्या किमान एक दिवस आधी खरेदी करा.</em></p>\n<p>एक्स-डेटला, शेअरची किंमत सहसा उघडते <strong>अंदाजे लाभांश रक्कम कमी</strong>, कारण रोख कंपनी सोडणार आहे. रु. 1,000 चा स्टॉक रु. 10 लाभांश देणारा रु. 990 च्या जवळ उघडतो. तुम्ही रु. 10 गमावले नाहीत; ते नुकतेच शेअरच्या किमतीवरून तुमच्या बँक खात्यात गेले.</p>\n<h3 id=\"bonus-shares\">बोनस शेअर्स</h3>\n<p>ए <strong>बोनस समस्या</strong> विद्यमान भागधारकांना देते <em>मोफत</em> 1:1 सारख्या गुणोत्तरामध्ये कंपनीच्या संचित रिझर्व्हमधून अतिरिक्त शेअर्स (प्रत्येकासाठी एक विनामूल्य शेअर). पैशाचा हात बदलत नाही. कंपनीचे एकूण मूल्य बदललेले नाही, त्यामुळे किंमत प्रमाणानुसार कमी होते.</p>\n<h3 id=\"stock-split\">स्टॉक विभाजित</h3>\n<p>ए <strong>स्टॉक विभाजन</strong> प्रत्येक वाटा अनेकांमध्ये विभागतो. कंपनी कमी करते <strong>दर्शनी मूल्य</strong>, 10 रुपयांवरून 1 रुपये असे म्हणा आणि एक शेअर दहा होतो, किंमत दहाव्या भागापर्यंत घसरते. हे पूर्णपणे कॉस्मेटिक आहे, बहुतेकदा उच्च-किंमतीचा शेअर अधिक परवडणारा दिसण्यासाठी आणि अधिक सक्रियपणे व्यापार करण्यासाठी केला जातो.</p>\n<h3 id=\"buyback\">बायबॅक</h3>\n<p>ए <strong>बायबॅक</strong> ताज्या इश्यूच्या विरुद्ध आहे: कंपनी स्वतःची रोख रक्कम यासाठी वापरते <em>परत खरेदी</em> आणि त्याचे शेअर्स रद्द करा, सामान्यतः प्रीमियमवर, एकतर ए द्वारे <strong>निविदा ऑफर</strong> (तुम्ही तुमचे शेअर्स परत ऑफर करा) किंवा <strong>खुले बाजार</strong> खरेदी कमी शेअर्स शिल्लक आहेत, त्यामुळे प्रत्येक हयात असलेला शेअर कंपनीचा थोडा मोठा भाग दर्शवतो.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>1 ऑक्टोबर 2024 पासून, बायबॅकवरील कर नियम बदलले: तुम्हाला बायबॅकमध्ये मिळणारे पैसे आता कर आकारले जातात <em>आपले</em> शेअरहोल्डर स्तरावर पूर्वीप्रमाणे करमुक्त होण्याऐवजी लाभांश उत्पन्न समजले जाते. बायबॅक हा अजूनही कंपन्यांसाठी रोख परत करण्याचा एक अस्सल मार्ग आहे, फक्त कर शॉर्टकट नाही.</p>\n</div></div>\n<h2 id=\"the-part-that-scares-beginners-the-price-falls-but-you-don-t-lose\">नवशिक्यांना घाबरवणारा भाग: किंमत \"पडते\" परंतु आपण गमावत नाही</h2>\n<p>धड्यातील ही सर्वात महत्त्वाची कल्पना आहे, म्हणून आपण त्यास वास्तविक उदाहरणासह ठोस करू या. ऑक्टोबर 2024 मध्ये, रिलायन्स इंडस्ट्रीजने ए <strong>1:1 बोनस</strong>, आयोजित केलेल्या प्रत्येकासाठी एक विनामूल्य शेअर.</p>\n<p>समजा तुमची मालकी आहे <strong>10 शेअर्स 2,900 रु</strong> आदल्या दिवशी संध्याकाळी. तुमची होल्डिंग 29,000 रुपये होती.</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th align=\"right\">बोनस आधी</th>\n<th align=\"right\">1:1 बोनस नंतर</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>तुमच्या मालकीचे शेअर्स</td>\n<td align=\"right\">10</td>\n<td align=\"right\">20</td>\n</tr>\n<tr>\n<td>प्रति शेअर किंमत</td>\n<td align=\"right\">2,900 रु</td>\n<td align=\"right\">1,450 रु</td>\n</tr>\n<tr>\n<td><strong>एकूण मूल्य</strong></td>\n<td align=\"right\"><strong>२९,००० रु</strong></td>\n<td align=\"right\"><strong>२९,००० रु</strong></td>\n</tr>\n</tbody></table>\n<p>तुमचे शेअर्स दुप्पट झाले, किंमत निम्मी झाली आणि तुमची संपत्ती एका रुपयानेही हलली नाही. स्टॉक स्प्लिट सारखेच कार्य करते, अधिक शेअर्स, प्रमाणानुसार कमी किंमत, समान एकूण. लाभांश ही तीच कल्पना आहे ज्याचे मूल्य तुम्हाला अतिरिक्त शेअर्सऐवजी रोख स्वरूपात दिले जाते.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>बोनस, विभाजन आणि लाभांश करतात <strong>नाही</strong> ज्या दिवशी ते घडतात त्या दिवशी तुम्हाला अधिक श्रीमंत किंवा गरीब बनवतात, ते फक्त बदलतात <em>फॉर्म</em> तुमच्या मालकीचे. स्क्रीन कमी किंमत दाखवते कारण आपोआप एक्सचेंज होते <strong>समायोजित करते</strong> ते; तुमची मागील खरेदी किंमत आणि चार्ट देखील समायोजित केले आहेत. \"रु. 1,450\" पाहणे जिथे \"रु. 2,900\" असायचे ते सामान्य अंकगणित आहे, क्रॅश नाही.</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch09-split-bonus-adjust.png\" alt=\"2,900 किमतीचा एक शेअर 1:1 बोनसनंतर रु. 1,450 वर दोन शेअर बनतो, शेअरची संख्या दुप्पट होते, किंमत अर्धी होते आणि एकूण संपत्ती सारखीच राहते\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>2,900 किमतीचा एक शेअर 1:1 बोनसनंतर रु. 1,450 वर दोन शेअर बनतो, शेअरची संख्या दुप्पट होते, किंमत अर्धी होते आणि एकूण संपत्ती सारखीच राहते</figcaption></figure>\n<p>मग कंपन्या कशाला त्रास देतात? बोनस आणि स्प्लिट्स प्रति-शेअर किंमत कमी करतात, ज्यामुळे खरेदीदारांचा पूल वाढू शकतो आणि व्यापार क्रियाकलाप सुधारू शकतो आणि ते भविष्यातील कमाईवर व्यवस्थापनाचा विश्वास दर्शवतात. ते पातळ हवेतून मूल्य निर्माण करत नाहीत, परंतु अधिक द्रव, अधिक प्रवेशयोग्य स्टॉक हा एक उत्तम परिणाम आहे.</p>\n<h2 id=\"every-corporate-action-at-a-glance\">प्रत्येक कॉर्पोरेट क्रिया एका दृष्टीक्षेपात</h2>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch09-corporate-actions-grid.png\" alt=\"कॉर्पोरेट क्रिया, अधिकार, FPO, OFS, लाभांश, बोनस, स्प्लिट आणि बायबॅक, प्रत्येकासाठी नवीन शेअर्स तयार केले आहेत की नाही, पैसा कुठे वाहतो आणि किंमतीवर होणारा परिणाम यांचा तुलनात्मक ग्रिड.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">इन्फोग्राफिक</span>कॉर्पोरेट क्रिया, अधिकार, FPO, OFS, लाभांश, बोनस, स्प्लिट आणि बायबॅक यांचा तुलनात्मक ग्रिड, प्रत्येकासाठी नवीन शेअर्स तयार केले आहेत की नाही, पैसा कुठे वाहतो आणि किंमतीवर होणारा परिणाम दर्शवितो.</figcaption></figure>\n<table>\n<thead>\n<tr>\n<th>कृती</th>\n<th>ते काय आहे</th>\n<th>शेअरच्या संख्येवर परिणाम</th>\n<th>किंमतीवर परिणाम</th>\n<th>तुमच्या संपत्तीवर परिणाम</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>हक्काचा मुद्दा</strong></td>\n<td>विद्यमान धारकांना सवलतीत नवीन शेअर्स ऑफर केले जातात</td>\n<td>अधिक (आपण सदस्यता घेतल्यास)</td>\n<td>थोडेसे खाली समायोजित करते (माजी हक्क)</td>\n<td>तटस्थ; तुम्ही नवीन शेअर्ससाठी पैसे द्या</td>\n</tr>\n<tr>\n<td><strong>FPO</strong></td>\n<td>नवीन शेअर्स लोकांना विकले गेले</td>\n<td>अधिक (एकूण)</td>\n<td>dilution वर बुडविणे शकता</td>\n<td>आपण खरेदी केल्याशिवाय थोडे सौम्य करणे</td>\n</tr>\n<tr>\n<td><strong>OFS</strong></td>\n<td>मोठे धारक विद्यमान समभाग विकतात</td>\n<td>बदल नाही</td>\n<td>अल्पकालीन दबाव</td>\n<td>सौम्यता नाही</td>\n</tr>\n<tr>\n<td><strong>लाभांश</strong></td>\n<td>नफ्यातून रोख रक्कम दिली</td>\n<td>बदल नाही</td>\n<td>एक्स-डेटला लाभांशानुसार थेंब</td>\n<td>तटस्थ (मूल्य रोखकडे जाते)</td>\n</tr>\n<tr>\n<td><strong>बोनस</strong></td>\n<td>एका गुणोत्तरामध्ये मोफत अतिरिक्त शेअर्स</td>\n<td>वर</td>\n<td>प्रमाणानुसार पडतो</td>\n<td>अपरिवर्तित</td>\n</tr>\n<tr>\n<td><strong>स्टॉक विभाजित</strong></td>\n<td>एक वाटा अनेकांत विभागला</td>\n<td>वर</td>\n<td>प्रमाणानुसार पडतो</td>\n<td>अपरिवर्तित</td>\n</tr>\n<tr>\n<td><strong>बायबॅक</strong></td>\n<td>कंपनी स्वतःचे शेअर्स परत विकत घेते</td>\n<td>खाली</td>\n<td>अनेकदा आश्वासक</td>\n<td>तटस्थ ते सौम्य सकारात्मक</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>जेव्हा तुमच्या पोर्टफोलिओमधील स्टॉक कोणत्याही स्पष्ट कारणाशिवाय झपाट्याने खाली येतो, तेव्हा तपासा <strong>कॉर्पोरेट क्रिया</strong> किंवा <strong>घोषणा</strong> प्रतिक्रिया देण्यापूर्वी टॅब. दहा पैकी नऊ वेळा हा एक्स-डिव्हिडंड, बोनस किंवा स्प्लिट असतो आणि योग्य प्रतिसाद म्हणजे काहीही न करणे.</p>\n</div></div>\n<h2 id=\"quick-recap\">क्विक रिकॅप</h2>\n<ul>\n<li>लिस्ट केल्यानंतर कंपन्या बाजाराला स्पर्श करत राहतात <strong>भांडवल वाढवा</strong> (अधिकार, FPO, OFS) किंवा ते <strong>परत करा आणि आकार बदला</strong> मूल्य (लाभांश, बोनस, विभाजन, बायबॅक).</li>\n<li>ए <strong>अधिकार समस्या</strong> विद्यमान धारकांना सवलतीच्या दरात नवीन शेअर्स ऑफर; एक <strong>FPO</strong> प्रत्येकाला नवीन शेअर्स विकतो; एक <strong>OFS</strong> बड्या धारकांना तुमचे विद्यमान समभाग विकू देते.</li>\n<li><strong>लाभांश</strong> नफ्यातून रोख रक्कम द्या; वर लाभांश द्वारे किंमत कमी <strong>माजी तारीख</strong>त्यामुळे तुम्ही त्या दिवशी श्रीमंत किंवा गरीब नसाल.</li>\n<li><strong>बोनस आणि विभाजन</strong> तुमचे शेअर्स गुणाकार करा आणि प्रमाणानुसार किंमत कमी करा, <strong>तुमची एकूण संपत्ती बदलत नाही</strong>.</li>\n<li>ए <strong>बायबॅक</strong> रोख परत करून शेअर्सची संख्या कमी करते; ऑक्टोबर 2024 पासून मिळालेल्या रकमेवर तुमच्या हातात लाभांश म्हणून कर आकारला जाईल.</li>\n<li>नवशिक्याची सर्वात मोठी चूक आहे <strong>समायोजित किंमतीवर घाबरणे</strong>, प्रतिक्रिया देण्यापूर्वी नेहमी कॉर्पोरेट-ॲक्शन कॅलेंडर तपासा.</li>\n</ul>\n<p>तुम्हाला आता समजले आहे की शेअर्स कसे तयार केले जातात, वितरीत केले जातात आणि आकार बदलला जातो. पुढे आपण स्क्रीनकडे वळतो जिथे हे सर्व रिअल टाइममध्ये दिसते <strong>स्टॉक कोट</strong>, आणि त्यावरील प्रत्येक संख्या डीकोड करा, शेवटच्या ट्रेड केलेल्या किंमतीपासून ते पाच-स्तरीय ऑर्डर बुकपर्यंत.</p>\n","toc":[{"level":2,"text":"कॉर्पोरेट कारवाईची दोन कुटुंबे","id":"two-families-of-corporate-action"},{"level":2,"text":"अधिक पैसे उभारणे","id":"raising-more-money"},{"level":3,"text":"हक्काचा मुद्दा","id":"rights-issue"},{"level":3,"text":"FPO (फॉलो-ऑन / पुढील सार्वजनिक ऑफर)","id":"fpo-follow-on-further-public-offer"},{"level":3,"text":"OFS (विक्रीसाठी ऑफर)","id":"ofs-offer-for-sale"},{"level":2,"text":"पुरस्कृत आणि आकार बदलणे","id":"rewarding-and-reshaping"},{"level":3,"text":"लाभांश","id":"dividends"},{"level":3,"text":"बोनस शेअर्स","id":"bonus-shares"},{"level":3,"text":"स्टॉक विभाजित","id":"stock-split"},{"level":3,"text":"बायबॅक","id":"buyback"},{"level":2,"text":"नवशिक्यांना घाबरवणारा भाग: किंमत \"पडते\" परंतु आपण गमावत नाही","id":"the-part-that-scares-beginners-the-price-falls-but-you-don-t-lose"},{"level":2,"text":"प्रत्येक कॉर्पोरेट क्रिया एका दृष्टीक्षेपात","id":"every-corporate-action-at-a-glance"},{"level":2,"text":"क्विक रिकॅप","id":"quick-recap"}],"imgCount":2,"hasContent":true},"10":{"html":"<p>जेव्हा तुम्ही स्टॉकवर पहिल्यांदा टॅप करता आणि कोट स्क्रीन उघडते तेव्हा ते एअरलाइन कॉकपिटमध्ये, संख्यांची भिंत, बाण आणि लहान तक्ते, सर्व एकाच वेळी बदलल्यासारखे वाटू शकते. तरीही तिथली प्रत्येक आकृती तुम्हाला एका प्रश्नाबद्दल काहीतरी सोपी आणि उपयुक्त सांगत आहे: <em>लोक सध्या हा शेअर कोणत्या किंमतीला विकत घेत आहेत आणि त्यांना किती वाईट रीतीने हवे आहे?</em></p>\n<p>एकदा आपण कोट वाचू शकलो की, बाजार गोंगाट करणे थांबवते आणि संभाषण सुरू होते. या धड्यात आपण एका चालू उदाहरणाचा वापर करून ठराविक स्क्रीनवरील प्रत्येक संख्या डीकोड करू, <strong>रिलायन्स इंडस्ट्रीज</strong> NSE वर. खालील आकडे एक आहेत <strong>शिकवण्यासाठी उदाहरणात्मक स्नॅपशॉट</strong>, रिअल-टाइम किंमत नाही, परंतु वास्तविक कोट असेल त्याप्रमाणे ते व्यवस्थित केले जातात.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch10-quote-screen-annotated.png\" alt=\"रिलायन्स इंडस्ट्रीजसाठी एक भाष्य केलेली स्टॉक-कोट स्क्रीन, ज्यात कॉलआउट्समध्ये शेवटची ट्रेड केलेली किंमत, बिड आणि आस्क, ओपन-हाय-लो-क्लोज, दिवसाचा आवाज आणि टक्केवारी बदल आहे.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>रिलायन्स इंडस्ट्रीजसाठी एक भाष्य केलेली स्टॉक-कोट स्क्रीन, ज्यात कॉलआउट्समध्ये शेवटची ट्रेड केलेली किंमत, बिड आणि आस्क, ओपन-हाय-लो-क्लोज, दिवसाचा आवाज आणि टक्केवारी बदल आहे.</figcaption></figure>\n<h2 id=\"the-headline-ltp-and-last-traded-quantity\">मथळा: LTP आणि शेवटचे ट्रेड केलेले प्रमाण</h2>\n<p>स्क्रीनवर सर्वात मोठी संख्या आहे <strong>LTP, शेवटची ट्रेडिंग किंमत</strong>. ही फक्त किंमत आहे ज्यावर <em>सर्वात अलीकडील</em> या स्टॉकमध्ये व्यवहार प्रत्यक्षात झाला. सरासरी नाही, अंदाज नाही, खरेदीदार आणि विक्रेता यांच्यातील शेवटचा वास्तविक हँडशेक.</p>\n<table>\n<thead>\n<tr>\n<th>फील्ड</th>\n<th align=\"right\">मूल्य (स्नॅपशॉट)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>LTP</td>\n<td align=\"right\">रु. 1,476.30</td>\n</tr>\n<tr>\n<td>शेवटचे ट्रेड केलेले प्रमाण</td>\n<td align=\"right\">45 शेअर्स</td>\n</tr>\n<tr>\n<td>मागील बंद</td>\n<td align=\"right\">1,468.50 रु</td>\n</tr>\n<tr>\n<td>बदला</td>\n<td align=\"right\">+ रु ७.८० (+०.५३%)</td>\n</tr>\n</tbody></table>\n<p>त्याच्या अगदी बाजूला बसतो <strong>शेवटचे ट्रेड केलेले प्रमाण</strong>, त्या अंतिम व्यापारात किती शेअर्सचे हात बदलले (येथे, 45). द <strong>बदल</strong> कालच्या शी LTP ची तुलना करते <strong>मागील बंद</strong>, आणि रुपयात आणि टक्केवारी म्हणून दाखवले आहे. हिरवा म्हणजे स्टॉक कालच्या क्लोजच्या वर आहे, लाल म्हणजे खाली. ती टक्केवारी, रुपयाचा आकडा नव्हे, जेव्हा लोक म्हणतात की स्टॉक \"अर्धा टक्का वाढला आहे.\"</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>LTP हा इतिहास आहे, वचन नाही. शेवटचा व्यापार कुठे आहे ते सांगते <em>केले</em> घडते, पुढचे कुठे नाही <em>इच्छा</em>. अगदी पुढचा ट्रेड वेगळ्या किंमतीवर होऊ शकतो, जे नेमके काय बिड आणि मागते, पुढे येत आहे, तुम्हाला अंदाज लावण्यास मदत करते.</p>\n</div></div>\n<h2 id=\"bid-ask-and-the-spread\">बोली, विचारा आणि प्रसार</h2>\n<p>स्टॉकची एकच किंमत नसते; प्रत्येक क्षणाला दोन किंमती आहेत:</p>\n<ul>\n<li>द <strong>बोली</strong> सर्वोच्च किंमत आहे a <em>खरेदीदार</em> सध्या पैसे देण्यास तयार आहे.</li>\n<li>द <strong>विचारा</strong> (किंवा ऑफर) ही सर्वात कमी किंमत आहे a <em>विक्रेता</em> सध्या स्वीकारण्यास तयार आहे.</li>\n</ul>\n<p>आमच्या स्नॅपशॉटमध्ये सर्वोत्तम बोली आहे <strong>रु. 1,476.20</strong> आणि सर्वोत्तम विचारणे आहे <strong>रु. 1,476.30</strong>. व्यापार तेव्हाच होतो जेव्हा एखादा खरेदीदार मागणीचे पैसे देण्यास सहमत असतो किंवा विक्रेता बोली घेण्यास सहमत असतो, ज्या क्षणी ते भेटतात, नवीन LTP जन्माला येतो.</p>\n<p>त्यांच्यातील अंतर, येथे फक्त <strong>0.10 रु</strong>, आहे <strong>प्रसार</strong>. हा एक शांत परंतु शक्तिशाली गुणवत्ता सिग्नल आहे:</p>\n<ul>\n<li>ए <strong>अरुंद पसरला</strong> (रिलायन्ससारखे काही पैसे) म्हणजे स्टॉक आहे <strong>द्रव</strong>, बरेच खरेदीदार आणि विक्रेते, वाजवी किंमतीजवळ व्यापार करणे सोपे.</li>\n<li>ए <strong>विस्तृत पसरला</strong> (रुपये वेगळे) म्हणजे स्टॉक आहे <strong>तरल</strong>, कमी व्याज, आणि तुम्ही फक्त व्यापार पूर्ण करण्यासाठी पैसे देऊ शकता किंवा खाली विकू शकता.</li>\n</ul>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>कोणताही छोटा किंवा अपरिचित स्टॉक खरेदी करण्यापूर्वी, स्प्रेडकडे एक नजर टाका. एक विस्तृत प्रसार एक चेतावणी आहे की मिळत <em>बाहेर</em> नंतर तुम्हाला तुमच्या अपेक्षेपेक्षा जास्त खर्च येऊ शकतो, तुम्ही वाटेत ओलांडलेले अंतर भरून काढण्यासाठी किंमत तुमच्या बाजूने जाणे आवश्यक आहे.</p>\n</div></div>\n<h2 id=\"open-high-low-close-the-day-s-story-in-four-numbers\">उघडा, उच्च, निम्न, बंद: चार अंकांमध्ये दिवसाची कथा</h2>\n<p>चार नंबर, एकत्र कॉल <strong>OHLC</strong>, संपूर्ण ट्रेडिंग दिवसाचा सारांश द्या:</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th align=\"right\">मूल्य (स्नॅपशॉट)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>उघडा</strong></td>\n<td align=\"right\">रु 1,470.00</td>\n</tr>\n<tr>\n<td><strong>उच्च</strong></td>\n<td align=\"right\">रु. 1,482.70</td>\n</tr>\n<tr>\n<td><strong>कमी</strong></td>\n<td align=\"right\">1,466.20 रु</td>\n</tr>\n<tr>\n<td><strong>मागील बंद</strong></td>\n<td align=\"right\">1,468.50 रु</td>\n</tr>\n</tbody></table>\n<ul>\n<li><strong>उघडा</strong>, बाजार सकाळी 9:15 वाजता उघडला तेव्हा पहिल्या व्यापाराची किंमत.</li>\n<li><strong>उच्च</strong>, आजपर्यंतचा उच्चांक गाठला आहे.</li>\n<li><strong>कमी</strong>, आजपर्यंतची सर्वात कमी किंमत आहे.</li>\n<li><strong>बंद करा</strong>, दिवसाची अंतिम किंमत (बाजार बंद होईपर्यंत, द <strong>मागील बंद</strong> संदर्भ म्हणून उभे आहे).</li>\n</ul>\n<p>हे चौघे प्रत्येकाचा कच्चा माल आहेत <strong>मेणबत्ती</strong> किंमत चार्टवर: प्रत्येक मेणबत्ती एका कालावधीच्या खुल्या, उच्च, कमी आणि बंद एकाच आकारात पॅक करते. OHLC वाचायला शिका आणि तुम्ही आधीच मेणबत्त्या वाचत आहात.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch10-reliance-candlestick.png\" alt=\"रिलायन्स इंडस्ट्रीजचा एक दैनिक कँडलस्टिक चार्ट, जिथे प्रत्येक मेणबत्तीचे शरीर उघडे आणि जवळ पसरलेले असते आणि पातळ विक्स दिवसाच्या उच्च आणि निम्न पातळीवर पोहोचतात\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>रिलायन्स इंडस्ट्रीजचा एक दैनिक कँडलस्टिक चार्ट, जिथे प्रत्येक मेणबत्तीचे शरीर उघडे आणि जवळ पसरलेले असते आणि पातळ विक्स दिवसाच्या उच्च आणि निम्न पातळीवर पोहोचतात</figcaption></figure>\n<h2 id=\"volume-how-much-conviction-is-behind-the-move\">खंड: हालचाली मागे किती खात्री आहे</h2>\n<p><strong>खंड</strong> आमच्या स्नॅपशॉटमध्ये, दिवसभरातील एकूण समभागांची संख्या आहे <strong>85 लाख शेअर्स</strong> आतापर्यंत व्हॉल्यूम हा बाजाराचा आहे <em>तीव्रता डायल</em>. जड व्हॉल्यूमवर किंमत हलवणे म्हणजे बरेच सहभागी सहमत आहेत आणि त्यावर कार्य करत आहेत; थिन व्हॉल्यूमवर तीच हालचाल म्हणजे मूठभर ट्रेड्स जे चिकटू शकत नाहीत.</p>\n<ul>\n<li><strong>किंमत वाढ + उच्च खंड</strong> = त्यामागची खरी खात्री असलेली चाल.</li>\n<li><strong>किंमत वाढ + कमी आवाज</strong> = एक तात्पुरता प्रवाह जो सहज उलटू शकतो.</li>\n</ul>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>NSE वर, रिलायन्ससारखा सक्रिय लार्ज-कॅप <em>कोटी</em> एका दिवसात शेअर्स, म्हणजे सकाळी 9:15 ते दुपारी 3:30 दरम्यान हात बदलणारे हजारो कोटी रुपयांचे शेअर्स. त्या प्रत्येक ट्रेडने तुम्ही पाहत असलेले LTP अपडेट केले. कोट स्क्रीन हा ऑर्डरच्या समुद्राचा पृष्ठभाग आहे जो खाली हलतो.</p>\n</div></div>\n<h2 id=\"market-depth-the-five-level-order-book\">मार्केट डेप्थ: पाच-स्तरीय ऑर्डर बुक</h2>\n<p>हा एक भाग आहे जो प्रासंगिक दर्शकाला खरोखरच कोट वाचणाऱ्यांपासून वेगळे करतो, द <strong>बाजाराची खोली</strong>, देखील म्हणतात <strong>ऑर्डर बुक</strong>. हे दाखवते <strong>पाच सर्वोत्तम खरेदी ऑर्डर आणि पाच सर्वोत्तम विक्री ऑर्डर</strong> त्यांच्या किंमती आणि प्रमाणांसह रांगेत प्रतीक्षा करत आहे. (मानक किरकोळ स्क्रीन प्रत्येक बाजूला पाच स्तर दर्शवितात; आम्हाला एवढेच हवे आहे.)</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch10-market-depth-orderbook.png\" alt=\"रिलायन्ससाठी पाच-स्तरीय मार्केट-डेप्थ विंडो, ज्यामध्ये खरेदीच्या बाजूने पाच बोली किमती आणि परिमाण आहेत आणि विक्रीच्या बाजूला पाच विचारलेल्या किंमती आणि प्रमाण, तसेच एकूण खरेदी आणि विक्रीचे प्रमाण\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">डेटा उदा</span>रिलायन्ससाठी पाच-स्तरीय मार्केट-डेप्थ विंडो, ज्यामध्ये खरेदीच्या बाजूने पाच बोली किमती आणि परिमाण आहेत आणि विक्रीच्या बाजूला पाच विचारलेल्या किंमती आणि प्रमाण, तसेच एकूण खरेदी आणि विक्रीचे प्रमाण</figcaption></figure>\n<table>\n<thead>\n<tr>\n<th align=\"right\">बोली प्रमाण</th>\n<th align=\"right\">बोली किंमत</th>\n<th align=\"right\">किंमत विचारा</th>\n<th align=\"right\">प्रमाण विचारा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td align=\"right\">320</td>\n<td align=\"right\">1,476.20</td>\n<td align=\"right\">1,476.30</td>\n<td align=\"right\">280</td>\n</tr>\n<tr>\n<td align=\"right\">540</td>\n<td align=\"right\">1,476.10</td>\n<td align=\"right\">1,476.40</td>\n<td align=\"right\">610</td>\n</tr>\n<tr>\n<td align=\"right\">1,250</td>\n<td align=\"right\">1,476.00</td>\n<td align=\"right\">1,476.50</td>\n<td align=\"right\">900</td>\n</tr>\n<tr>\n<td align=\"right\">410</td>\n<td align=\"right\">1,475.90</td>\n<td align=\"right\">1,476.60</td>\n<td align=\"right\">350</td>\n</tr>\n<tr>\n<td align=\"right\">760</td>\n<td align=\"right\">1,475.80</td>\n<td align=\"right\">1,476.70</td>\n<td align=\"right\">1,100</td>\n</tr>\n</tbody></table>\n<p>मध्यभागी दोन पायऱ्या भेटल्यासारखे वाचा. द <strong>डावी बाजू</strong> मागणी आहे, खरेदीदार सध्याच्या किमतीच्या अगदी खाली स्टॅक केलेले आहेत. द <strong>उजवी बाजू</strong> पुरवठा आहे, विक्रेते अगदी वर स्टॅक केलेले आहेत. वरच्या पंक्तीमध्ये सर्वोत्तम बिड आहे आणि आम्ही आधीच भेटलेले सर्वोत्तम विचारू; खालील प्रत्येक पंक्ती त्याच्या वळणाची वाट पाहत थोडीशी वाईट किंमत आहे.</p>\n<p>खोली विंडो प्रकट करते <strong>जेथे दबाव आहे</strong>. खरेदीचे प्रमाण विक्रीच्या प्रमाणापेक्षा कमी असल्यास, किमतीच्या तुलनेत पुरवठ्यापेक्षा जास्त मागणी असते आणि त्याउलट. अनेक स्क्रीन देखील म्हणून एकूण <strong>एकूण खरेदी प्रमाण</strong> आणि <strong>एकूण विक्री प्रमाण</strong> सर्व प्रलंबित ऑर्डरवर, एकूण टग-ऑफ-वॉरचे द्रुत वाचन.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>मार्केट डेप्थ आहे <em>मागणी आणि पुरवठा दृश्यमान झाला</em>. बोलीवर बसलेला एक मोठा ऑर्डर तात्पुरत्या मजल्याप्रमाणे कार्य करू शकतो; अगदी वरती विक्री ऑर्डरची भिंत कमाल मर्यादेसारखी काम करू शकते. हा क्रिस्टल बॉल नाही, त्या ऑर्डर एका झटपट रद्द केल्या जाऊ शकतात, परंतु ते तुम्हाला सध्याच्या किमतीच्या आसपास खरेदीदार आणि विक्रेत्यांचे तात्काळ शिल्लक दाखवते.</p>\n</div></div>\n<h2 id=\"circuit-limits-the-market-s-safety-valve\">सर्किट मर्यादा: बाजारातील सुरक्षा झडप</h2>\n<p>एका सत्रात स्टॉकला अनियंत्रितपणे वाढण्यापासून किंवा क्रॅश होण्यापासून रोखण्यासाठी, एक्सचेंज ए सेट करते <strong>किंमत बँड</strong>, आणि त्या बँडच्या कडा आहेत <strong>सर्किट मर्यादा</strong>:</p>\n<ul>\n<li>द <strong>वरचे सर्किट</strong> आज किंमत वाढण्याची कमाल आहे.</li>\n<li>द <strong>लोअर सर्किट</strong> तो आज घसरण्याची कमाल आहे.</li>\n</ul>\n<p>बँड सामान्यतः आहेत <strong>2%, 5%, 10% किंवा 20%</strong>, स्टॉकवर अवलंबून. जेव्हा एखादा स्टॉक त्याच्या वरच्या सर्किटला आदळतो तेव्हा तेथे फक्त खरेदीदार असतात आणि कोणीही विक्रेता नसतो, त्यामुळे त्या किंमतीवर व्यापार प्रभावीपणे गोठतो; लोअर सर्किटवर, उलट. स्मॉल-कॅप्स नियमितपणे त्यांच्या सर्किट्समध्ये स्लॅमचा व्यापार केला जातो, जे ते जोखमीचे आणखी एक कारण आहे. डेरिव्हेटिव्ह विभागातील मोठ्या, लिक्विड स्टॉकमध्ये विस्तीर्ण, लवचिक बँड असतात आणि क्वचितच लॉक असतात, परंतु सेफ्टी व्हॉल्व्ह नेहमीच असतो.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>\"अप्पर सर्किटमध्ये लॉक केलेला\" स्टॉक रोमहर्षक दिसू शकतो, परंतु तो अधीरांसाठी एक सापळा आहे: जर तुम्ही तेथे एक गोठवलेला विकत घेतला असेल, तर खरेदीदार दिसेपर्यंत तुम्ही विक्री करू शकत नाही आणि जेव्हा हायप केलेली स्मॉल-कॅप शेवटी वळते तेव्हा तो आदळू शकतो. <em>कमी</em> दिवसेंदिवस एकही खरेदीदार दिसत नसलेली सर्किट्स, ज्यामुळे तुम्हाला बाहेर पडता येत नाही. सर्किट दोन्ही मार्ग कट.</p>\n</div></div>\n<h2 id=\"quick-recap\">क्विक रिकॅप</h2>\n<ul>\n<li>द <strong>LTP</strong> सह शेवटच्या वास्तविक व्यापाराची किंमत आहे <strong>बदल</strong> कालच्या तुलनेत मोजले <strong>मागील बंद</strong>, सहसा टक्केवारी म्हणून वाचा.</li>\n<li>द <strong>बोली</strong> (सर्वोत्तम खरेदीदार) आणि <strong>विचारा</strong> (सर्वोत्तम विक्रेता) किंमत कंसात; द <strong>प्रसार</strong> त्यांच्या दरम्यान स्टॉक किती द्रव आहे हे सूचित करते.</li>\n<li><strong>OHLC</strong>, उघडा, उच्च, निम्न, बंद, दिवसाची कथा चार अंकांमध्ये आणि प्रत्येक फॉर्ममध्ये सांगते <strong>मेणबत्ती</strong> चार्टवर.</li>\n<li><strong>खंड</strong> खात्रीशीर उपाय: जड व्हॉल्यूमवर चालणे म्हणजे व्यवसाय; पातळ व्हॉल्यूमवर, सावधगिरीने उपचार करा.</li>\n<li>द <strong>पाच-स्तरीय बाजार खोली</strong> सध्याच्या किमतीच्या आसपास दिसणाऱ्या पाच सर्वोत्तम खरेदी आणि विक्री ऑर्डरची प्रतीक्षा, पुरवठा आणि मागणी दर्शविते.</li>\n<li><strong>सर्किट मर्यादा</strong> स्टॉक एका दिवसात किती पुढे जाऊ शकतो हे निर्धारित करा, गोठवणारा धावपळ वाढतो आणि क्रॅश होतो आणि अधीरांना अडकवतो.</li>\n</ul>\n<p>तुम्ही आता आत्मविश्वासाने एकाच स्टॉकचे कोट वाचू शकता. पुढे आम्ही बातम्यांवर प्रत्येकाने उद्धृत केलेल्या संख्येवर झूम आउट करतो <strong>निफ्टी आणि सेन्सेक्स</strong>, आणि या डझनभर वैयक्तिक स्टॉक्समधून निर्देशांक कसा तयार होतो आणि तो का वाढतो आणि का पडतो ते पहा.</p>\n","toc":[{"level":2,"text":"मथळा: LTP आणि शेवटचे ट्रेड केलेले प्रमाण","id":"the-headline-ltp-and-last-traded-quantity"},{"level":2,"text":"बोली, विचारा आणि प्रसार","id":"bid-ask-and-the-spread"},{"level":2,"text":"उघडा, उच्च, निम्न, बंद: चार अंकांमध्ये दिवसाची कथा","id":"open-high-low-close-the-day-s-story-in-four-numbers"},{"level":2,"text":"खंड: हालचाली मागे किती खात्री आहे","id":"volume-how-much-conviction-is-behind-the-move"},{"level":2,"text":"मार्केट डेप्थ: पाच-स्तरीय ऑर्डर बुक","id":"market-depth-the-five-level-order-book"},{"level":2,"text":"सर्किट मर्यादा: बाजारातील सुरक्षा झडप","id":"circuit-limits-the-market-s-safety-valve"},{"level":2,"text":"क्विक रिकॅप","id":"quick-recap"}],"imgCount":3,"hasContent":true},"11":{"html":"<p>कोणतेही बिझनेस न्यूज चॅनल चालू करा आणि दहा सेकंदात तुम्हाला एकच नंबर ऐकू येईल जो तुम्हाला आज \"बाजार\" कसा झाला हे सांगेल. \"निफ्टी 120 अंकांनी वर बंद झाला.\" \"सेन्सेक्स अर्धा टक्का घसरला.\" परंतु भारतात 2,000 हून अधिक सूचीबद्ध कंपन्या आहेत आणि कोणत्याही दिवशी काही वाढतात तर काही कमी होतात. मग एक संख्या हजारो चलती किंमतींची बेरीज कशी करू शकते? उत्तर आहे एक <strong>निर्देशांक</strong>, अंकगणिताचा एक हुशार तुकडा जो स्टॉकची संपूर्ण टोपली एका आकृतीमध्ये पिळून टाकतो ज्याचा तुम्ही एका नजरेत मागोवा घेऊ शकता. हे बाजाराचे थर्मामीटर आहे.</p>\n<p>या प्रकरणात आपण ते थर्मामीटर उघडू आणि त्यात नेमके काय आहे ते पाहू: त्यात कोणता साठा आहे (त्याचे <strong>घटक</strong>), प्रत्येकाची गणना किती आहे (त्याची <strong>वजन</strong>), आणि, हा भाग बहुतेक नवशिक्यांना कधीच तंतोतंत समजत नाही <em>कसे</em> ते साठे दिवसभर फिरत असताना संख्या वाढते किंवा कमी होते.</p>\n<h2 id=\"what-an-index-actually-is\">इंडेक्स प्रत्यक्षात काय आहे</h2>\n<p>एक निर्देशांक फक्त ए <strong>स्टॉकच्या निवडलेल्या टोपलीचा भारित सारांश</strong>, एकल संख्या म्हणून व्यक्त. भारताचे दोन प्रमुख निर्देशांक आहेत:</p>\n<ul>\n<li>द <strong>निफ्टी 50</strong>, NSE द्वारे चालवले जाते, ते ट्रॅक करते <strong>50 मोठ्या कंपन्या</strong>.</li>\n<li>द <strong>सेन्सेक्स</strong> (संवेदनशील निर्देशांकासाठी लहान), BSE द्वारे चालवले जाते, ते ट्रॅक करते <strong>30 मोठ्या कंपन्या</strong>.</li>\n</ul>\n<p>दोन्ही व्यापक बाजारपेठेचे प्रतिनिधित्व करण्यासाठी डिझाइन केले आहेत: प्रमुख क्षेत्रांमधील सर्वात मोठ्या, सर्वाधिक-व्यापार केलेल्या कंपन्या निवडा, त्यांना एकत्रित करा आणि परिणामी संख्या \"बाजार\" च्या मार्गाने वर आणि खाली हलते. जेव्हा लोक म्हणतात \"आज बाजार तेजीत होता,\" तेव्हा त्यांचा जवळजवळ नेहमीच अर्थ होतो की या दोन निर्देशांकांपैकी एक वाढला.</p>\n<p>पातळीच, निफ्टी आजूबाजूला घिरट्या घालत आहे <strong>23,800</strong> किंवा सेन्सेक्स जवळ आहे <strong>76,200</strong> (अंदाजे, 2026 च्या मध्यात), रुपये नाही आणि तुम्ही खरेदी करू शकता अशी किंमत नाही. हा फक्त एक धावण्याचा स्कोअर आहे, जो दशकांपूर्वी मूळ मूल्यापासून सुरू झाला आणि घटक कंपन्या वाढल्याप्रमाणे पुढे चक्रवाढ झाली.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>निफ्टी आणि सेन्सेक्स मोठ्या प्रमाणात ओव्हरलॅप होतात, दिग्गज बँका, रिलायन्स आणि IT प्रमुख कंपन्या दोन्हीमध्ये बसतात, म्हणूनच कोणत्याही दिवशी दोन्ही निर्देशांक जवळजवळ नेहमीच समान टक्केवारीने एकाच दिशेने फिरतात. निफ्टी 50 हा फंड आणि डेरिव्हेटिव्हसाठी अधिक व्यापकपणे ट्रॅक केलेला बेंचमार्क आहे.</p>\n</div></div>\n<h2 id=\"the-constituents-who-is-actually-inside\">घटक: कोण प्रत्यक्षात आत आहे</h2>\n<p>ज्या कंपन्या इंडेक्स बनवतात त्या आहेत <strong>घटक</strong>. परंतु ही एक महत्त्वाची कल्पना आहे जी जवळजवळ प्रत्येक नवशिक्यापर्यंत पोहोचते: <strong>प्रत्येक घटक समान गणला जात नाही.</strong> रिलायन्स सारखी दिग्गज कंपनी एका लहान सदस्यापेक्षा खूप कठीण निर्देशांकावर खेचते. प्रत्येक स्टॉक नियुक्त केला आहे a <strong>वजन</strong>, एकूण निर्देशांकातील त्याचा वाटा आणि त्या वजनाने ठरवले जाते <strong>फ्री-फ्लोट मार्केट कॅपिटलायझेशन</strong>.</p>\n<p>तो वाक्प्रचार भीतीदायक वाटतो; एकदा दोन तुकडे केले तर ते सोपे आहे:</p>\n<ul>\n<li><strong>बाजार भांडवलीकरण</strong> = शेअरची किंमत x एकूण शेअर्सची संख्या. हा संपूर्ण कंपनीचा संपूर्ण किंमत टॅग आहे.</li>\n<li><strong>फ्री-फ्लोट</strong> = फक्त शेअर्स प्रत्यक्षात लोकांसाठी व्यापारासाठी उपलब्ध आहेत <em>वगळते</em> भाग प्रवर्तक, सरकार किंवा धोरणात्मक धारकांसह बंद केला आहे.</li>\n</ul>\n<p>त्यामुळे कंपनीचे वजन त्याचे मूल्य प्रतिबिंबित करते <em>व्यापार करण्यायोग्य</em> शेअर्स फ्री-फ्लोट व्हॅल्यू जितकी मोठी असेल तितका त्याचा इंडेक्सचा तुकडा मोठा असेल आणि ती संख्या जितकी जास्त घट्ट करेल.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch11-weighted-basket.png\" alt=\"निफ्टी 50 हे वजनदार बास्केट म्हणून काढलेले आहे, हेवीवेट जसे की HDFC बँक, ICICI बँक आणि रिलायन्स बहुतेक जागा भरतात, तर सर्वात लहान सदस्य स्लिव्हर आहेत\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">इन्फोग्राफिक</span>निफ्टी 50 हे वजनदार बास्केट म्हणून काढलेले आहे, हेवीवेट जसे की HDFC बँक, ICICI बँक आणि रिलायन्स बहुतेक जागा भरतात, तर सर्वात लहान सदस्य स्लिव्हर आहेत</figcaption></figure>\n<p>NSE च्या स्वतःच्या इंडेक्स फॅक्टशीटमधून घेतलेल्या निफ्टी 50 च्या शीर्षस्थानी काय आहे ते येथे आहे. प्रत्येक आकृतीला म्हणून हाताळा <strong>अंदाजे</strong>, दर दिवसेंदिवस वाढतात आणि वर्षातून दोनदा फेरबदल केले जातात.</p>\n<table>\n<thead>\n<tr>\n<th>रँक</th>\n<th>कंपनी</th>\n<th>सेक्टर</th>\n<th align=\"right\">अंदाजे वजन</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>HDFC बँक</td>\n<td>आर्थिक (बँकिंग)</td>\n<td align=\"right\">~10.6%</td>\n</tr>\n<tr>\n<td>2</td>\n<td>ICICI बँक</td>\n<td>आर्थिक (बँकिंग)</td>\n<td align=\"right\">~8.3%</td>\n</tr>\n<tr>\n<td>3</td>\n<td>रिलायन्स इंडस्ट्रीज</td>\n<td>ऊर्जा / किरकोळ / दूरसंचार</td>\n<td align=\"right\">~8.3%</td>\n</tr>\n<tr>\n<td>4</td>\n<td>भारती एअरटेल</td>\n<td>दूरसंचार</td>\n<td align=\"right\">~5.2%</td>\n</tr>\n<tr>\n<td>5</td>\n<td>लार्सन अँड टुब्रो</td>\n<td>बांधकाम / इन्फ्रा</td>\n<td align=\"right\">~4.4%</td>\n</tr>\n<tr>\n<td>6</td>\n<td>इन्फोसिस</td>\n<td>IT</td>\n<td align=\"right\">~3.8%</td>\n</tr>\n<tr>\n<td>7</td>\n<td>स्टेट बँक ऑफ इंडिया</td>\n<td>आर्थिक (बँकिंग)</td>\n<td align=\"right\">~3.7%</td>\n</tr>\n<tr>\n<td>8</td>\n<td>ॲक्सिस बँक</td>\n<td>आर्थिक (बँकिंग)</td>\n<td align=\"right\">~3.4%</td>\n</tr>\n<tr>\n<td>9</td>\n<td>कोटक महिंद्रा बँक</td>\n<td>आर्थिक (बँकिंग)</td>\n<td align=\"right\">~2.6%</td>\n</tr>\n<tr>\n<td>10</td>\n<td>ITC</td>\n<td>FMCG</td>\n<td align=\"right\">~2.6%</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch11-top-weights-bar.png\" alt=\"वजनानुसार टॉप टेन निफ्टी 50 घटक ( NSE फॅक्टशीट), HDFC बँकेपासून खाली एक उंच पायऱ्या, निर्देशांक खरोखर किती एकतर्फी आहे हे दर्शविते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>वजनानुसार टॉप टेन निफ्टी 50 घटक ( NSE फॅक्टशीट), HDFC बँकेपासून खाली एक उंच पायऱ्या, निर्देशांक खरोखर किती एकतर्फी आहे हे दर्शविते</figcaption></figure>\n<p>एकाग्रता पहा. द <strong>केवळ शीर्ष 10 नावे अर्ध्याहून अधिक आहेत</strong> (सुमारे 53%) संपूर्ण 50-स्टॉक निर्देशांकाच्या. उर्वरित 40 कंपन्या जे शिल्लक आहे ते शेअर करतात. आणि कसे ते लक्षात घ्या <strong>आर्थिक वर्चस्व</strong>, मोठ्या बँका आणि इतर कर्जदारांना एकत्र आणणे आणि केवळ आर्थिक सेवा याबद्दल आहे <strong>35%</strong> निफ्टीचा, एका सेक्टरमध्ये एक तृतीयांशपेक्षा जास्त. म्हणूनच बँकांसाठी वाईट दिवस हा संपूर्ण निर्देशांकासाठी वाईट दिवस असतो.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>एकच कंपनी संपूर्ण भारतीय बाजारपेठ वळवू शकते. HDFC बँक, संपूर्ण निर्देशांकाच्या अंदाजे दहाव्या भागावर निफ्टीचा सर्वात मोठा घटक आहे, जेव्हा निफ्टीला काही टक्क्यांनी उडी मारते तेव्हा ती स्वतःहून लक्षणीय वाढू शकते. आणि HDFC बँक आणि रिलायन्स एकत्रितपणे टोपलीचा जवळपास पाचवा भाग आहे, इतर 48 सदस्यांनी एक गोष्ट केली आहे.</p>\n</div></div>\n<h2 id=\"how-the-index-actually-rises-and-falls\">प्रत्यक्षात निर्देशांक कसा वाढतो आणि घसरतो</h2>\n<p>आता सर्वांना हवा असलेला भाग आणि काही जण स्पष्टपणे स्पष्ट करतात. निर्देशांक पातळी आहे <strong>त्याच्या सर्व घटकांच्या हालचालींची भारित बेरीज.</strong> प्रत्येक स्टॉक दिवसाच्या बदलामध्ये योगदान देतो <em>त्याच्या वजनाच्या प्रमाणात.</em></p>\n<p>मानसिक सूत्र फक्त आहे:</p>\n<blockquote>\n<p>निर्देशांकात स्टॉकचे योगदान = (त्याचे वजन) x (त्याची टक्केवारी हलवा)</p>\n</blockquote>\n<p>काम केलेल्या उदाहरणासह ते ठोस बनवू.</p>\n<p>समजा <strong>HDFC बँकेचे वजन ~10.6% आहे आणि 2% वाढते</strong> चांगल्या दिवशी. निर्देशांकावर त्याचा पुश आहे:</p>\n<p>0.106 x 2% = <strong>0.212%</strong>, त्याबद्दल कॉल करा <strong>+0.21%</strong>.</p>\n<p>तो एकच स्टॉक, माफक 2% हलवून, संपूर्ण निफ्टी अंदाजे एका टक्क्याच्या पाचव्या भागाने उचलतो.</p>\n<p>आता ए <strong>फक्त ~0.3% वजन असलेले लहान घटक जे 2% वाढतात.</strong> त्याचे योगदान आहे:</p>\n<p>0.003 x 2% = <strong>0.006%</strong>, मूलत: <strong>काहीही नाही</strong>. तुला ते दिसलेही नसते.</p>\n<p>दोन्ही समभागांमध्ये समान 2% हालचाल, परंतु HDFC बँकेने निर्देशांक ढोबळमानाने ढकलला <strong>35 पट कठीण</strong>, पूर्णपणे कारण त्याचे वजन सुमारे 35 पट मोठे आहे. छोट्या स्टॉकचा दिवस विलक्षण असू शकतो आणि निर्देशांक केवळ त्याची नोंद करेल.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>निर्देशांक प्रत्येक कंपनीबद्दल समान काळजी घेत नाही. हेवीवेटची छोटी हालचाल एका लहान मुलाच्या मोठ्या चालीला मागे टाकते. म्हणून हिरव्या दिवशी, मूठभर मोठ्या वजनाच्या स्टॉक्सने सहसा जवळजवळ सर्व उचल केली आणि लाल दिवशी, त्याच काहींनी ड्रॅगिंग केले. \"आज बाजार घसरला\" याचा अर्थ \"आज तीन किंवा चार दिग्गज पडले.\"</p>\n</div></div>\n<p>यामुळेच तुम्ही विश्लेषकांना रॅली \"अरुंद\" किंवा \"काही हेवीवेट्सच्या नेतृत्वात\" असे म्हणताना ऐकू शकाल. जर फक्त रिलायन्स आणि वरच्या बँका वाढल्या तर इतर बहुतेक स्टॉक्स घसरले, तरीही निर्देशांक हिरवा बंद होऊ शकतो, हेवीवेट लोकांनी गर्दीला मागे टाकले. प्रत्येक घटकाचे भारित योगदान, सकारात्मक आणि नकारात्मक जोडा आणि एकूण म्हणजे दिवसाच्या निर्देशांकातील बदल.</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">खरे उदाहरण</span><div><p>एका लहान 3-स्टॉक निर्देशांकाची कल्पना करा. स्टॉक A चे वजन 60% आहे आणि ते 1% वाढते; स्टॉक बी चे वजन 30% आहे आणि 1% कमी आहे; स्टॉक सी चे वजन 10% आहे आणि 3% वाढते. योगदान: A = +0.60%, B = -0.30%, C = +0.30%. नेट = <strong>+0.60%</strong>. तीनपैकी दोन समभागांनी क्वचितच मदत केली असली तरी, एका मोठ्या सदस्याने टोन सेट केला.</p>\n</div></div>\n<h2 id=\"broad-indices-vs-sector-indices\">विस्तृत निर्देशांक वि क्षेत्र निर्देशांक</h2>\n<p>निफ्टी 50 आणि सेन्सेक्स आहेत <strong>रुंद</strong> निर्देशांक, संपूर्ण बाजाराचा क्रॉस-सेक्शन. पण तीच भारित-बास्केट युक्ती अरुंद बांधण्यासाठी वापरली जाते <strong>क्षेत्र निर्देशांक</strong> जे अर्थव्यवस्थेचा एक भाग ट्रॅक करते:</p>\n<ul>\n<li><strong>बँक निफ्टी</strong>, फक्त प्रमुख बँका (HDFC बँक, ICICI बँक, SBI, Axis, Kotak आणि इतर). निफ्टी नंतर हा भारतातील सर्वात जास्त व्यवहार झालेला निर्देशांक आहे.</li>\n<li><strong>निफ्टी IT</strong>, TCS, Infosys, Wipro आणि HCLTech सारखे सॉफ्टवेअर निर्यातदार.</li>\n<li>इतरांमध्ये निफ्टी ऑटो, निफ्टी फार्मा, निफ्टी FMCG आणि निफ्टी मेटल यांचा समावेश आहे.</li>\n</ul>\n<p>क्षेत्र निर्देशांक तुम्हाला पाहू द्या <em>दिवस काय चालवत आहे</em>. जर निफ्टी सपाट असेल पण निफ्टी IT 3% खाली असेल, तर तुम्हाला तात्काळ कळेल की सॉफ्टवेअर स्टॉक्समध्ये उग्र सत्र चालू आहे आणि बाकीचे मार्केट स्थिर आहे. तसेच आहेत <strong>व्यापक</strong> बेंचमार्क, निफ्टी 100, निफ्टी 500 आणि मिड-कॅप आणि स्मॉल-कॅप निर्देशांक, जे शीर्ष 50 पेक्षा कितीतरी जास्त कॅप्चर करतात.</p>\n<h2 id=\"why-indices-matter-to-you\">निर्देशांक तुमच्यासाठी महत्त्वाचे का आहेत</h2>\n<p>निर्देशांक केवळ टेलिव्हिजन सजावट नाहीत. ते खरी नोकरी करतात:</p>\n<ul>\n<li><strong>एक बेंचमार्क.</strong> जेव्हा एखादा फंड मॅनेजर म्हणतो की त्यांनी \"बाजारावर मात केली,\" तेव्हा त्यांचा अर्थ असा होतो की त्यांनी निफ्टी ५० सारख्या निर्देशांकावर मात केली आहे. हे स्कोअरकार्ड आहे ज्यावर प्रत्येकजण मोजला जातो.</li>\n<li><strong>बाजाराचा मूड रिंग.</strong> 2,000 किमती स्कॅन न करता, आज भावना भयभीत आहे की लोभी आहे हे एका नजरेने सांगते.</li>\n<li><strong>तुमच्या मालकीचे असू शकते असे काहीतरी.</strong> तुम्ही \"निफ्टी\" खरेदी करू शकत नाही, पण तुम्ही <em>करू शकता</em> खरेदी करा <strong>इंडेक्स फंड</strong> किंवा <strong>ETF</strong> जे यांत्रिकरित्या सर्व 50 घटक त्यांच्या अचूक वजनात धारण करतात. एक युनिट खरेदी करा आणि तुमच्याकडे संपूर्ण टोपलीचा तुकडा, झटपट विविधीकरण, स्टॉक निवडण्याची आवश्यकता नाही. नवशिक्यांसाठी गुंतवणूक करण्याचा हा एकमेव सर्वात लोकप्रिय मार्ग आहे आणि आम्ही अभ्यासक्रमात नंतर त्यावर परत येऊ.</li>\n</ul>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>इंडेक्स फंड वैभवशाली आळशी आहेत आणि हीच त्यांची ताकद आहे. फंड फक्त निर्देशांकाला प्रतिबिंबित करतो, स्टार मॅनेजर नाही, विजेत्यांचा अंदाज लावणारा कोणताही रिसर्च डेस्क नाही, तरीही दीर्घकाळापर्यंत या \"बाय द संपूर्ण बास्केट\" पध्दतीने बाजी मारली आहे. <em>बहुमत</em> सक्रियपणे व्यवस्थापित केलेल्या निधीचे जे त्यास मागे टाकण्याचा प्रयत्न करतात आणि खर्चाच्या काही अंशाने.</p>\n</div></div>\n<h2 id=\"quick-recap\">क्विक रिकॅप</h2>\n<ul>\n<li>अ <strong>निर्देशांक</strong> ही एकच संख्या आहे जी स्टॉकच्या टोपलीचा सारांश देते, बाजाराचा थर्मामीटर. भारताचे मथळे आहेत <strong>निफ्टी 50</strong> (NSE, 50 स्टॉक) आणि द <strong>सेन्सेक्स</strong> (BSE, 30 स्टॉक).</li>\n<li>आत साठा आहे <strong>घटक</strong>, आणि प्रत्येकामध्ये a आहे <strong>वजन</strong> त्याच्या द्वारे सेट <strong>फ्री-फ्लोट मार्केट कॅप</strong>, मोठे व्यापारयोग्य मूल्य म्हणजे निर्देशांकाचा मोठा तुकडा.</li>\n<li>निफ्टी आहे <strong>टॉप-जड</strong>: अंदाजे शीर्ष 10 नावे त्यापैकी जवळपास निम्मी आहेत आणि आर्थिक बाबी त्यांच्या स्वत: च्या जवळपास एक तृतीयांश आहेत.</li>\n<li>निर्देशांक याप्रमाणे हलतो <strong>भारित बेरीज</strong> त्याच्या घटकांपैकी: प्रत्येक स्टॉकचे योगदान = त्याचे वजन x त्याची टक्केवारी हलवा.</li>\n<li>ए <strong>हेवीवेटची छोटी चाल एका लहान मुलाच्या मोठ्या चालीला मागे टाकते</strong>, बहुतेक हिरव्या दिवसांमध्ये काही दिग्गजांनी उचलण्याचे काम केले आणि लाल दिवसांमध्ये त्याच काही दिग्गजांनी ड्रॅगिंग केले.</li>\n<li><strong>क्षेत्र निर्देशांक</strong> (बँक निफ्टी, निफ्टी IT) एका स्लाइसमध्ये झूम करा, तर <strong>इंडेक्स फंड</strong> एका स्वस्त, वैविध्यपूर्ण खरेदीमध्ये तुम्हाला संपूर्ण बास्केटची मालकी देऊ द्या.</li>\n</ul>\n<p>पुढे, आम्ही बाजारात बोलणारी भाषा, बुल आणि अस्वल, लार्ज-कॅप्स आणि पेनी स्टॉक्स, सर्किट्स आणि शॉर्ट सेलिंग डिकोड करतो, त्यामुळे तुमच्या स्क्रीनवर आणिTV′ वर शब्दाचा अर्थ शेवटी स्पष्ट होतो.</p>\n","toc":[{"level":2,"text":"इंडेक्स प्रत्यक्षात काय आहे","id":"what-an-index-actually-is"},{"level":2,"text":"घटक: कोण प्रत्यक्षात आत आहे","id":"the-constituents-who-is-actually-inside"},{"level":2,"text":"प्रत्यक्षात निर्देशांक कसा वाढतो आणि घसरतो","id":"how-the-index-actually-rises-and-falls"},{"level":2,"text":"विस्तृत निर्देशांक वि क्षेत्र निर्देशांक","id":"broad-indices-vs-sector-indices"},{"level":2,"text":"निर्देशांक तुमच्यासाठी महत्त्वाचे का आहेत","id":"why-indices-matter-to-you"},{"level":2,"text":"क्विक रिकॅप","id":"quick-recap"}],"imgCount":2,"hasContent":true},"12":{"html":"<p>प्रत्येक क्षेत्राची स्वतःची अपभाषा असते आणि शेअर बाजार हा सर्वात वाईट अपराधी असू शकतो. बाजाराच्या वेळेत व्यवसाय चॅनेल चालू करा आणि तुमच्यावर \"बुल्स परत आले आहेत,\" \"स्मॉल कॅप्सला हातोडा पडला,\" \"तो वरच्या सर्किटला लागला,\" \"एफआयआय कमी झाले\", वेगाने वितरित केले, जसे की पाहणाऱ्या प्रत्येकाला त्यांचा अर्थ काय आहे हे आधीच माहित आहे. नवशिक्यासाठी असे वाटू शकते की अशा खोलीत जावे जेथे प्रत्येकजण खाजगी कोड बोलत आहे.</p>\n<p>हा अध्याय तुमचा डीकोडर रिंग आहे. कोणीतरी साध्या इंग्रजीत त्यांची व्याख्या केल्यावर यापैकी कोणतीही संज्ञा कठीण नसते आणि शेवटी तुम्हाला ते शब्द समजतील जे सर्वात जास्त फेकले जातात, ज्यामध्ये ते पहिल्यांदा ऐकल्यावर जवळजवळ प्रत्येकजण गोंधळात टाकतो: <strong>कमी विक्री</strong>, जेथे लोक कसा तरी पैसे कमवतात तेव्हा स्टॉक <em>पडतो</em>.</p>\n<h2 id=\"bulls-and-bears-the-market-s-two-moods\">बैल आणि अस्वल: बाजाराचे दोन मूड</h2>\n<p>सर्व गुंतवणुकीतील दोन सर्वात प्रसिद्ध शब्द बाजाराच्या एकूण दिशेचे वर्णन करतात.</p>\n<ul>\n<li>ए <strong>बैल बाजार</strong> वाढत्या किमती आणि आशावादाचा शाश्वत कालावधी आहे. गुंतवणूकदार आत्मविश्वासाने भरलेले असतात, पैशाचा प्रवाह येतो आणि कल वाढतो.</li>\n<li>ए <strong>अस्वल बाजार</strong> विरुद्ध आहे, एक दीर्घकाळ पडणे, सहसा एक थेंब म्हणून परिभाषित <strong>20% किंवा अधिक</strong> अलीकडील शिखरावरून, भीती आणि निराशावादाने गुंडाळलेले.</li>\n</ul>\n<p>हे दोन प्राणी का? लोकप्रिय स्पष्टीकरण मध्ये आहे <em>प्रत्येक प्राणी कसा हल्ला करतो</em>. ए <strong>बैल</strong> त्याची शिंगे जोरात मारतो <strong>वरच्या दिशेने</strong> प्रतिस्पर्ध्याला मारण्यासाठी, किमती वाढतात. ए <strong>अस्वल</strong> त्याचे पंजे स्वाइप करते <strong>खालच्या दिशेने</strong> किमती कमी केल्या जात आहेत. वर-शिंगे, खाली-पंजे. ही एक संस्मरणीय प्रतिमा आहे आणि ती शतकानुशतके अडकली आहे.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch12-bull-vs-bear.png\" alt=\"वाढत्या ट्रेंड लाईन वर चार्ज करणारा बैल विरुद्ध खाली पडणाऱ्याला स्वाइप करत असलेला अस्वल, वरची-शिंगे आणि खाली-पंजेचा आकृतिबंध ज्याने बाजाराच्या दोन मूड्सना नाव दिले\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>वाढत्या ट्रेंड लाईन वर चार्ज करणारा बैल विरुद्ध खाली पडणाऱ्याला स्वाइप करत असलेला अस्वल, वरची-शिंगे आणि खाली-पंजेचा आकृतिबंध ज्याने बाजाराच्या दोन मूड्सना नाव दिले</figcaption></figure>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>बैल आणि अस्वल भाषा खऱ्या अर्थाने जुनी आहे. \"अस्वल\" प्रथम आले, 18व्या शतकातील लंडनमधील व्यापारी ज्यांनी त्यांच्याकडे अद्याप नसलेली वस्तू विकली ते \"अस्वल पकडण्याआधी अस्वलाचे कातडे\" विकत असल्याचे म्हटले जाते. आशावादी \"वळू\" नंतर त्याच्या नैसर्गिक विरुद्ध म्हणून तयार केले गेले. हे शब्द जगातील बहुतेक स्टॉक एक्सचेंजपेक्षा जुने आहेत.</p>\n</div></div>\n<h2 id=\"large-cap-mid-cap-small-cap\">लार्ज-कॅप, मिड-कॅप, स्मॉल-कॅप</h2>\n<p>तुम्हाला सतत साठा क्रमवारी ऐकू येईल <strong>बाजार भांडवलीकरण</strong> (किंमत x समभागांची संख्या) तीन बादल्यांमध्ये. भारतात, SEBI द्वारे व्याख्या निश्चित करते <em>रँक</em>, एका निश्चित रुपयाच्या मूल्यानुसार नाही, त्यामुळे बाजार जसजसा वाढत जातो तसतसे लेबले अर्थपूर्ण राहतात:</p>\n<table>\n<thead>\n<tr>\n<th>श्रेणी</th>\n<th>SEBI मार्केट कॅपनुसार रँक</th>\n<th>उग्र वर्ण</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>लार्ज-कॅप</strong></td>\n<td>शीर्ष 100 कंपन्या</td>\n<td>मोठा, स्थापित, स्थिर. घरगुती नाव \"ब्लू-चिप्स\", रिलायन्स आणि HDFC बँका. कमी जोखीम, स्थिर वाढ.</td>\n</tr>\n<tr>\n<td><strong>मिड-कॅप</strong></td>\n<td>101 वा ते 250 वा</td>\n<td>मध्यम आकाराचे, अनेकदा वेगाने वाढणारे. अधिक बक्षीस, अधिक जोखीम.</td>\n</tr>\n<tr>\n<td><strong>स्मॉल-कॅप</strong></td>\n<td>२५१ वा पुढे</td>\n<td>लहान, कमी सिद्ध कंपन्या. सर्वाधिक वाढीची क्षमता आणि तीव्र पडझडीचा सर्वाधिक धोका.</td>\n</tr>\n</tbody></table>\n<p>ट्रेड-ऑफ ही संपूर्ण कथा आहे: स्मॉल-कॅप्स तुमचा पैसा सर्वात जलद गुणाकार करू शकतात <em>आणि</em> सर्वात कठीण पडणे. गर्जना करणाऱ्या बुल मार्केटमध्ये स्मॉल कॅप्स अनेकदा उडतात; जेव्हा भीती परत येते तेव्हा ते प्रथम आणि सर्वात खोल क्रॅश होतात. नवशिक्या सहसा लार्ज-कॅप्सकडे या कारणास्तव वळवले जातात, ते मालवाहू जहाजे असतात, स्पीडबोट्स नाहीत.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>\"ब्लू-चिप\" म्हणजे एक मोठी, आर्थिकदृष्ट्या मजबूत, लांब ट्रॅक रेकॉर्ड असलेली सुप्रसिद्ध कंपनी, हा शब्द पोकरकडून घेतला जातो, जेथे ब्लू चिप्सचे मूल्य सर्वाधिक असते. दुसऱ्या टोकाला, ए <strong>पेनी स्टॉक</strong> हा एक अतिशय स्वस्त, लहान, अनेकदा क्वचितच-व्यापार केलेला शेअर आहे. कमी किंमत म्हणजे सौदा नाही; हे सहसा लहान, नाजूक, सहजपणे हाताळलेल्या कंपनीला सूचित करते.</p>\n</div></div>\n<h2 id=\"circuits-the-market-s-automatic-brakes\">सर्किट्स: मार्केटचे स्वयंचलित ब्रेक</h2>\n<p>घाबरणे किंवा उन्मादाला जंगली धावण्यापासून रोखण्यासाठी, भारतीय एक्सचेंज लादतात <strong>सर्किट मर्यादा</strong>, किंमत बँड की <em>थांबणे</em> स्टॉकमध्ये ट्रेडिंग जेव्हा तो एकाच दिवसात खूप पुढे जातो.</p>\n<ul>\n<li>अ <strong>वरचे सर्किट</strong> त्या दिवशी स्टॉक जास्तीत जास्त वाढू शकतो. तो दाबा आणि फक्त खरेदीदार आहेत, विक्रेते नाहीत, किंमत शीर्षस्थानी गोठलेली आहे.</li>\n<li>ए <strong>लोअर सर्किट</strong> तो पडू शकतो कमाल आहे. ते दाबा आणि तळाशी फक्त विक्रेते आहेत, खरेदीदार नाहीत.</li>\n</ul>\n<p>वैयक्तिक स्टॉकमध्ये स्टॉकवर अवलंबून 2%, 5%, 10% किंवा 20% सारखे बँड असतात. तसेच आहेत <strong>मार्केट-व्यापी सर्किट ब्रेकर</strong>: जर संपूर्ण निफ्टी किंवा सेन्सेक्स एका दिवसात 10%, 15% किंवा 20% घसरला तर संपूर्ण बाजारातील व्यापार थंडावण्याच्या कालावधीसाठी थांबतो. सर्किट्स हे सेफ्टी व्हॉल्व्ह आहेत, सक्तीचे कालबाह्य आहेत जेणेकरून प्रत्येकजण आपला श्वास घेऊ शकेल.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>मध्ये लॉक केलेला स्टॉक <strong>वरचे सर्किट</strong> खात्रीशीर विजेत्यासारखे वाटू शकते, प्रत्येकाला हवे आहे, कोणीही विकत नाही. हा एक क्लासिक ट्रॅप आहे. जेव्हा मूड फ्लिप होतो, तेव्हा तोच स्टॉक मध्ये अडकू शकतो <strong>लोअर सर्किट</strong> दिवसेंदिवस, खरेदीदार नसल्यामुळे, धारकांना कोणत्याही किंमतीला विकता येत नाही. सर्किट्स दोन्ही मार्गांनी कापतात आणि ते पातळ, हायप्ड स्मॉल-कॅप्समध्ये सर्वात कठीण कापतात.</p>\n</div></div>\n<h2 id=\"volume-and-liquidity\">खंड आणि तरलता</h2>\n<p><strong>खंड</strong> एका कालावधीत, एक दिवस, एक तास, एक मिनिटात व्यापार केलेल्या समभागांची संख्या आहे. उच्च व्हॉल्यूम म्हणजे भरपूर क्रियाकलाप आणि स्वारस्य; ट्रेडच्या ट्रिकलवरील समान हालचालींपेक्षा भारी व्हॉल्यूमवरील किंमती अधिक गंभीरपणे घेतल्या जातात.</p>\n<p><strong>तरलता</strong> तुम्ही किती सहज खरेदी किंवा विक्री करू शकता <em>किंमत हलविल्याशिवाय</em>. अत्यंत तरल स्टॉक (रिलायन्स किंवा HDFC बँक विचार करा) इतके खरेदीदार आणि विक्रेते आहेत की तुम्ही वाजवी किमतीत त्वरित मोठ्या प्रमाणात व्यापार करू शकता. अलिक्विड स्टॉकमध्ये इतका कमी असतो की अगदी माफक ऑर्डर देखील किंमत बदलते आणि सर्वात वाईट म्हणजे तुम्हाला त्रास होऊ शकतो <em>बाहेर पडा</em> जेव्हा तुम्हाला बाहेर हवे असते. तरलता सोडण्याचे स्वातंत्र्य आहे. कधीही कमी लेखू नका.</p>\n<h2 id=\"long-short-and-the-magic-of-selling-first\">लांब, लहान आणि प्रथम विक्रीची जादू</h2>\n<p>बहुतेक लोक फक्त कधी जातात <strong>लांब</strong>: तू <em>खरेदी</em> स्टॉक वाढेल या आशेने, नंतर नफ्यासाठी नंतर विक्री करा. कमी खरेदी करा, जास्त विक्री करा. साधे.</p>\n<p><strong>लहान विक्री</strong> त्याच्या डोक्यावर ऑर्डर flips, आपण विक्री <em>प्रथम</em> आणि खरेदी करा <em>नंतर परत</em>, म्हणून जेव्हा स्टॉक तेव्हा तुम्हाला फायदा होतो <strong>पडतो</strong>. हे अशक्य वाटते: तुमच्या मालकीची नसलेली वस्तू तुम्ही कशी विकता? आपण <strong>कर्ज घेणे</strong> ते</p>\n<p>येथे क्रम आहे:</p>\n<ol>\n<li>तुम्हाला विश्वास आहे की स्टॉक एक्स, रु. 100 वर ट्रेडिंग, घसरणार आहे.</li>\n<li>आपण <strong>कर्ज घेणे</strong> शेअर्स (तुमच्या ब्रोकर/एक्स्चेंजच्या लेंडिंग पूलकडून) आणि <strong>विक्री</strong> त्यांनी ताबडतोब 100 रुपये, रोख खिशात टाकले.</li>\n<li>तुमच्या अपेक्षेप्रमाणे किंमत 80 रुपयांपर्यंत घसरली.</li>\n<li>आपण <strong>खरेदी</strong> शेअर्स परत 80 रुपये आणि <strong>परत</strong> कर्जदाराला कर्ज घेतलेले शेअर्स.</li>\n<li>तुम्ही फरक ठेवा: <strong>20 रुपये प्रति शेअर</strong> नफा</li>\n</ol>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch12-short-selling-flow.png\" alt=\"पाच-स्टेप शॉर्ट-सेल लूप, शेअर्स उधार घ्या, उच्च विक्री करा, पडण्याची प्रतीक्षा करा, कमी खरेदी करा, शेअर्स परत करा आणि फरक ठेवा\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">फ्लो चार्ट</span>पाच-स्टेप शॉर्ट-सेल लूप, शेअर्स उधार घ्या, उच्च विक्री करा, पडण्याची प्रतीक्षा करा, कमी खरेदी करा, शेअर्स परत करा आणि फरक ठेवा</figcaption></figure>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>कमी विक्रीमध्ये धोका असतो की खरेदी कधीच करत नाही: <strong>तुमचे नुकसान अमर्यादित असू शकते.</strong> जेव्हा तुम्ही 100 रुपयांना शेअर खरेदी करता, तेव्हा सर्वात वाईट गोष्ट म्हणजे ती शून्यावर जाते, तुमचे 100 रुपये गमवावे लागतात. पण जर तुम्ही <em>लहान</em> रु. 100 वर आणि स्टॉक चढत राहतो, रु. 150, रु. 300, रु. 500, तुमचा तोटा कमाल मर्यादेशिवाय वाढतो, कारण किंमत कायमची वाढू शकते पण फक्त शून्यावर येऊ शकते. ही विषमता म्हणूनच लहान विक्री ही एक प्रगत, उच्च-जोखीम क्रियाकलाप आहे.</p>\n</div></div>\n<p>भारतात, बहुतेक किरकोळ व्यापाऱ्यांसाठी आणखी एक नियम आहे: तुम्ही साधारणपणे फक्त लहान करू शकता <strong>इंट्राडे</strong>, आपण परत खरेदी आणि स्थिती बंद करणे आवश्यक आहे <strong>त्याच दिवशी बाजार बंद होण्यापूर्वी</strong>. रात्रभर थोडा वेळ ठेवण्यासाठी तुम्हाला सिक्युरिटीज लेंडिंग अँड बोरोइंग (SLB) यंत्रणेद्वारे औपचारिकपणे स्टॉक उधार घ्यावा लागेल. नवशिक्यासाठी, लहान विक्री ही गोष्ट आहे <em>समजून घेणे</em>, करू नये.</p>\n<h2 id=\"the-rest-of-the-tv-vocabulary\">बाकी TV शब्दसंग्रह</h2>\n<p>तुम्ही सतत ऐकत असलेल्या इतर शब्दांची द्रुत-फायर शब्दकोष:</p>\n<table>\n<thead>\n<tr>\n<th>मुदत</th>\n<th>एका ओळीचा अर्थ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>52-आठवडे उच्च / कमी</strong></td>\n<td>मागील वर्षात स्टॉकची सर्वोच्च आणि सर्वात कमी किंमत, तो कुठे उभा आहे याचे द्रुत गेज.</td>\n</tr>\n<tr>\n<td><strong>रॅली</strong></td>\n<td>अल्प कालावधीत किमतींमध्ये तीव्र, सतत वाढ.</td>\n</tr>\n<tr>\n<td><strong>सुधारणा</strong></td>\n<td>अंदाजे एक गडी बाद होण्याचा क्रम <strong>10% किंवा अधिक</strong> अलीकडील शिखरावरून, सामान्य, निरोगी आणि वारंवार.</td>\n</tr>\n<tr>\n<td><strong>क्रॅश</strong></td>\n<td>एका दिवसात किंवा काही दिवसांत अचानक, तीव्र, अनेकदा घाबरून जाणारी उडी.</td>\n</tr>\n<tr>\n<td><strong>बाजार रुंदी</strong></td>\n<td>किती शेअर्स वाढले विरुद्ध घसरले, \"अग्रिम विरुद्ध घसरण.\" मजबूत रुंदी (बहुतेक स्टॉक अप) म्हणजे एक व्यापक, निरोगी हालचाल; कमकुवत रुंदी म्हणजे काही दिग्गज पडत्या गर्दीला मुखवटा घालत आहेत.</td>\n</tr>\n<tr>\n<td><strong>अस्थिरता</strong></td>\n<td>किमती किती बिनधास्तपणे वाढत आहेत. उच्च अस्थिरता = दोन्ही दिशांमध्ये मोठी, वेगवान हालचाल.</td>\n</tr>\n<tr>\n<td><strong>बोली / विचारा</strong></td>\n<td>सर्वोत्तम किंमत खरेदीदार देईल (बिड) आणि विक्रेता स्वीकारेल (विचारेल).</td>\n</tr>\n<tr>\n<td><strong>ब्लू-चिप</strong></td>\n<td>एक मोठी, स्थिर, प्रतिष्ठित कंपनी.</td>\n</tr>\n<tr>\n<td><strong>पेनी स्टॉक</strong></td>\n<td>एक अतिशय स्वस्त, लहान, जोखमीचा वाटा.</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>तुम्हाला हा शब्दकोष लक्षात ठेवण्याची गरज नाही. ते संदर्भ म्हणून ठेवा आणि तुम्ही काही आठवडे बाजार पाहता तेव्हा अटी नैसर्गिकरित्या बुडतील. या कल्पनांचा दररोज वापर करणाऱ्या लोकांमध्ये जार्गन हा एक लघुलेख आहे आणि लवकरच, त्यात तुमचा समावेश होईल.</p>\n</div></div>\n<h2 id=\"quick-recap\">क्विक रिकॅप</h2>\n<ul>\n<li>ए <strong>बैल बाजार</strong> उगवते (शिंगे वर जोरात); a <strong>अस्वल बाजार</strong> त्याच्या शिखरावरून 20%+ खाली पडते (पंजे खाली स्वाइप करतात). प्राणी प्रत्येक हल्ला कसा करतात याचे वर्णन करतात.</li>\n<li>स्टॉक्समध्ये विभागले गेले <strong>मोठी टोपी</strong> (टॉप 100, सर्वात सुरक्षित), <strong>मिड-कॅप</strong> (101-250) आणि <strong>लहान टोपी</strong> SEBI च्या मार्केट-कॅप रँकिंगनुसार (251+, सर्वोच्च जोखीम आणि बक्षीस).</li>\n<li><strong>सर्किट्स</strong> स्वयंचलित किंमत-बँड थांबे आहेत, <strong>वरचा</strong> (गोठवलेले, फक्त खरेदीदार) आणि <strong>कमी</strong> (गोठवलेले, फक्त विक्रेते), तसेच मार्केट-व्यापी ब्रेकर्स.</li>\n<li><strong>खंड</strong> किती व्यापार होतो; <strong>तरलता</strong> किंमत न हलवता तुम्ही किती सहजतेने बाहेर पडू शकता आणि तुम्ही बाहेर पडू इच्छिता तेव्हा हे सर्वात महत्त्वाचे आहे.</li>\n<li>जात आहे <strong>लांब</strong> म्हणजे खरेदी-नंतर-विक्री (जेव्हा तो वाढतो तेव्हा नफा); <strong>कमी विक्री</strong> म्हणजे उधार-विक्री-खरेदी-परत (नफा कमी झाल्यावर), सह <strong>अमर्यादित</strong> तोट्याचा धोका आणि, भारतातील बहुतेक किरकोळ विक्रीसाठी, फक्त इंट्रा-डे.</li>\n<li>सारखे शब्द <strong>52-आठवड्याचा उच्च /low, रॅली, सुधारणा, क्रॅश, रुंदी, ब्लू-चिप</strong> आणि <strong>पेनी स्टॉक</strong> फक्त दैनंदिन मार्केट शॉर्टहँड आहेत जे तुम्ही पटकन आत्मसात कराल.</li>\n</ul>\n<p>पुढे, आम्ही या सर्वांच्या हृदयापर्यंत पोहोचतो: <em>स्टॉकची हालचाल कशामुळे होते?</em> आम्ही ऑर्डर बुकमध्ये टीक्क करून किंमत सेट केली आहे ते पाहू आणि चांगली कमाई देखील स्टॉक का पाठवू शकते ते पाहू. <em>खाली</em>.</p>\n","toc":[{"level":2,"text":"बैल आणि अस्वल: बाजाराचे दोन मूड","id":"bulls-and-bears-the-market-s-two-moods"},{"level":2,"text":"लार्ज-कॅप, मिड-कॅप, स्मॉल-कॅप","id":"large-cap-mid-cap-small-cap"},{"level":2,"text":"सर्किट्स: मार्केटचे स्वयंचलित ब्रेक","id":"circuits-the-market-s-automatic-brakes"},{"level":2,"text":"खंड आणि तरलता","id":"volume-and-liquidity"},{"level":2,"text":"लांब, लहान आणि प्रथम विक्रीची जादू","id":"long-short-and-the-magic-of-selling-first"},{"level":2,"text":"बाकी TV शब्दसंग्रह","id":"the-rest-of-the-tv-vocabulary"},{"level":2,"text":"क्विक रिकॅप","id":"quick-recap"}],"imgCount":2,"hasContent":true},"13":{"html":"<p>येथे एक प्रश्न आहे जो सोपा वाटतो परंतु बाजारातील जवळजवळ सर्व काही अनलॉक करतो: <em>स्टॉकची किंमत अजिबात का बदलते?</em> एक मिनिट रिलायन्स 1,420 रुपये आहे, काही सेकंदांनंतर ते 1,420.50 रुपये आहे, नंतर 1,419.80 रुपये आहे. ते आकडे कोण ठरवणार? कंपनी नाही. देवाणघेवाण नाही. काही समिती \"वाजवी किंमत\" ठरवत नाही. सत्य नम्र आणि अधिक शक्तिशाली आहे: <strong>स्टॉकची किंमत ही अगदी अलीकडील रक्कम आहे ज्यावर इच्छुक खरेदीदार आणि इच्छुक विक्रेता सहमत आहे.</strong> आणखी काही नाही.</p>\n<p>तुम्हाला स्क्रीनवर दिसणारी प्रत्येक टिक हा ताजे हँडशेक आहे. वरून दिलेली किंमत ही वस्तुस्थिती नाही, ती आहे <em>वाटाघाटी</em>शेअरची किंमत काय आहे याबद्दल असहमत असलेल्या लोकांमध्ये सेकंदाला हजारो वेळा घडत आहे. ते समजून घ्या, आणि या प्रकरणाचा उर्वरित भाग लागू होईल.</p>\n<h2 id=\"the-order-book-a-continuous-auction\">ऑर्डर बुक: सतत लिलाव</h2>\n<p>प्रत्येक स्टॉकच्या मागे एक बसतो <strong>ऑर्डर बुक</strong>, खरेदी करू इच्छिणाऱ्या प्रत्येकाची आणि ज्यांना विक्री करायची आहे अशा प्रत्येकाची थेट यादी आणि कोणत्या किंमतीला. एका बाजूला आहेत <strong>खरेदीदार</strong> त्यांच्या सह <strong>बोली</strong> (ते द्यायला तयार असलेल्या किमती). इतर वर आहेत <strong>विक्रेते</strong> त्यांच्या सह <strong>विचारतो</strong> (त्यांना ज्या किमती मिळवायच्या आहेत).</p>\n<p>खरेदीदार आणि विक्रेता तेव्हाच व्यापार होतो <strong>किंमतीवर सहमत</strong>, जेव्हा कोणीतरी पैसे देण्यास तयार असतो तेव्हा कोणीतरी स्वीकारण्यास तयार असते. त्या जुळलेल्या व्यापाराची किंमत ही नवीन \"शेवटची व्यापार केलेली किंमत\" बनते, जी तुम्ही उद्धृत केलेली संख्या पाहता. मग पुढची मॅच पुढची किंमत ठरवते आणि असेच दिवसभर. ते अ <strong>सतत लिलाव</strong>, दिवसातून एकदा गिव्हल नाही तर एक रोलिंग वाटाघाटी जी बाजाराच्या वेळेत कधीही थांबत नाही.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch13-order-book-auction.png\" alt=\"सतत लिलाव म्हणून ऑर्डर बुक, खरेदीच्या बाजूने रचलेल्या बोली, विक्रीच्या बाजूने विचारणा आणि नवीनतम जुळलेला व्यापार मध्यभागी थेट किंमत सेट करतो\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>सतत लिलाव म्हणून ऑर्डर बुक, खरेदीच्या बाजूने रचलेल्या बोली, विक्रीच्या बाजूने विचारणा आणि नवीनतम जुळलेला व्यापार मध्यभागी थेट किंमत सेट करतो</figcaption></figure>\n<p>यामुळेच किंमत टिक करून टिकते, आणि तर्क खूपच सोपे आहे:</p>\n<ul>\n<li>जेव्हा <strong>विक्रेत्यांपेक्षा खरेदीदार अधिक उत्सुक आहेत</strong>, पुरवठ्यापेक्षा जास्त मागणी, खरेदीदार त्यांचे शेअर्स मिळवण्यासाठी जास्त मागणी स्वीकारू लागतात. किंमत <strong>ticks</strong>.</li>\n<li>जेव्हा <strong>विक्रेते खरेदीदारांपेक्षा अधिक उत्सुक आहेत</strong>, मागणीपेक्षा जास्त पुरवठा, विक्रेते ऑफलोड करण्यासाठी कमी बोली स्वीकारू लागतात. किंमत <strong>खाली ticks</strong>.</li>\n</ul>\n<p>ते संपूर्ण इंजिन आहे. वर किंवा खाली, प्रत्येक हालचाल एका असंतुलनाकडे परत येते: या क्षणी, जास्त भूक होती का? <em>खरेदी</em> किंवा जास्त भूक लागते <em>विक्री</em>?</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>स्टॉकची किंमत ही कंपनी \"किमतीची\" नसते. खरेदीदार आणि विक्रेते यांच्यात सुरू असलेल्या टग-ऑफ-वॉरचा हा थेट स्कोअर आहे. विक्रेत्यांपेक्षा अधिक उत्सुक खरेदीदार ते वाढवतात; खरेदीदारांपेक्षा अधिक उत्सुक विक्रेते ते खाली खेचतात. या प्रकरणातील इतर सर्व काही खरोखरच आहे <em>कशामुळे गर्दी एक किंवा इतर मार्गाने झुकते.</em></p>\n</div></div>\n<h2 id=\"what-tips-the-balance\">शिल्लक काय टिपा</h2>\n<p>जर किंमत ही टग-ऑफ-वॉर असेल, तर मनोरंजक प्रश्न उद्भवतो: लोकांची अचानक खरेदी करण्याची किंवा विकण्याची घाई कशामुळे होते? काही मोठ्या शक्ती:</p>\n<ul>\n<li><strong>बातम्या.</strong> नवीन सरकारी करार, फॅक्टरी आग, नियामक बंदी, CEO राजीनामा, ताजी माहिती लोक कंपनीचे मूल्य कसे बदलतात आणि ते बदलतात.</li>\n<li><strong>कमाई.</strong> प्रत्येक तिमाहीत, कंपन्या त्यांच्या नफ्याची नोंद करतात. मजबूत परिणाम खरेदीदारांना आकर्षित करतात; कमकुवत विक्रेते धावत पाठवतात. (खालील ट्विस्टवर अधिक.)</li>\n<li><strong>अपेक्षा.</strong> हे सूक्ष्म, बाजार-परिभाषित आहे. किंमती केवळ आजच नव्हे तर लोक काय दर्शवतात <em>उद्याची अपेक्षा करा</em>.</li>\n<li><strong>भावना.</strong> काहीवेळा संपूर्ण बाजार फक्त भयभीत किंवा लोभी असतो आणि तो मूड वैयक्तिक शेअर्सच्या स्वत:च्या बातम्यांची पर्वा न करता स्वीप करतो.</li>\n</ul>\n<h2 id=\"markets-price-the-future-not-the-present\">बाजार भविष्याची किंमत ठरवते, वर्तमानाची नाही</h2>\n<p>नवशिक्यांसाठी हे एकमेव सर्वात प्रति-अंतर्ज्ञानी सत्य आहे, आणि ते लवकर मिळाल्याने तुमचा अनेक वर्षांचा गोंधळ वाचेल: <strong>बाजार हे एक दूरदर्शी मशीन आहे.</strong> आजची किंमत आधीच गुंतवणुकदारांमध्ये काय बेक करते <em>अपेक्षा</em> घडणे त्यामुळे बातमी चांगली आहे की वाईट यावर स्टॉक प्रतिक्रिया देत नाही, ती बातमी आहे की नाही यावर प्रतिक्रिया देतो. <strong>आधीच अपेक्षित असलेल्यापेक्षा चांगले किंवा वाईट.</strong></p>\n<p>यामुळे तुम्हाला कंपनीच्या अहवालात नफा, खऱ्या अर्थाने उत्कृष्ट आकडा आणि स्टॉक पहाताना दिसेल <em>पडणे</em> त्याच दुपारी. कसे? कारण गुंतवणूकदारांची अपेक्षा होती <em>आणखी चांगले</em>. अजूनही महान परिणाम <strong>सम-उच्च अपेक्षा चुकल्या</strong> आधीच किंमत आहे, त्यामुळे ज्या खरेदीदारांनी अपेक्षेने स्टॉकची बोली लावली होती ते आता निराश होऊन विक्री करतात.</p>\n<p>फ्लिप बाजू तितकीच खरी आहे: एक संघर्ष करणारी कंपनी कुरूप नुकसान आणि स्टॉकची तक्रार करू शकते <em>उगवतो</em>, फक्त कारण नुकसान होते <em>भीतीपेक्षा लहान</em>. बाजार नेहमी अपेक्षेविरुद्ध वास्तवाची तुलना करत असतो, शून्याशी नाही.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>यासाठी व्यापाऱ्यांची एक म्हण आहे. <strong>\"अफवा विकत घ्या, बातम्या विका.\"</strong> स्टॉक अनेकदा आठवडे चढतो <em>अपेक्षेने</em> एक उत्तम परिणाम, जसे अपेक्षा निर्माण होते, आणि नंतर <em>पडतो</em> ज्या क्षणी खरी चांगली बातमी येते, कारण ज्या लोकांनी अफवा विकत घेतली ते आता त्यांचा नफा घेतात. प्रत्येकजण ज्या बातमीची वाट पाहत होता ती विक्रीसाठी ट्रिगर बनते. चांगली बातमी, घसरण किंमत, आणि आता तुम्हाला का माहित आहे.</p>\n</div></div>\n<h2 id=\"sentiment-and-the-herd\">भावना आणि कळप</h2>\n<p>बाजारपेठ लोकांपासून बनलेली असते आणि लोक भावनिक आणि सामाजिक असतात. जेव्हा किंमती वाढत असतात, तेव्हा आशावाद स्वतःलाच फीड करतो, इतर पैसे कमवत असतात, त्यामुळे अधिक ढीग होतात, किमती अजून वाढतात. हे आहे <strong>कळपाचे वर्तन</strong>, आणि ते उलट देखील कार्य करते: जेव्हा किंमती घसरतात तेव्हा भीती पसरते, लोक पुढील वेदना टाळण्यासाठी विक्री करतात आणि विक्रीमुळेच किंमती कमी होतात.</p>\n<p>सेंटिमेंट एखाद्या स्टॉकला त्याच्या मूलभूत गोष्टींपासून आश्चर्यकारकपणे लांब पसरवण्यापासून वेगळे करू शकते, कोणत्याही शांत मूल्यमापनाने बबलमध्ये न्याय्य ठरविण्यापेक्षा जास्त किंवा घाबरलेल्या स्थितीत त्याच्या पात्रतेपेक्षा कमी पाठवणे. ते ओळखून <em>गर्दी हा किमतीचा भाग आहे</em> तुम्ही वाहून घेऊ शकता हे सर्वात उपयुक्त मानसिक मॉडेलपैकी एक आहे. तुमच्या स्वतःच्या मानसशास्त्रावर प्रभुत्व मिळविण्यासाठी आम्ही नंतरचा संपूर्ण अध्याय समर्पित करतो जेणेकरून कळप वाहून जाऊ नये <em>आपण</em> बाजूने</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>\"प्रत्येकजण ते विकत घेत आहे\" हे खरेदी करण्याचे कारण नाही. प्रत्येक व्हॉट्सॲप ग्रुपमध्ये स्टॉक हा चर्चेचा विषय असतो तोपर्यंत, बहुतेक आशावाद आधीच किंमतीत असतो आणि तुम्ही खरेदी करत असाल जेव्हा सुरुवातीचा जमाव विक्रीच्या तयारीत असेल. कळप वळण्यापूर्वी सर्वात मोठा आवाज आहे.</p>\n</div></div>\n<h2 id=\"a-concrete-example-results-day\">एक ठोस उदाहरण: निकालाचा दिवस</h2>\n<p>काल्पनिक IT कंपनीचे चित्र काढा, <strong>इन्फोकोर</strong>, येथे ट्रेडिंग <strong>५०० रु</strong>. विश्लेषकांना तिमाही नफ्यात 15% ची वाढ अपेक्षित आहे आणि गुंतवणूकदारांनी मजबूत आकडा ठेवल्यामुळे गेल्या महिन्यात स्टॉक शांतपणे रु. 450 ते रु. 500 वर गेला आहे. परिणाम बाहेर येतात: नफा वाढला <strong>12%</strong>, खरोखर निरोगी वाढ, पण <em>खाली</em> मार्केटमध्ये 15% किंमत होती. काही मिनिटांत, निराश खरेदीदार विक्रेते वळतात, ऑर्डर बुक विक्रीच्या बाजूकडे झुकते आणि इन्फोकोर खाली येते <strong>465 रु</strong>.</p>\n<p>एक शेजारी जो फक्त मथळा वाचतो तो गोंधळून जातो: \"नफा <em>वाढले</em> आणि स्टॉक <em>पडले</em>?\" पण आता तुम्हाला समजले आहे, बाजाराची तुलना अपेक्षित 15% विरुद्ध 12% होती, शून्याशी नाही. वाढ खरी होती; ती फक्त नव्हती <em>पुरेसे</em>. जर इन्फोकोरने 18% वितरित केले असते, तर त्याच अहवालाने ते वाढले असते.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch13-results-reaction-chart.png\" alt=\"स्टॉकच्या निकालांवर प्रतिक्रिया देणारा कॅन्डलस्टिक चार्ट, घोषणेमध्ये स्थिर चढाई, त्यानंतर ज्या दिवशी अपेक्षा चुकल्या त्या दिवशी एक तीव्र अंतर\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>स्टॉकच्या निकालांवर प्रतिक्रिया देणारा कॅन्डलस्टिक चार्ट, घोषणेमध्ये स्थिर चढाई, त्यानंतर ज्या दिवशी अपेक्षा चुकल्या त्या दिवशी एक तीव्र अंतर</figcaption></figure>\n<h2 id=\"putting-a-number-on-it-calculating-your-return\">त्यावर नंबर टाकणे: तुमच्या परताव्याची गणना करणे</h2>\n<p>स्टॉक कोणत्या मार्गाने फिरतो, तुम्हाला ते कसे मोजायचे आहे <em>आपण</em> केले दोन नंबर महत्त्वाचे.</p>\n<p><strong>पूर्ण परतावा</strong> साधा रुपया फायदा किंवा तोटा आहे:</p>\n<blockquote>\n<p>परिपूर्ण परतावा = विक्री किंमत, खरेदी किंमत</p>\n</blockquote>\n<p>400 रुपयांना खरेदी करा, 500 रुपयांना विक्री करा आणि तुमचा पूर्ण फायदा आहे <strong>100 रु</strong> प्रति शेअर.</p>\n<p><strong>टक्केवारी परतावा</strong> ते तुमच्या गुंतवणुकीशी मोजा, ​​जेणेकरून तुम्ही इतर कोणत्याही गोष्टीशी त्याची तुलना करू शकता:</p>\n<blockquote>\n<p>टक्केवारी परतावा = (प्राप्त / खरेदी किंमत) x 100</p>\n</blockquote>\n<p>येथे: (100 / 400) x 100 = <strong>25%</strong>. 25% परतावा.</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">खरे उदाहरण</span><div><p>टक्केवारी रुपयापेक्षा जास्त महत्त्वाची आहे. 400 रुपयांच्या स्टॉकवर 100 रुपयांचा फायदा होतो <strong>25%</strong> परत 2,000 रुपयांच्या स्टॉकवर 100 रुपयांचा तोच फायदा होतो <strong>5%</strong>. तेच रुपये, खूप वेगळा निकाल, नेहमी टक्केवारीत विचार करा म्हणजे तुम्ही लाईकशी तुलना करता.</p>\n</div></div>\n<p>आणखी एक थर आहे: <strong>वेळ</strong>. 25% परतावा एका वर्षात नेत्रदीपक आणि दहापेक्षा जास्त मध्यम आहे. वेगवेगळ्या कालावधीसाठी ठेवलेल्या गुंतवणुकीची तुलना करण्यासाठी, लोक परतावा a मध्ये रूपांतरित करतात <strong>प्रति वर्ष</strong> आकृती, द <strong>वार्षिक</strong> परत अचूक गणिते नंतर येतात; आत्तासाठी, कोणत्याही रिटर्नबद्दल नेहमी दोन प्रश्न विचारण्यासाठी फक्त अंतःप्रेरणा लॉक करा: <em>किती,</em> आणि <em>किती काळ?</em> कालमर्यादा नसलेली संख्या ही अर्धी वस्तुस्थिती असते.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>जेव्हा एखादा स्टॉक \"दुप्पट\" झाल्याची बढाई मारतो तेव्हा तुमचा पहिला प्रश्न \"कोणत्या कालावधीत?\" एका वर्षात दुप्पट होणे विलक्षण आहे; पंधरा वर्षांमध्ये दुप्पट करणे हे एका वर्षातील 5% च्या खाली काम करते, मुदत ठेवीपेक्षा कमी. परतावा आणि वेळ अविभाज्य आहेत. दुसऱ्याशिवाय कोणीही तुम्हाला एक उद्धृत करू देऊ नका.</p>\n</div></div>\n<h2 id=\"quick-recap\">क्विक रिकॅप</h2>\n<ul>\n<li>एक स्टॉक <strong>किंमत फक्त नवीनतम करार आहे</strong> इच्छुक खरेदीदार आणि इच्छुक विक्रेता यांच्यात, नवीन हँडशेक, सेकंदाला हजारो वेळा, वरून खाली दिलेले मूल्य नाही.</li>\n<li>द <strong>ऑर्डर बुक</strong> धावा a <strong>सतत लिलाव</strong>: विक्रेत्यांपेक्षा अधिक उत्सुक खरेदीदार किंमतीवर टिक करतात <strong>वर</strong>, खरेदीदारांपेक्षा अधिक उत्सुक विक्रेते त्यावर टिक करतात <strong>खाली</strong>.</li>\n<li><strong>बातम्या, कमाई, अपेक्षा आणि भावना</strong> काय टीप आहे की शिल्लक आणि जमाव एक मार्ग झुकणे पाठवा.</li>\n<li>बाजारपेठा <strong>भविष्याची किंमत</strong>, म्हणून स्टॉक परिणामांवर प्रतिक्रिया देतो <em>अपेक्षांच्या सापेक्ष</em>, एक महान चतुर्थांश <strong>अगदी-उच्च आशा अजूनही कमी होऊ शकतात</strong> (\"अफवा विकत घ्या, बातम्या विका\").</li>\n<li><strong>कळपाचे वर्तन</strong> किमती वाजवी मूल्यापेक्षा जास्त किंवा खाली ढकलू शकतात, म्हणूनच \"प्रत्येकजण खरेदी करत आहे\" ही चेतावणी आहे, कारण नाही.</li>\n<li>यासह आपले परिणाम मोजा <strong>निरपेक्ष</strong> (रुपया) आणि <strong>टक्केवारी</strong> रिटर्न, आणि नेहमी कोणत्याही रिटर्नशी जोडा <strong>कालमर्यादा</strong> घेतला.</li>\n</ul>\n<p>पुढे, आम्ही एका समभागापासून संपूर्ण अर्थव्यवस्थेकडे लेन्स रुंद करतो, व्याजदर, महागाई, रुपया, कच्चे तेल आणि जागतिक प्रवाह वरून भारतीय शेअर्सवर कसा घसरण करतो.</p>\n","toc":[{"level":2,"text":"ऑर्डर बुक: सतत लिलाव","id":"the-order-book-a-continuous-auction"},{"level":2,"text":"शिल्लक काय टिपा","id":"what-tips-the-balance"},{"level":2,"text":"बाजार भविष्याची किंमत ठरवते, वर्तमानाची नाही","id":"markets-price-the-future-not-the-present"},{"level":2,"text":"भावना आणि कळप","id":"sentiment-and-the-herd"},{"level":2,"text":"एक ठोस उदाहरण: निकालाचा दिवस","id":"a-concrete-example-results-day"},{"level":2,"text":"त्यावर नंबर टाकणे: तुमच्या परताव्याची गणना करणे","id":"putting-a-number-on-it-calculating-your-return"},{"level":2,"text":"क्विक रिकॅप","id":"quick-recap"}],"imgCount":2,"hasContent":true},"14":{"html":"<p>काही सकाळी, तुमच्या स्क्रीनवरील जवळजवळ प्रत्येक स्टॉक एकाच वेळी खाली उघडतो, उत्तम व्यवसाय आणि कमकुवत, ज्या कंपनीने नुकताच विक्रमी नफा पोस्ट केला आणि ज्याने काहीही पोस्ट केले नाही. त्या कंपन्यांमध्ये रातोरात काहीही बदलले नाही. काय बदलले आहे <em>हवामान</em>. प्रत्येक वैयक्तिक समभागाच्या वरती उंचावर बसलेला महाकाय, संथ गतीने चालणारी शक्ती, व्याजदर, चलनवाढ, रुपयाचे मूल्य, कच्च्या तेलाच्या किमती, देशात आणि बाहेर जाणारा पैसा, आणि जेव्हा हवामान बदलते तेव्हा ते एकाच वेळी संपूर्ण बाजारावर झुकते.</p>\n<p>शेवटच्या प्रकरणात एक स्टॉक काय हलतो ते पाहिले. हे हलवणाऱ्या शक्तींपर्यंत झूम करते <em>सर्व</em> त्यापैकी एकत्र. तुम्ही या हवामानावर कधीही नियंत्रण ठेवू शकणार नाही, आणि चांगली बातमी, तुम्हाला याचा अंदाज लावण्याची गरज नाही. पण ते वाचायला शिकल्याने बाजाराचा एक भयानक, गोंधळात टाकणारा दिवस तुम्हाला समजू शकेल अशा गोष्टीत बदलतो आणि बहुतेक वेळा शांतपणे दुर्लक्ष करतो.</p>\n<h2 id=\"interest-rates-the-price-of-money\">व्याज दर: पैशाची किंमत</h2>\n<p>त्याच्या मध्यभागी सर्व बसलेले आहे <strong>भारतीय रिझर्व्ह बँक (RBI)</strong>, देशाची मध्यवर्ती बँक, आणि ती नियंत्रित करणारी एकल सर्वात शक्तिशाली संख्या: द <strong>रेपो दर</strong>.</p>\n<p>रेपो रेटला पैशाची किंमत समजा. हा व्याज दर आहे ज्यावर RBI व्यावसायिक बँकांना कर्ज देते. जेव्हा तो दर कमी असतो, तेव्हा बँकांना स्वस्तात पैसे मिळतात, त्यामुळे त्या स्वस्तात कर्ज देतात, गृहकर्ज, कार लोन, व्यावसायिक कर्जे हे सर्व अधिक परवडणारे मिळते. कंपन्या कर्ज घेतात आणि विस्तारतात, लोक कर्ज घेतात आणि खर्च करतात, नफा वाढतो आणि स्टॉक्स अनेकदा वाढतात. जेव्हा RBI <em>वाढवते</em> रेपो रेट, उलट घडते: पैसे महाग होतात, कर्ज घेणे मंद होते, अर्थव्यवस्था थंड होते आणि स्टॉक्सला हेडवाइंडचा सामना करावा लागतो.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch14-macro-forces.png\" alt=\"बाजारावर झुकलेल्या मोठ्या शक्ती, व्याजदर, महागाई, कच्चे तेल, रुपया, FII/DII प्रवाह आणि जागतिक संकेत, सर्व एकाच वेळी निफ्टीला धक्का देतात.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">इन्फोग्राफिक</span>बाजारावर झुकलेल्या मोठ्या शक्ती, व्याजदर, महागाई, कच्चे तेल, रुपया, FII/DII प्रवाह आणि जागतिक संकेत, सर्व एकाच वेळी निफ्टीला धक्का देतात.</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>व्याजदर शेअरच्या किमतींवर गुरुत्वाकर्षणाप्रमाणे काम करतात. स्वस्त पैसा साठा उचलण्यासाठी कल; महाग पैसे त्यांना खाली तोलणे झुकत. हे समजण्यासाठी सर्वात महत्वाचे मॅक्रो लीव्हर आहे, आणि RBI ते मुद्दाम, छोट्या पायऱ्यांमध्ये, अर्थव्यवस्था पाहिल्यानंतर हलवते.</p>\n</div></div>\n<h3 id=\"why-lower-rates-often-lift-stocks\">कमी दर अनेकदा स्टॉक का उचलतात</h3>\n<ul>\n<li><strong>स्वस्त EMI आणि कर्ज</strong> अधिक खर्च करण्यासाठी घरे सोडा, कंपनीच्या विक्रीसाठी चांगले.</li>\n<li><strong>स्वस्त कॉर्पोरेट कर्ज घेणे</strong> व्यवसायांना गुंतवणूक, विस्तार आणि नफा वाढवू देते.</li>\n<li><strong>मुदत ठेवी आणि रोखे कमी पैसे देतात</strong>त्यामुळे काही गुंतवणूकदार जास्त परताव्याच्या शोधात इक्विटीकडे पैसे वळवतात.</li>\n<li><strong>भविष्यातील नफा आज अधिक मोलाचा आहे</strong> जेव्हा दर कमी असतात, तेव्हा गुंतवणूकदार स्टॉकसाठी काय पैसे देतील ते उचलतात.</li>\n</ul>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch14-rate-transmission.png\" alt=\"एका RBI दरात कपात केल्याने स्वस्त बँक कर्ज, अधिक खर्च आणि गुंतवणूक, कंपनीचा नफा आणि शेअर्सच्या किमती वाढतात\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">फ्लो चार्ट</span>स्वस्त बँक कर्ज, अधिक खर्च आणि गुंतवणूक, कंपनीचा नफा आणि शेअर्सच्या किमतींमध्ये एकच RBI दर कसा कमी होतो.</figcaption></figure>\n<p>एक वास्तविक, अलीकडील उदाहरण: 2025 पर्यंत RBI स्थिरपणे <em>कट</em> रेपो दर, वर्षाच्या सुरुवातीला सुमारे 6.5% वरून डिसेंबरपर्यंत (अंदाजे) 5.25% पर्यंत खाली आला, कारण महागाई थंडावली आणि मध्यवर्ती बँकेने वाढीला समर्थन देणे निवडले. स्वस्त पैसा हा त्या वर्षी भारतीय समभागांसाठी एक टेलविंड होता.</p>\n<h2 id=\"inflation-what-the-rbi-is-really-fighting\">महागाई: RBI खरोखर काय लढत आहे</h2>\n<p>पहिल्याच प्रकरणापासून चलनवाढ लक्षात ठेवा, किमतीतील मूक वाढ ज्यामुळे तुमचे पैसे कमी होतात. ते लढणे हे RBI चे मुख्य काम आहे. किरकोळ महागाई जवळ ठेवणे हे त्याचे अधिकृत लक्ष्य आहे <strong>4%</strong>, च्या सहिष्णुता बँडमध्ये <strong>2% ते 6%</strong>. त्याच रेपो दर हे त्याचे प्रमुख शस्त्र आहे.</p>\n<p>जेव्हा चलनवाढ खूप गरम होते, RBI <em>वाढवते</em> खर्च आणि कर्ज थंड करण्यासाठी दर. जेव्हा चलनवाढ मर्यादेत आरामात येते तेव्हा, RBI मध्ये जागा असते <em>कट</em> दर आणि अर्थव्यवस्था वाढण्यास मदत करते. त्यामुळे चलनवाढ आणि व्याजदर ही एकाच लीव्हरची दोन टोके आहेत, म्हणूनच गुंतवणूकदार मासिक चलनवाढीचा आकडा इतक्या बारकाईने पाहतात. RBI पुढे काय करेल ते तुम्हाला अनेकदा सांगते.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>2025 च्या उत्तरार्धात, भारताची किरकोळ चलनवाढ अनेक वर्षांच्या नीचांकी पातळीवर आली, एका टप्प्यावर 1% (अंदाजे) च्या खाली मुद्रित झाली, यानेचRBI′ ला दर कमी ठेवण्यासाठी जागा दिली. कमी महागाई फक्त तुमच्या किराणा बिलासाठी चांगली नाही; पैसे स्वस्त करण्यासाठी ते शांतपणे सेंट्रल बँकेला हिरवा कंदील देते.</p>\n</div></div>\n<h2 id=\"fiis-vs-diis-the-two-great-rivers-of-money\">FII विरुद्ध DII: पैशाच्या दोन महान नद्या</h2>\n<p>भारतीय बाजारपेठेतून दररोज दोन प्रचंड पैशांचा प्रवाह वाहत असतो आणि त्यांच्यातील रस्सीखेच बरेचसे मूड सेट करते.</p>\n<ul>\n<li><strong>FIIs / FPIs (विदेशी संस्थात्मक / पोर्टफोलिओ गुंतवणूकदार)</strong> परदेशी फंड, जागतिक पेन्शन फंड, हेज फंड, मालमत्ता व्यवस्थापक, भारतात गुंतवणूक करणे. त्यांचा पैसा मोठा, वेगवान आणि जागतिक परिस्थितीसाठी अतिशय संवेदनशील आहे. जेव्हा FII मोठ्या प्रमाणावर विक्री करतात तेव्हा निर्देशांक अनेकदा घसरतो.</li>\n<li><strong>DII (देशांतर्गत संस्थात्मक गुंतवणूकदार)</strong> हे भारतीय म्युच्युअल फंड, विमा कंपन्या आणि पेन्शन फंड आहेत आणि त्यांच्या मागे स्थिर मासिक भरती वाहते. <em>किरकोळ SIP पैसे</em> तुमच्यासारख्या सामान्य गुंतवणूकदारांकडून.</li>\n</ul>\n<p>अनेक दशकांपासून जुनी म्हण आहे: \"जेव्हा FII शिंकतात, दलाल स्ट्रीटला थंडी पडते.\" ते झपाट्याने बदलत आहे.</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>FIIs / FPIs</th>\n<th>डीआयआय</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ते कोण आहेत</td>\n<td>परदेशी निधी, पेन्शन, हेज फंड</td>\n<td>भारतीय म्युच्युअल फंड, विमा कंपन्या, पेन्शन फंड</td>\n</tr>\n<tr>\n<td>त्यांच्या मागे पैसा</td>\n<td>जागतिक भांडवल</td>\n<td>देशांतर्गत बचत आणि SIP</td>\n</tr>\n<tr>\n<td>वागणूक</td>\n<td>मोठे, जलद, जागतिक संकेतांवर प्रतिक्रिया देते</td>\n<td>स्थिर, मासिक SIP द्वारे दिले जाते</td>\n</tr>\n<tr>\n<td>जेव्हा ते मोठ्या प्रमाणावर विकतात</td>\n<td>निर्देशांक अनेकदा झपाट्याने घसरतो</td>\n<td>गडी बाद होण्याचा क्रम उशी आहे</td>\n</tr>\n</tbody></table>\n<p>याचे ताजे उदाहरण येथे आहे. 2025 मध्ये, FII ने ए <em>रेकॉर्ड</em> भारतीय इक्विटी पैकी रक्कम, अंदाजे <strong>1.66 लाख कोटी रुपये</strong> (सुमारे 19 अब्ज डॉलर्स, अंदाजे), रेकॉर्डवरील सर्वात मोठे वार्षिक परदेशी निर्गमन. दशकभरापूर्वी, अशा प्रकारच्या विक्रीने बाजार चिरडला असता. त्याऐवजी, देशांतर्गत पैशाने मोठ्या प्रमाणात हा फटका शोषून घेतला: DII खरेदी करत राहिले, विक्रमीSIP आवक द्वारे समर्थित जे सुमारे वर चढले. <strong>महिन्याला 31,000 कोटी रुपये</strong> डिसेंबर 2025 पर्यंत. 2025 च्या सुरुवातीला, प्रथमच, DII ची NSE-सूचीबद्ध कंपन्यांची मालकी वाढली <em>भूतकाळ</em> FII'</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch14-fii-dii-flows.png\" alt=\"उदाहरणात्मक मासिक FII वि DII प्रवाह, विदेशी गुंतवणूकदार विक्री करत असताना देशांतर्गत संस्था आणि SIP पैसे खरेदी करत राहतात, बाजाराला उशीर करतात (अंदाजे, उदाहरणासाठी)\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">डेटा उदा</span>उदाहरणात्मक मासिक FII वि DII प्रवाह, विदेशी गुंतवणूकदार विक्री करत असताना देशांतर्गत संस्था आणि SIP पैसे खरेदी करत राहतात, बाजाराला उशीर करतात (अंदाजे, उदाहरणासाठी)</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>कोट्यवधी भारतीयांची मासिक SIP ही सवय शांतपणे बाजारपेठेतील शॉक शोषक बनली आहे. जेव्हा परदेशी लोक बाहेर पडण्यासाठी घाई करतात, तेव्हा गुंतवणुकीच्या पैशाची ती स्थिर देशांतर्गत थेंब वाढत्या प्रमाणात मजला खाली पडण्यापासून रोखते.</p>\n</div></div>\n<h2 id=\"crude-oil-and-the-rupee-india-s-imported-headache\">कच्चे तेल आणि रुपया: भारताची आयात डोकेदुखी</h2>\n<p>भारत अंदाजे खरेदी करतो <strong>त्यातील 85% कच्चे तेल परदेशातून येते</strong>, आणि ती एक वस्तुस्थिती तीन गोष्टींना जोडते: तेलाची किंमत, रुपया आणि महागाई.</p>\n<p>जेव्हा जागतिक क्रूडच्या किमती वाढतात तेव्हा भारताचे आयात बिल फुगे. त्या सर्व तेलाची किंमत देण्यासाठी, देशाने अधिक US डॉलर्स खरेदी केले पाहिजेत, जे रुपयाला धक्का देतात. <em>खाली</em>. तेव्हा कमकुवत रुपया बनतो <em>सर्व</em> आयात, फक्त तेलच नाही, अधिक महाग, जे महागाई वाढवते, जे RBI ला दर जास्त ठेवण्यास भाग पाडू शकतात. कच्च्या तेलाची एक वाढ संपूर्ण साखळीला तरंगू शकते.</p>\n<p>कमकुवत रुपया सर्वांना समान त्रास देत नाही. ज्या कंपन्या <em>आयात</em> (तेल विक्रेते, बरेच उत्पादक) पिळून काढतात, तर <em>निर्यातदार</em> जे डॉलरमध्ये कमावतात, IT सेवा आणि फार्मा, उदाहरणार्थ, त्यांना अनेकदा फायदा होतो, कारण ते कमावलेले प्रत्येक डॉलर अधिक रुपयांमध्ये रूपांतरित होते.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>भारताचे वार्षिक तेल आयातीचे बिल अनेक लाख कोटी रुपयांचे आहे, त्यामुळे क्रूडच्या किमतीत 10-डॉलरची वाढ ही येथे खरी बातमी आहे. तुमच्या पेट्रोलच्या किमती, रुपया, चलनवाढ आणि व्याजदर हे सर्व एकाच वेळी मोजू शकतील अशा काही जागतिक क्रमांकांपैकी हा एक आहे.</p>\n</div></div>\n<p>ताज्या उदाहरणाने ते एकमेकांशी जोडले आहे: 2025 च्या सुरुवातीस रुपया 85 रुपयांवरून डॉलरच्या तुलनेत 2026 च्या सुरुवातीच्या 90 च्या दशकात (अंदाजे) कमी झाला, क्रूडच्या किमती आणि जागतिक तणावामुळे काही प्रमाणात दबाव आला, क्रूड, चलन आणि भावना एक म्हणून फिरत असलेल्या पाठ्यपुस्तकातील प्रकरण.</p>\n<h2 id=\"global-cues-why-india-wakes-up-reacting\">जागतिक संकेत: भारत का उठतो प्रतिक्रिया</h2>\n<p>टाइम झोनमध्ये मार्केट्स एकमेकांशी जोडलेले असतात. भारत सकाळी 9:15 वाजता उघडेल तोपर्यंत रात्रभर बरेच काही घडले आहे:</p>\n<ul>\n<li><strong>US फेडरल रिझर्व्ह</strong> जगातील सर्वात महत्वाचे व्याज दर सेट करते. जेव्हा फेड दर वाढवते किंवा फक्त चकचकीत वाटते तेव्हा जागतिक पैसा प्रवाहित होतो <em>दिशेने</em> US आणि <em>दूर</em> भारतासारख्या उदयोन्मुख बाजारपेठांमधून.</li>\n<li><strong>US बाजार</strong> (S&amp;P 500, Nasdaq) आणि ते कसे बंद झाले; <strong>आशियाई बाजार</strong> सकाळी, जे अनेकदा वॉल स्ट्रीटचे अनुसरण करतात; आणि <strong>GIFT निफ्टी</strong>, भारत कसा उघडू शकतो याचे प्रारंभिक सूचक.</li>\n<li><strong>भूराजनीती</strong>, युद्धे, तेलाचे धक्के, निवडणुका आणि व्यापारातील तणाव, काही तासांतच सीमा ओलांडल्या.</li>\n</ul>\n<p>TV अँकरचा \"जागतिक संकेत\" चा अर्थ या बंडलचा आहे: एकच देशांतर्गत घटना घडण्याआधी भारत अनेकदा प्रतिक्रिया देत रात्रभर सेट केलेला मूड.</p>\n<h2 id=\"reading-the-macro-mood-without-obsessing\">वेड न लावता मॅक्रो मूड वाचणे</h2>\n<p>नवशिक्यासाठी सर्वात महत्त्वाचा भाग येथे आहे: तुम्ही करता <em>नाही</em> यापैकी कोणत्याही एका तासाचा मागोवा घेणे आवश्यक आहे. मॅक्रो हवामान वळणाच्या ठिकाणी महत्त्वाचे असते, प्रत्येक सामान्य सकाळी नाही. एक दीर्घकालीन गुंतवणूकदार अधूनमधून त्याकडे पाहतो, ज्या प्रकारे खलाशी आकाश तपासतो, सतत नाही.</p>\n<p>एक साधा मानसिक डॅशबोर्ड पुरेसे आहे:</p>\n<ul>\n<li>व्याजदर वाढत आहेत की कमी होत आहेत?</li>\n<li>महागाई नियंत्रणात आहे का?</li>\n<li>रुपया स्थिर आहे की घसरत आहे?</li>\n<li>क्रूड शांत आहे की स्पाइकिंग?</li>\n<li>FII हे भारी विक्रेते आहेत की स्थिर खरेदीदार आहेत?</li>\n<li>जागतिक मूड \"रिस्क-ऑन\" आहे की \"रिस्क-ऑफ\" आहे?</li>\n</ul>\n<p>बहुतेक दिवस, प्रामाणिक उत्तर \"काहीही नाट्यमय नाही,\" आणि योग्य कृती म्हणजे काहीही न करणे.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>मॅक्रो साठी आहे <em>संदर्भ</em>, साठी नाही <em>वेळ</em>. कोणीही, अर्थतज्ञ नाही, निधी व्यवस्थापक नाही, फेडच्या पुढील हालचालीचा किंवा पुढच्या महिन्यात क्रूड कुठे जाईल याचा विश्वासार्हपणे अंदाज लावत नाही. ज्या गुंतवणूकदारांनी 2025 च्या विक्रमी विदेशी विक्रीतून शांतपणे त्यांच्या SIP चालू ठेवल्या त्यांनी प्रत्येक भीतीदायक मथळ्यावर घाबरलेल्या लोकांपेक्षा खूप चांगले काम केले. मॅक्रोला तुमची समज कळू द्या, तुमची योजना हायजॅक करू नका.</p>\n</div></div>\n<h2 id=\"quick-recap\">क्विक रिकॅप</h2>\n<ul>\n<li>द <strong>रेपो दर</strong>, द्वारे सेट <strong>RBI</strong>, पैशाची किंमत आहे, कमी दर सामान्यतः स्टॉक उचलतात, उच्च दर त्यांच्यावर वजन करतात.</li>\n<li>RBI मुख्यतः लढण्यासाठी दर हलवते <strong>महागाई</strong>; 2025 मध्ये थंडावलेली चलनवाढ यामुळे दरांमध्ये कपात होऊ दे, इक्विटीसाठी एक टेलविंड.</li>\n<li><strong>एफआयआय</strong> (परकीय पैसा) वेगवान आणि जागतिक आहेत; <strong>डीआयआय</strong> अधिक <strong>किरकोळ SIP</strong> अधिक स्थिर आहेत आणि आता बाजाराला उशीर आहे, 2025 मध्ये विक्रमीSIP′ आवक शोषून विक्रमी विक्री.</li>\n<li>भारत त्यातील बहुतांश आयात करतो <strong>तेल</strong>, त्यामुळे उच्च क्रूड कमकुवत होते <strong>रुपया</strong> आणि महागाई वाढवते; कमजोर रुपयामुळे निर्यातदारांना फायदा, आयातदार तोट्यात.</li>\n<li><strong>जागतिक संकेत</strong>, US फेड, रातोरात वॉल स्ट्रीट, भू-राजकारण, मूड सेट करते ज्यावर भारत अनेकदा प्रतिक्रिया देतो.</li>\n<li>मॅक्रो मूड म्हणून वाचा <em>संदर्भ</em>, वेळ सिग्नल नाही; बहुतेक दिवस, योग्य प्रतिसाद म्हणजे तुमच्या योजनेला चिकटून राहणे.</li>\n</ul>\n<p>पुढे, आम्ही मॅक्रोच्या संथ हवामानापासून तीक्ष्ण, अनुसूचित उत्प्रेरकांकडे वळतो जे वैयक्तिक स्टॉक, कमाईचा हंगाम, लाभांश, मार्गदर्शन आणि प्रत्येक गुंतवणूकदार पाहण्यास शिकत असलेल्या धक्कादायक घटनांना धक्का देतात.</p>\n","toc":[{"level":2,"text":"व्याज दर: पैशाची किंमत","id":"interest-rates-the-price-of-money"},{"level":3,"text":"कमी दर अनेकदा स्टॉक का उचलतात","id":"why-lower-rates-often-lift-stocks"},{"level":2,"text":"महागाई: RBI खरोखर काय लढत आहे","id":"inflation-what-the-rbi-is-really-fighting"},{"level":2,"text":"FII विरुद्ध DII: पैशाच्या दोन महान नद्या","id":"fiis-vs-diis-the-two-great-rivers-of-money"},{"level":2,"text":"कच्चे तेल आणि रुपया: भारताची आयात डोकेदुखी","id":"crude-oil-and-the-rupee-india-s-imported-headache"},{"level":2,"text":"जागतिक संकेत: भारत का उठतो प्रतिक्रिया","id":"global-cues-why-india-wakes-up-reacting"},{"level":2,"text":"वेड न लावता मॅक्रो मूड वाचणे","id":"reading-the-macro-mood-without-obsessing"},{"level":2,"text":"क्विक रिकॅप","id":"quick-recap"}],"imgCount":3,"hasContent":true},"15":{"html":"<p>स्टॉक काही आठवडे शांतपणे वाहून जाऊ शकतो, क्वचितच हलतो आणि नंतर एकाच सकाळी 10% उडी मारतो किंवा क्रॅश होऊ शकतो. नवागताला ते यादृच्छिक, अगदी अयोग्य वाटते. पण जवळजवळ नेहमीच, एक होते <em>तारीख</em> त्या हालचालीच्या मागे, कॅलेंडरवर बसले जे कोणीही येताना पाहिले असेल. कंपन्या त्यांचा नफा शेड्यूलनुसार नोंदवतात, शेड्यूलनुसार लाभांश देतात आणि देशाचा अर्थसंकल्प आणि निवडणुकीचे दिवस आधीपासून चिन्हांकित केले जातात.</p>\n<p>शेवटचा अध्याय मॅक्रो फोर्सच्या मंद हवामानाबद्दल होता. हे तीक्ष्ण, नियोजित झटके, उत्प्रेरकांबद्दल आहे. किंमती हलवणाऱ्या घटनांचे कॅलेंडर शिकणे हे गुंतवणूकदार तयार करू शकणारे सर्वात व्यावहारिक कौशल्य आहे, कारण ते \"पृथ्वीवर का कमी झाले?\" \"अहो, आज निकाल लागणार होता.\" आपण मोठ्यांमधून चालत जाऊ या.</p>\n<h2 id=\"results-season-the-market-s-quarterly-report-card\">निकालांचा हंगाम: बाजाराचे त्रैमासिक अहवाल कार्ड</h2>\n<p>भारतातील प्रत्येक सूचीबद्ध कंपनीने त्यांच्या आर्थिक परिणामांचा अहवाल देणे आवश्यक आहे <strong>वर्षातून चार वेळा</strong>, दर तिमाहीत एकदा:</p>\n<ul>\n<li><strong>Q1</strong> एप्रिल ते जून कव्हर, <strong>Q2</strong> जुलै ते सप्टेंबर, <strong>Q3</strong> ऑक्टोबर ते डिसेंबर, आणि <strong>Q4</strong> जानेवारी ते मार्च.</li>\n<li>प्रत्येक तिमाही संपल्यानंतर काही आठवड्यांनी निकाल जाहीर केले जातात, त्यामुळे कंपनीच्या घोषणांचा पूर अंदाजे सहा आठवड्यांच्या कालावधीत येतो. त्या ताणाला म्हणतात <strong>परिणाम हंगाम</strong> (किंवा कमाईचा हंगाम).</li>\n</ul>\n<p>जेव्हा संख्या बाहेर येते, तेव्हा चार गोष्टी सर्वात महत्त्वाच्या असतात:</p>\n<ul>\n<li><strong>महसूल</strong> (\"टॉप लाइन\"), कंपनीने केलेली एकूण विक्री.</li>\n<li><strong>निव्वळ नफा</strong> (\"तळ ओळ\"), सर्व खर्च आणि कर नंतर काय उरते.</li>\n<li><strong>समास</strong>, कमाईची टक्केवारी म्हणून नफा, जे कंपनी विक्रीचे किती कार्यक्षमतेने नफ्यात रूपांतर करते हे दर्शवते.</li>\n<li><strong>वाढ</strong>, गेल्या वर्षीच्या त्याच तिमाहीच्या तुलनेत (वर्ष-दर-वर्ष, किंवा YoY) आणि मागील तिमाहीच्या (तिमाही-प्रति-तिमाही, QoQ).</li>\n</ul>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch15-results-timeline.png\" alt=\"भारताचे त्रैमासिक निकाल कॅलेंडर, वर्षभरातील चार रिपोर्टिंग सीझन आणि प्रत्येक कंपनी जेव्हा घोषणा करते तेव्हा उग्र विंडो\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">फ्लो चार्ट</span>भारताचे त्रैमासिक निकाल कॅलेंडर, वर्षभरातील चार रिपोर्टिंग सीझन आणि प्रत्येक कंपनी जेव्हा घोषणा करते तेव्हा उग्र विंडो</figcaption></figure>\n<h3 id=\"why-a-stock-can-post-record-profit-and-still-crash\">स्टॉक रेकॉर्ड नफा का पोस्ट करू शकतो आणि तरीही क्रॅश होऊ शकतो</h3>\n<p>प्रत्येक नवशिक्याला आश्चर्यचकित करणारा भाग येथे आहे: शेअरची किंमत कच्च्या संख्येवर प्रतिक्रिया देत नाही, ती संख्येवर प्रतिक्रिया देते <em>बाजाराला आधीच अपेक्षित असलेल्या विरुद्ध</em>. विश्लेषक आणि गुंतवणूकदार निकालाच्या दिवसात अपेक्षा ठेवतात (बहुतेकदा \"अंदाज\" किंवा \"रस्त्याचा नंबर\" म्हणतात). त्या अपेक्षेसाठी स्टॉकची किंमत आधीच ठरलेली आहे.</p>\n<ul>\n<li><strong>अपेक्षांवर मात करा</strong>, नफा अपेक्षेपेक्षा जास्त येतो आणि स्टॉक अनेकदा उडी मारतो.</li>\n<li><strong>अपेक्षा चुकल्या</strong>, अपेक्षेपेक्षा कमी, आणि तो अनेकदा पडतो.</li>\n<li><strong>अपेक्षा पूर्ण कराल</strong> नक्की, आणि प्रतिक्रिया सहसा निःशब्द केली जाते.</li>\n</ul>\n<p>त्यामुळे एखादी कंपनी तिचा आतापर्यंतचा सर्वाधिक नफा जाहीर करू शकते आणि <em>अजूनही</em> घसरण, कारण बाजाराला आणखी अपेक्षा आहेत. आश्चर्य, संख्या नाही, किंमत हलवते.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch15-results-gap.png\" alt=\"निकालाच्या दिवशी शेअर्समध्ये झपाट्याने फरक पडणारा कॅन्डलस्टिक चार्ट, एक लांब मेणबत्ती आणि बाजारातील ठोके किंवा चुकल्यावर किंमतीतील अंतर\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>निकालाच्या दिवशी शेअर्समध्ये झपाट्याने फरक पडणारा कॅन्डलस्टिक चार्ट, एक लांब मेणबत्ती आणि बाजारातील ठोके किंवा चुकल्यावर किंमतीतील अंतर</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>शेअर किमती वर हलवा <em>आश्चर्य</em> अपेक्षांच्या सापेक्ष, परिपूर्ण परिणामावर नाही. जर बाजाराला मोठ्या लोकांची आशा असेल तर \"चांगले परिणाम\" स्टॉक बुडवू शकतात आणि जर प्रत्येकाला वाईट होण्याची भीती वाटत असेल तर \"कमकुवत परिणाम\" स्टॉक उचलू शकतात.</p>\n</div></div>\n<p>हे जुन्या बाजाराचे स्पष्टीकरण देखील देते: <strong>\"अफवा विकत घ्या, बातम्या विका.\"</strong> एक स्टॉक अनेकदा दिवसांमध्ये वाढतो <em>आधी</em> चांगल्या संख्येसाठी लोकांची स्थिती म्हणून परिणाम. चांगली बातमी प्रत्यक्षात घोषित होईपर्यंत, ती आधीच किंमतीत भाजलेली असते, त्यामुळे सुरुवातीच्या खरेदीदारांनी नफा घेतल्याने स्टॉक अगदी ठोस अहवालावरही खाली जाऊ शकतो.</p>\n<p>ते ठोसपणे चित्रित करा. समजा बाजाराला कंपनीचा तिमाही नफा १५% ने वाढण्याची अपेक्षा आहे. जर तो 20% नोंदवला तर, स्टॉक झपाट्याने वाढू शकतो, एक आनंदी आश्चर्य. जर ते फक्त 12% नोंदवते, तरीही वास्तविक वाढ, स्टॉक होऊ शकतो <em>पडणे</em>, कारण ते बारपेक्षा कमी पडले. तीच कंपनी, कोणत्याही प्रकारे खरी वाढ, विरुद्ध प्रतिक्रिया, सर्व अपेक्षांनुसार ठरलेले.</p>\n<h2 id=\"dividends-getting-paid-to-hold\">लाभांश: ठेवण्यासाठी पैसे मिळणे</h2>\n<p>ए <strong>लाभांश</strong> एक कंपनी तिच्या नफ्यातून तिच्या भागधारकांसोबत शेअर करते रोख पेआउट आहे, 10 रुपये प्रति शेअर. तुमच्या बँक खात्यात 100 शेअर्स आणि रु 1,000 जमीन आहे. स्टॉक्स तुम्हाला बक्षीस देणाऱ्या दोन मार्गांपैकी एक मार्ग आहे (दुसरा म्हणजे कालांतराने किंमत वाढत आहे).</p>\n<p>तीन तारखा महत्त्वाच्या आहेत, आणि त्या समजून घेतल्याने बरीच अनावश्यक भीती वाचते:</p>\n<ul>\n<li><strong>घोषणा तारीख</strong>, कंपनीचे बोर्ड लाभांश आणि त्याची रक्कम घोषित करते.</li>\n<li><strong>माजी लाभांश तारीख</strong>, कट ऑफ. वाटा स्वतःचा <em>आधी</em> या तारखेला आणि तुम्हाला लाभांश मिळेल; ते विकत घ्या <em>वर किंवा नंतर</em> ही तारीख आणि तुम्ही हे विशिष्ट पेआउट चुकवत आहात.</li>\n<li><strong>रेकॉर्ड तारीख</strong>, पात्र भागधारक कोण आहेत याची पुष्टी करण्यासाठी कंपनी आपली पुस्तके तपासते ती तारीख.</li>\n</ul>\n<p>आता नवशिक्यांना घाबरवणारा भाग. वर <strong>एक्स-डिव्हिडंडची तारीख, स्टॉकची किंमत साधारणपणे डिव्हिडंडच्या रकमेने कमी होते.</strong> जर रु. 500 चा स्टॉक रु. 10 लाभांश देत असेल, तर तो रु. 490 च्या जवळ उघडू शकतो. नवीन गुंतवणूकदारांना लाल रंग दिसतो आणि काहीतरी चूक झाली आहे असे समजतात.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>एक्स-डिव्हिडंड ड्रॉप आहे <strong>तोटा नाही</strong>, हे साधे अंकगणित आहे. कंपनीने रोख रक्कम दिली आहे, त्यामुळे व्यवसायाची किंमत अगदी कमी आहे आणि शेअरची किंमत सुमारे लाभांशाने कमी होते. तुम्ही गरीब नाही आहात: मूल्य \"शेअर किंमत\" वरून \"तुमच्या खात्यात रोख\" मध्ये हलविले आहे. घाबरू नका आणि त्यावर विक्री करू नका.</p>\n</div></div>\n<p>तुम्हाला ऐकू येईल असा संबंधित क्रमांक आहे <strong>लाभांश उत्पन्न</strong>, वार्षिक लाभांश भागिले शेअर किंमत, टक्केवारी म्हणून व्यक्त. 400 रुपयांच्या स्टॉकवर 20 रुपये वार्षिक लाभांश म्हणजे 5% उत्पन्न. हे तुम्हाला सांगते की स्टॉक त्याच्या किंमतीच्या तुलनेत किती रोख उत्पन्न फेकून देतो.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>भारतातील काही स्थिर ब्लू-चिप आणि सार्वजनिक क्षेत्रातील कंपन्यांनी विनाविलंब लाभांश दिला आहे <em>दशके</em>. दीर्घकालीन धारकांसाठी, ते पेआउट, वर्षानुवर्षे पुन्हा गुंतवलेले, शांतपणे एकूण परताव्यांच्या अर्थपूर्ण स्लाइसमध्ये एकत्रित केले जातात, शेअरच्या किमतीतील कोणत्याही वाढीच्या शीर्षस्थानी.</p>\n</div></div>\n<h2 id=\"guidance-and-management-commentary\">मार्गदर्शन आणि व्यवस्थापन भाष्य</h2>\n<p>अनेकदा, काय व्यवस्थापन <em>म्हणतो</em> भविष्याबद्दल शेअर्स स्वतःच्या परिणामांपेक्षा अधिक हलवतात, कारण बाजारपेठा भविष्याकडे पाहतात. निकाल जाहीर केल्यानंतर, कंपन्यांनी ए <strong>कमाई कॉल</strong> (किंवा \"कॉन्कॉल\") जेथे व्यवस्थापन तिमाहीची चर्चा करते आणि विश्लेषकांच्या प्रश्नांची उत्तरे देते. ऐकण्यासाठी दोन गोष्टी:</p>\n<ul>\n<li><strong>मार्गदर्शन</strong>, भविष्यातील महसूल, मार्जिन किंवा वाढीसाठी कंपनीचा स्वतःचा अंदाज. मार्गदर्शन वाढवल्याने आत्मविश्वास वाढतो आणि अनेकदा स्टॉक उचलतो; तो कापल्याने स्टॉक बुडू शकतो <em>चांगल्या वर्तमान परिणामांवर देखील</em>.</li>\n<li><strong>स्वर</strong>, आत्मविश्वासपूर्ण आणि विस्तृत, किंवा सावध आणि बचावात्मक. अनुभवी गुंतवणूकदार आकड्यांइतकेच मूड वाचतात.</li>\n</ul>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>जेव्हा तुम्ही निकाल वाचता तेव्हा नफ्याच्या आकड्यावर थांबू नका. व्यवस्थापन भाष्य आणि मार्गदर्शन देखील स्किम करा. मागास दिसणारा क्रमांक तुम्हाला कंपनी कुठे आहे ते सांगतो <em>केले आहे</em>; ते कुठे आहे हे मार्गदर्शन सूचित करते <em>जात आहे</em>, आणि बाजार भविष्यासाठी पैसे देते.</p>\n</div></div>\n<h2 id=\"other-events-that-jolt-a-single-stock\">एकाच स्टॉकला धक्का देणारे इतर कार्यक्रम</h2>\n<p>परिणामांच्या पलीकडे, मूठभर एक-ऑफ इव्हेंट्स विशिष्ट स्टॉक जलद हलवू शकतात:</p>\n<ul>\n<li><strong>विलीनीकरण आणि अधिग्रहण (M&amp;A)</strong>, एक कंपनी दुसरी खरेदी करते. अधिग्रहित केलेली कंपनी अनेकदा उडी मारते; खरेदीदार कोणत्याही मार्गाने जाऊ शकतो.</li>\n<li><strong>नियामक बातम्या</strong>, कंपनी किंवा क्षेत्राला प्रभावित करणारा नवीन नियम, बंदी, मान्यता, दंड किंवा कर बदल.</li>\n<li><strong>व्यवस्थापन बदल</strong>, एक आदरणीय CEO सोडत आहे, किंवा एक मजबूत नवीन नेता सामील होत आहे.</li>\n<li><strong>निर्देशांक समावेश किंवा बहिष्कार</strong>, जेव्हा निफ्टी 50 किंवा सेन्सेक्समध्ये स्टॉक जोडला जातो, तेव्हा इंडेक्स फंडांना ते विकत घेण्यास भाग पाडले जाते, ज्यामुळे मागणी निर्माण होते; काढणे उलट होते.</li>\n<li><strong>मोठे आदेश, न्यायालयीन निर्णय, क्रेडिट-रेटिंग बदल</strong>, भविष्यातील नफ्याचा दृष्टीकोन बदलणारी कोणतीही बातमी.</li>\n</ul>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch15-catalyst-calendar.png\" alt=\"उत्प्रेरकांचे वर्ष, निकालांचा हंगाम, लाभांशाच्या तारखा, अर्थसंकल्पाचा दिवस, निवडणुकीचे निकाल आणि संपूर्ण कॅलेंडरवर चिन्हांकित केलेले जागतिक धक्का\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">इन्फोग्राफिक</span>उत्प्रेरकांचे वर्ष, निकालांचे हंगाम, लाभांशाच्या तारखा, अर्थसंकल्पाचे दिवस, निवडणुकीचे निकाल आणि संपूर्ण कॅलेंडरवर चिन्हांकित केलेले जागतिक धक्का</figcaption></figure>\n<h2 id=\"shock-events-when-the-whole-market-lurches\">धक्कादायक घटना: जेव्हा संपूर्ण बाजार लुकलुकतो</h2>\n<p>काही घटना हलतात <em>सर्व काही</em> एकाच वेळी, फक्त एक स्टॉक नाही:</p>\n<ul>\n<li><strong>केंद्रीय अर्थसंकल्प दिवस</strong> (1 फेब्रुवारी), कर, खर्च आणि क्षेत्र धोरणातील बदल काही मिनिटांत बाजाराला स्विंग करू शकतात.</li>\n<li><strong>निवडणूक निकालाचा दिवस</strong>, राष्ट्रीय आणि मोठे राज्य निकाल नाटकीय एक-दिवसीय हालचाली निर्माण करू शकतात कारण गुंतवणूकदार राजकीय दृष्टिकोनाची पुनर्मूल्यांकन करतात.</li>\n<li><strong>अनियोजित जागतिक धक्के</strong>, एक महामारी, एक युद्ध, एक बँकिंग भीती, एक आश्चर्यचकित केंद्रीय-बँक हलवा. हे चेतावणीशिवाय येतात आणि संपूर्ण निर्देशांकाला धक्का बसू शकतात.</li>\n</ul>\n<p>तुम्ही अनुसूचित नसलेल्यांची डायरी करू शकत नाही, परंतु ते अस्तित्वात आहेत हे जाणून घेतल्याने जेव्हा एखादा आदळतो तेव्हा तुम्ही शांत राहता.</p>\n<h2 id=\"building-a-simple-watch-routine\">एक साधी घड्याळाची दिनचर्या तयार करणे</h2>\n<p>तुम्हाला ब्लूमबर्ग टर्मिनलची गरज नाही. नवशिक्याची दिनचर्या हलकी असू शकते:</p>\n<ul>\n<li>ठेवा ए <strong>लहान वॉचलिस्ट</strong> तुमच्या मालकीच्या किंवा जवळून फॉलो करत असलेल्या काही स्टॉक्सपैकी.</li>\n<li>त्यांची नोंद घ्या <strong>निकालाच्या तारखा</strong>, कंपन्या त्यांची आगाऊ घोषणा करतात आणि एक्सचेंज कॅलेंडर प्रकाशित करतात.</li>\n<li>निकालापूर्वी, ची उग्र जाणीव ठेवा <strong>काय अपेक्षित आहे</strong>; निकालानंतर, साधा प्रश्न तपासा: त्यांनी केले <em>मारणे किंवा चुकणे</em>, आणि केले <em>मार्गदर्शन सुधारणे किंवा खराब होणे</em>?</li>\n<li>खूण करा <strong>माजी लाभांश तारखा</strong> त्यामुळे किंमतीतील घसरण तुम्हाला कधीही आश्चर्यचकित करत नाही.</li>\n<li>सर्वात महत्त्वाचे म्हणजे, <strong>आवाजाचा व्यापार करू नका.</strong> एकच तिमाही क्वचितच दीर्घकालीन दृश्य बदलते. साठी कॅलेंडर पहा <em>शिका</em> तुमच्या कंपन्या कसे वागतात, आत आणि बाहेर उडी मारत नाही.</li>\n</ul>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>परिणामांचे दिवस हे स्टॉकसाठी सर्वात अस्थिर आणि अप्रत्याशित सत्रांपैकी असतात, किमती काही मिनिटांत दोन्ही दिशांनी वाढू शकतात. नवशिक्यासाठी, आवेगावर व्यापार करण्याचा हा सर्वात वाईट क्षण आहे. धूळ निवळू द्या, संपूर्ण चित्र वाचा आणि व्यवसायाचा एक नव्हे तर अनेक स्तरांवर न्याय करा.</p>\n</div></div>\n<h2 id=\"quick-recap\">क्विक रिकॅप</h2>\n<ul>\n<li>सूचीबद्ध कंपन्यांचा अहवाल <strong>वर्षातून चार वेळा निकाल</strong>; सहा आठवड्यांची गर्दी आहे <strong>परिणाम हंगाम</strong>, महसूल, नफा, मार्जिन आणि वाढ पाहिली.</li>\n<li>किंमती वर प्रतिक्रिया <strong>आश्चर्य विरुद्ध अपेक्षा</strong>, कच्चा आकडा नाही, त्यामुळे विक्रमी नफा अजूनही स्टॉक बुडवू शकतो आणि \"अफवा विकत घ्या, बातम्या विकून टाका\" असे दिसते.</li>\n<li>ए <strong>लाभांश</strong> नफ्यातून रोख आहे; वर अंदाजे लाभांश द्वारे स्टॉक कमी <strong>माजी लाभांश तारीख</strong>, सामान्य अंकगणित, <em>नाही</em> नुकसान</li>\n<li><strong>मार्गदर्शन आणि व्यवस्थापन भाष्य</strong> भविष्याबद्दल अनेकदा मागील तिमाहीच्या आकड्यांपेक्षा स्टॉक अधिक हलवा.</li>\n<li><strong>M&amp;A, नियमन, व्यवस्थापन बदल, निर्देशांक समावेश</strong> आणि <strong>धक्कादायक घटना</strong> (अर्थसंकल्प, निवडणुका, जागतिक संकटे) हे जाणून घेण्यासाठी इतर उत्प्रेरक आहेत.</li>\n<li>बांधा a <strong>हलकी घड्याळाची दिनचर्या</strong> परिणाम कॅलेंडरच्या आसपास, आणि एकाच अस्थिर सत्राच्या गोंगाटाचा व्यापार करण्यास विरोध करा.</li>\n</ul>\n<p>मंद मॅक्रो हवामानापासून तीक्ष्ण अनुसूचित उत्प्रेरकांपर्यंत किंमती कशा हलवतात हे आता तुम्हाला समजले आहे. पुढील प्रकरणामध्ये आपल्याला व्यावहारिक माहिती मिळते: एक सामान्य बचतकर्ता प्रत्यक्षात गुंतवणूकदार कसा बनतो, खाते उघडणे, इंडेक्स-फंड एसआयपी विरुद्ध थेट स्टॉकचे दोन मार्ग आणि लहान आणि सुरक्षित सुरुवात करण्यासाठी एक समजूतदार रोडमॅप.</p>\n","toc":[{"level":2,"text":"निकालांचा हंगाम: बाजाराचे त्रैमासिक अहवाल कार्ड","id":"results-season-the-market-s-quarterly-report-card"},{"level":3,"text":"स्टॉक रेकॉर्ड नफा का पोस्ट करू शकतो आणि तरीही क्रॅश होऊ शकतो","id":"why-a-stock-can-post-record-profit-and-still-crash"},{"level":2,"text":"लाभांश: ठेवण्यासाठी पैसे मिळणे","id":"dividends-getting-paid-to-hold"},{"level":2,"text":"मार्गदर्शन आणि व्यवस्थापन भाष्य","id":"guidance-and-management-commentary"},{"level":2,"text":"एकाच स्टॉकला धक्का देणारे इतर कार्यक्रम","id":"other-events-that-jolt-a-single-stock"},{"level":2,"text":"धक्कादायक घटना: जेव्हा संपूर्ण बाजार लुकलुकतो","id":"shock-events-when-the-whole-market-lurches"},{"level":2,"text":"एक साधी घड्याळाची दिनचर्या तयार करणे","id":"building-a-simple-watch-routine"},{"level":2,"text":"क्विक रिकॅप","id":"quick-recap"}],"imgCount":3,"hasContent":true},"16":{"html":"<p>मार्केट कसे काम करते, शेअर काय आहे, एक्सचेंजेस कोण चालवतात, किंमती कशा बदलतात, मॅक्रो हवामान कसे चालते हे शिकण्यात तुम्ही शेवटचे पंधरा अध्याय घालवले आहेत. आता एक अध्याय येतो जो खरोखर तुमचे जीवन बदलतो: सर्व समज काही सोप्या कृतींमध्ये बदलणे. बहुतेक लोक जाणून घेणे आणि करणे यामधील अंतरात अडकून, कायमचे \"एखाद्या दिवशी गुंतवणूकदार\" राहतात. ते अंतर शांतपणे, स्वस्तात आणि सुरक्षितपणे बंद करणे हे येथे उद्दिष्ट आहे, जेणेकरून शेवटपर्यंत तुम्हाला पहिल्या पायऱ्या कशा दिसतात हे कळेल.</p>\n<p>आम्ही सुरू करण्यापूर्वी एक सौम्य आठवण: हे शिक्षण आहे, सल्ला नाही. हे एका ब्रोकर किंवा फंडाचे नाव घेणार नाही, कारण योग्य तो तुमच्यावर अवलंबून आहे. ते काय <em>इच्छा</em> तुम्हाला बचतकर्ता पासून गुंतवणुकदारापर्यंत एक स्पष्ट, भयानक नसलेला नकाशा द्या.</p>\n<h2 id=\"step-one-the-demat-and-trading-account\">पहिली पायरी: डीमॅट आणि ट्रेडिंग खाते</h2>\n<p>शेअर्स खरेदी करण्यासाठी आणि ठेवण्यासाठी, तुम्हाला दोन लिंक केलेली खाती आवश्यक आहेत आणि आजकाल ते सहसा एकत्र, पूर्णपणे ऑनलाइन, एक किंवा दोन दिवसात उघडले जातात:</p>\n<ul>\n<li>ए <strong>डिमॅट खाते</strong> तुमचे शेअर्स इलेक्ट्रॉनिक स्वरूपात ठेवतात, ज्या प्रकारे बँक खाते तुमचे पैसे ठेवते. (मार्केट-इकोसिस्टम प्रकरणातील डिपॉझिटरीज,NSDL′ आणि CDSL आठवा, तुमचे डिमॅट खाते त्यापैकी एकावर आहे.)</li>\n<li>ए <strong>ट्रेडिंग खाते</strong> जे तुम्हाला एक्सचेंजवर खरेदी आणि विक्री ऑर्डर देऊ देते.</li>\n</ul>\n<h3 id=\"kyc-in-plain-words\">KYC, सोप्या शब्दात</h3>\n<p>एकतर खाते उघडण्यापूर्वी, तुम्ही पूर्ण करणे आवश्यक आहे <strong>KYC</strong>, \"तुमचा ग्राहक जाणून घ्या.\" तुम्ही म्हणता ते तुम्ही आहात हे फक्त कायदेशीर तपासणी आहे आणि तेच संरक्षण आहे ज्यामुळे संपूर्ण आर्थिक प्रणालीमध्ये फसवणूक करणे कठीण होते. आपल्याला सामान्यतः आवश्यक असेल:</p>\n<ul>\n<li><strong>PAN कार्ड</strong>, तुमचा कर ID, कोणत्याही भारतीय आर्थिक खात्याचा कणा आहे.</li>\n<li><strong>आधार</strong>, ओळख आणि पत्त्यासाठी वापरले जाते, अनेकदा OTP द्वारे त्वरित ई-सत्यापनासाठी.</li>\n<li><strong>बँक खाते</strong>, लिंक केले आहे जेणेकरून पैसे आत आणि बाहेर जाऊ शकतात (रद्द केलेला चेक किंवा तुमचे बँक तपशील).</li>\n<li><strong>एक फोटो आणि स्वाक्षरी</strong>, आणि कधीकधी एक संक्षिप्त व्हिडिओ सत्यापन.</li>\n</ul>\n<p>संपूर्ण प्रक्रिया आता ऑनलाइन आहे, अपलोड करा, OTP, ई-साइनसह सत्यापित करा, पूर्ण झाले. जुन्या दिवसांप्रमाणे फोटोकॉपीच्या जाड फाईल्स, रांगा नाहीत.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch16-account-kyc.png\" alt=\"ऑनलाइन खाते उघडणे, PAN, आधार आणि बँक लिंक KYC पडताळणीद्वारे तयार डीमॅट आणि ट्रेडिंग खात्यात वाहते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">इन्फोग्राफिक</span>ऑनलाइन खाते उघडणे, PAN, आधार आणि बँक लिंक KYC पडताळणीद्वारे तयार डिमॅट आणि ट्रेडिंग खात्यात वाहते.</figcaption></figure>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>भारताने ढोबळमानाने पार केले आहे <strong>21.6 कोटी डिमॅट खाती, सुमारे 216 दशलक्ष</strong> (डिसेंबर 2025 पर्यंत), काही वर्षांपूर्वीच्या संख्येच्या अनेक पट. एक संपूर्ण पिढी काही मिनिटांत त्यांच्या फोनवरून खाती उघडत आहे, हे काम ज्यासाठी एकदा कागदोपत्री काही आठवडे लागले.</p>\n<p>:::की\nखाते उघडणे हा सोपा भाग आहे आणि सर्वात लहान आहे. त्यापैकी 21.6 कोटी डिमॅट खाती, पेक्षा कमी <strong>5 कोटी सक्रिय आहेत</strong> कोणत्याही दिलेल्या वर्षात; बाकीचे बरेच उघडले आणि निष्क्रिय राहिले, किंवा डुप्लिकेट आहेत ज्या एका व्यक्तीने ब्रोकरमध्ये ठेवल्या आहेत. खाते फक्त ए <em>दार</em>. जात <strong>तयार</strong> गुंतवणुकीसाठी, आपत्कालीन निधी, महागडे कर्ज मंजूर, एक साधी योजना आणि स्थिर SIP, हा खरा मैलाचा दगड आहे. जर तुम्ही खाते उघडले आणि कधीही गुंतवणूक केली नाही, तर तुम्ही मागे नाही; तुम्ही नक्की आहात जिथे बहुतेक लोक आहेत. या प्रकरणाचा उरलेला भाग त्या दारातून व्यवस्थित चालण्याबद्दल आहे.</p>\n</div></div>\n<p>:::</p>\n<h2 id=\"two-paths-from-here\">इथून दोन वाटा</h2>\n<p>तुमचे खाते उघडल्यावर, नवशिक्या रस्त्याच्या फाट्यावर पोहोचतो. दोन्ही मार्ग वैध आहेत; ते वेगवेगळ्या लोकांना अनुकूल करतात आणि बऱ्याचदा उत्तम काम करतात <em>एकत्र</em>.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch16-two-paths.png\" alt=\"इंडेक्स-फंड SIP द्वारे संपूर्ण बाजाराची मालकी विरुद्ध वैयक्तिक स्टॉक स्वत: निवडणे हे दोन सुरुवातीचे मार्ग शेजारी शेजारी आहेत.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>इंडेक्स-फंड SIP द्वारे संपूर्ण बाजाराची मालकी विरुद्ध वैयक्तिक स्टॉक स्वत: निवडणे हे दोन सुरुवातीचे मार्ग शेजारी शेजारी आहेत.</figcaption></figure>\n<h3 id=\"path-1-buy-individual-stocks-directly\">मार्ग 1: वैयक्तिक स्टॉक थेट खरेदी करा</h3>\n<p>तुम्ही संशोधन करून विशिष्ट कंपन्यांची निवड करा, नंतर त्यांचे शेअर्स स्वतः खरेदी करा.</p>\n<ul>\n<li><strong>वरची बाजू:</strong> पूर्ण नियंत्रण, तुम्ही जे निवडता ते तुमच्या मालकीचे आहे आणि तुम्ही चांगले निवडल्यास जास्त परतावा मिळण्याची शक्यता आहे. तुम्ही या प्रकारे सर्वात जलद शिका.</li>\n<li><strong>तोटे:</strong> हे प्रत्येक कंपनीवर वास्तविक संशोधनाची मागणी करते, अधिक जोखीम घेते (एक वाईट निवड दुखापत करू शकते), वेळ आणि स्थिर स्वभाव आवश्यक आहे आणि भावनिक चुका करणे सोपे करते.</li>\n</ul>\n<p>हा मार्ग तुम्हाला सर्वात अनुकूल आहे <em>नंतर</em> तुम्ही मूलभूत गोष्टी शिकलात आणि तुम्हाला सक्रिय भूमिका हवी आहे, सामान्यत: तुमच्या पैशाच्या छोट्या तुकड्यापासून सुरुवात होते.</p>\n<h3 id=\"path-2-mutual-funds-and-index-funds-via-sip\">मार्ग २: म्युच्युअल फंड आणि इंडेक्स फंड, SIP मार्गे</h3>\n<p>स्वत: स्टॉक्स निवडण्याऐवजी, तुम्ही एक फंड खरेदी करा ज्यामध्ये तुमच्यासाठी बरेच स्टॉक आहेत.</p>\n<ul>\n<li><p>ए <strong>म्युच्युअल फंड</strong> हजारो गुंतवणूकदारांकडून पैसे गोळा करतात आणि एक व्यावसायिक अनेक कंपन्यांमध्ये त्याची गुंतवणूक करतो, ज्यामुळे तुम्हाला एकाच खरेदीमध्ये झटपट वैविध्य मिळते.</p>\n</li>\n<li><p>अ <strong>इंडेक्स फंड</strong> म्युच्युअल फंडाचा हा एक खास, कमी किमतीचा प्रकार आहे <em>आरसे</em> निफ्टी ५० सारखा निर्देशांक. तो सर्व ५० समभागांची खरेदी निर्देशांकाच्या समान प्रमाणात करतो, त्यामुळे एक खरेदी तुम्हाला एकाच वेळी भारतातील ५० मोठ्या कंपन्यांचे अंश-मालक बनवते. मार्केटला हरवण्याचा प्रयत्न करणारा कोणताही व्यवस्थापक नाही, तो अगदी कमी फीमध्ये शांतपणे त्याचा मागोवा घेतो.</p>\n</li>\n<li><p><strong>वरची बाजू:</strong> झटपट वैविध्य, हँड्स-ऑफ, कमी खर्च आणि वैयक्तिक कंपन्यांचे विश्लेषण करण्याची आवश्यकता नाही, म्हणूनच ते बहुतेक नवशिक्यांसाठी योग्य आहे.</p>\n</li>\n<li><p><strong>तोटे:</strong> तुम्ही इंडेक्सशी जुळवून घ्याल, त्याला हरवणार नाही आणि विजेते निवडण्यापेक्षा ते खूपच कमी रोमांचक वाटते.</p>\n</li>\n</ul>\n<h3 id=\"the-sip-habit\">SIP सवय</h3>\n<p>सर्व गुंतवणुकीत एकच नवशिक्यासाठी अनुकूल सवय आहे <strong>SIP, पद्धतशीर गुंतवणूक योजना.</strong> तुम्ही ठराविक रक्कम, रु. 1,000 किंवा रु. 5,000, प्रत्येक महिन्याला आपोआप एका फंडात गुंतवता. तीन शांत महासत्ता त्याच्यासोबत येतात:</p>\n<ul>\n<li><strong>ऑटोपायलट वर शिस्त</strong>, तुमचा मूड किंवा दिवसाची भितीदायक मथळ्याची पर्वा न करता तुम्ही दर महिन्याला गुंतवणूक करता.</li>\n<li><strong>रुपया-खर्च सरासरी</strong>, किंमत कमी असताना समान निश्चित रक्कम अधिक युनिट्स खरेदी करते आणि जास्त असताना कमी, वेळोवेळी तुमची सरासरी खरेदी किंमत कमी करते.</li>\n<li><strong>आपण लहान सुरू करू शकता</strong>, अनेक SIPs फक्त 500 रुपये प्रति महिना सुरू होतात, त्यामुळे प्रतीक्षा करण्याचे कोणतेही कारण नाही.</li>\n</ul>\n<p>ही एक फ्रिंज कल्पना नाही. 2025 च्या उत्तरार्धात भारतीयांनी विक्रम नोंदवला होता <strong>महिन्याला 31,000 कोटी रुपये</strong> (अंदाजे) म्युच्युअल फंडांमध्ये SIPs द्वारे, जवळपास <strong>10 कोटी</strong> SIP खाती, स्थिर देशांतर्गत भरती आम्ही मॅक्रो अध्यायात भेटलो.</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>थेट साठा</th>\n<th>इंडेक्स-फंड SIP</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जे तुमच्या मालकीचे आहे</td>\n<td>तुम्ही निवडलेल्या विशिष्ट कंपन्या</td>\n<td>संपूर्ण निर्देशांकाचा तुकडा</td>\n</tr>\n<tr>\n<td>विविधीकरण</td>\n<td>आपण ते स्वतः तयार केले पाहिजे</td>\n<td>झटपट, एका खरेदीत</td>\n</tr>\n<tr>\n<td>प्रयत्न</td>\n<td>उच्च, प्रत्येक स्टॉक संशोधन</td>\n<td>कमी, स्वयंचलित मासिक</td>\n</tr>\n<tr>\n<td>धोका</td>\n<td>एकाग्र, उच्च</td>\n<td>अनेक स्टॉक्समध्ये पसरले</td>\n</tr>\n<tr>\n<td>साठी सर्वोत्तम</td>\n<td>सक्रिय भूमिका, एकदा तुम्ही शिकलात</td>\n<td>जवळजवळ प्रत्येक नवशिक्या, हात-बंद</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>बऱ्याच नवशिक्यांसाठी, सर्वात हुशार सुरुवात ही एक छोटी, स्वयंचलित असते <strong>इंडेक्स-फंड SIP</strong>, झटपट विविधीकरण, जवळजवळ कोणतेही प्रयत्न नाही, खूप कमी किमतीत, आणि नंतर काही जोडणे <strong>थेट साठा</strong> हळूहळू, जसे तुमचे ज्ञान आणि आत्मविश्वास वाढतो. दोन मार्ग भागीदार आहेत, प्रतिस्पर्धी नाहीत.</p>\n</div></div>\n<h2 id=\"form-your-own-point-of-view-first\">प्रथम तुमचा स्वतःचा दृष्टिकोन तयार करा</h2>\n<p>आपण खरेदी करण्यापूर्वी <em>कोणतेही</em> वैयक्तिक स्टॉक, तुम्ही तुमच्या स्वतःच्या स्पष्ट शब्दात तीन गोष्टी स्पष्ट करू शकता:</p>\n<ul>\n<li>व्यवसाय प्रत्यक्षात काय करतो आणि त्यातून पैसे कसे कमावतात.</li>\n<li>पाच ते दहा वर्षांत ते मोठे किंवा अधिक फायदेशीर होईल असा तुमचा विश्वास का आहे.</li>\n<li>त्या कथेत काय चूक होऊ शकते.</li>\n</ul>\n<p>जर तुम्ही स्वतःला \"का\" समजावून सांगू शकत नसाल, तर तुम्ही गुंतवणूक करत नाही, तुम्ही टिपवर जुगार खेळत आहात. तुम्हाला तयार करण्यात मदत करण्यासाठी आधीच्या अध्यायातील प्रत्येक गोष्ट (साठा काय हलवतो, मॅक्रो फोर्स, कमाई कशी कार्य करते) अस्तित्वात आहे <em>तुमचे स्वतःचे</em> एखाद्या अनोळखी व्यक्तीकडून कर्ज घेण्याऐवजी पहा.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>कधीही शेअर खरेदी करू नका कारण तुम्हाला कोणीतरी WhatsApp ग्रुप, एक आकर्षक सोशल मीडिया \"टिप,\" TV वर आत्मविश्वासाने सांगितली आहे. उधार घेतलेली खात्री लगेचच किमतीत घसरण करते, आणि जेव्हा नवशिक्या घाबरून तोट्यात विकतात. आम्ही नंतरच्या अध्यायात या सापळ्यांचा आणि सरळ घोटाळ्यांचा शोध घेऊ. (इंडेक्स फंड हा सन्माननीय अपवाद आहे: तुम्हाला कोणत्याही एका कंपनीकडे पाहण्याची गरज नाही, जे नवशिक्यांसाठी इतके चांगले का आहे याचा एक भाग आहे.)</p>\n</div></div>\n<h2 id=\"a-sensible-beginner-roadmap\">एक समजूतदार नवशिक्या रोडमॅप</h2>\n<p>येथे ऑपरेशनचा एक शांत क्रम आहे, कंटाळवाणा क्रम जो शांतपणे कार्य करतो:</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch16-saver-to-investor.png\" alt=\"बचतकर्ता ते गुंतवणूकदार, आपत्कालीन निधी, नंतर खाते उघडा आणि KYC पूर्ण करा, एक लहान SIP स्वयंचलित करा, शिकत राहा आणि नंतरच थेट स्टॉक जोडा\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">फ्लो चार्ट</span>बचतकर्ता ते गुंतवणूकदार, आपत्कालीन निधी, नंतर खाते उघडा आणि KYC पूर्ण करा, एक लहान SIP स्वयंचलित करा, शिकत राहा आणि नंतरच थेट स्टॉक जोडा</figcaption></figure>\n<ol>\n<li><strong>प्रथम आपत्कालीन निधी तयार करा</strong>, सुरक्षित, तरल ठिकाणी तीन ते सहा महिन्यांचा खर्च, त्यामुळे तुम्हाला संकटाच्या वेळी कधीही गुंतवणूक विकावी लागणार नाही.</li>\n<li><strong>महागडे कर्ज साफ करा</strong>, क्रेडिट-कार्ड शिल्लक आणि महागड्या वैयक्तिक कर्जांची किंमत बाजारातून परत येण्याची शक्यता आहे त्यापेक्षा कितीतरी जास्त आहे.</li>\n<li><strong>तुमचे डीमॅट आणि ट्रेडिंग खाते उघडा</strong> आणि KYC समाप्त करा.</li>\n<li><strong>एक लहान, स्वयंचलित SIP सुरू करा</strong> ब्रॉड इंडेक्स फंडात, अगदी 500 ते 1,000 रुपये दरमहा. रिटर्नचा पाठलाग करण्यापूर्वी सवय तयार करा.</li>\n<li><strong>शिकत रहा</strong>, तुम्हाला स्वारस्य असलेल्या कंपन्यांचे निकाल वाचा, मॅक्रो मूडचे अनुसरण करा, तुमच्या मालकीचे काय ते समजून घ्या.</li>\n<li><strong>हळूहळू थेट साठा जोडा</strong>, फक्त पैशाने तुम्ही गमावू शकता, फक्त एकदाच तुम्ही तुमचा स्वतःचा दृष्टिकोन तयार करू शकता आणि सुरुवातीला फक्त एक लहान तुकडा.</li>\n<li><strong>सातत्यपूर्ण आणि संयम ठेवा</strong>, तर कंपाउंडिंग, पहिल्याच अध्यायातील धडा, वर्षानुवर्षे भारी उचल करूया.</li>\n</ol>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>आपले पहिले ध्येय आहे <em>नाही</em> परतावा, ही सवय तयार करत आहे आणि तुमचा स्वतःचा स्वभाव खूप कमी पणाला लावून शिकत आहे. 1,000 रु. SIP जो तुम्ही कधीही न थांबता, दशकांनंतर, तुम्ही एकदा लावलेल्या 50,000 रुपयांच्या चतुर पैजला जवळजवळ नेहमीच हरवणार आणि घाबरून बाहेर पडणार.</p>\n</div></div>\n<h2 id=\"start-small-start-safe\">लहान प्रारंभ करा, सुरक्षित प्रारंभ करा</h2>\n<p>तुम्हाला सुरुवात करण्यासाठी फॅट बँक बॅलन्स किंवा परिपूर्ण ज्ञानाची गरज नाही, फक्त अशी रक्कम जी पडल्यास दुखापत होणार नाही आणि सुरू करण्याची इच्छा. सुरुवातीची वर्षे शिकवणी आहेत: तुम्ही कसे शिकत आहात <em>आपण</em> जेव्हा किंमती डळमळीत होतात तेव्हा प्रतिक्रिया द्या, कोणत्याही एका वर्षाच्या नफ्यापेक्षा कितीतरी जास्त किमतीची. लहान सुरुवात करा, कंटाळवाणा भाग स्वयंचलित करा, वाचत राहा आणि तुमचा पैसा आणि तुमची समज दोन्ही एकत्र करा.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>येथे काहीही विशिष्ट स्टॉक, फंड किंवा उत्पादन खरेदी करण्याची शिफारस नाही आणि कोणीही तुम्हाला परतावा देण्याचे वचन देऊ शकत नाही. हा प्रवास सहसा कसा सुरू होतो याचा नकाशा आहे. विशिष्ट निवडी, कोणता प्रदाता, कोणता निधी, किती, हे एकदा तुम्हाला समजले की तुम्ही कराव्यात.</p>\n</div></div>\n<h2 id=\"quick-recap\">क्विक रिकॅप</h2>\n<ul>\n<li>गुंतवणूक करण्यासाठी तुम्हाला ए <strong>डीमॅट</strong> खाते (शेअर ठेवतात) आणि अ <strong>व्यापार</strong> खाते (ऑर्डर देते), साधे नंतर ऑनलाइन उघडले <strong>KYC</strong> PAN, आधार आणि बँक लिंकसह.</li>\n<li>नवशिक्यांना दोन मार्गांचा सामना करावा लागतो: <strong>थेट साठा</strong> (अधिक नियंत्रण, अधिक संशोधन, अधिक जोखीम) किंवा <strong>म्युच्युअल / इंडेक्स फंड</strong> (त्वरित विविधता, हात बंद).</li>\n<li>अ <strong>इंडेक्स फंड</strong> निफ्टी ५० सारख्या निर्देशांकाला स्वस्तात प्रतिबिंबित करा; a <strong>SIP</strong> एक निश्चित मासिक गुंतवणूक स्वयंचलित करते, शिस्त निर्माण करते आणि तुमची किंमत सरासरी करते.</li>\n<li>कोणताही एकच स्टॉक खरेदी करण्यापूर्वी, <strong>तुमचा स्वतःचा दृष्टिकोन तयार करा</strong>, व्यवसाय आणि \"का\" समजून घ्या आणि उधार घेतलेल्या टिपांवर कधीही कार्य करू नका.</li>\n<li>एक समजूतदार अनुसरण करा <strong>रोडमॅप</strong>: आपत्कालीन निधी, महागडे कर्ज साफ करा, खाते उघडा, एक लहान SIP स्वयंचलित करा, शिकत रहा, थेट स्टॉक हळूहळू जोडा.</li>\n<li><strong>लहान आणि सुरक्षित प्रारंभ करा</strong>, पहिले ध्येय म्हणजे सवय आणि धडे, परतावा नव्हे; हे शिक्षण आहे, सल्ला नाही.</li>\n</ul>\n<p>तुमची पहिली खरी पावले कशी उचलायची हे आता तुम्हाला माहीत आहे. पण चांगल्या गुंतवणुकीत सगळ्यात मोठा अडथळा असतो तो बाजाराचा नसून, ते पाहणारे मन. पुढे, आम्ही जोखीम, मानसशास्त्र आणि बहुतेक गुंतवणूकदारांना शांतपणे पराभूत करणाऱ्या सामान्य चुका आणि त्यांना कसे हरवायचे याकडे वळतो.</p>\n","toc":[{"level":2,"text":"पहिली पायरी: डीमॅट आणि ट्रेडिंग खाते","id":"step-one-the-demat-and-trading-account"},{"level":3,"text":"KYC, सोप्या शब्दात","id":"kyc-in-plain-words"},{"level":2,"text":"इथून दोन वाटा","id":"two-paths-from-here"},{"level":3,"text":"मार्ग 1: वैयक्तिक स्टॉक थेट खरेदी करा","id":"path-1-buy-individual-stocks-directly"},{"level":3,"text":"मार्ग २: म्युच्युअल फंड आणि इंडेक्स फंड, SIP मार्गे","id":"path-2-mutual-funds-and-index-funds-via-sip"},{"level":3,"text":"SIP सवय","id":"the-sip-habit"},{"level":2,"text":"प्रथम तुमचा स्वतःचा दृष्टिकोन तयार करा","id":"form-your-own-point-of-view-first"},{"level":2,"text":"एक समजूतदार नवशिक्या रोडमॅप","id":"a-sensible-beginner-roadmap"},{"level":2,"text":"लहान प्रारंभ करा, सुरक्षित प्रारंभ करा","id":"start-small-start-safe"},{"level":2,"text":"क्विक रिकॅप","id":"quick-recap"}],"imgCount":3,"hasContent":true},"17":{"html":"<p>मार्केट कसे काम करते, शेअर्स आणि इंडेक्स, IPO आणि सेटलमेंट, काय किंमत वर किंवा खाली येते हे शिकण्यात तुम्ही हा संपूर्ण कोर्स घालवला आहे. हे सर्व एकत्र बांधणारे अस्वस्थ सत्य आहे: यंत्रणा समजून घेणे हे आहे <em>सोपे</em> अर्धा कठीण अर्धा भाग चिंताग्रस्त, आशावादी, सहज घाबरलेल्या माणसाचे व्यवस्थापन करत आहे ज्यांना त्यांचे पैसे वाढत आणि कमी होत असताना शांत बसावे लागते. दशकांचा डेटा समान निष्कर्षाकडे निर्देश करतो, बहुतेक गुंतवणूकदार बाजाराने मारलेले नाहीत. ते स्वतःच मारहाण करतात.</p>\n<p>हा अध्याय आरशातील त्या प्रतिस्पर्ध्याबद्दल आहे. जोखीम नेमकी काय आहे, तुमच्या बेटांचा आकार कसा घ्यावा, जेणेकरून कोणतीही एक चूक तुम्हाला पुसून टाकू शकत नाही आणि मूठभर मानसिक सापळे जे हुशार, चांगल्या अर्थी लोकांकडून परत येतात ते आम्ही पाहू. यापैकी कशासाठीही वित्त पदवी आवश्यक नाही. दबावाखाली तुमचा मेंदू कसा काम करतो याबद्दल प्रामाणिकपणा आवश्यक आहे.</p>\n<h2 id=\"risk-and-reward-there-is-no-free-lunch\">जोखीम आणि बक्षीस: मोफत जेवण नाही</h2>\n<p>प्रत्येक गुंतवणूक हा दोन गोष्टींमधील व्यापार असतो: तो किती वाढू शकतो आणि वाटेत किती घसरू शकतो. हे दोघे नितंबावर जोडलेले आहेत. जास्त परतावा मिळण्याची शक्यता <em>नेहमी</em> एक खडबडीत राइड किंवा तोटा होण्याची उच्च शक्यता सह एकत्रित येते. कोणतीही जोखीम न घेता मोठी बक्षिसे देतात असे दिसते ते एकतर गैरसमज किंवा खोटे आहे, सहसा दुसरे.</p>\n<ul>\n<li>बँक मुदत ठेव क्वचितच हलते. कमी जोखीम, कमी बक्षीस.</li>\n<li>मोठ्या, प्रस्थापित कंपनीचे शेअर्स डळमळीत होतात. मध्यम जोखीम, मध्यम बक्षीस.</li>\n<li>एक लहान अज्ञात स्मॉल-कॅप एका महिन्यात दुप्पट किंवा अर्धवट होऊ शकते. उच्च जोखीम, उच्च बक्षीस.</li>\n</ul>\n<p>हा आउटस्मार्ट होण्यासाठी व्यवस्थेतील दोष नाही; ती व्यवस्था आहे. कौशल्य हे जोखीम मुक्त संपत्ती शोधत नाही, ते अस्तित्वात नाही. कौशल्य ठरवत आहे <em>किती</em> जोखीम तुमची उद्दिष्टे, तुमची टाइमलाइन आणि तुम्ही रात्री किती चांगले झोपता.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>\"जोखीम\" हा \"तोटा\" सारखा नाही. जोखीम म्हणजे अनिश्चितता, घडू शकणाऱ्या गोष्टींची श्रेणी. असा साठा जो चकचकीतपणे फिरतो परंतु तुम्ही वीस वर्षे धरून ठेवता तो खूप दूर असू शकतो <em>कमी</em> चलनवाढीला शांतपणे गमावलेल्या रोख रकमेपेक्षा तुमच्या वास्तविक ध्येयासाठी धोकादायक. जोखीम तुमच्याकडे असलेल्या वेळेशी जुळवा, आज तुमच्या मूडशी नाही.</p>\n</div></div>\n<h2 id=\"don-t-bet-the-farm-position-sizing-and-diversification\">शेतावर पैज लावू नका: स्थिती आकार आणि विविधता</h2>\n<p>येथे एकच सर्वात महाग नवशिक्या चूक आहे: तुमच्या पैशाचा मोठा भाग एका \"निश्चित गोष्टी\" मध्ये टाकणे. खात्री वाटते. हे खरे तर तुमच्या भविष्याशी एक नाणे-फ्लिप आहे. फिक्सला जुने नाव आहे, <strong>तुमची सर्व अंडी एका टोपलीत ठेवू नका</strong>, आणि थोडा जास्त मोठा झालेला: <strong>स्थिती आकारमान</strong> आणि <strong>विविधीकरण</strong>.</p>\n<p>पोझिशन साइझिंग म्हणजे तुमच्या एकूण पैशांपैकी किती पैसे कोणत्याही एका स्टॉकची परवानगी आहे हे आधीच ठरवणे. जर एखाद्या कंपनीच्या खराब निकालामुळे 50% बुडता येत असेल आणि चांगल्या कंपन्या कधी कधी असे करतात, तर ते तुमच्या पोर्टफोलिओच्या 5% वर ठेवणे म्हणजे तुमच्या <em>संपूर्ण</em> संपत्ती फक्त 2.5% कमी होते. त्रासदायक, जगण्याजोगे. त्याच स्टॉकमध्ये 80% ठेवा आणि तोच वाईट दिवस एक आपत्ती बनतो ज्यातून तुम्ही कधीही पुनर्प्राप्त होऊ शकत नाही.</p>\n<p>विविधीकरण ही एकच कल्पना व्यापकपणे पसरलेली आहे: विविध उद्योगांमध्ये अनेक समभागांची मालकी घ्या, जेणेकरून कोणतीही एक कंपनी, क्षेत्र किंवा वाईट बातमी तुम्हाला बुडवू शकणार नाही. जेव्हा तुमच्याकडे ब्रॉड इंडेक्स फंड असतो, तेव्हा तुम्हाला हे जवळपास मोफत मिळते, निफ्टी 50 तुमचे पैसे एकाच वेळी डझनभर उद्योगांमधील पन्नास मोठ्या कंपन्यांमध्ये पसरवते.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>अंगठ्याचा एक साधा नवशिक्या नियम: तुमच्या पोर्टफोलिओचा फार मोठा हिस्सा म्हणून कोणताही एकच स्टॉक नाही आणि पुढील तीन ते पाच वर्षात तुम्हाला लागणारे पैसे कधीही गुंतवू नका. बाजार दोन वर्षे खाली राहू शकतात, आणि आपण होऊ इच्छित नाही <em>सक्ती</em> तळाशी विक्रेता कारण भाडे देय आहे.</p>\n</div></div>\n<h2 id=\"the-enemy-in-the-mirror\">आरशात शत्रू</h2>\n<p>आता या प्रकरणाचा खरा विषय. तुमचा मेंदू एखाद्या पूर्वजांना सावनावर जिवंत ठेवण्यासाठी, कळपासोबत धावण्यासाठी, नुकसानाची भीती बाळगण्यासाठी, भीतीवर जलद कृती करण्यासाठी तयार करण्यात आला होता. त्या अंतःप्रेरणा गुंतवणुकीसाठी आपत्तीजनक असतात, जेथे जिंकण्याची चाल सहसा असते <em>काहीही करू नका</em> तुमच्या सभोवतालचे प्रत्येकजण घाबरत असताना किंवा उत्सव साजरा करत असताना. मार्केटमध्ये एक प्रसिद्ध भावनिक आकार देखील असतो, प्रत्येक तेजी आणि दिवाळे मध्ये पुनरावृत्ती होते.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch17-emotion-cycle.png\" alt=\"बाजाराच्या चक्राचे मानसशास्त्र, आशावाद अगदी शीर्षस्थानी उत्साह निर्माण करतो (जास्तीत जास्त आर्थिक जोखमीचा बिंदू), नंतर भीती आणि घाबरून खाली निराशेकडे सरकतो (जास्तीत जास्त संधीचा बिंदू)\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">इन्फोग्राफिक</span>बाजाराच्या चक्राचे मानसशास्त्र, आशावाद अगदी शीर्षस्थानी उत्साह निर्माण करतो (जास्तीत जास्त आर्थिक जोखमीचा बिंदू), नंतर भीती आणि घाबरून खाली निराशेकडे सरकतो (जास्तीत जास्त संधीचा बिंदू)</figcaption></figure>\n<p>ते वक्र पहा. प्रत्येकाला जाणवणारा मुद्दा <em>सर्वाधिक</em> आत्मविश्वास, उत्साह, शिखराच्या जवळ, सर्वात मोठ्या धोक्याचा क्षण आहे. ज्या ठिकाणी प्रत्येकाला आजारी आणि हताश, निराशा, तळागाळाजवळ वाटते, तेथे सर्वोत्तम दीर्घकालीन सौदे बसतात. आमच्या भावना जवळजवळ परिपूर्ण आहेत <em>उलट</em> सिग्नल हे समजून घेणे ही अर्धी लढाई आहे. खाली दिलेले सापळे तुम्हाला भावना मिळवून देण्याचे विशिष्ट मार्ग आहेत.</p>\n<h3 id=\"fomo-and-the-herd\">FOMO आणि कळप</h3>\n<p>जेव्हा स्टॉक आधीच 200% वाढला आहे आणि तुमचा शेजारी, तुमचा बार्बर आणि तीन टेलीग्राम गट याबद्दल बोलत आहेत, तेव्हा उडी मारण्याची ओढ प्रचंड आहे. ते म्हणजे <strong>हरवण्याची भीती</strong>, आणि हे कामावर कळपाचे वर्तन आहे, गर्दी जे करत आहे ते करण्यात आम्हाला सुरक्षित वाटते. क्रूर विनोद म्हणजे तोपर्यंत काहीतरी आहे <em>स्पष्टपणे</em> काम करत आहे आणि प्रत्येकजण आत आहे, बहुतेक फायदा आधीच झाला आहे, आणि तुम्ही शांतपणे तुम्हाला विकत असलेल्या स्मार्ट पैशातून खरेदी करत आहात.</p>\n<h3 id=\"loss-aversion-watering-weeds-cutting-flowers\">नुकसान टाळणे: तणांना पाणी देणे, फुले तोडणे</h3>\n<p>मानसशास्त्रज्ञांनी दर्शविले आहे की पैसे गमावण्याची वेदना ढोबळमानाने आहे <em>दोनदा</em> समान रक्कम मिळविण्याचा आनंद जितका तीव्र आहे. या एकाच क्वर्कमुळे एक सामान्य चूक होते: गुंतवणूकदार त्यांच्या गमावलेल्यांना खूप लांब धरून ठेवतात (\"मी जे पैसे दिले ते परत मिळतील तेव्हा मी विक्री करेन\") आणि त्यांच्या विजेत्यांना खूप लवकर विकू (\"तो नाहीसा होण्यापूर्वी मला या छोट्या नफ्यात लॉक करू द्या\"). याचा परिणाम असा पोर्टफोलिओ आहे जिथे तुम्ही तणांना पाणी देत ​​राहता आणि फुलं कापता, अगदी मागे.</p>\n<h3 id=\"anchoring-the-price-you-paid-doesn-t-care-about-you\">अँकरिंग: तुम्ही दिलेली किंमत तुमची काळजी करत नाही</h3>\n<p>तुम्ही 500 रुपयांना स्टॉक विकत घेतला. तो आता 380 रुपये आहे. तुम्ही विक्री करण्यास नकार दिला कारण तुम्ही आहात <em>अँकर केलेले</em> त्या 500 पर्यंत, तो तुमच्या डोक्यात एक जादूचा आकडा बनला आहे. पण तुम्ही काय पैसे दिले याची स्टॉकला कल्पना नाही. त्याचे भवितव्य केवळ येथून व्यवसायावर अवलंबून आहे, तुमच्या खरेदी किमतीवर नाही. कंपनी आता प्रत्यक्षात काय किंमत आहे यापेक्षा, तुमच्या प्रवेशाच्या किंमतीशी निर्णय बांधणे, हे सर्वात शांत, महागडे पूर्वाग्रह आहे.</p>\n<h3 id=\"overconfidence-and-recency-bias\">अतिआत्मविश्वास आणि ताजेपणाचा पूर्वाग्रह</h3>\n<p>काही चांगल्या कॉल्सनंतर, जवळजवळ प्रत्येकजण एक अलौकिक बुद्धिमत्ता वाटू लागतो. म्हणजे <strong>अतिआत्मविश्वास</strong>, आणि वास्तविकता तुम्हाला नम्र करण्याआधीच ते मोठे पैज, अधिक व्यापार आणि कमी सावधगिरी बाळगतात. त्याचा चुलत भाऊ आहे <strong>ताजेपणा पूर्वाग्रह</strong>: जे काही आत्ताच घडले ते होत राहील असे गृहीत धरून. जेव्हा बाजार तीन वर्षांपासून वाढतो, तेव्हा लोकांना वाटते की ते नेहमीच वाढतील; क्रॅश झाल्यानंतर, ते शपथ घेतात की स्टॉक हा घोटाळा आहे. दोन्ही मेंदू कायम भविष्यासाठी अलीकडील भूतकाळ चुकीचे आहेत.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>वास्तविक गुंतवणूकदारांच्या वर्तनाचा मागोवा घेणारे अभ्यास, जसे की मॉर्निंगस्टारचे दीर्घकाळ चाललेले \"माइंड द गॅप\" संशोधन, वारंवार असे आढळून आले की सरासरी फंड गुंतवणूकदार लक्षणीय कमाई करतो. <em>कमी</em> त्यांच्या मालकीच्या निधीपेक्षा प्रति वर्ष, बहुतेकदा सुमारे एक ते दीड टक्के गुणांनी, पूर्णपणे चुकीच्या क्षणी खरेदी आणि विक्रीमुळे. फंडाने चांगले काम केले. भावनेच्या भरात गुंतवणुकदारांनी स्वत:ची तोडफोड केली. (आकडे अंदाजे आहेत आणि कालावधीनुसार बदलतात.)</p>\n</div></div>\n<h2 id=\"why-most-people-who-trade-lose\">का बहुतेक लोक \"व्यापार\" गमावतात</h2>\n<p>हे संपूर्ण कोर्सच्या मुख्य संदेशाशी जोडते: <strong>तुम्ही बाजारपेठेचा विश्वासार्हपणे वेळ काढू शकत नाही आणि बहुतेक लोक कसे गमावतात हे पाहण्याचा प्रयत्न करा.</strong> वृत्ति म्हणजे जेव्हा गोष्टी भितीदायक दिसतात तेव्हा विकणे आणि जेव्हा गोष्टी रोमांचक दिसतात तेव्हा विकत घेणे, ज्याचा अर्थ, भावना वक्र दर्शविल्याप्रमाणे, म्हणजे तळाच्या जवळ विकणे आणि टॉपच्या जवळ खरेदी करणे. असे काही वेळा करा आणि तुम्ही सर्वात वाईट परिणाम प्राप्त केला आहे.</p>\n<p>सक्रिय, वारंवार व्यापार करणाऱ्या व्यापाऱ्यांचा डेटा सर्व देशांमध्ये क्रूर आणि सातत्यपूर्ण आहे: बहुसंख्य लोक कालांतराने पैसे गमावतात, विशेषत: इंट्राडे आणि डेरिव्हेटिव्ह सारख्या जलद उत्पादनांमध्ये, एकदा तुम्ही खर्च आणि कर मोजले. दरम्यान, \"कंटाळवाणे\" गुंतवणूकदार जो दर महिन्याला कमी किमतीचा इंडेक्स फंड खरेदी करत राहतो, क्रॅशद्वारे, तेजीतून, कोलाहलाकडे दुर्लक्ष करून, सहसा हुशार गर्दीच्या पुढे संपतो. ते हुशार होते म्हणून नाही. कारण ते आपापल्या मार्गातून बाहेर पडले.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch17-behavioural-traps.png\" alt=\"गुंतवणुकदाराच्या मार्गावर लेबल केलेले नुकसान, FOMO, नुकसान टाळणे, अँकरिंग, अतिआत्मविश्वास आणि नवीनपणाचा पूर्वाग्रह, प्रत्येक एक अशी जागा आहे जिथे भावना शांतपणे योजनेला ओव्हरराइड करते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>गुंतवणुकदाराच्या मार्गावर लेबल केलेले नुकसान, FOMO, नुकसान टाळणे, अँकरिंग, अतिआत्मविश्वास आणि नवीनपणाचा पूर्वाग्रह, प्रत्येक एक अशी जागा आहे जिथे भावना शांतपणे योजना ओव्हरराइड करते</figcaption></figure>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>विशेषत: मोठा विजय किंवा मोठा पराभव झाल्यानंतर स्वतःपासून सावध रहा. विजयानंतर तुम्हाला अजिंक्य वाटेल आणि एक बेपर्वा पैज लागेल; पराभवानंतर तुम्हाला हताश वाटेल आणि \"ते परत जिंकण्याचा\" प्रयत्न करा. लोक खाती उडवतात तेव्हा दोन्ही राज्ये असतात. ॲप बंद करणे आणि एका दिवसासाठी काहीही न करणे ही त्या क्षणांमधील सर्वात मजबूत हालचाल आहे.</p>\n</div></div>\n<h2 id=\"habits-that-beat-your-own-brain\">आपल्याच मेंदूला मारणाऱ्या सवयी</h2>\n<p>आपण या अंतःप्रेरणा हटवू शकत नाही, ते फॅक्टरी-स्थापित आहेत. परंतु तुम्ही अशा प्रणाली तयार करू शकता ज्या त्यांना तुमच्यासाठी तुमचे निर्णय घेण्यापासून रोखतील.</p>\n<ul>\n<li><strong>ते स्वयंचलित करा.</strong> स्वयंचलित मासिक गुंतवणूक सेट करा (एक SIP). ऑटोपायलटवर खरेदी होते तेव्हा, FOMO आणि भीतीला कधीही मत मिळत नाही.</li>\n<li><strong>तुमची योजना लिहा</strong>, तुमची मालकी काय आहे, का आहे आणि तुम्हाला काय विकायला लावेल. जेव्हा भावना आदळतात तेव्हा प्रतिक्रिया देण्याऐवजी ते पुन्हा वाचा.</li>\n<li><strong>तुमचा पोर्टफोलिओ कमी तपासा.</strong> दैनंदिन पाहण्यामुळे सामान्य गडबड तणावात बदलते आणि तुम्हाला टिंगलटवाळी करण्याचा मोह होतो. मासिक किंवा त्रैमासिक भरपूर आहे.</li>\n<li><strong>अगोदरच नियम ठरवा,</strong> शांत क्षणांमध्ये, तुमची स्थिती-आकार मर्यादा, तुम्ही किती रोख ठेवता, अपघातात तुम्ही कसे वागाल. शांत-तुम्ही घाबरलेले शासन करावे.</li>\n<li><strong>क्रॅशची अपेक्षा करा.</strong> बाजार दर वारंवार 30-50% घसरतात, हे सामान्य आहे, शेवट नाही. गुंतवणूकदार कोण <em>अपेक्षा</em> ते शांत राहते; ज्यांना याचा धक्का बसला ते सर्वात वाईट वेळी विकतात.</li>\n</ul>\n\n<div class=\"callout example\"><span class=\"callout-tag\">खरे उदाहरण</span><div><p>दोन मित्र 35% मार्केट क्रॅशमुळे गुंतवणूक करतात. अंजली, भयभीतपणे बातम्या पाहत आहे, \"रक्तस्राव थांबवण्यासाठी\" तळाजवळील सर्व काही विकते, नंतर परत खरेदी करण्यासाठी खूप घाबरलेली वाट पाहते आणि बहुतेक पुनर्प्राप्ती चुकवते. विक्रम काही करत नाही; त्याचे स्वयंचलित SIP अगदी स्वस्त युनिट्स खरेदी करत राहतात. दोन वर्षांनंतर निर्देशांक पूर्णपणे सावरला आणि वर गेला. तोच बाजार, तोच क्रॅश. अंजली कायमच्या तोट्यात; विक्रम पुढे आला. फरक फक्त वागण्यात होता.</p>\n</div></div>\n<h2 id=\"quick-recap\">क्विक रिकॅप</h2>\n<ul>\n<li><strong>उच्च रिवॉर्ड नेहमी जास्त जोखीम घेऊन चालते</strong>, कोणतीही जोखीम न घेता मोठ्या परताव्याची आशा देणारी कोणतीही गोष्ट म्हणजे गैरसमज किंवा खोटेपणा.</li>\n<li><strong>तुमच्या पदांचा आकार वाढवा आणि विविधता वाढवा</strong> त्यामुळे कोणताही एक स्टॉक किंवा क्षेत्र तुम्हाला नष्ट करू शकत नाही; ब्रॉड इंडेक्स फंड जवळजवळ विनामूल्य विविधता आणतो.</li>\n<li><strong>बाजार भावनिक चक्रात फिरतो</strong>, पीक उत्साह जास्तीत जास्त धोका आहे, सर्वात खोल निराशा ही जास्तीत जास्त संधी आहे; तुमच्या भावना उलट सिग्नल आहेत.</li>\n<li><strong>मोठे सापळे</strong>, FOMO आणि कळप, नुकसान टाळणे, अँकरिंग, अतिआत्मविश्वास, नवीनपणाचा पूर्वाग्रह, शांतपणे हुशार लोकांना गरीब गुंतवणूकदार बनवतात.</li>\n<li><strong>तुम्ही बाजाराला वेळ देऊ शकत नाही;</strong> पॅनिक-सेलिंग आणि लोभ-खरेदी हे बहुतेक लोक कसे गमावतात, तर स्थिर, कंटाळवाणे, स्वयंचलित गुंतवणूकदार सहसा जिंकतात.</li>\n<li><strong>प्रणाली तयार करा</strong>, स्वयंचलित करा, योजना लिहा, कमी तपासा, शांत असताना नियम ठरवा, तुमच्या स्वतःच्या मेंदूला निर्णय घेण्यापासून रोखा.</li>\n</ul>\n<p>पैसे गमावण्याचा आणखी एक मार्ग आहे ज्याचा तुमच्या मानसशास्त्राशी काहीही संबंध नाही आणि प्रत्येक गोष्टीचा दुसऱ्याच्या लोभाशी संबंध नाही, तो उघड घोटाळा. शेवटच्या अध्यायात आम्ही भारतातील सर्वात कुप्रसिद्ध फसवणूक, ते सर्व सामायिक केलेले लाल झेंडे आणि आपण कधीही बळी पडणार नाही याची खात्री कशी करायची ते पाहू.</p>\n","toc":[{"level":2,"text":"जोखीम आणि बक्षीस: मोफत जेवण नाही","id":"risk-and-reward-there-is-no-free-lunch"},{"level":2,"text":"शेतावर पैज लावू नका: स्थिती आकार आणि विविधता","id":"don-t-bet-the-farm-position-sizing-and-diversification"},{"level":2,"text":"आरशात शत्रू","id":"the-enemy-in-the-mirror"},{"level":3,"text":"FOMO आणि कळप","id":"fomo-and-the-herd"},{"level":3,"text":"नुकसान टाळणे: तणांना पाणी देणे, फुले तोडणे","id":"loss-aversion-watering-weeds-cutting-flowers"},{"level":3,"text":"अँकरिंग: तुम्ही दिलेली किंमत तुमची काळजी करत नाही","id":"anchoring-the-price-you-paid-doesn-t-care-about-you"},{"level":3,"text":"अतिआत्मविश्वास आणि ताजेपणाचा पूर्वाग्रह","id":"overconfidence-and-recency-bias"},{"level":2,"text":"का बहुतेक लोक \"व्यापार\" गमावतात","id":"why-most-people-who-trade-lose"},{"level":2,"text":"आपल्याच मेंदूला मारणाऱ्या सवयी","id":"habits-that-beat-your-own-brain"},{"level":2,"text":"क्विक रिकॅप","id":"quick-recap"}],"imgCount":2,"hasContent":true},"18":{"html":"<p>जिथे पैसा आहे तिथे लोक हुशारीने तुमच्याकडून हिसकावून घेण्याचा प्रयत्न करतात. शेअर बाजार, विश्वास आणि स्क्रीनवर हात बदलणारे पैशाचे महासागर, नेहमीच हुशार, मोहक बदमाशांना आकर्षित करतात. चांगली बातमी अशी आहे की 1992 च्या मेगा-फसवणुकीपासून ते 2026 च्या टेलिग्राम टिपपर्यंत जवळजवळ प्रत्येक घोटाळा, त्याच मूठभर युक्त्यांवर चालतो. कथा आणि नमुने एकदा जाणून घ्या आणि तुम्हाला मूर्ख बनवणे खूप कठीण होईल.</p>\n<p>हा शेवटचा धडा तुम्हाला मोठ्या गोष्टी स्पष्टपणे आणि अचूकपणे सांगतो, नंतर तुमच्या फसवणुकीकडे वळतो <em>प्रत्यक्षात</em> आज भेटा, WhatsApp वर, YouTube वर, मित्राच्या \"गॅरंटीड रिटर्न\" योजनेत. शेवटी तुमच्याकडे एक साधा रेड-फ्लेग रडार आणि एक संरक्षण चेकलिस्ट असेल जी तुम्ही तुमच्या उर्वरित गुंतवणूक आयुष्यासाठी वापरू शकता.</p>\n<h2 id=\"the-big-bull-harshad-mehta-1992\">द बिग बुल: हर्षद मेहता (1992)</h2>\n<p>1990 च्या दशकाच्या सुरुवातीस, हर्षद मेहता नावाचा मुंबईतील स्टॉक ब्रोकर एक घरगुती नाव बनला, एक चमकदार \"बिग बुल\" जो बाजाराला नाचवणारा दिसत होता. त्याचे रहस्य स्टॉक पिकिंग अलौकिक बुद्धिमत्ता नव्हते. हे बँकिंग प्लंबिंगमध्ये एक छिद्र होते.</p>\n<p>बँकांनी कागदी स्लिप्स वापरून सरकारी बॉण्ड्सवर अल्प मुदतीसाठी एकमेकांना पैसे दिले <strong>बँक पावत्या (BRs)</strong> IOUs म्हणून. या सौद्यांच्या मध्यभागी बसून मेहता यांनी बँकांना इश्यू करण्याची व्यवस्था केली <strong>बनावट BR</strong>, अस्तित्वात नसलेल्या रोख्यांच्या पावत्या, आणि मूठभर स्टॉक्समध्ये वाहणारी रोख रक्कम ओतली, त्यांच्या किंमती गगनाला भिडल्या. ACC, या सिमेंट कंपनीने अंदाजे वर्षभरात सुमारे 200 रुपयांवरून जवळपास 9,000 रुपयांपर्यंत उलाढाल केली. पत्रकार सुचेता दलाल यांनी एप्रिल 1992 मध्ये या रॅकेटचा पर्दाफाश केला तेव्हा मार्केट क्रॅश झाले आणि नंतर एका अधिकृत समितीने या अनियमिततेचा अंदाज लावला. <strong>4,000 कोटी रुपये</strong>, नंतर एक आश्चर्यकारक रक्कम.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch18-harshad-mehta-mechanism.png\" alt=\"1992 चा बँक-पावती घोटाळा कसा चालला, बनावट बँक पावत्या बँकांकडून ब्रोकरकडे पैसे वाहू देत, ज्यांनी त्यांच्या किमती वाढवण्यासाठी काही स्टॉक्समध्ये ते ओतले, जोपर्यंत उघडकीस येईपर्यंत मार्केट क्रॅश झाले.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>1992 चा बँक-पावती घोटाळा कसा चालला, बनावट बँक पावत्या बँकांकडून ब्रोकरकडे पैसे वाहू देत, ज्यांनी त्यांच्या किमती वाढवण्यासाठी काही स्टॉक्समध्ये ते ओतले, जोपर्यंत उघडकीस येईपर्यंत मार्केट क्रॅश झाले.</figcaption></figure>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>त्याच्या शिखरावर, हर्षद मेहता एका मिनी गोल्फ कोर्ससह सुमारे 15,000 चौरस फूट समुद्र-मुखी वरळी पेंटहाऊसमध्ये राहत होते, आयात केलेल्या आलिशान गाड्या चालवतात आणि एकदा त्यांची प्रतिमा जाळण्यासाठी कोट्यवधींचा आगाऊ कर भरला होता. शेअर्सच्या किमतींइतकीच ही जीवनशैली होती, ज्याने सामान्य गुंतवणूकदारांना असा विश्वास दिला की त्याला जादूचा स्पर्श आहे.</p>\n</div></div>\n<p>चिरस्थायी सुवार्ता म्हणजे काय घोटाळा <em>बांधले</em>. याने भारताला आपल्या बाजारपेठेत खऱ्याखुऱ्या पोलीस दलाचा धक्का दिला: <strong>SEBI ला 1992 मध्ये वैधानिक दात देण्यात आले</strong>, द <strong>नॅशनल स्टॉक एक्सचेंज (NSE)</strong> पूर्ण इलेक्ट्रॉनिक, पारदर्शक स्क्रीन-आधारित ट्रेडिंग आणि नंतर लवकरच लॉन्च केले गेले <strong>अभौतिकीकरण</strong> नंतर शेअर्स बनावट कागदाच्या बाहेर आणि सुरक्षित इलेक्ट्रॉनिक खात्यांमध्ये हलवले. या घोटाळ्यामुळे तुम्ही आज ज्या संरक्षणांवर अवलंबून आहात तेच मुख्यत्वे अस्तित्वात आहेत.</p>\n<h2 id=\"the-pentafour-bull-ketan-parekh-early-2000s\">द पेंटाफोर बुल: केतन पारेख (2000 च्या सुरुवातीस)</h2>\n<p>एका दशकानंतर, इतिहासाची तालमी झाली. स्टॉकब्रोकर केतन पारेख, एके काळी मेहता यांच्या वर्तुळाच्या जवळचे होते, त्यांनी स्टॉकचा एक संच चालवला ज्याला मार्केट टोपणनाव होते. <strong>\"K-10\"</strong> (झी टेलिफिल्म्स, HFCL आणि इतर सारखी नावे). त्याचे साधन होते <strong>परिपत्रक व्यापार</strong>: तयार करण्यासाठी एकमेकांशी समान समभाग खरेदी आणि विक्री कनेक्ट केलेल्या घटकांची एक अंगठी <em>भ्रम</em> प्रचंड मागणी, किमतींना हास्यास्पद उंचीवर नेणे आणि ज्यांना गमावण्याची भीती वाटत होती अशा वास्तविक गुंतवणूकदारांना आकर्षित करणे.</p>\n<p>इंधनाचा, पुन्हा, बँकेच्या पैशाचा दुरुपयोग झाला, विशेषत: माधवपुरा मर्कंटाईल को-ऑपरेटिव्ह बँक आणि ग्लोबल ट्रस्ट बँकेशी लिंक. 2001 मध्ये जेव्हा फुगा फुटला तेव्हा K-10 साठा कोसळला, बँका डबघाईला आल्या आणि शेवटी SEBI <strong>पारेख यांना 14 वर्षांसाठी बाजारातून बंदी घातली</strong>. धडा: कोणत्याही खऱ्या बातम्यांवर होणारी किंमत ही अनेकदा पंप असते, शोध नाही.</p>\n<h2 id=\"india-s-enron-satyam-2009\">भारताचे एनरॉन: सत्यम (2009)</h2>\n<p>पहिल्या दोन घोटाळ्यांनी किंमतींमध्ये फेरफार केला. सत्यम फसवणूक अधिक गडद होती, संस्थापक फक्त <em>शोध लावला</em> कंपनीचे यश. जानेवारी 2009 मध्ये, सत्यम कॉम्प्युटर्सचे चेअरमन रामलिंगा राजू यांनी फर्मची पुस्तके काल्पनिक असल्याची कबुली आजच्या प्रसिद्ध पत्रात दिली. त्याने वर्षानुवर्षे नफा फुगवला आणि ढोबळपणे बनाव केला <strong>रु 7,000+ कोटी</strong>, सुमारे समावेश <strong>5,000 कोटी रुपयांची रोकड जी अस्तित्वात नव्हती</strong>, रोख रक्कम ज्यावर लेखापरीक्षकांनी आनंदाने स्वाक्षरी केली होती.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>बनावट महसूल तयार करण्यासाठी, सत्यमने कधीही न केलेल्या कामासाठी 7,500 हून अधिक बोगस पावत्या तयार केल्या, आणि त्याच्या वेतनात अंदाजे 13,000 \"भूत कर्मचारी\", असे लोक होते जे कधीही अस्तित्वात नव्हते, पगार काढत होते जे शांतपणे काढून टाकले गेले होते. यामुळे कंपनीला \"इंडियाज एनरॉन\" असे भयंकर टोपणनाव मिळाले.</p>\n</div></div>\n<p>शेअरहोल्डर्स जवळपास रातोरात नष्ट झाले. पण पुन्हा एकदा प्रणाली शिकली: कॉर्पोरेट-गव्हर्नन्स आणि ऑडिटिंग नियम कडक केले गेले, स्वतंत्र संचालक आणि लेखापरीक्षकांची भूमिका आणि उत्तरदायित्व कठोर तपासणीखाली आले आणि भारताने नंतर कंपनी कायद्यात सुधारणा केली. खुल्या लिलावाद्वारे सत्यमचीच सुटका झाली आणि दुसऱ्या फर्मने आत्मसात केली.</p>\n<h2 id=\"when-the-plumbing-fails-nsel-and-karvy\">जेव्हा प्लंबिंग अयशस्वी होते: NSEL आणि कार्वी</h2>\n<p>आणखी दोन अलीकडील प्रकरणे दर्शवितात की घोटाळे केवळ किंमतीमध्ये हेराफेरी करतात असे नाही तर काहीवेळा तुमचा विश्वास असलेली संस्था तुमच्या पैशांचा गैरवापर करते.</p>\n<p>2013 मध्ये, द <strong>नॅशनल स्पॉट एक्सचेंज (NSEL)</strong> सुमारे पेमेंट डीफॉल्ट उघड करून, अचानक व्यापार गोठवला <strong>5,600 कोटी रुपये</strong>. याने स्पॉट कमोडिटी ट्रेडच्या रूपात तयार केलेले \"पेअर कॉन्ट्रॅक्ट्स\" ऑफर केले होते, ज्याला गोदामांमध्ये सामानाचा आधार असल्याचे मानले जाते, शिवाय अनेक प्रकरणांमध्ये माल क्वचितच अस्तित्वात होता. खात्रीशीर परताव्याचा पाठलाग करणारे हजारो गुंतवणूकदार अडकून पडले होते.</p>\n<p>2019 मध्ये, <strong>कार्वी स्टॉक ब्रोकिंग</strong> चा गैरवापर करताना पकडले गेले <strong>मुखत्यारपत्र</strong> ग्राहकांनी नियमित व्यापारासाठी स्वाक्षरी केली होती. त्याने शांतपणे त्याच्या क्लायंटचे स्वतःचे शेअर्स कर्ज घेण्यासाठी गहाण ठेवले <strong>2,000 कोटी रुपये</strong> स्वत: साठी, अंदाजे 95,000 गुंतवणूकदारांना मारले ज्यांना त्यांचे होल्डिंग संपार्श्विक असल्याची कल्पना नव्हती. SEBI नंतर कायमचे नियम कडक केले जेणेकरून ब्रोकर यापुढे अशा प्रकारे क्लायंट सिक्युरिटीज जमा करू शकत नाहीत किंवा तारण ठेवू शकत नाहीत आणि तुमचे शेअर्स आता तुमच्या स्वतःच्या डीमॅट खात्यात अधिक सुरक्षितपणे बसतात.</p>\n<table>\n<thead>\n<tr>\n<th>घोटाळा</th>\n<th>वर्ष</th>\n<th>काय झाले (अंदाजे)</th>\n<th>काय बदलले</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>हर्षद मेहता</td>\n<td>1992</td>\n<td>बनावट बँक पावत्यांमुळे ~4,000+ कोटी रुपयांचा स्टॉक रॅम्प; बाजार कोसळला</td>\n<td>SEBI सशक्त; NSE आणि इलेक्ट्रॉनिक ट्रेडिंग सुरू केले; डीमॅट सुरू झाले</td>\n</tr>\n<tr>\n<td>केतन पारेख</td>\n<td>2001</td>\n<td>\"K-10\" साठा गैरवापर केलेल्या बँकेच्या पैशावर परिपत्रक व्यापाराद्वारे पंप केला</td>\n<td>कडक पाळत ठेवणे; पारेख यांच्यावर १४ वर्षांची बंदी</td>\n</tr>\n<tr>\n<td>सत्यम</td>\n<td>2009</td>\n<td>संस्थापकाने ~7,000+ कोटी रुपये नफा आणि रोख बनावट; \"भारताचा एनरॉन\"</td>\n<td>मजबूत ऑडिटिंग आणि कॉर्पोरेट-गव्हर्नन्स नियम</td>\n</tr>\n<tr>\n<td>NSEL</td>\n<td>2013</td>\n<td>वास्तविक माल नसलेल्या कमोडिटी करारावर ~ 5,600 कोटी रुपये डिफॉल्ट</td>\n<td>स्पॉट-एक्सचेंज निरीक्षणाची दुरुस्ती केली</td>\n</tr>\n<tr>\n<td>कारवी</td>\n<td>2019</td>\n<td>ब्रोकरने संमतीशिवाय क्लायंटचे 2,000 कोटी रुपयांचे शेअर्स गहाण ठेवले</td>\n<td>क्लायंट सिक्युरिटीज रिंग-फेन्स्ड; प्रतिज्ञा नियम कडक केले</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch18-scam-timeline.png\" alt=\"1992 मधील हर्षद मेहता ते आजच्या सोशल मीडिया पंप-अँड-डंप्सपर्यंत भारतातील सर्वात मोठ्या बाजारपेठेतील घोटाळ्यांची टाइमलाइन, प्रत्येकाला त्याच्या ढोबळ स्केलसह चिन्हांकित केले गेले आणि त्यामुळे झालेल्या सुधारणा\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">इन्फोग्राफिक</span>1992 मधील हर्षद मेहता ते आजच्या सोशल मीडिया पंप-अँड-डंप्सपर्यंत भारतातील सर्वात मोठ्या बाजारपेठेतील घोटाळ्यांची टाइमलाइन, प्रत्येकाला त्याच्या ढोबळ स्केलसह चिन्हांकित केले गेले आणि त्यामुळे झालेल्या सुधारणा</figcaption></figure>\n<h2 id=\"the-new-playground-scams-you-ll-actually-meet-today\">नवीन खेळाचे मैदान: घोटाळे तुम्हाला आज प्रत्यक्षात भेटतील</h2>\n<p>तुम्हाला खोट्या बँक पावतीने फसवले जाण्याची शक्यता नाही. तुम्हाला तुमच्या फोनवर लक्ष्य केले जाण्याची शक्यता आहे. क्लासिक फसवणूक मोठ्या आणि मोठ्याने गेला; आधुनिक तुमच्याकडे वैयक्तिकरित्या येतात, मैत्रीपूर्ण दिसतात आणि शेवटच्या अध्यायातील अचूक भावनांशी जुळतात.</p>\n<h3 id=\"pump-and-dump-on-whatsapp-and-telegram\">व्हॉट्सॲप आणि टेलिग्रामवर पंप आणि डंप</h3>\n<p>हे केतन पारेख प्लेबुक आहे, लोकशाहीकरण. ऑपरेटर शांतपणे स्वस्त, बारीक व्यापार केलेली स्मॉल-कॅप खरेदी करतात, नंतर पूर येतो <strong>व्हॉट्सॲप, टेलिग्राम आणि एक्स</strong> श्वास नसलेले गट \"आता खरेदी करा, लक्ष्य दुप्पट करा\" संदेश. लहान गुंतवणूकदार, किमती वाढतात आणि ऑपरेटर्समध्ये ढीग करतात <strong>डंप</strong> त्या खरेदीमध्ये त्यांचे शेअर्स, इतर प्रत्येकजण कोसळणारा स्टॉक ठेवतो. SEBI ने वारंवार क्रॅक डाउन केले आहे: 2024-2026 च्या आसपासच्या प्रकरणांमध्ये त्याने कोट्यवधींचा बेकायदेशीर नफा जप्त केला आहे, टेलीग्राम-चालित योजना जसे की दर्शन ओरना प्रकरणाला दंडित केले आहे आणि डझनभर स्क्रिपमध्ये हेराफेरी करणाऱ्या ऑपरेटरना प्रतिबंधित केले आहे. जर एखाद्या समूहातील अनोळखी व्यक्ती मोफत संपत्ती देत ​​असेल, तर तुम्ही पाहुणे नसून तुम्ही जेवण आहात.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch18-pump-and-dump-mechanism.png\" alt=\"पंप आणि डंपची रचना, ऑपरेटर शांतपणे स्वस्त स्मॉल कॅप जमा करतात, व्हॉट्सॲप आणि टेलिग्रामवर त्याचा प्रचार करतात, किरकोळ गुंतवणूकदार ढीग करतात आणि किंमत वाढवतात, मग ऑपरेटर त्यांचे शेअर्स टाकतात आणि किंमत कोसळते\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">फ्लो चार्ट</span>पंप आणि डंपची रचना, ऑपरेटर शांतपणे स्वस्त स्मॉल कॅप जमा करतात, व्हॉट्सॲप आणि टेलिग्रामवर त्याचा प्रचार करतात, किरकोळ गुंतवणूकदार ढीग करतात आणि किंमत वाढवतात, मग ऑपरेटर त्यांचे शेअर्स टाकतात आणि किंमत कोसळते</figcaption></figure>\n<h3 id=\"finfluencers-and-fake-tips\">Finfluencers आणि बनावट \"टिप्स\"</h3>\n<p>सोशल मीडिया आत्मविश्वासाने भरलेले \"तज्ञ\" <strong>finfluencers</strong>, सशुल्क अभ्यासक्रम, प्रीमियम टिप चॅनेल आणि \"गॅरंटीड मल्टीबॅगर\" कॉलद्वारे समृद्धीचे आश्वासन. बहुतेक आहेत <strong>SEBI सह नोंदणीकृत नाही</strong> गुंतवणुकीचा सल्ला देण्यासाठी, आणि पुष्कळांना शांतपणे पैसे दिले जातात आणि ते ज्या शेअर्सचा प्रचार करतात. धोका ओळखून, <strong>SEBI ने 2024 मध्ये नियम कडक केले</strong>: नोंदणीकृत ब्रोकर्स आणि सल्लागारांना आता नोंदणीकृत नसलेल्या फिनफ्लुएंसर्सशी संबंध ठेवण्यापासून प्रतिबंधित केले आहे आणि वास्तविक शिक्षक थेट खरेदी /sell कॉल देऊ शकत नाहीत. शिक्षण ठीक आहे. एक अनोळखी व्यक्ती तुम्हाला नेमके काय खरेदी करायचे हे सांगतो, फीसाठी, सहसा नाही.</p>\n<h3 id=\"know-your-advisers-ra-ria-and-the-fakes\">तुमच्या सल्लागारांना जाणून घ्या: RA, RIA आणि बनावट</h3>\n<p>स्टॉकबद्दल बोलणाऱ्या प्रत्येकाला तुम्हाला सल्ला देण्याची परवानगी नाही आणि फरक महत्त्वाचा आहे. SEBI दोन प्रकारच्या अस्सल व्यावसायिकांची नोंदणी करते:</p>\n<ul>\n<li>ए <strong>संशोधन विश्लेषक (RA)</strong> वर नोंदणीकृत आहे <em>संशोधन प्रकाशित करा</em>, अहवाल आणि खुलासेसह, स्टॉकवर खरेदी/विक्री/होल्ड शिफारसी. ते विश्लेषण करतात आणि कॉल करतात; ते तुमचे वैयक्तिक पैसे व्यवस्थापित करत नाहीत.</li>\n<li>ए <strong>नोंदणीकृत गुंतवणूक सल्लागार (RIA)</strong> देण्यासाठी नोंदणीकृत आहे <em>वैयक्तिक गुंतवणूक सल्ला</em> फी साठी, आणि a द्वारे बांधील आहे <strong>विश्वासू कर्तव्य</strong>, तुमचे स्वारस्य प्रथम ठेवण्याचे कायदेशीर बंधन. अस्सल RIA आहे <strong>फक्त फी</strong> आणि पुशिंग उत्पादनांसाठी छुपे कमिशन खिशात ठेवत नाही.</li>\n</ul>\n<p>दोघांमध्ये SEBI आहे <strong>नोंदणी क्रमांक</strong> तुम्ही sebi.gov.in वर पाहू शकता. वास्तविक सल्लागाराची चाचणी सोपी आहे: <em>नोंदणीकृत, संघर्षांबद्दल अगोदर, आणि कधीही हमीपरताव्याचे आश्वासन दिलेले नाही.</em></p>\n<p>ए <strong>बनावट सल्लागार</strong> कोणी टिप्स किंवा \"सल्ला\" साठी शुल्क आकारत आहे का <em>शिवाय</em> ती नोंदणी, टेलीग्राम \"संशोधन\" चॅनेल, WhatsApp \"SEBI-मंजूर\" टिपस्टर, दरमहा 30% हमी देणारे ॲप. SEBI नोंदणीशिवाय सशुल्क गुंतवणुकीचा सल्ला देणे बेकायदेशीर आहे आणि या प्रकरणातील पंप-अँड-डंप आणि पॉन्झी योजनांच्या मागे हे ऑपरेटर सहसा समान गर्दी करतात. तुम्ही कोणाला सल्ल्यासाठी पैसे देण्यापूर्वी, त्यांचा नोंदणी क्रमांक स्वतः पहा. एक नसेल तर, ते <em>आहे</em> तुमचे उत्तर.</p>\n<h3 id=\"fake-apps-and-guaranteed-return-ponzi-schemes\">बनावट ॲप्स आणि गॅरंटीड-रिटर्न पॉन्झी योजना</h3>\n<p>एक पॉलिश ॲप तुमची \"गुंतवणूक\" दर आठवड्याला 5% वाढत असल्याचे दाखवते. लवकर पैसे काढणे उत्तम प्रकारे कार्य करते, कारण त्यांना पैसे दिले जातात <em>नवीन</em> पीडितांच्या ठेवी, अ.ची स्वाक्षरी <strong>पॉन्झी योजना</strong>. मग एक दिवस ॲप गायब होतो, ॲडमिन गप्प बसतो आणि पैसे निघून जातात. हे सहसा एखाद्या मित्राद्वारे (ज्याला देखील फसवले गेले होते), डेटिंग-ॲप संपर्क किंवा कोणत्याही वास्तविक एक्सचेंजशी कनेक्ट केलेले नसलेले चपळ \"प्लॅटफॉर्म\" द्वारे येतात.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch18-ponzi-mechanism.png\" alt=\"पॉन्झी किंवा गॅरंटीड-रिटर्न योजना कशी कार्य करते, नवीन गुंतवणूकदारांच्या ठेवींचा वापर पूर्वीच्या गुंतवणूकदारांना खोटा नफा देण्यासाठी केला जातो, जोपर्यंत नवीन पैसे सुकत नाहीत आणि संपूर्ण योजना कोलमडत नाही तोपर्यंत भ्रम टिकवून ठेवतात.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">फ्लो चार्ट</span>पॉन्झी किंवा गॅरंटीड-रिटर्न योजना कशी कार्य करते, नवीन गुंतवणूकदारांच्या ठेवींचा वापर पूर्वीच्या गुंतवणूकदारांना खोटा नफा देण्यासाठी केला जातो, जोपर्यंत नवीन पैसे सुकत नाहीत आणि संपूर्ण योजना कोलमडत नाही तोपर्यंत भ्रम टिकवून ठेवतात.</figcaption></figure>\n<h3 id=\"dabba-trading\">डब्बा ट्रेडिंग</h3>\n<p>शेवटी, आधुनिक चेहरा असलेला जुना अवैध व्यापार: <strong>डब्बा (बॉक्स) व्यापार</strong>. एक संदिग्ध ऑपरेटर तुम्हाला पुस्तकांचा \"व्यापार\" करू देतो, कोणतीही वास्तविक ऑर्डर कधीही NSE किंवा BSE पर्यंत पोहोचत नाही; हे सर्व त्याच्या खाजगी खात्यातील नोंद आहे, अनेकदा बेपर्वा फायदा आणि \"कोणताही कर नाही, कागदपत्र नाही.\" ते अ <strong>फौजदारी गुन्हा</strong> सिक्युरिटीज कॉन्ट्रॅक्ट्स (नियमन) कायद्यांतर्गत, 10 वर्षांपर्यंत तुरुंगवास किंवा भारी दंड. आणि कोणताही खरा व्यापार अस्तित्वात नसल्यामुळे, ऑपरेटर तुमच्या पैशाने नाहीसा झाला तर तुमच्याकडे आहे <strong>कोणतेही कायदेशीर संरक्षण नाही</strong>.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch18-red-flags.png\" alt=\"सार्वत्रिक लाल ध्वजांची स्कॅम-स्पॉटर चेकलिस्ट, हमी किंवा निश्चित उच्च परतावा, आता काम करण्याचा दबाव, नोंदणी न केलेले सल्लागार, अस्पष्ट स्मॉल-कॅप्सवरील टिपा आणि तुमच्या OTP किंवा लॉगिनसाठी विनंत्या\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">इन्फोग्राफिक</span>सार्वत्रिक लाल ध्वजांची स्कॅम-स्पॉटर चेकलिस्ट, हमी किंवा निश्चित उच्च परतावा, आता काम करण्याचा दबाव, नोंदणी न केलेले सल्लागार, अस्पष्ट स्मॉल-कॅप्सवरील टिपा आणि तुमच्या OTP किंवा लॉगिनसाठी विनंत्या</figcaption></figure>\n<h2 id=\"the-red-flags-they-all-share\">लाल ध्वज ते सर्व सामायिक करतात</h2>\n<p>युग आणि तंत्रज्ञान काढून टाका, आणि यापैकी प्रत्येक फसवणूक समान झेंडे फडकवते. तुम्हाला एकही दिसला तर थांबा.</p>\n<ul>\n<li><strong>हमी, निश्चित किंवा \"जोखीम मुक्त\" उच्च परतावा.</strong> वास्तविक बाजार कधीही परताव्याची हमी देत ​​नाही. हे एकच सर्वात मोठे सांगणे आहे.</li>\n<li><strong>कृती करण्याचा दबाव <em>आता</em></strong>, \"ऑफर आज रात्री बंद होईल,\" \"फक्त 10 जागा शिल्लक आहेत.\" तुमची विचारसरणी बंद करण्याची निकड आहे.</li>\n<li><strong>नोंदणी नसलेले सल्लागार किंवा प्लॅटफॉर्म</strong>, SEBI नोंदणी क्रमांकाशिवाय सशुल्क स्टॉक सल्ला देणारा कोणीही.</li>\n<li><strong>अस्पष्ट, अलिक्विड स्मॉल-कॅप्सवरील हॉट टिप्स</strong>, पंप आणि डंपसाठी योग्य दारूगोळा.</li>\n<li><strong>खूप-चांगले-ते-खरे,</strong> गुप्त \"आतल्या\" माहिती, किंवा एक प्रणाली जी \"गमवू शकत नाही.\"</li>\n<li><strong>तुमचा पासवर्ड, OTP किंवा रिमोट ॲक्सेस विचारणारे कोणीही</strong> तुमच्या खात्यावर. कोणताही वैध दलाल किंवा नियामक कधीही करणार नाही.</li>\n</ul>\n<h2 id=\"your-protection-checklist\">तुमची संरक्षण चेकलिस्ट</h2>\n<p>तुम्हाला निंदक असण्याची गरज नाही, फक्त काळजी घ्या. काही कायमस्वरूपी सवयी तुम्हाला जवळजवळ फसवणूक-पुरावा बनवतात.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p><strong>फक्त SEBI-नोंदणीकृत मध्यस्थांशी व्यवहार करा आणि ते स्वतः सत्यापित करा.</strong> प्रत्येक कायदेशीर ब्रोकर, सल्लागार आणि संशोधन विश्लेषक यांचा नोंदणी क्रमांक SEBI च्या अधिकृत वेबसाइटवर (sebi.gov.in) सूचीबद्ध आहे. जर तुम्हाला ते तिथे सापडले नाहीत तर, त्यांचे परिणाम कितीही प्रभावी दिसत असले तरीही तेथून निघून जा.</p>\n</div></div>\n<ul>\n<li><strong>तुम्ही विश्वास ठेवण्यापूर्वी सत्यापित करा.</strong> SEBI साइटवर तुम्ही शोधू शकता असा वास्तविक नोंदणी क्रमांक नफ्याच्या कोणत्याही स्क्रीनशॉटला मागे टाकतो.</li>\n<li><strong>तक्रार करण्यासाठी SCORES वापरा.</strong> जर एखाद्या नोंदणीकृत संस्थेने तुमची चूक केली तर, SEBI च्या अधिकृत निवारण प्लॅटफॉर्मवर तक्रार नोंदवा, <strong>scores.sebi.gov.in</strong>, विनामूल्य आणि ट्रॅक केलेले.</li>\n<li><strong>\"नक्की-शॉट\" टिपांकडे दुर्लक्ष करा.</strong> प्रत्येक गॅरंटीड कॉल, हॉट व्हॉट्सॲप फॉरवर्ड आणि \"दुप्पट\" लक्ष्याला विक्री पिच म्हणून हाताळा, कारण ते एक आहे.</li>\n<li><strong>सोशल मीडिया टिप्सबद्दल संशयी रहा.</strong> आत्मविश्वासपूर्ण व्हिडिओ संशोधन नाही. विचारा: ही व्यक्ती नोंदणीकृत आहे, आणि मी खरेदी केल्यास त्यांना काय फायदा होईल?</li>\n<li><strong>तुमचा लॉगिन, पासवर्ड किंवा OTP कधीही शेअर करू नका</strong> कोणाशीही, \"दलाल\" नाही, \"सपोर्ट\" नाही. OTP शेअर करणे म्हणजे चाव्या सुपूर्द करणे.</li>\n<li><strong>रेल्स वर रहा</strong>, रिअल एक्स्चेंज, रिअल डीमॅट खाती, रिअल कॉन्ट्रॅक्ट नोट्स. डब्बा ट्रेडिंग सारख्या ऑफ-मार्केट शॉर्टकटमध्ये सुरक्षिततेचे जाळे नसते.</li>\n</ul>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>आधीच काहीतरी चूक झाली असेल, बनावट ॲपवर पैसे पाठवले गेले, संमतीशिवाय शेअर्स हलवले गेले, तुमची फी घेतली आणि गायब झाले असे टिप-चॅनल, जलद कृती करा. पुढील सर्व पेमेंट थांबवा, स्क्रीनशॉट आणि व्यवहार रेकॉर्ड गोळा करा, नोंदणीकृत संस्थांसाठी SCORES वर तक्रार दाखल करा आणि राष्ट्रीय सायबर-गुन्हेगारी हेल्पलाइन (1930) आणि cybercrime.gov.in द्वारे आर्थिक फसवणुकीचा अहवाल द्या. वेग महत्त्वाचा; गोठवलेला निधी कधी कधी वसूल केला जाऊ शकतो.</p>\n</div></div>\n<h2 id=\"where-to-go-from-here\">इथून कुठे जायचे</h2>\n<p>\"वाट म्हणजे काय?\" पासून तुम्ही खूप पुढे आला आहात. एक कोट वाचण्यासाठी, किंमती कशा हलवतात हे समजून घेणे, स्वतःचे मन व्यवस्थापित करणे आणि आता लांडगे शोधणे. आत्मविश्वासपूर्ण, स्वावलंबी गुंतवणूकदाराला जे आवश्यक असते त्यापैकी हेच खरे आहे. बाजार हा कॅसिनो नाही आणि तो कटही नाही; रुग्णाच्या बचतीला खऱ्या संपत्तीमध्ये रूपांतरित करण्यासाठी हे एक शक्तिशाली, मुख्यतः न्याय्य मशीन आहे, एकदा ते कसे कार्य करते आणि कोणावर विश्वास ठेवायचा हे आपल्याला कळते.</p>\n<p>म्हणून हळूवारपणे चालत रहा. लहान सुरुवात करा, तुमची गुंतवणूक स्वयंचलित करा, वैविध्यपूर्ण रहा, गोंगाटाकडे दुर्लक्ष करा आणि वेळ आणि कंपाऊंडिंग यांना हेवी लिफ्टिंग करू द्या. शिकत राहा, तुम्ही जितके अधिक समजून घ्याल तितके शांत आणि मूर्ख बनणे कठीण होईल. जेव्हा तुम्ही तांत्रिक आणि मूलभूत विश्लेषण, पर्याय, ट्रेडर्ससाठी पायथन किंवा अल्गोरिदमिक ट्रेडिंगमध्ये खोलवर जाण्यासाठी तयार असाल, तेव्हा OpenAlgo चे इतर विनामूल्य अभ्यासक्रम येथे प्रतीक्षेत आहेत <strong>/learn</strong>.</p>\n<p>बाजारात आपले स्वागत आहे. तुम्ही आता नवशिक्या नाही आहात, तुम्ही माहितीदार गुंतवणूकदार आहात. संयमाने गुंतवणूक करा, स्वतःचे रक्षण करा आणि वर्षे तुमच्या बाजूने जाऊ द्या.</p>\n","toc":[{"level":2,"text":"द बिग बुल: हर्षद मेहता (1992)","id":"the-big-bull-harshad-mehta-1992"},{"level":2,"text":"द पेंटाफोर बुल: केतन पारेख (2000 च्या सुरुवातीस)","id":"the-pentafour-bull-ketan-parekh-early-2000s"},{"level":2,"text":"भारताचे एनरॉन: सत्यम (2009)","id":"india-s-enron-satyam-2009"},{"level":2,"text":"जेव्हा प्लंबिंग अयशस्वी होते: NSEL आणि कार्वी","id":"when-the-plumbing-fails-nsel-and-karvy"},{"level":2,"text":"नवीन खेळाचे मैदान: घोटाळे तुम्हाला आज प्रत्यक्षात भेटतील","id":"the-new-playground-scams-you-ll-actually-meet-today"},{"level":3,"text":"व्हॉट्सॲप आणि टेलिग्रामवर पंप आणि डंप","id":"pump-and-dump-on-whatsapp-and-telegram"},{"level":3,"text":"Finfluencers आणि बनावट \"टिप्स\"","id":"finfluencers-and-fake-tips"},{"level":3,"text":"तुमच्या सल्लागारांना जाणून घ्या: RA, RIA आणि बनावट","id":"know-your-advisers-ra-ria-and-the-fakes"},{"level":3,"text":"बनावट ॲप्स आणि गॅरंटीड-रिटर्न पॉन्झी योजना","id":"fake-apps-and-guaranteed-return-ponzi-schemes"},{"level":3,"text":"डब्बा ट्रेडिंग","id":"dabba-trading"},{"level":2,"text":"लाल ध्वज ते सर्व सामायिक करतात","id":"the-red-flags-they-all-share"},{"level":2,"text":"तुमची संरक्षण चेकलिस्ट","id":"your-protection-checklist"},{"level":2,"text":"इथून कुठे जायचे","id":"where-to-go-from-here"}],"imgCount":5,"hasContent":true}}
